INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b272803-d9f2-5138-bd49-4e0b87265d3b','Background correction','An energy-based adjustment that removes the contribution of background noise from a measurement of source-plus-background, so the source level alone is obtained. Because levels combine on a power basis, the background is subtracted in the power domain; standards require the source to exceed the background by a stated margin, and when the difference is small the correction grows large and uncertain, so measurements below a minimum margin are considered invalid.','Background correction removes the room''s own noise from a reading. You measure the source plus the background together. Then you subtract the background on a power basis, not by simple decibels. The source must be clearly above the background for this to work. If they are too close, the result is not trusted.','Recovers the true source level by stripping out background noise, and warns when the two are too close to separate reliably.','Technicians measure background alone, then source-plus-background, and apply the energy subtraction, rejecting results where the margin is too small.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Background noise','Signal-to-noise ratio','Sound power level','Reverberation correction','Reference environment']::text[],ARRAY['Subtracting decibels arithmetically instead of on a power basis','Applying the correction when the source barely exceeds the background','Forgetting to measure the background under the same conditions']::text[],ARRAY['Correcting a machine sound-power test for room background','Rejecting a reading where source and background differ by too little','Measuring background before and after a source-on run']::text[],'advanced','L_S = 10·log10(10^(L_SN/10) − 10^(L_N/10)) dB','The source level equals ten times the base-ten logarithm of the difference between the antilog of the source-plus-noise level and the antilog of the background-noise level, each divided by ten.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b272803-d9f2-5138-bd49-4e0b87265d3b','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b272803-d9f2-5138-bd49-4e0b87265d3b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b272803-d9f2-5138-bd49-4e0b87265d3b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20a1df77-a9c7-5e17-8796-d5de3a91d8f4','Reverberation correction','An adjustment applied in sound power determination to remove the influence of reflected (reverberant) sound in the test room, so results approximate free-field radiation. Known as the environmental correction, it is derived from the room''s acoustic absorption relative to the measurement surface area; a larger reverberant contribution yields a larger correction, and standards limit its magnitude to keep the test room acceptable.','Reverberation correction removes the effect of reflected sound in a test room. In a live room, echoes add to the direct sound and inflate readings. The correction is based on how absorbent the room is. A more reflective room needs a bigger correction. Standards cap how large it may be.','Strips out the room''s reflected sound from sound-power measurements so results reflect the source, not the room.','Technicians compute the environmental correction from room absorption when measuring sound power in an ordinary room instead of a special chamber.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Reverberant condition','Sound power level','Background correction','Absorption coefficient','Reference environment']::text[],ARRAY['Confusing the reverberation correction with a simple background subtraction','Using a room whose correction exceeds the allowed limit','Ignoring room absorption when estimating the reverberant contribution']::text[],ARRAY['Applying an environmental correction in a hard-walled test room','Estimating room absorption for a sound-power measurement','Rejecting a room whose reverberation correction is too large']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberation correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20a1df77-a9c7-5e17-8796-d5de3a91d8f4','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20a1df77-a9c7-5e17-8796-d5de3a91d8f4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20a1df77-a9c7-5e17-8796-d5de3a91d8f4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48bdeb6c-0339-5af1-89fd-1d7d48030c17','Distance correction','An adjustment that translates a sound level measured at one distance to another distance, based on how level falls with distance for the source and field concerned. For a point source in a free field the level decreases by about 6 dB per doubling of distance following the inverse-square law, so the correction between two distances is twenty times the base-ten logarithm of their ratio; line sources and reverberant fields follow different rates.','Distance correction changes a level from one distance to another. For a small source in the open, sound spreads and weakens with distance. Each doubling of distance drops the level by about six decibels. The exact change is twenty times the log of the distance ratio. Long sources and reflective rooms behave differently.','Lets a level measured at one distance be restated at another, using the source''s known falloff with distance.','Technicians normalise measured levels to a reference distance, applying inverse-square falloff for point sources in the open.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Inverse-square law','Reference distance','Free-field condition','Point source','Far-field condition']::text[],ARRAY['Applying the 6 dB per doubling rule inside a reverberant room','Treating a line source as if it were a point source','Forgetting that near-field readings do not follow inverse-square falloff']::text[],ARRAY['Normalising an outdoor level to a 1 m reference distance','Predicting the level at a boundary from a closer measurement','Checking a point source falls off 6 dB per distance doubling']::text[],'intermediate','ΔL = 20·log10(r_2 / r_1) dB','The level change equals twenty times the base-ten logarithm of the second distance divided by the first distance, for a point source in a free field.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distance correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48bdeb6c-0339-5af1-89fd-1d7d48030c17','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48bdeb6c-0339-5af1-89fd-1d7d48030c17') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48bdeb6c-0339-5af1-89fd-1d7d48030c17');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e1eed76-0852-5680-a543-0486050adbcc','Reference distance','A standardised distance from a source at which a level or performance figure is stated, so that specifications and measurements can be compared on a common basis. Common reference distances are 1 m for loudspeaker sensitivity and equipment ratings and larger fixed distances for community and environmental assessment; a level quoted without its reference distance is ambiguous.','A reference distance is a fixed distance used when stating a level. It gives everyone the same starting point for comparison. Loudspeaker sensitivity is often quoted at one metre. Community noise may use a larger set distance. A level with no stated distance is unclear.','Fixes a common distance for quoting levels so specifications and measurements can be compared fairly.','Technicians read and quote loudspeaker sensitivity at 1 m and normalise field levels to the reference distance a standard names.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Distance correction','Sensitivity','Free-field condition','Sound pressure level','Inverse-square law']::text[],ARRAY['Quoting a level without stating the reference distance','Comparing figures taken at different reference distances directly','Assuming every rating uses a 1 m reference distance']::text[],ARRAY['Reading a loudspeaker sensitivity quoted at 1 m','Normalising a measured level to a standard reference distance','Comparing two speakers at the same reference distance']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference distance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e1eed76-0852-5680-a543-0486050adbcc','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e1eed76-0852-5680-a543-0486050adbcc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e1eed76-0852-5680-a543-0486050adbcc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d62e23f-cc73-5bfa-ae12-a4759d775a9b','Far-field condition','The region far enough from a source that its radiation behaves simply: the sound pressure falls off inversely with distance, the wavefront is locally plane, and pressure and particle velocity are in phase so intensity is straightforward. The far field begins at distances large compared with both the source size and the wavelength, and it is where directivity and inverse-square predictions hold.','The far-field condition is the region well away from a source. There the sound behaves in a simple, predictable way. Doubling the distance drops the level by about six decibels. The wavefront looks flat and pressure lines up with air motion. Directivity patterns only settle here.','Marks where a source radiates predictably, so inverse-square falloff and directivity measurements are valid.','Technicians place measurement microphones in the far field so directivity and sensitivity readings follow inverse-square behaviour.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Near-field condition','Inverse-square law','Directivity','Free-field condition','Distance correction']::text[],ARRAY['Measuring directivity too close, inside the near field','Assuming inverse-square falloff holds right up against the source','Confusing the acoustic far field with a loudspeaker''s nearfield-monitor label']::text[],ARRAY['Positioning a microphone in the far field for a directivity test','Verifying 6 dB per doubling to confirm far-field measurement','Choosing a measurement distance beyond the source''s near field']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d62e23f-cc73-5bfa-ae12-a4759d775a9b','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d62e23f-cc73-5bfa-ae12-a4759d775a9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d62e23f-cc73-5bfa-ae12-a4759d775a9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a340f90-5a6b-5b0f-afed-d98680f55ee5','Near-field condition','The region close to a source where the sound field is complicated: level can vary strongly and non-monotonically with position, pressure and particle velocity may be out of phase in the reactive near field, and contributions from different parts of an extended source interfere. Inverse-square falloff and stable directivity do not yet apply, so measurements taken here are not representative of the source''s radiated field.','The near-field condition is the region right next to a source. There the sound is messy and hard to predict. The level can jump up and down as you move a little. Different parts of the source interfere with each other. Simple distance rules do not work yet.','Warns that measurements close to a source are unstable and not representative of its true radiated field.','Technicians avoid taking directivity or sensitivity readings in the near field, moving out until the field settles into far-field behaviour.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Far-field condition','Reactive near field','Directivity','Inverse-square law','Distance correction']::text[],ARRAY['Taking a representative level reading inside the near field','Expecting smooth inverse-square falloff close to the source','Confusing the reactive near field with a monitor''s nearfield label']::text[],ARRAY['Recognising unstable readings taken too close to a loudspeaker','Moving a microphone out of the near field before measuring','Explaining why near-field level jumps around with position']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a340f90-5a6b-5b0f-afed-d98680f55ee5','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a340f90-5a6b-5b0f-afed-d98680f55ee5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a340f90-5a6b-5b0f-afed-d98680f55ee5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65c112fe-2ddb-5098-aa00-6f715f34893d','Anechoic condition','A measurement condition approximating a free field, in which boundary reflections are made negligible so that only the direct sound from the source reaches the microphone. It is realised in an anechoic chamber whose surfaces are lined with deep absorptive wedges effective above a low cutoff frequency; the condition is the reference for free-field sensitivity, directivity, and sound-power measurements.','An anechoic condition means almost no reflections reach the microphone. Only the direct sound from the source arrives. It is created in a room lined with deep sound-absorbing wedges. Below a cutoff frequency the wedges stop working well. It is the reference setup for clean free-field tests.','Provides a reflection-free reference field so a source can be measured without room effects.','Technicians use anechoic chambers for loudspeaker frequency response, directivity, and free-field microphone calibration.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Free-field condition','Semi-anechoic condition','Reverberant condition','Absorption coefficient','Directivity']::text[],ARRAY['Assuming a chamber is anechoic below its wedge cutoff frequency','Confusing an anechoic condition with a merely quiet room','Ignoring residual reflections from fixtures inside the chamber']::text[],ARRAY['Measuring loudspeaker frequency response in an anechoic chamber','Calibrating a free-field microphone with no reflections','Checking a chamber''s low-frequency cutoff before testing']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anechoic condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65c112fe-2ddb-5098-aa00-6f715f34893d','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65c112fe-2ddb-5098-aa00-6f715f34893d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65c112fe-2ddb-5098-aa00-6f715f34893d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bf9d22c-f2c7-5bc9-9f79-3b1250f643db','Semi-anechoic condition','A measurement condition that is free of reflections except from a single rigid reflecting plane, typically a hard floor, so the source radiates into a half-space. It is realised in a semi-anechoic chamber with absorptive walls and ceiling over a hard floor, and it is used for sound-power and directivity measurements of equipment that normally stands on the ground.','A semi-anechoic condition is free of reflections except from the floor. The source sits on a hard floor and radiates into the half-space above. Walls and ceiling are covered in absorber. It suits gear that normally stands on the ground. The floor reflection is expected and accounted for.','Represents equipment radiating over a hard floor, giving a controlled half-space field for sound-power tests.','Technicians measure the sound power of floor-standing machinery in a semi-anechoic room that keeps the floor but absorbs other reflections.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Anechoic condition','Free-field condition','Ground reflection','Sound power level','Reflecting plane']::text[],ARRAY['Treating a semi-anechoic result as if it were full free-field','Forgetting the floor reflection that a semi-anechoic setup includes','Confusing semi-anechoic with fully anechoic conditions']::text[],ARRAY['Measuring the sound power of a floor-standing machine','Testing appliance noise over a hard reflecting floor','Accounting for the floor reflection in a half-space measurement']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Semi-anechoic condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bf9d22c-f2c7-5bc9-9f79-3b1250f643db','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bf9d22c-f2c7-5bc9-9f79-3b1250f643db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bf9d22c-f2c7-5bc9-9f79-3b1250f643db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14e04a7a-56d1-5565-9f79-618926cc3456','Reverberant condition','A measurement condition dominated by reflected sound, approximating a diffuse field in which the reverberant energy is uniform in level and random in direction throughout the space. It is realised in a reverberation room with hard, non-parallel or diffuser-fitted surfaces and a long reverberation time, and it is used for absorption, sound-power, and transmission measurements that rely on a diffuse field.','A reverberant condition is dominated by reflected sound. Echoes fill the room so evenly that the level is nearly the same everywhere. The sound arrives from all directions at random. It is created in a hard, very live reverberation room. It suits absorption and sound-power tests.','Provides a uniform diffuse field so absorption and sound-power measurements can rely on even, random-direction energy.','Technicians measure absorption coefficients and sound power in reverberation rooms, using random-incidence microphones and spatial averaging.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Diffuse field','Reverberation time','Random-incidence microphone','Absorption coefficient','Sound power level']::text[],ARRAY['Assuming the field is diffuse right next to the source','Confusing a reverberant condition with an ordinary echoey room','Taking a single-point reading instead of spatial averaging']::text[],ARRAY['Measuring absorption in a reverberation room','Determining sound power from a diffuse-field level','Spatially averaging microphone positions in a live room']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberant condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14e04a7a-56d1-5565-9f79-618926cc3456','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14e04a7a-56d1-5565-9f79-618926cc3456') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14e04a7a-56d1-5565-9f79-618926cc3456');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2fed5bc5-c56d-579a-9854-556085274b21','Outdoor free-field condition','An outdoor measurement condition approximating a free field, where the site is open enough that the only significant reflection is from the ground and no nearby structures return sound. It is used when a purpose-built chamber is impractical; careful siting, meteorological control, and attention to the ground reflection are needed to keep it a valid approximation to free-field radiation.','An outdoor free-field condition is an open-air setup with almost no reflections. The site is clear of nearby walls and objects. The main reflection left is from the ground. It stands in for a chamber when one is not practical. Weather and the ground must be watched closely.','Offers a practical open-air free field when a chamber is unavailable, provided reflections and weather are controlled.','Technicians measure large sources or loudspeakers outdoors in open spaces, choosing sites free of nearby reflectors and calm weather windows.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Free-field condition','Ground reflection','Meteorological condition','Far-field condition','Anechoic condition']::text[],ARRAY['Ignoring reflections from nearby buildings or vehicles','Overlooking the ground reflection that remains outdoors','Measuring in wind or strong temperature gradients that bend sound']::text[],ARRAY['Testing a large loudspeaker in an open field','Choosing an open site clear of reflecting structures','Waiting for calm weather to approximate a free field outdoors']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Outdoor free-field condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2fed5bc5-c56d-579a-9854-556085274b21','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2fed5bc5-c56d-579a-9854-556085274b21') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2fed5bc5-c56d-579a-9854-556085274b21');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10925504-0639-5415-8f03-66ddc8e45cde','Ground reflection','The reflection of sound from the floor or ground that combines with the direct sound at the microphone, producing constructive and destructive interference that varies with frequency, source and receiver heights, and ground impedance. This interference creates a comb-filter pattern with a characteristic ground-dip cancellation, so it must be controlled or accounted for in both indoor and outdoor measurements.','Ground reflection is sound bouncing off the floor or ground. It reaches the mic just after the direct sound and mixes with it. The mix boosts some frequencies and cancels others. This makes a comb pattern with a clear dip. Heights and ground type set where the dip lands.','Explains the interference floor reflections cause, so measurements can control or correct the resulting comb filtering.','Technicians manage the ground dip by choosing heights, using ground-plane technique, or gating the reflection out in measurements.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Comb filtering','Semi-anechoic condition','Measurement height','Reflecting plane','Free-field condition']::text[],ARRAY['Blaming a response dip on the source when it is a ground reflection','Ignoring how source and mic heights move the ground dip','Assuming a soft ground reflects the same as a hard one']::text[],ARRAY['Explaining a comb-filter dip in an outdoor measurement','Using a ground-plane microphone to fix the reflection','Gating out the floor reflection in a room measurement']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10925504-0639-5415-8f03-66ddc8e45cde','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10925504-0639-5415-8f03-66ddc8e45cde') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10925504-0639-5415-8f03-66ddc8e45cde');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02cc71a3-9c4c-51d9-b6f4-07111a0f7654','Meteorological condition','The state of the atmosphere during outdoor measurement, including wind speed and direction, temperature and its vertical gradient, humidity, and turbulence, all of which affect sound propagation. Wind and temperature gradients refract sound rays upward or downward, changing levels at distance, while humidity governs air absorption; standards restrict acceptable meteorological conditions and require them to be recorded.','Meteorological conditions are the weather during an outdoor measurement. Wind, temperature, and humidity all bend or absorb sound. Wind and temperature layers steer sound up or down. This changes the level far from the source. Standards limit the weather allowed and require it be logged.','Captures the weather factors that steer and absorb outdoor sound, so measurements stay valid and comparable.','Technicians record wind, temperature, and humidity during outdoor surveys and reject data taken in unfavourable conditions.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Wind-induced noise','Atmospheric absorption','Sound propagation','Outdoor free-field condition','Refraction']::text[],ARRAY['Ignoring temperature gradients that refract sound over distance','Measuring in high wind that both bends sound and adds microphone noise','Failing to record the weather with the measurement']::text[],ARRAY['Logging wind and temperature during a community noise survey','Rejecting a long-range reading taken in a strong temperature inversion','Accounting for humidity in high-frequency propagation']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Meteorological condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02cc71a3-9c4c-51d9-b6f4-07111a0f7654','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02cc71a3-9c4c-51d9-b6f4-07111a0f7654') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02cc71a3-9c4c-51d9-b6f4-07111a0f7654');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6f1eb30-a780-51b7-84d0-8ba7f848a28a','Wind-induced noise','Pseudo-noise generated at the microphone by pressure fluctuations from wind and turbulence flowing over the diaphragm, rather than by genuine airborne sound. It is concentrated at low frequencies, can dominate outdoor readings, and is reduced with foam or fur windscreens; because it is not real acoustic signal, it corrupts measured levels and must be minimised or excluded.','Wind-induced noise is fake noise made by wind hitting the microphone. It is not real sound travelling through the air. Moving air pushes on the diaphragm and creates low-frequency rumble. A foam or fur windscreen cuts it down. Left uncontrolled, it spoils outdoor readings.','Identifies wind-driven pseudo-noise so it can be suppressed and kept out of genuine acoustic measurements.','Technicians fit foam or fur windscreens and pick calm periods to keep wind-induced noise from corrupting outdoor levels.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Windscreen correction','Turbulence noise','Meteorological condition','Low-frequency noise','Flow noise']::text[],ARRAY['Reading wind-induced noise as if it were real environmental sound','Leaving the windscreen off in breezy conditions','Assuming the noise is high-frequency when it is mostly low-frequency']::text[],ARRAY['Fitting a fur windscreen for a windy outdoor survey','Discarding data spoiled by gusts hitting the microphone','Recognising low-frequency rumble as wind, not the source']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-induced noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6f1eb30-a780-51b7-84d0-8ba7f848a28a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6f1eb30-a780-51b7-84d0-8ba7f848a28a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6f1eb30-a780-51b7-84d0-8ba7f848a28a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25f8edb3-bdd7-5909-a2b0-da6e06151da3','Turbulence noise','Noise arising from turbulent, chaotic air motion, whether generated at a source such as a jet or exhaust or produced at the microphone by turbulent flow over it. Turbulent eddies create broadband pressure fluctuations; at the microphone these are pseudo-noise concentrated at low frequencies, while as a radiated source they contribute genuine broadband sound, so context determines whether they are signal or artefact.','Turbulence noise comes from chaotic, swirling air. It can be real sound from a jet or exhaust. It can also be fake noise made when swirling air hits the microphone. The eddies create broadband pressure changes. Whether it is signal or error depends on the situation.','Distinguishes turbulence as either a genuine broadband source or a microphone artefact, guiding whether to keep or reject it.','Technicians treat turbulence at the microphone as an artefact to shield against, while measuring turbulence from jets and vents as a real source.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Wind-induced noise','Flow noise','Broadband noise','Windscreen correction','Aerodynamic noise']::text[],ARRAY['Confusing turbulence artefact at the microphone with radiated source noise','Assuming turbulence noise is tonal rather than broadband','Leaving the microphone unshielded in turbulent airflow']::text[],ARRAY['Shielding a microphone from turbulence near an air outlet','Measuring broadband jet turbulence as a genuine source','Separating microphone turbulence artefact from real signal']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulence noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25f8edb3-bdd7-5909-a2b0-da6e06151da3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25f8edb3-bdd7-5909-a2b0-da6e06151da3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25f8edb3-bdd7-5909-a2b0-da6e06151da3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2079ab4-d5ed-5fd2-a131-7fce6237fbe0','Flow noise','Noise produced by fluid flowing over a microphone or nearby structure, in which the moving air or water and its boundary-layer turbulence create pressure fluctuations sensed as pseudo-noise. Common where microphones sit in ducts, airstreams, or moving vehicles, flow noise is largely a near-field, low-frequency artefact rather than radiated sound, and it is mitigated with nose cones, windscreens, and flow-aligned mounting.','Flow noise is noise made when air or water flows over the microphone. The moving fluid and its rough boundary layer push on the diaphragm. It shows up when a mic sits in a duct or airstream. It is mostly a low-frequency artefact, not real sound. Nose cones and windscreens reduce it.','Names the artefact from fluid flowing past a microphone so it can be reduced with aerodynamic mounting and screens.','Technicians fit nose cones and align microphones with the flow when measuring in ducts, airstreams, or moving vehicles.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Wind-induced noise','Turbulence noise','Windscreen correction','Boundary layer','Near-field condition']::text[],ARRAY['Treating flow noise as genuine airborne sound','Mounting a microphone across the flow instead of aligned with it','Assuming a plain windscreen fully removes duct flow noise']::text[],ARRAY['Fitting a nose cone for in-duct microphone measurement','Reducing flow noise on a microphone in a moving vehicle','Aligning a probe with airflow to cut pressure artefacts']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flow noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2079ab4-d5ed-5fd2-a131-7fce6237fbe0','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2079ab4-d5ed-5fd2-a131-7fce6237fbe0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2079ab4-d5ed-5fd2-a131-7fce6237fbe0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ddca023-8a23-56ff-b624-7252d386c747','Calibration condition','The defined set of conditions under which an instrument calibration is performed and remains valid, including the reference signal (such as a 94 dB, 1 kHz acoustic input from a sound calibrator), the coupling, and the environmental parameters of temperature, humidity, and static pressure. Sound calibrators and meters specify these conditions, and corrections are applied when calibrating away from the reference static pressure.','The calibration condition is the exact setup where a check is valid. It fixes the test signal, often a set tone at a set level. It also fixes the room heat, damp, and air pressure. A good check means you match these. When the air pressure differs, you add a small fix.','Pins down the exact reference setup for calibration so instruments read correctly and traceably.','Technicians calibrate a sound level meter with a 94 dB calibrator, noting temperature and pressure and correcting for altitude when needed.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound calibrator','Reference environment','Instrument response','Traceability','Static pressure']::text[],ARRAY['Calibrating without correcting for static pressure at altitude','Ignoring temperature and humidity limits for the calibrator','Assuming a single calibration holds in any environment']::text[],ARRAY['Applying a 94 dB acoustic calibrator to a sound level meter','Correcting a calibration for high-altitude static pressure','Recording ambient conditions at the time of calibration']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ddca023-8a23-56ff-b624-7252d386c747','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ddca023-8a23-56ff-b624-7252d386c747') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ddca023-8a23-56ff-b624-7252d386c747');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da6461c4-ac14-518a-8778-f2eb49194780','Reference environment','A standardised, reproducible acoustic environment specified so that measurements made in different places or times can be compared on a common basis. It defines the field type (free, semi-free, or diffuse), boundary and background-noise limits, and other conditions; free-field and diffuse-field reference environments underpin sensitivity, directivity, and sound-power determinations.','A reference environment is a standard, repeatable place to measure. It fixes the kind of field, such as free or diffuse. It also limits reflections and background noise. Using the same environment lets results be compared fairly. Free-field and diffuse-field references are the common choices.','Defines a common, controlled acoustic setting so measurements from different labs and times can be compared.','Technicians choose a free-field or diffuse-field reference environment matching the standard for sensitivity, directivity, or sound-power work.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Free-field condition','Reverberant condition','Anechoic condition','Reference distance','Calibration condition']::text[],ARRAY['Comparing results taken in different reference environments as if identical','Ignoring the background-noise limit a reference environment sets','Assuming any quiet room qualifies as a reference environment']::text[],ARRAY['Selecting a free-field reference environment for a directivity test','Using a diffuse-field reference for sound-power comparison','Checking a room against reference-environment limits']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference environment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da6461c4-ac14-518a-8778-f2eb49194780','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da6461c4-ac14-518a-8778-f2eb49194780') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da6461c4-ac14-518a-8778-f2eb49194780');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74099c72-ea2e-50b4-9084-b1950b96d4c3','Instrument response','The way a measuring instrument reacts to an input across level, frequency, time, and direction of arrival, comprising its amplitude linearity, frequency weighting and bandwidth, time weighting or integration behaviour, and directional (free-field or random-incidence) characteristic. Standards define tolerance limits on each of these so that instruments of a given class read consistently; departures from the ideal response are the instrument''s contribution to measurement error.','Instrument response is how a meter reacts to sound it receives. It covers level, frequency, timing, and arrival direction all together. A good meter stays linear and follows its weighting curve. It also has a set time behaviour and a known directional pattern. Standards limit how far each may stray.','Describes the full set of instrument behaviours that must stay within tolerance so measurements are trustworthy.','Technicians check that a meter meets its class tolerances for weighting, time response, and directionality before trusting field readings.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Frequency weighting','Time weighting','Incidence angle','Linearity','Calibration condition']::text[],ARRAY['Assuming instrument response only means frequency response','Ignoring the time-weighting behaviour when reading fast transients','Overlooking the directional characteristic a meter class requires']::text[],ARRAY['Verifying a sound level meter meets its class tolerances','Checking time weighting before measuring impulsive noise','Confirming the directional response of a measurement microphone']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instrument response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74099c72-ea2e-50b4-9084-b1950b96d4c3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74099c72-ea2e-50b4-9084-b1950b96d4c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74099c72-ea2e-50b4-9084-b1950b96d4c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c0bb338-9b65-5493-b91d-7acfcd6cf6e2','Quantization step','The smallest amplitude increment a uniform quantiser can resolve, equal to the full-scale input range divided by the number of code levels, which is two raised to the bit depth. Also called the least-significant-bit size, it sets the granularity of quantisation; the difference between the true and quantised value is quantisation error, whose spread and the resulting signal-to-noise ratio both scale with this step.','The quantization step is the smallest amplitude jump a converter can record. It equals the full range divided by the number of code levels. More bits mean more levels and a smaller step. A smaller step captures finer detail. The leftover rounding is quantization error.','Sets the amplitude resolution of a digital system, fixing how finely signals are captured and the size of quantisation error.','Technicians relate bit depth to step size and noise floor when choosing converter resolution and judging low-level detail.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bit depth','Quantization error','Dynamic range','Least significant bit','Dither']::text[],ARRAY['Confusing the quantization step with the sampling interval in time','Assuming more bits change the full-scale range rather than the step size','Ignoring dither, which shapes how quantization error behaves near the step']::text[],ARRAY['Estimating the noise floor from a converter''s bit depth','Choosing bit depth for adequate low-level resolution','Explaining why quiet detail hides below one quantization step']::text[],'intermediate','Δ = V_FS / 2^N','The quantization step equals the full-scale range divided by two raised to the power of the number of bits.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quantization step');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c0bb338-9b65-5493-b91d-7acfcd6cf6e2','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c0bb338-9b65-5493-b91d-7acfcd6cf6e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c0bb338-9b65-5493-b91d-7acfcd6cf6e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '715665c8-e097-502d-8265-fee57b4a6a5a','Frame','A short block of consecutive audio samples treated as a single unit for processing or analysis, typically a few milliseconds to tens of milliseconds long. Framing divides a continuous signal into segments, usually overlapping and windowed, so that short-time analyses such as the short-time Fourier transform, level metering, and coding can assume the signal is approximately stationary within each frame.','A frame is a short block of audio samples handled as one unit. It usually lasts a few to a few tens of milliseconds. Long signals are cut into frames for analysis. The signal is treated as steady inside each frame. Frames often overlap so nothing is missed.','Breaks a continuous signal into short segments so short-time analysis can assume the signal barely changes within each one.','Technicians work with frames in short-time Fourier analysis, loudness metering, and codecs, choosing frame length to balance time and frequency detail.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Windowing','Short-time Fourier transform','Overlap','Bin width','Analysis bandwidth']::text[],ARRAY['Confusing an analysis frame with a single audio sample','Choosing a frame so long that transient timing is smeared','Forgetting that overlapping frames share samples']::text[],ARRAY['Setting a frame length for a spectrogram','Selecting frame size for a loudness meter','Balancing time and frequency detail through frame length']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '715665c8-e097-502d-8265-fee57b4a6a5a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='715665c8-e097-502d-8265-fee57b4a6a5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='715665c8-e097-502d-8265-fee57b4a6a5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4744a1fc-8774-5cb7-b542-a178ac864efd','Bin width','The frequency spacing between adjacent points (bins) of a discrete Fourier transform, equal to the sampling rate divided by the transform length in samples. It sets the frequency resolution of the analysis: a longer transform gives a smaller bin width and finer resolution but needs a longer time record, embodying the time-frequency trade-off inherent in block-based spectral analysis.','Bin width is the frequency gap between neighbouring points in an FFT. It equals the sample rate divided by the block length. A longer block gives a smaller gap and finer detail. But a longer block needs more time. So finer frequency detail costs time resolution.','Sets how finely a transform resolves frequency, capturing the trade-off between frequency detail and time record length.','Technicians pick transform length to get the bin width needed to separate close tones in spectrum analysis.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fast Fourier transform','Frame','Frequency resolution','Analysis bandwidth','Windowing']::text[],ARRAY['Confusing bin width with the width of a filter''s passband','Expecting finer frequency detail without a longer time record','Assuming zero-padding adds true resolution rather than interpolation']::text[],ARRAY['Choosing an FFT length to resolve two close tones','Setting bin width for a spectrum analyser display','Trading time detail for finer frequency spacing']::text[],'intermediate','Δf = f_s / N','The bin width equals the sampling rate divided by the number of samples in the transform.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bin width');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4744a1fc-8774-5cb7-b542-a178ac864efd','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4744a1fc-8774-5cb7-b542-a178ac864efd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4744a1fc-8774-5cb7-b542-a178ac864efd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba396f50-ba7f-5582-91ad-d4093d3ec01d','RMS averaging','Averaging that combines samples on a squared (energy) basis by taking the square root of the mean of the squared values, yielding the root-mean-square level that reflects effective signal power. Unlike simple linear averaging, RMS averaging is insensitive to instantaneous polarity and represents the power delivered, which is why sound and signal levels, and their exponential time weightings, are based on it.','RMS averaging combines a signal by its power, not its raw value. It squares each sample, averages, then takes the square root. This ignores whether the wave is up or down at that moment. The result tracks the effective power delivered. Sound levels are built on this kind of average.','Produces a level that reflects effective power, the basis for sound-level metering and signal amplitude measurement.','Technicians rely on RMS averaging in level meters and analysers to report the power-based level of steady and varying signals.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Root mean square','Time weighting','Equivalent continuous sound level','Crest factor','Power']::text[],ARRAY['Confusing an RMS average with a simple linear average of samples','Assuming RMS equals peak level, ignoring crest factor','Using too short a window to average a low-frequency signal']::text[],ARRAY['Reading an RMS level on a metering bridge','Computing an equivalent level from squared samples','Comparing RMS and peak to find crest factor']::text[],'intermediate','x_RMS = sqrt( (1/N)·Σ x_i^2 )','The root-mean-square value equals the square root of the average of the squared sample values.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RMS averaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba396f50-ba7f-5582-91ad-d4093d3ec01d','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba396f50-ba7f-5582-91ad-d4093d3ec01d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba396f50-ba7f-5582-91ad-d4093d3ec01d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96cccd56-5a64-5040-90de-446864e93ba0','Analysis bandwidth','The span of frequencies included in a given analysis, from its lower to upper limit, together with the resolution used within it. It may be constant-bandwidth, as in an FFT with uniform bin spacing, or proportional, as in fractional-octave analysis where bands widen with frequency; the chosen analysis bandwidth, bounded above by the Nyquist frequency, determines what content is captured and how it is resolved.','Analysis bandwidth is the range of frequencies an analysis looks at. It runs from a low limit to a high limit. Some analyses use equal-width bands, like an FFT. Others use bands that widen with frequency, like octave bands. The top limit cannot exceed the Nyquist frequency.','Defines which frequency range and resolution an analysis covers, shaping what content is captured and how it is grouped.','Technicians set the analysis bandwidth and band type, constant or fractional-octave, to match the measurement and stay below Nyquist.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bin width','Fractional-octave analysis','Nyquist frequency','Frequency resolution','Frame']::text[],ARRAY['Confusing constant-bandwidth with fractional-octave analysis','Setting an upper limit above the Nyquist frequency','Assuming wider bandwidth always improves frequency detail']::text[],ARRAY['Choosing octave versus one-third-octave analysis bands','Setting the frequency span of a spectrum measurement','Keeping the analysis range below the Nyquist frequency']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Analysis bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96cccd56-5a64-5040-90de-446864e93ba0','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96cccd56-5a64-5040-90de-446864e93ba0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96cccd56-5a64-5040-90de-446864e93ba0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14119adf-b662-51dd-8076-e858a1ff1879','Near-field acoustical holography','An acoustic imaging technique that measures the sound field on a surface placed very close to a source, within a fraction of a wavelength, and then reconstructs the full three-dimensional field from that data by inverting the wave equation. Because the measurement surface lies in the near field, it captures both the propagating and the rapidly decaying evanescent components; retaining the evanescent terms is what lets the method resolve source detail finer than the acoustic wavelength. The measured pressure (or particle velocity) is transformed into the spatial-wavenumber domain, propagated toward the source with the appropriate wavenumber propagator, and inverted to yield surface velocity, pressure, and intensity maps.','This method maps sound right next to its source. The probes sit less than a wavelength away. That close, it also catches sound that fades very fast. Using that faint sound, it rebuilds the whole field. It can show detail finer than the sound''s wavelength. Engineers use it to find where noise comes from.','Turns a set of near-field pressure measurements into detailed maps of surface vibration, radiated pressure, and intensity, so a source''s radiation can be studied without a full anechoic far-field survey.','Used to locate and rank noise sources on machines, engines, tyres, panels, and loudspeakers, mapping which surface regions radiate most at each frequency for noise-control redesign.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Hologram plane','Sound-field reconstruction','Evanescent wave','Spatial Fourier transform','Inverse acoustic problem','Planar NAH']::text[],ARRAY['Measuring too far from the source so evanescent detail is lost and resolution collapses','Spacing microphones too coarsely, which spatially aliases the wavenumber spectrum','Forgetting that inversion amplifies noise and must be regularized']::text[],ARRAY['Mapping the radiating regions of a vibrating engine cover','Ranking noise hot spots on a washing-machine panel','Diagnosing where a loudspeaker cabinet leaks sound']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field acoustical holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14119adf-b662-51dd-8076-e858a1ff1879','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14119adf-b662-51dd-8076-e858a1ff1879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14119adf-b662-51dd-8076-e858a1ff1879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8a925a0-26c2-56ac-85bb-4bb6680ec02c','Hologram plane','In near-field acoustical holography, the surface on which the acoustic field is actually sampled by the microphone or probe array, held parallel and close to the source in planar NAH. The complex pressure (and sometimes particle velocity) measured over this plane forms the acoustic hologram, the input data from which the field elsewhere is reconstructed. Its size sets the spatial aperture, its point spacing sets the highest resolvable wavenumber, and its standoff distance from the source governs how much evanescent information survives to be captured.','This is the surface where the sound is actually measured. The microphones sit on this plane. It stays close to the source and parallel to it. The recorded sound here is called the hologram. All later results are rebuilt from this data.','Defines where and how densely the field is sampled, setting the aperture, spatial resolution, and the amount of near-field detail available to the reconstruction.','Technicians choose its spacing and size when laying out a microphone grid or scan pattern for a measurement, balancing resolution against aperture and time.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Reconstruction plane','Source plane','Holographic surface','Near-field acoustical holography','Aperture']::text[],ARRAY['Confusing the hologram plane, where data is measured, with the source plane being imaged','Making the plane too small, so the aperture truncates the field and blurs the result','Placing it too far from the source and losing evanescent content']::text[],ARRAY['Laying out a scanning microphone grid in front of a panel','Choosing standoff distance before a near-field scan','Explaining why grid spacing limits resolution']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hologram plane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8a925a0-26c2-56ac-85bb-4bb6680ec02c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8a925a0-26c2-56ac-85bb-4bb6680ec02c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8a925a0-26c2-56ac-85bb-4bb6680ec02c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b1aedd9-3faa-5a11-982b-5840de6c40ad','Reconstruction plane','Any surface, parallel to the hologram plane in planar NAH, on which the acoustic quantities are computed from the measured hologram data. By choosing the reconstruction plane closer to or farther from the source than the measurement plane, the field can be back-propagated toward the source or forward-propagated outward. Back-propagation toward the source amplifies evanescent components and is the ill-posed step that requires regularization; forward-propagation away from the source attenuates them and is stable.','This is any surface where the sound field is worked out. It is not where you measured. You pick it closer to or farther from the source. Moving toward the source shows fine detail but is unstable. Moving away from the source is safe and smooth.','Lets the same measured data be evaluated at many depths, so the field can be traced back to the source or projected outward as needed.','An analyst steps the reconstruction plane onto the source surface to read vibration, or outward to predict radiated pressure at a target location.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Hologram plane','Source plane','Forward propagation','Back-propagation','Sound-field reconstruction']::text[],ARRAY['Back-propagating past the source, which blows up amplified evanescent noise','Assuming reconstruction accuracy is uniform at every depth','Confusing the reconstruction plane with the physical source plane']::text[],ARRAY['Stepping the field back onto a vibrating surface','Projecting near-field data to a far target plane','Comparing pressure maps at several depths']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reconstruction plane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b1aedd9-3faa-5a11-982b-5840de6c40ad','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b1aedd9-3faa-5a11-982b-5840de6c40ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b1aedd9-3faa-5a11-982b-5840de6c40ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b790c9a2-b421-56d6-96d0-9d6a3928c289','Source plane','The surface, coincident with or just enclosing the physical radiator, on which the reconstructed quantities represent the true source behaviour, such as surface normal velocity and pressure. It is the ultimate target of the back-propagation in NAH: reconstructing the field onto the source plane yields the vibration pattern that produced the measured sound. Because it lies at the maximum back-propagation distance from the hologram, it is where evanescent amplification and therefore noise sensitivity are greatest.','This is the surface of the real source. Think of the vibrating face of a machine or speaker. NAH aims to rebuild the sound right here. That shows how the surface moves. It is also the hardest plane to get right.','Represents the physical radiator whose surface velocity and pressure the reconstruction seeks to recover, linking the measured sound to its mechanical cause.','Engineers read the reconstructed source-plane velocity to see exactly which parts of a structure vibrate and radiate, guiding damping or stiffening.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Reconstruction plane','Hologram plane','Surface velocity reconstruction','Radiated sound field','Near-field acoustical holography']::text[],ARRAY['Treating the source plane as the measurement plane','Ignoring that noise sensitivity peaks at the source plane','Assuming a flat source plane fits a curved radiator well']::text[],ARRAY['Reading surface velocity across a vibrating panel','Locating the exact vibrating region of a motor housing','Guiding where to add damping material']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source plane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b790c9a2-b421-56d6-96d0-9d6a3928c289','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b790c9a2-b421-56d6-96d0-9d6a3928c289') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b790c9a2-b421-56d6-96d0-9d6a3928c289');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fbb9ae7a-9d5e-56e5-a19b-7af98e6f6db4','Holographic surface','The measurement surface over which sound pressure, or pressure together with particle velocity, is sampled in acoustic holography before transformation and reconstruction of the three-dimensional field. In planar NAH it is flat, but the term also covers cylindrical, spherical, and conformal geometries that wrap around a source. Its shape, extent, and sampling density determine which reconstruction basis (plane, cylindrical, or spherical waves) applies and set the spatial bandwidth of the captured hologram.','This is the surface where sound is captured for holography. It can be flat, curved, or shaped to the source. The probes measure pressure, and sometimes velocity, on it. Its shape decides the math used to rebuild the field. Its spacing sets the finest detail you can see.','Provides the sampled data set and, through its geometry, fixes which wave basis and resolution the reconstruction can use.','A technician picks a flat, cylindrical, or body-hugging measurement surface to suit the object under test, then scans or arrays microphones over it.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Hologram plane','Conformal NAH','Planar NAH','Near-field acoustical holography']::text[],ARRAY['Choosing a flat surface for a strongly curved source','Under-sampling the surface and aliasing the hologram','Confusing the capture surface with the reconstruction target']::text[],ARRAY['Wrapping a cylindrical array around a motor','Choosing a conformal surface for an irregular part','Setting probe spacing for a flat scan']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fbb9ae7a-9d5e-56e5-a19b-7af98e6f6db4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fbb9ae7a-9d5e-56e5-a19b-7af98e6f6db4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fbb9ae7a-9d5e-56e5-a19b-7af98e6f6db4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac45601e-a440-5f79-b580-ba575a2d100d','Sound-field reconstruction','The computational recovery of acoustic quantities, pressure, particle velocity, intensity, or radiation pattern, at points other than those measured, obtained by fitting a physical wave model to a finite set of measurements and evaluating it elsewhere. It underlies NAH, equivalent-source methods, and boundary-integral approaches. Because recovering fine spatial detail requires inverting an operator that suppresses high-wavenumber and evanescent content, reconstruction is an inverse problem that is generally ill-posed and needs regularization to stay stable against measurement noise.','This means working out the sound where you did not measure. You fit a wave model to your data. Then you use it to find sound at new points. It can give pressure, velocity, or intensity. Fine detail is hard, so the math needs care to stay stable.','Extends a limited set of acoustic measurements into full spatial maps of the field, enabling source study, prediction, and visualization beyond the sampled points.','Sits at the core of NAH, beamforming post-processing, and equivalent-source tools that turn microphone-array data into pressure and intensity images.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-source reconstruction','Inverse acoustic problem','Near-field acoustical holography','Equivalent source distribution','Regularization']::text[],ARRAY['Expecting exact recovery from noisy, finite data','Skipping regularization and getting noise-dominated results','Confusing reconstructing the field with reconstructing the source']::text[],ARRAY['Turning array data into a pressure map','Predicting the field between measured points','Building an intensity image of a radiating panel']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac45601e-a440-5f79-b580-ba575a2d100d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac45601e-a440-5f79-b580-ba575a2d100d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac45601e-a440-5f79-b580-ba575a2d100d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bc30c8c-8f6b-59a7-b9cf-2bcb15ad4ee2','Sound-source reconstruction','The inverse process of estimating the strength and spatial distribution of the acoustic sources, such as surface velocity, monopole amplitudes, or an equivalent source layer, that produced a measured field. Unlike field reconstruction, which recovers acoustic quantities in space, source reconstruction recovers the radiator itself, so it depends on a source model (surface, equivalent sources, or radiation modes) and is typically more ill-posed, requiring stronger regularization and good near-field sampling.','This means finding the source that made the sound. You do not just map the field. You estimate what was vibrating or driving it. This needs a model of the source. It is harder and needs careful, stable math.','Identifies and quantifies the actual radiators behind a measured field, so noise can be traced to specific parts rather than just observed in space.','Used in noise-source identification to attribute measured sound to particular panels, joints, or components on a product.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-field reconstruction','Inverse acoustic problem','Equivalent source distribution','Surface velocity reconstruction','Source contribution map']::text[],ARRAY['Assuming a wrong source model still gives a correct source map','Under-regularizing and getting unphysical hot spots','Confusing where sound is with what makes it']::text[],ARRAY['Attributing cabin noise to specific body panels','Estimating surface velocity of a vibrating cover','Ranking component sources on a running engine']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-source reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bc30c8c-8f6b-59a7-b9cf-2bcb15ad4ee2','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bc30c8c-8f6b-59a7-b9cf-2bcb15ad4ee2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bc30c8c-8f6b-59a7-b9cf-2bcb15ad4ee2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f66670f6-4d8d-5240-a235-4cb71f8f7236','Radiated sound field','The acoustic field established in the surrounding medium by a vibrating body or driven source, comprising the pressure and particle-velocity distribution that carries energy away as sound. It divides into a near field, where reactive, evanescent, and geometric effects dominate close to the source, and a far field, where pressure decays inversely with distance and behaves locally like a propagating plane wave. Characterizing the radiated field, its directivity, radiated power, and intensity, is the end goal of most reconstruction methods.','This is the sound a vibrating object sends into the air. Close to the source it is complex and reactive. Far away it spreads out and weakens with distance. Its shape and strength describe how the object radiates. Reconstruction methods aim to map this field.','Describes how a source couples vibration into airborne sound, providing the directivity, power, and intensity that quantify its acoustic output.','Engineers characterize a product''s radiated field to check noise limits, directivity, and which operating conditions radiate most.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Near field','Far field','Sound power','Directivity']::text[],ARRAY['Assuming near-field readings equal far-field behaviour','Treating radiated pressure as constant with distance','Ignoring reactive near-field energy that does not radiate']::text[],ARRAY['Measuring a product''s radiated noise for compliance','Mapping directivity of a loudspeaker','Comparing radiated output across operating speeds']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiated sound field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f66670f6-4d8d-5240-a235-4cb71f8f7236','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f66670f6-4d8d-5240-a235-4cb71f8f7236') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f66670f6-4d8d-5240-a235-4cb71f8f7236');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69cef33d-9e56-5c1e-8be4-c8c2d2b07b3c','Forward propagation','In NAH, the stable direction of the reconstruction that computes the field on a plane farther from the source than the measurement plane, moving away from the radiator. In the wavenumber domain each spatial component is multiplied by the propagator exp(i k_z Δz), so propagating components are simply phase-shifted while evanescent components are further attenuated. Because it multiplies by a factor of magnitude ≤ 1, forward propagation is well-posed and noise-stable, in contrast to the ill-posed back-propagation toward the source.','This traces the sound field outward, away from the source. It uses your near data to predict sound farther away. In this direction the math is stable. Fading parts of the field just fade more. So this step is safe and reliable.','Projects measured near-field data outward to predict pressure and intensity at farther planes without amplifying noise.','Used to estimate radiated sound at a listener or target plane from near-field measurements taken close to a machine.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Back-propagation','Reconstruction plane','Wavenumber-domain NAH','Evanescent wave','Far-field prediction from near-field data']::text[],ARRAY['Confusing stable forward propagation with unstable back-propagation','Expecting new source detail to appear when projecting outward','Ignoring that far results still depend on aperture size']::text[],ARRAY['Predicting sound at a target plane from near data','Estimating far output of a machine','Checking near-to-far consistency of a source']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forward propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69cef33d-9e56-5c1e-8be4-c8c2d2b07b3c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69cef33d-9e56-5c1e-8be4-c8c2d2b07b3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69cef33d-9e56-5c1e-8be4-c8c2d2b07b3c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a1b71ac-87af-5aa9-8d90-c12f12c8c182','Inverse acoustic problem','The class of problems in which the acoustic sources or a field nearer the source are estimated from remote or partial measurements, inverting the forward radiation operator that maps sources to field. Because that operator smooths and attenuates high-wavenumber and evanescent detail, its inverse amplifies exactly those components, making the problem ill-posed: solutions are highly sensitive to noise and non-unique without added constraints. Practical solution therefore combines a physical model with regularization such as Tikhonov or truncated SVD.','This means going backward from sound to its cause. Normally a source makes a field. Here you have the field and want the source. Small errors can grow into big ones. So the math must be stabilized to work.','Provides the mathematical framework for recovering sources or near-source fields from measurements, at the cost of instability that must be controlled.','Underlies NAH, equivalent-source reconstruction, and source identification, all of which invert a radiation model against measured data.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Ill-posed problem','Sound-source reconstruction','Tikhonov regularization','Truncated singular value decomposition','Regularization']::text[],ARRAY['Assuming an inverse solution is unique without constraints','Ignoring noise amplification in the inversion','Skipping regularization and trusting raw inverse results']::text[],ARRAY['Recovering surface velocity from remote pressure','Estimating source strengths from array data','Explaining why source maps need regularization']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inverse acoustic problem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a1b71ac-87af-5aa9-8d90-c12f12c8c182','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a1b71ac-87af-5aa9-8d90-c12f12c8c182') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a1b71ac-87af-5aa9-8d90-c12f12c8c182');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '61b0d112-0f3a-5c1e-a075-059d3e372fd2','Ill-posed problem','A problem that violates one of Hadamard''s conditions for well-posedness, so that a solution may not exist, may not be unique, or does not depend continuously on the data. In acoustic reconstruction the last condition fails: because inversion amplifies high-wavenumber and evanescent components, tiny measurement errors produce large, unphysical swings in the estimated source. Ill-posedness is quantified by a large condition number of the discretized operator and is controlled by regularization, which trades a little bias for a large reduction in noise amplification.','An ill-posed problem is very touchy to errors. A tiny change in the data can cause a huge change in the answer. Acoustic back-tracing is like this. Small mic noise can wreck the result. So the math needs steadying to be usable.','Names why acoustic inversion is unstable and motivates the regularization used to keep reconstructions physical and repeatable.','Explains to technicians why raw NAH source maps look noisy and why a regularization setting must be chosen.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Inverse acoustic problem','Regularization','Tikhonov regularization','Truncated singular value decomposition','Condition number']::text[],ARRAY['Believing more data alone removes instability','Treating a noisy inverse result as physical detail','Choosing regularization arbitrarily without checking the trade-off']::text[],ARRAY['Diagnosing noise-blown source maps','Selecting a regularization parameter','Explaining instability to a client']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ill-posed problem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '61b0d112-0f3a-5c1e-a075-059d3e372fd2','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='61b0d112-0f3a-5c1e-a075-059d3e372fd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='61b0d112-0f3a-5c1e-a075-059d3e372fd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10f37b04-61b1-5c6c-b8f7-00e8ce2395c1','Tikhonov regularization','A regularization method that stabilizes an ill-posed inverse problem by minimizing the data misfit plus a penalty on the solution norm, weighted by a regularization parameter. The penalty damps the small singular values that otherwise amplify noise, yielding a filtered solution that trades a small bias for greatly reduced variance. The parameter is commonly chosen by the L-curve criterion or generalized cross-validation, balancing residual error against solution energy.','This is a way to steady an unstable inverse problem. It adds a penalty on wild, large answers. That holds noise down. You tune one number to set the balance. Too little leaves noise; too much blurs the result.','Suppresses noise amplification in acoustic inversion by penalizing large solutions, making source and field estimates stable and physical.','Applied in NAH and equivalent-source software, where the user sets or auto-selects the regularization parameter for clean source maps.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Regularization','Ill-posed problem','Truncated singular value decomposition','L-curve','Inverse acoustic problem']::text[],ARRAY['Setting the parameter too high and over-smoothing real detail','Setting it too low and leaving noise in the map','Assuming one parameter fits every frequency']::text[],ARRAY['Tuning regularization on a noisy source map','Using an L-curve to pick the parameter','Stabilizing an equivalent-source inversion']::text[],'advanced','x̂ = argmin_x ( ||A x − b||² + λ² ||x||² ) = (Aᴴ A + λ² I)⁻¹ Aᴴ b','The estimate minimizes the squared data mismatch plus lambda-squared times the squared solution size; equivalently, it solves the normal equations with lambda-squared added along the diagonal.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tikhonov regularization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10f37b04-61b1-5c6c-b8f7-00e8ce2395c1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10f37b04-61b1-5c6c-b8f7-00e8ce2395c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10f37b04-61b1-5c6c-b8f7-00e8ce2395c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a5e2fb1-7146-5ba0-8a7a-a5c7cefbd029','Truncated singular value decomposition','A regularization strategy that solves an ill-posed inverse problem by expanding the solution in the singular vectors of the system operator and discarding the terms associated with the smallest singular values. Since noise is amplified by division by these small values, truncating the expansion at a chosen rank removes the most unstable components while keeping the well-determined ones. The truncation rank plays the role of the regularization parameter, trading resolution for stability.','This method splits the problem into stable and unstable parts. The unstable parts come from very small numbers. Dividing by them blows up noise. So you just drop those parts. You keep the steady parts and get a cleaner answer.','Stabilizes acoustic inversion by cutting off the noise-dominated singular components, providing a simple rank-based regularization.','Used in reconstruction codes where the number of retained singular values is set to control noise versus spatial resolution.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Tikhonov regularization','Regularization','Ill-posed problem','Singular value decomposition','Inverse acoustic problem']::text[],ARRAY['Keeping too many singular values and readmitting noise','Truncating too hard and losing real resolution','Assuming the same rank works at every frequency']::text[],ARRAY['Choosing a truncation rank for a source map','Comparing TSVD with Tikhonov results','Stabilizing a rank-deficient reconstruction']::text[],'advanced','x̂_k = Σ_{i=1}^{k} (uᵢᴴ b / σᵢ) vᵢ,  σ₁ ≥ σ₂ ≥ … ≥ σ_r','The estimate keeps only the k largest singular values: for each, project the data onto its left singular vector, divide by that singular value, and scale the matching right singular vector; smaller singular values are discarded.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Truncated singular value decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a5e2fb1-7146-5ba0-8a7a-a5c7cefbd029','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a5e2fb1-7146-5ba0-8a7a-a5c7cefbd029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a5e2fb1-7146-5ba0-8a7a-a5c7cefbd029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aecec02b-b864-5bca-8a67-a3022ac77c98','Wavenumber-domain NAH','The classical formulation of planar near-field acoustical holography that operates in the two-dimensional spatial-frequency (wavenumber) domain. The measured pressure on the hologram plane is spatially Fourier-transformed into an angular spectrum, each component is propagated to the reconstruction plane by multiplying by the wavenumber propagator, and the result is inverse-transformed back to space. Propagating components (k_x²+k_y² ≤ k²) carry a real axial wavenumber and only phase-shift, whereas evanescent components decay exponentially, so back-propagation must divide by these decaying factors and requires k-space filtering to remain stable.','This version of NAH works in spatial-frequency space. It turns the sound map into wave patterns of different fineness. Each pattern is moved to a new plane by a simple factor. Fast-fading patterns need careful handling. Then it converts back to a normal sound map.','Provides an efficient FFT-based route from measured near-field pressure to reconstructed fields by treating propagation as a multiplication in wavenumber space.','Implemented in planar NAH software where the microphone-grid pressure is FFT''d, propagated with the propagator, filtered, and inverse-transformed.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Spatial Fourier transform','Wavenumber spectrum','Propagating wave component','Evanescent wave','Planar NAH']::text[],ARRAY['Ignoring wavenumber aliasing from too-coarse grids','Applying no k-space filter and amplifying evanescent noise','Assuming a finite aperture causes no edge (leakage) errors']::text[],ARRAY['Running an FFT-based planar reconstruction','Applying a k-space low-pass filter to a source map','Diagnosing aliasing in a wavenumber spectrum']::text[],'advanced','P(k_x,k_y,z) = P(k_x,k_y,z₀) · e^{i k_z (z−z₀)},  k_z = √(k² − k_x² − k_y²),  k = ω/c','Each wavenumber component of the pressure at a new plane equals its value on the measurement plane times a propagator with axial wavenumber k_z, the square root of the acoustic wavenumber squared minus the in-plane wavenumbers squared; k_z is real for propagating components and imaginary (giving exponential decay) for evanescent ones.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavenumber-domain NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aecec02b-b864-5bca-8a67-a3022ac77c98','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aecec02b-b864-5bca-8a67-a3022ac77c98') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aecec02b-b864-5bca-8a67-a3022ac77c98');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c065b088-dd45-5b60-a444-a23b62bef4eb','Spatial Fourier transform','A Fourier transform taken over spatial coordinates rather than time, decomposing a field sampled over a surface into components indexed by spatial frequency (wavenumber). In planar NAH the two-dimensional spatial Fourier transform maps the pressure p(x,y) into the angular spectrum P(k_x,k_y), converting the convolution of radiation into a simple multiplication by the propagator. In practice it is computed as a 2-D FFT over the microphone grid, so grid spacing sets the maximum wavenumber and aperture sets the wavenumber resolution.','This transform sorts a sound map by spatial detail. Broad, smooth patterns and fine, tight patterns are separated. Each becomes a wavenumber component. In NAH this makes the math simple. It is computed with an FFT over the mic grid.','Converts spatial pressure patterns into wavenumber components so that radiation and propagation become simple multiplications in the transform domain.','Runs as the 2-D FFT step in planar NAH, and its grid and aperture limits directly set resolution and the aliasing threshold.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Wavenumber spectrum','Wavenumber-domain NAH','Angular spectrum','Spatial Nyquist','Fast Fourier transform']::text[],ARRAY['Confusing spatial frequency (per metre) with temporal frequency (per second)','Ignoring spatial aliasing when grid spacing is too large','Forgetting finite-aperture leakage in the transform']::text[],ARRAY['Transforming a mic-grid pressure map to k-space','Reading the wavenumber content of a field','Checking grid spacing against the spatial Nyquist limit']::text[],'advanced','P(k_x,k_y) = ∬ p(x,y) e^{−i(k_x x + k_y y)} dx dy','The wavenumber spectrum is the double integral over the plane of the pressure times a complex exponential in the two spatial coordinates and their matching wavenumbers.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial Fourier transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c065b088-dd45-5b60-a444-a23b62bef4eb','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c065b088-dd45-5b60-a444-a23b62bef4eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c065b088-dd45-5b60-a444-a23b62bef4eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8a2ff2b-276e-5bdc-aba9-ee8c769304c0','Wavenumber spectrum','The representation of an acoustic field as a function of spatial frequency, obtained by spatially Fourier-transforming the field over a surface; also called the angular spectrum. Each point in the spectrum gives the amplitude and phase of a plane-wave (propagating) or evanescent component travelling in a specific direction with in-plane wavenumbers k_x, k_y. Components inside the radiation circle k_x²+k_y² ≤ k² propagate to the far field, while those outside it are evanescent and confined to the near field.','This shows a sound field broken into wave patterns by fineness. Each entry is one plane-wave direction. Broad patterns travel far as real sound. Fine patterns stay near the source and fade. The split happens at a circle set by frequency.','Reveals which spatial components of a field radiate and which stay evanescent, and is the domain in which NAH propagation and filtering are performed.','Analysts inspect the wavenumber spectrum to see radiating versus evanescent content and to set k-space filters during reconstruction.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Spatial Fourier transform','Angular spectrum','Propagating wave component','Evanescent wave','Wavenumber-domain NAH']::text[],ARRAY['Assuming all wavenumber content radiates to the far field','Overlooking that fine detail lives in evanescent, high-wavenumber components','Confusing the radiation circle radius (k) with a fixed number']::text[],ARRAY['Separating radiating from evanescent components','Designing a k-space filter for reconstruction','Explaining why fine detail decays quickly']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavenumber spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8a2ff2b-276e-5bdc-aba9-ee8c769304c0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8a2ff2b-276e-5bdc-aba9-ee8c769304c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8a2ff2b-276e-5bdc-aba9-ee8c769304c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd609748d-8773-5f64-8534-d581809be332','Propagating wave component','A spatial-frequency component of a sound field whose in-plane wavenumber satisfies k_x²+k_y² ≤ k², giving a real axial wavenumber k_z so the component travels as a plane wave and carries energy to the far field without spatial decay. These components lie inside the radiation circle of the wavenumber spectrum and set the sound power radiated by the source. They contrast with evanescent components (k_x²+k_y² > k²), which have imaginary k_z, decay exponentially with distance, and do not radiate.','This is a field pattern that actually travels outward. Its spatial detail is coarse enough to become a plane wave. It carries energy to the far field. It does not fade with distance like near-field parts. These parts set how much sound escapes.','Identifies the field components that radiate real acoustic power, separating them from evanescent parts that stay trapped near the source.','Used to compute radiated sound power and to decide which wavenumber band a reconstruction should keep as physically radiating.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Evanescent wave','Wavenumber spectrum','Radiation circle','Supersonic acoustic intensity','Wavenumber-domain NAH']::text[],ARRAY['Assuming every measured component propagates','Confusing the radiation-circle boundary with the sampling limit','Ignoring that only propagating parts carry far-field power']::text[],ARRAY['Computing radiated power from the spectrum','Separating radiating from evanescent content','Setting a radiating-band filter in reconstruction']::text[],'advanced','k_x² + k_y² ≤ k² = (ω/c)²  ⇒  k_z = √(k² − k_x² − k_y²) real (propagating)','A component propagates when the sum of its squared in-plane wavenumbers is at most the acoustic wavenumber squared, so its axial wavenumber is real; beyond that limit the axial wavenumber is imaginary and the component is evanescent.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Propagating wave component');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd609748d-8773-5f64-8534-d581809be332','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d609748d-8773-5f64-8534-d581809be332') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d609748d-8773-5f64-8534-d581809be332');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1347b459-e323-5e25-befe-67833842ec5d','Supersonic acoustic intensity','A quantity, introduced by Williams, formed by filtering the reconstructed field to retain only components whose trace wavenumber lies inside the radiation circle (k_x²+k_y² ≤ k²) before computing intensity, so that it maps only the part of the surface intensity that actually radiates to the far field. By removing the subsonic, non-radiating (evanescent) contributions that clutter the ordinary near-field intensity, it localizes the true radiating regions of a source. It is computed by wavenumber low-pass filtering of pressure and velocity, then forming the active intensity.','This shows only the sound that truly radiates away. It filters out near-field parts that do not escape. Ordinary intensity mixes both and can mislead. This version keeps just the far-reaching part. It points to the real radiating spots on a source.','Isolates the radiating portion of surface intensity so that far-field noise can be traced to the specific source regions responsible for it.','Used in noise-source ranking to distinguish patches that merely vibrate from patches that actually radiate sound outward.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Subsonic acoustic intensity','Complex acoustic intensity','Propagating wave component','Radiation circle','Sound-intensity reconstruction']::text[],ARRAY['Equating strong near-field intensity with strong radiation','Skipping the wavenumber filter and mislocating radiators','Confusing supersonic (radiating) with subsonic (non-radiating) intensity']::text[],ARRAY['Finding the truly radiating patches on a panel','Separating radiating from reactive near-field energy','Ranking real noise sources on a machine']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Supersonic acoustic intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1347b459-e323-5e25-befe-67833842ec5d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1347b459-e323-5e25-befe-67833842ec5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1347b459-e323-5e25-befe-67833842ec5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cf3b91c-dfe0-5566-8209-44d92f67674f','Subsonic acoustic intensity','The complement of supersonic intensity: the intensity contribution from field components whose trace wavenumber lies outside the radiation circle (k_x²+k_y² > k²), i.e. the evanescent, subsonic components that decay with distance and do not radiate to the far field. It represents reactive, near-field energy circulating close to the source rather than net radiated power. Separating it out clarifies why near-field intensity maps can show strong local activity that contributes little to far-field sound.','This is near-field energy that does not radiate. Its wave patterns are too fine to travel. They fade fast with distance. This energy sloshes near the source. It can look strong yet send little sound outward.','Labels the non-radiating, reactive part of near-field intensity, so it can be excluded when tracing far-field noise to its true sources.','Understood when interpreting near-field intensity maps, to avoid mistaking strong reactive activity for real radiation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Supersonic acoustic intensity','Complex acoustic intensity','Evanescent wave','Reactive intensity','Wavenumber spectrum']::text[],ARRAY['Reading subsonic intensity as radiated sound','Ignoring the split between radiating and non-radiating energy','Assuming near-field strength predicts far-field level']::text[],ARRAY['Explaining strong near-field but weak far-field readings','Interpreting reactive zones on an intensity map','Filtering out non-radiating energy in analysis']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subsonic acoustic intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cf3b91c-dfe0-5566-8209-44d92f67674f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cf3b91c-dfe0-5566-8209-44d92f67674f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cf3b91c-dfe0-5566-8209-44d92f67674f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd698075d-1b6e-5296-b758-70281a6553bb','Complex acoustic intensity','A frequency-domain description of sound intensity in which the product of complex pressure and the conjugate of complex particle velocity is retained as a complex quantity: its real part is the active (time-averaged, net-energy-transporting) intensity, and its imaginary part is the reactive intensity associated with locally oscillating, non-propagating energy. The complex intensity thus characterizes both the flow of radiated energy and the reactive near-field storage, and is central to distinguishing radiating from non-radiating regions of a source.','This describes intensity as two parts at once. The real part is energy that truly flows away. The imaginary part is energy that just rocks back and forth. Together they show both real sound and near-field storage. It helps tell radiating spots from quiet ones.','Separates the net radiated energy flow (active) from the oscillating near-field storage (reactive), giving a fuller picture of how a source behaves.','Used in intensity-based diagnostics to map active energy flow and to flag reactive near-field zones around a source.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Active intensity','Reactive intensity','Sound-intensity reconstruction','Particle velocity','Supersonic acoustic intensity']::text[],ARRAY['Reporting only the active part and ignoring reactive energy','Confusing reactive intensity with measurement error','Assuming reactive energy transports net power']::text[],ARRAY['Mapping active energy flow from a source','Identifying reactive near-field regions','Interpreting intensity phase near a radiator']::text[],'advanced','I = ½ P U* ;  active I_a = ½ Re{P U*},  reactive I_r = ½ Im{P U*}','Complex intensity is one half the complex pressure times the conjugate of the complex particle velocity; its real part is the active intensity and its imaginary part is the reactive intensity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex acoustic intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd698075d-1b6e-5296-b758-70281a6553bb','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d698075d-1b6e-5296-b758-70281a6553bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d698075d-1b6e-5296-b758-70281a6553bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc5a5ec8-77be-5042-ad4c-244f01726342','Particle-velocity NAH','A variant of near-field acoustical holography whose measured input is the acoustic particle velocity, obtained with velocity or pressure-gradient transducers, rather than, or in addition to, sound pressure. Because normal particle velocity couples directly to surface vibration and weights the wavenumber spectrum differently from pressure, velocity-based holography can improve reconstruction of surface velocity and radiated intensity, particularly for the evanescent, high-wavenumber content that dominates fine source detail.','This kind of NAH measures air motion, not pressure. Tiny probes sense how fast air particles move. That motion links closely to surface vibration. It can sharpen maps of how a surface moves. It is often paired with pressure data.','Uses particle velocity as the hologram input to strengthen recovery of surface velocity and near-field detail that pressure alone captures less well.','Applied with particle-velocity probes to reconstruct vibrating-surface velocity and intensity, often on complex or low-frequency sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Pressure-velocity NAH','P-U probe','Surface velocity reconstruction','Particle velocity','Near-field acoustical holography']::text[],ARRAY['Assuming velocity probes need no calibration or alignment','Ignoring probe directionality relative to the surface normal','Treating velocity and pressure holography as interchangeable']::text[],ARRAY['Reconstructing surface velocity of a panel','Using velocity probes near a low-frequency source','Improving fine detail over pressure-only NAH']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc5a5ec8-77be-5042-ad4c-244f01726342','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc5a5ec8-77be-5042-ad4c-244f01726342') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc5a5ec8-77be-5042-ad4c-244f01726342');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd87f04d-bfbe-5136-99a2-d0bb4ef17ae3','Pressure-velocity NAH','A holography approach that measures both sound pressure and particle velocity at each point, typically with p-u probes, and uses the combined data in the reconstruction. Having both quantities lets the method separate incoming and outgoing waves, apply sound-field separation to suppress reflections and rear sources, and better condition the inverse problem than pressure-only measurement. It is a natural pairing with statistically optimized NAH (SONAH), which fits an elementary-wave model directly to the measured pressure and velocity.','This NAH measures both sound pressure and air motion together. Special probes capture both at once. With both, you can tell waves coming in from waves going out. That helps remove reflections and stray sources. It makes the rebuild more reliable.','Combines pressure and velocity data to enable wave separation, reject unwanted fields, and stabilize the reconstruction relative to pressure-only NAH.','Used with p-u probe arrays and SONAH to measure sources in non-ideal rooms where reflections would otherwise corrupt pressure-only results.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Particle-velocity NAH','P-U probe','Sound-field separation','Statistically optimized NAH','Complex acoustic intensity']::text[],ARRAY['Assuming combined data removes all reflection error','Neglecting phase matching between pressure and velocity channels','Confusing p-u NAH with pressure-only planar NAH']::text[],ARRAY['Measuring a source in a reflective room','Separating a target source from a rear source','Feeding p-u data into a SONAH reconstruction']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-velocity NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd87f04d-bfbe-5136-99a2-d0bb4ef17ae3','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd87f04d-bfbe-5136-99a2-d0bb4ef17ae3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd87f04d-bfbe-5136-99a2-d0bb4ef17ae3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fda61db-5eed-5d5f-abf8-5ad764216456','P-U probe','A transducer that measures sound pressure (p) and one component of acoustic particle velocity (u) at essentially the same point, typically pairing a pressure microphone with a hot-wire (Microflown-type) or pressure-gradient velocity sensor. By providing both quantities co-located, it enables direct sound-intensity measurement, wave-direction discrimination, and pressure-velocity holography without the finite-difference approximation of a two-microphone (p-p) intensity probe.','A p-u probe measures two things at one spot. It senses sound pressure and air motion together. Pressure comes from a small mic. Air motion comes from a special velocity sensor. Having both lets you measure intensity and wave direction directly.','Supplies co-located pressure and particle velocity, enabling direct intensity and holography that a pressure-only or two-mic setup cannot provide as cleanly.','Used for sound-intensity mapping and p-u based NAH, mounted in scanning rigs or arrays around a source under test.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Pressure-velocity NAH','Particle-velocity NAH','Sound intensity','Particle velocity','Statistically optimized NAH']::text[],ARRAY['Assuming a p-u probe needs no phase or gain calibration','Ignoring the probe''s velocity-axis orientation','Confusing a p-u probe with a two-microphone p-p intensity probe']::text[],ARRAY['Scanning intensity over a machine surface','Capturing p and u for holography','Calibrating a probe before a measurement']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='P-U probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fda61db-5eed-5d5f-abf8-5ad764216456','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fda61db-5eed-5d5f-abf8-5ad764216456') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fda61db-5eed-5d5f-abf8-5ad764216456');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fc0c3eb-b5a4-54d0-9a86-0656d59952e9','Conformal NAH','A near-field acoustical holography formulation in which the measurement surface conforms to the geometry of the source rather than being a simple plane, cylinder, or sphere. It generalizes NAH to arbitrarily shaped radiators by using boundary-element or equivalent-source models to relate the measured near-field data to the conformal source surface, allowing accurate reconstruction of surface velocity and intensity on irregular objects that a planar transform cannot handle well.','This NAH uses a surface shaped like the object. The probes follow the object''s real shape. That suits parts that are not flat or round. It uses model-based math instead of a simple transform. It gives good maps on odd-shaped sources.','Extends holography to arbitrary source shapes so that curved or irregular radiators can be reconstructed accurately on their true surface.','Applied to real components like engine blocks or car bodies, where a body-hugging measurement surface fits the part under test.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Planar NAH','Cylindrical NAH','Spherical NAH','Boundary integral method','Equivalent source distribution']::text[],ARRAY['Forcing a planar model onto a curved source','Under-sampling a complex conformal surface','Ignoring geometry errors in the measurement mesh']::text[],ARRAY['Mapping an irregular engine component','Fitting a measurement mesh to a car body','Reconstructing velocity on a curved housing']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conformal NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fc0c3eb-b5a4-54d0-9a86-0656d59952e9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fc0c3eb-b5a4-54d0-9a86-0656d59952e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fc0c3eb-b5a4-54d0-9a86-0656d59952e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47eb44b4-5be0-5a8a-8398-47337e9667c4','Planar NAH','The original and most common form of near-field acoustical holography, in which the field is sampled on a flat plane close to a nominally planar source and reconstructed using the two-dimensional spatial Fourier transform and the plane-wave propagator. It is computationally efficient because propagation reduces to multiplication in the wavenumber domain, but it assumes an infinite plane, so a finite aperture causes leakage and edge errors, and it is best suited to flat, spatially bounded sources.','This is the basic, flat-plane form of NAH. Microphones sit on a flat grid near the source. The math uses a 2-D FFT, so it is fast. It works best for flat sources. A small grid can cause edge errors.','Provides a fast FFT-based reconstruction for flat sources, serving as the foundational NAH geometry from which others generalize.','Used to image flat radiators such as panels and loudspeaker baffles with a planar scanning grid or array.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Wavenumber-domain NAH','Spatial Fourier transform','Cylindrical NAH','Conformal NAH','Hologram plane']::text[],ARRAY['Applying a planar model to strongly curved sources','Using too small an aperture and getting edge leakage','Ignoring spatial aliasing from coarse grids']::text[],ARRAY['Imaging a flat vibrating panel','Scanning a loudspeaker baffle','Teaching NAH with the simplest geometry']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47eb44b4-5be0-5a8a-8398-47337e9667c4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47eb44b4-5be0-5a8a-8398-47337e9667c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47eb44b4-5be0-5a8a-8398-47337e9667c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52d5594b-10bc-52b4-b04f-369da350518c','Cylindrical NAH','A near-field acoustical holography formulation for sources whose geometry suits a cylindrical coordinate system, in which the field is measured on a cylindrical surface surrounding the source and expanded in cylindrical harmonics and Hankel functions rather than plane waves. Propagation between concentric cylinders is handled by ratios of Hankel functions that play the role of the planar propagator, allowing reconstruction of surface velocity, pressure, and intensity for elongated or rotationally shaped radiators.','This NAH wraps the measurement around a cylinder. It suits long, tube-shaped sources. The math uses circular wave shapes, not flat ones. Sound is moved between cylinders with special functions. It rebuilds the field on the source surface.','Adapts holography to cylindrical sources by using a wave basis matched to their geometry, improving accuracy over a forced planar model.','Applied to elongated radiators such as motors, pipes, and machine shafts using a cylindrical microphone array.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Planar NAH','Spherical NAH','Conformal NAH','Near-field acoustical holography','Wavenumber spectrum']::text[],ARRAY['Using a planar model where a cylindrical one fits better','Under-sampling around the circumference and aliasing','Ignoring truncation at the cylinder ends']::text[],ARRAY['Measuring an electric motor with a ring array','Imaging a vibrating pipe','Reconstructing a shaft''s radiated field']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52d5594b-10bc-52b4-b04f-369da350518c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52d5594b-10bc-52b4-b04f-369da350518c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52d5594b-10bc-52b4-b04f-369da350518c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2509594-4ee9-58fa-88f4-50821d483ed0','Spherical NAH','A near-field acoustical holography formulation using a spherical measurement surface and an expansion of the field in spherical harmonics and spherical Hankel functions, well suited to compact sources that radiate in all directions. Radial propagation between concentric spheres is governed by ratios of spherical Hankel functions, and the method is naturally implemented with spherical microphone arrays. It provides full three-dimensional directivity and is widely used for compact source characterization.','This NAH surrounds the source with a sphere of mics. It suits compact sources that radiate all around. The math uses spherical wave shapes. Sound is moved between spheres with special functions. It gives a full 3-D picture of the radiation.','Reconstructs the full three-dimensional field of a compact source using a spherical wave basis matched to omnidirectional radiation.','Used with spherical microphone arrays to characterize compact machines, instruments, or reference sources in all directions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Cylindrical NAH','Planar NAH','Spherical microphone array','Spherical harmonics','Near-field acoustical holography']::text[],ARRAY['Applying it to sources too large for the sphere','Truncating the harmonic order too low and blurring detail','Under-sampling the sphere and causing spatial aliasing']::text[],ARRAY['Characterizing a compact machine''s directivity','Measuring a musical instrument''s radiation','Using a spherical array on a reference source']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2509594-4ee9-58fa-88f4-50821d483ed0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2509594-4ee9-58fa-88f4-50821d483ed0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2509594-4ee9-58fa-88f4-50821d483ed0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4636337-fbdd-5158-ae87-2fd499108444','Transient NAH','An extension of near-field acoustical holography to time-varying, non-stationary sound fields, reconstructing the evolving pressure, velocity, and intensity of transient or impulsive events rather than a steady single-frequency field. It typically works from time-domain array data using time-domain or short-time/wavelet formulations, or by reconstructing many frequency components and recombining them, so that events such as impacts, starts, and rattles can be localized as they occur.','This NAH handles sound that changes over time. Normal NAH assumes a steady tone. This version follows short, changing events. It uses time-based data from an array. It can track bursts, impacts, and rattles as they happen.','Lets holography capture non-steady events, reconstructing how a transient source''s field develops in time as well as space.','Used to localize impact noise, gear rattle, or start-up transients where a steady-state assumption would fail.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Real-time NAH','Near-field acoustical holography','Sound-field reconstruction','Sparse NAH','Non-stationary signal']::text[],ARRAY['Applying steady-state NAH to a transient event','Under-sampling in time and missing fast changes','Ignoring that transients spread energy across frequencies']::text[],ARRAY['Localizing an impact noise on a panel','Tracking a gear-rattle transient','Imaging a start-up noise event']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4636337-fbdd-5158-ae87-2fd499108444','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4636337-fbdd-5158-ae87-2fd499108444') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4636337-fbdd-5158-ae87-2fd499108444');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53a3bd0d-3946-524a-9475-0afb105d4fc6','Real-time NAH','An implementation of near-field acoustical holography fast enough to produce reconstructed field or source maps at or near the rate of data acquisition, giving live feedback during a measurement. It relies on efficient formulations (FFT-based propagation, precomputed inverse operators, or sparse methods) and array hardware so that pressure or p-u data streams are turned into updating maps, supporting interactive source hunting rather than offline post-processing.','This NAH shows results as you measure. Normal NAH is worked out later. This version updates the map live. It needs fast math and array hardware. Engineers can hunt sources on the spot.','Provides live source and field maps during acquisition, enabling interactive noise-source hunting instead of slow offline analysis.','Used with array systems that display updating source maps while an operator moves the array or changes machine conditions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Transient NAH','Sparse NAH','Near-field acoustical holography','Microphone array','Sound-field reconstruction']::text[],ARRAY['Assuming real-time speed keeps full accuracy','Ignoring regularization when chasing frame rate','Under-sampling to gain speed and aliasing the field']::text[],ARRAY['Hunting a source live on a running machine','Adjusting a product while watching its map update','Demonstrating source location interactively']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-time NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53a3bd0d-3946-524a-9475-0afb105d4fc6','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53a3bd0d-3946-524a-9475-0afb105d4fc6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53a3bd0d-3946-524a-9475-0afb105d4fc6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85c4d22c-79dd-5e8a-afe9-930b266d08ad','Sparse NAH','A near-field acoustical holography approach that assumes the source or its representation is sparse, describable by relatively few significant components, and uses sparsity-promoting inversion (for example L1-regularized or compressed-sensing solvers) to reconstruct it from limited measurements. Exploiting sparsity can reduce the number of microphones needed and sharpen source localization compared with conventional least-squares regularization, provided the sparsity assumption fits the true source.','This NAH assumes the source is simple. It expects only a few strong parts. Using that idea, it needs fewer mics. Special math finds the few key components. It can sharpen source maps from limited data.','Uses sparsity to reconstruct sources from fewer measurements and to localize compact sources more sharply than plain least-squares methods.','Applied when only a small array is available and the source is expected to be a few compact radiators.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Compressive NAH','Compressive equivalent source method','Equivalent source distribution','Regularization','Real-time NAH']::text[],ARRAY['Assuming sparsity for a truly distributed source','Over-sparsifying and dropping real sources','Confusing sparse solvers with simple Tikhonov']::text[],ARRAY['Localizing a few compact sources with a small array','Reducing microphone count on a scan','Sharpening a source map under sparsity']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sparse NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85c4d22c-79dd-5e8a-afe9-930b266d08ad','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85c4d22c-79dd-5e8a-afe9-930b266d08ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85c4d22c-79dd-5e8a-afe9-930b266d08ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2d296b6-d5a1-5452-ae50-cbf0705c2f3e','Compressive NAH','A near-field acoustical holography method built on compressed-sensing theory, in which a sparse source or wavenumber representation is recovered from far fewer measurements than conventional sampling would require, using L1-minimization and incoherent (often randomized) sampling. When the field admits a sparse basis, compressive NAH can beat the spatial-Nyquist limit on microphone count while retaining localization accuracy, at the cost of a nonlinear reconstruction.','This NAH uses compressed sensing ideas. It rebuilds a source from very few mics. It works when the source is simple in some basis. The math finds the sparse answer that fits the data. It can use fewer mics than usual rules demand.','Reduces the measurement burden of holography by recovering sparse fields from sub-Nyquist sampling using compressed-sensing reconstruction.','Used where dense arrays are impractical, recovering compact sources from a reduced, sometimes randomized, set of microphone positions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Compressive equivalent source method','Sparse NAH','Equivalent source distribution','Spatial Nyquist','Regularization']::text[],ARRAY['Assuming any field is sparse enough for compressed sensing','Ignoring the need for incoherent sampling','Expecting linear-method intuition to hold for nonlinear recovery']::text[],ARRAY['Recovering a source from a sparse mic set','Using randomized positions to beat Nyquist','Imaging compact sources with limited hardware']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compressive NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2d296b6-d5a1-5452-ae50-cbf0705c2f3e','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2d296b6-d5a1-5452-ae50-cbf0705c2f3e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2d296b6-d5a1-5452-ae50-cbf0705c2f3e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99119517-4ee3-5a17-80e9-1f602e8208e2','Compressive equivalent source method','A source-reconstruction technique that models a radiator as a distribution of equivalent sources and solves for their amplitudes under a sparsity constraint using compressed-sensing (L1) minimization. By promoting a sparse set of active equivalent sources, it localizes compact radiators more sharply and works with fewer measurements than L2-regularized equivalent-source solving, and it serves as a common benchmark against which newer data-driven reconstruction methods are compared.','This method models a source as many small virtual sources. It then keeps only a few of them active. A sparse-fitting math picks those few. This sharpens where the sound comes from. It also needs fewer measurements.','Combines the equivalent-source model with sparsity to give sharp, economical source reconstructions and a standard benchmark for newer methods.','Used to localize compact radiators from limited array data and to benchmark machine-learning reconstruction approaches.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equivalent source distribution','Compressive NAH','Sparse NAH','Equivalent monopole source','Regularization']::text[],ARRAY['Forcing sparsity on a spread-out source','Placing equivalent sources poorly and biasing the fit','Confusing it with plain L2 equivalent-source solving']::text[],ARRAY['Localizing compact sources from few mics','Benchmarking a data-driven reconstruction','Solving an equivalent-source model with sparsity']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compressive equivalent source method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99119517-4ee3-5a17-80e9-1f602e8208e2','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99119517-4ee3-5a17-80e9-1f602e8208e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99119517-4ee3-5a17-80e9-1f602e8208e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd92bee8b-bef2-5af0-85d5-45af925cfcd3','Patch NAH','A near-field acoustical holography approach designed for measurement over an aperture (patch) that does not fully enclose or extend beyond the source, addressing the truncation and leakage errors that corrupt classical Fourier-based planar NAH when the hologram is spatially limited. Methods such as data extrapolation, iterative wavenumber processing, and statistically optimized NAH (SONAH) reconstruct the field over the patch without assuming an infinite plane, enabling holography on large sources with a modest array.','This NAH covers only part of a large source. Normal planar NAH assumes an endless plane. A small patch breaks that and causes edge errors. Patch methods fix this with smarter math. So a modest array can measure a big source.','Enables holography on sources larger than the array by controlling the truncation and leakage errors of a finite measurement aperture.','Used to measure a section of a large panel or structure with a manageable array instead of covering the whole source.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Statistically optimized NAH','Planar NAH','Wavenumber-domain NAH','Aperture','Sound-field reconstruction']::text[],ARRAY['Applying classical Fourier NAH to a truncated aperture','Ignoring leakage from the patch edges','Assuming a patch fully represents a larger source']::text[],ARRAY['Measuring a section of a large panel','Using a small array on a big machine','Reducing truncation error with SONAH']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Patch NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd92bee8b-bef2-5af0-85d5-45af925cfcd3','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d92bee8b-bef2-5af0-85d5-45af925cfcd3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d92bee8b-bef2-5af0-85d5-45af925cfcd3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8031132-491b-5904-96d6-9d766d9f69d6','Non-free-field NAH','Near-field acoustical holography adapted to realistic environments that are not anechoic, where reflections, reverberation, background sources, and scattering violate the free-field assumption of classical NAH. It relies on sound-field separation, double-layer (p-u or double-plane) measurement, or model-based inversion to distinguish the target source''s radiation from the interfering field, allowing in-situ reconstruction outside a specialized acoustic chamber.','This NAH works in normal, echoey rooms. Classic NAH assumes no reflections. Real rooms add echoes and stray sound. This method separates the target source from that clutter. So you can measure on site, not just in a lab.','Extends holography to non-ideal spaces by separating the wanted source from reflections and interference that would otherwise corrupt the result.','Used for in-situ source characterization on factory floors or ordinary rooms where an anechoic chamber is unavailable.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-field separation','Pressure-velocity NAH','Statistically optimized NAH','Near-field acoustical holography','Reverberation']::text[],ARRAY['Assuming free-field NAH works unchanged in a live room','Skipping field separation and mixing in reflections','Using a single measurement layer where two are needed']::text[],ARRAY['Measuring a machine on a factory floor','Separating a source from room reflections','Reconstructing in a reverberant space']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Non-free-field NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8031132-491b-5904-96d6-9d766d9f69d6','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8031132-491b-5904-96d6-9d766d9f69d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8031132-491b-5904-96d6-9d766d9f69d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bcd18d6-4096-58b9-93e1-50cbfd1437a4','Sound-field separation','A processing technique that decomposes a measured field into components travelling in opposite directions or originating from different sides, so that the radiation of a target source can be isolated from reflections, background noise, and sources on the far side of the measurement surface. It is commonly realized with double-layer measurements or combined pressure and particle-velocity data, and it is a key enabler of holography in non-anechoic, non-free-field conditions.','This splits a measured field by where sound comes from. It tells waves from the target apart from reflections. It also removes sound from behind the array. It often uses two measurement layers, or pressure plus velocity. This lets NAH work outside a quiet lab.','Isolates the target source''s field from interfering waves, making accurate reconstruction possible in reflective, multi-source environments.','Applied before or within NAH to strip out reflections and rear sources when measuring in ordinary rooms.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Non-free-field NAH','Pressure-velocity NAH','Double-layer measurement','Statistically optimized NAH','Sound-field reconstruction']::text[],ARRAY['Assuming one measurement layer can separate two-sided fields','Neglecting probe calibration needed for clean separation','Expecting perfect rejection of strong reflections']::text[],ARRAY['Removing rear-source contamination','Stripping reflections before reconstruction','Isolating a target source in a live room']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bcd18d6-4096-58b9-93e1-50cbfd1437a4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bcd18d6-4096-58b9-93e1-50cbfd1437a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bcd18d6-4096-58b9-93e1-50cbfd1437a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4841a43-3133-598a-8ea8-27e39c9eb9db','Equivalent source distribution','A source model, the basis of the equivalent source method (ESM), in which the field of a real radiator is represented by a set of simple virtual sources (typically monopoles, sometimes dipoles) placed on or inside the source surface, whose complex strengths are found by fitting their superposed field to the measurements. Once solved, the equivalent sources reproduce the field everywhere outside the source, allowing pressure, velocity, and intensity to be computed on any surface. The solution is an inverse problem requiring regularization.','This models a real source as many simple virtual sources. Each virtual source is a basic point radiator. Their combined sound is matched to the measured data. Then they can predict sound anywhere outside. It is a flexible way to rebuild a field.','Replaces a complex radiator with a solvable set of simple sources, so the field can be reconstructed on arbitrary surfaces from limited data.','Used in equivalent-source software to reconstruct pressure, velocity, and intensity around irregular sources from array measurements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equivalent monopole source','Equivalent dipole source','Combined source representation','Compressive equivalent source method','Inverse acoustic problem']::text[],ARRAY['Placing equivalent sources badly and biasing the fit','Using too many sources and overfitting noise','Skipping regularization on the inverse solve']::text[],ARRAY['Reconstructing an irregular source''s field','Fitting virtual sources to array data','Predicting intensity on a chosen surface']::text[],'advanced','p(r) ≈ Σ_{i=1}^{N} q_i g(r | r_i),  g(r|r_i) = e^{−ik|r−r_i|} / (4π|r−r_i|)','The pressure at a point is approximated by the sum over the equivalent sources of each source strength times the free-space Green''s function, a decaying complex exponential divided by four pi times the distance from that source.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent source distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4841a43-3133-598a-8ea8-27e39c9eb9db','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4841a43-3133-598a-8ea8-27e39c9eb9db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4841a43-3133-598a-8ea8-27e39c9eb9db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e8823a7-5cdc-5c80-9784-b9646607b05c','Equivalent monopole source','A virtual point source radiating uniformly in all directions, whose free-space field is described by the monopole Green''s function, used as the elementary building block in equivalent-source reconstruction. A distribution of such monopoles, each with a complex strength, is superposed and fitted to measured data to represent an arbitrary radiator. The monopole is the simplest and most common equivalent source because it captures net volume-velocity (breathing) radiation.','This is a simple virtual point source. It sends sound out evenly in every direction. Many of them together can mimic a real source. Each one gets a strength set by the data. It is the basic block of equivalent-source models.','Serves as the elementary radiator in equivalent-source models, letting complex sources be built up from simple omnidirectional points.','Populates the source layer in ESM/NAH software, where solved monopole strengths reconstruct the radiated field.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equivalent source distribution','Equivalent dipole source','Combined source representation','Monopole','Green''s function']::text[],ARRAY['Modeling strongly directional radiation with monopoles alone','Placing monopoles on the wrong surface offset','Ignoring regularization when solving strengths']::text[],ARRAY['Building an equivalent-source layer','Reconstructing a breathing-type source','Fitting monopole strengths to measurements']::text[],'advanced','p(r) = q · e^{−ikr} / (4π r),  r = |r − r₀|','A monopole''s pressure equals its complex strength times a decaying complex exponential in the wavenumber and distance, divided by four pi times the distance from the source point.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent monopole source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e8823a7-5cdc-5c80-9784-b9646607b05c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e8823a7-5cdc-5c80-9784-b9646607b05c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e8823a7-5cdc-5c80-9784-b9646607b05c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '62104705-aa0c-50a9-9f91-bd604f9fd36c','Equivalent dipole source','A virtual directional source formed from two closely spaced, out-of-phase monopoles, whose field is the normal derivative of the monopole Green''s function and which radiates with a figure-of-eight directivity. Used in equivalent-source reconstruction alongside or instead of monopoles, dipoles better represent radiators dominated by surface motion normal to a baffle and can improve the fit for directional or oscillating-force sources.','This is a directional virtual source. It acts like two point sources pushing opposite ways. It radiates strongly two ways and little sideways. It suits sources that push a surface back and forth. It adds direction that a monopole lacks.','Adds directional radiation to the equivalent-source toolbox, improving representation of sources with strong normal surface motion.','Used in ESM reconstructions of directional or force-driven radiators where monopoles alone fit poorly.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equivalent monopole source','Equivalent source distribution','Combined source representation','Dipole','Green''s function']::text[],ARRAY['Using dipoles where simple monopoles suffice','Mis-orienting the dipole axis relative to the surface','Overfitting with mixed source types']::text[],ARRAY['Modeling a directional radiator','Improving a fit with dipole terms','Representing normal surface motion']::text[],'advanced','p_dip(r) ∝ ∂/∂n [ e^{−ikr} / (4π r) ]','A dipole''s pressure is proportional to the derivative, along the dipole axis, of the monopole field, giving a directional figure-of-eight radiation pattern.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent dipole source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '62104705-aa0c-50a9-9f91-bd604f9fd36c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='62104705-aa0c-50a9-9f91-bd604f9fd36c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='62104705-aa0c-50a9-9f91-bd604f9fd36c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5278cd36-5f7c-542a-8c4f-7259ff117239','Combined source representation','An equivalent-source modeling strategy that uses more than one type of elementary source, most often monopoles together with dipoles, to represent a radiator, improving conditioning and accuracy over a single-type distribution. Mixing source types lets the model capture both volume-velocity and directional radiation, which can reduce the number of sources needed and mitigate errors when the true radiation is not well matched by monopoles alone.','This model mixes different virtual source types. It often blends point sources with directional ones. Together they match real radiation better. This can need fewer sources overall. It suits sources with both even and directional output.','Combines complementary elementary sources so the equivalent-source model fits complex radiation with better conditioning and fewer terms.','Used in ESM reconstructions where mixing monopole and dipole sources improves accuracy on real-world radiators.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equivalent source distribution','Equivalent monopole source','Equivalent dipole source','Compressive equivalent source method','Inverse acoustic problem']::text[],ARRAY['Adding source types without improving the fit','Overfitting by mixing too many basis types','Ignoring conditioning when combining sources']::text[],ARRAY['Mixing monopoles and dipoles in a model','Improving a fit on a complex radiator','Reducing source count with combined types']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Combined source representation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5278cd36-5f7c-542a-8c4f-7259ff117239','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5278cd36-5f7c-542a-8c4f-7259ff117239') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5278cd36-5f7c-542a-8c4f-7259ff117239');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca89445b-7636-59ab-9584-9348733eed55','Kirchhoff-Helmholtz integral','A boundary-integral identity that expresses the acoustic pressure at any point in a source-free region in terms of the pressure and its normal derivative (proportional to normal particle velocity) on an enclosing surface, combined with the free-space Green''s function. It is the rigorous foundation for boundary-element methods and for holographic reconstruction on arbitrary geometries, since knowing pressure and normal velocity on a closed surface determines the field everywhere outside the source.','This equation builds the field from surface data. It needs pressure and its slope on a closed surface. From those, it gives sound at any outside point. It is exact, not an approximation. It underlies model-based reconstruction on any shape.','Provides the exact surface-to-field relationship that lets pressure and normal velocity on a boundary determine the field throughout the exterior region.','Underlies boundary-element and conformal holography codes that reconstruct fields around arbitrarily shaped sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Helmholtz integral equation','Boundary integral method','Rayleigh integral','Green''s function','Conformal NAH']::text[],ARRAY['Assuming pressure alone (without normal velocity) suffices','Applying it inside the source region','Ignoring discretization error on the boundary mesh']::text[],ARRAY['Deriving a boundary-element reconstruction','Relating surface data to the exterior field','Setting up conformal holography on a shape']::text[],'advanced','p(r) = ∮_S [ G(r|r_s) ∂p/∂n − p(r_s) ∂G/∂n ] dS,  G = e^{−ik|r−r_s|}/(4π|r−r_s|)','The pressure at a field point is the surface integral over a closed boundary of the Green''s function times the pressure''s normal derivative minus the pressure times the Green''s function''s normal derivative.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kirchhoff-Helmholtz integral');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca89445b-7636-59ab-9584-9348733eed55','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca89445b-7636-59ab-9584-9348733eed55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca89445b-7636-59ab-9584-9348733eed55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6893ab69-82e1-5ee3-9a8d-294dcfafd3d9','Boundary integral method','A family of numerical techniques, chiefly the boundary element method, that solve acoustic radiation and scattering by discretizing the Kirchhoff-Helmholtz integral over the source or boundary surface rather than meshing the whole surrounding volume. Reducing a three-dimensional problem to a surface computation, it relates surface pressure and normal velocity and is widely used for forward radiation prediction and for the inverse problem of reconstructing surface quantities on arbitrary geometries.','This method solves sound using only surface data. It meshes the source surface, not the whole space. That makes a 3-D problem into a surface one. It links surface pressure and motion. It suits odd shapes that simple transforms cannot handle.','Turns volumetric radiation problems into surface computations, enabling both prediction and inverse reconstruction on complex geometries.','Used in acoustic BEM software to predict radiation from meshed parts and to reconstruct surface velocity in inverse NAH.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Kirchhoff-Helmholtz integral','Helmholtz integral equation','Conformal NAH','Equivalent source distribution','Surface velocity reconstruction']::text[],ARRAY['Under-meshing the boundary and losing high-frequency accuracy','Ignoring non-uniqueness at certain frequencies','Assuming the interior region need not be considered']::text[],ARRAY['Predicting radiation from a meshed part','Reconstructing surface velocity on a shape','Setting up an acoustic BEM model']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary integral method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6893ab69-82e1-5ee3-9a8d-294dcfafd3d9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6893ab69-82e1-5ee3-9a8d-294dcfafd3d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6893ab69-82e1-5ee3-9a8d-294dcfafd3d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2dd0239-d9dd-5366-8de9-441c35a86177','Rayleigh integral','A special case of the Kirchhoff-Helmholtz relation for a planar radiator set in an infinite rigid baffle, giving the radiated pressure directly as a surface integral of the normal velocity weighted by the free-space Green''s function. Because it needs only the surface normal velocity (not the surface pressure), the first Rayleigh integral is a convenient forward model for baffled planar sources and underpins planar radiation prediction and the forward step of planar holography.','This integral finds sound from a flat vibrating surface. It assumes the surface sits in a big rigid wall. It needs only how the surface moves. From that it gives the radiated pressure. It is a handy forward model for flat sources.','Provides a direct forward map from a baffled surface''s normal velocity to its radiated pressure, simplifying planar radiation prediction.','Used to predict radiation from baffled panels and loudspeaker diaphragms and as the forward model in planar reconstruction.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Kirchhoff-Helmholtz integral','Helmholtz integral equation','Planar NAH','Surface velocity reconstruction','Green''s function']::text[],ARRAY['Applying it to unbaffled or curved sources','Forgetting the infinite rigid-baffle assumption','Confusing the first and second Rayleigh integrals']::text[],ARRAY['Predicting radiation from a baffled panel','Modeling a loudspeaker diaphragm''s output','Providing the forward step in planar NAH']::text[],'advanced','p(r) = (iωρ₀ / 2π) ∬_S u_n(r_s) [ e^{−ik|r−r_s|} / |r−r_s| ] dS','The radiated pressure equals i times angular frequency times air density over two pi, times the surface integral of the normal velocity multiplied by a decaying complex exponential divided by the distance to each surface point.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rayleigh integral');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2dd0239-d9dd-5366-8de9-441c35a86177','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2dd0239-d9dd-5366-8de9-441c35a86177') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2dd0239-d9dd-5366-8de9-441c35a86177');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88265c1d-b53a-536f-9f8b-245afb2b3366','Helmholtz integral equation','The frequency-domain boundary equation obtained when the Kirchhoff-Helmholtz integral is evaluated with the field point taken onto the boundary itself, yielding an integral equation that relates surface pressure and normal velocity. It rests on the Helmholtz equation, the time-harmonic form of the wave equation, and is the equation actually solved by boundary-element methods for radiation, scattering, and inverse reconstruction; its discretization can suffer non-uniqueness at the interior resonance frequencies of the enclosed region.','This is the surface form of the sound equation. It links pressure and motion on a boundary. It comes from the steady, single-frequency wave equation. Boundary methods solve it to get radiation. At some frequencies it needs special care to stay unique.','Gives the boundary equation that ties surface pressure to surface velocity, forming the core relation solved in boundary-element acoustics.','Solved numerically in BEM tools for radiation and scattering and in inverse holography on arbitrary surfaces.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Kirchhoff-Helmholtz integral','Boundary integral method','Helmholtz equation','Rayleigh integral','Conformal NAH']::text[],ARRAY['Ignoring non-uniqueness at interior resonance frequencies','Confusing the Helmholtz equation with its integral form','Under-resolving the surface mesh at high frequency']::text[],ARRAY['Solving radiation with a BEM code','Handling non-uniqueness with a CHIEF/Burton-Miller fix','Setting up inverse reconstruction on a surface']::text[],'advanced','∇²p + k²p = 0,  k = ω/c   (time-harmonic Helmholtz equation)','The Helmholtz equation states that the Laplacian of the pressure plus the wavenumber squared times the pressure equals zero, where the wavenumber is angular frequency divided by the speed of sound.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helmholtz integral equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88265c1d-b53a-536f-9f8b-245afb2b3366','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88265c1d-b53a-536f-9f8b-245afb2b3366') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88265c1d-b53a-536f-9f8b-245afb2b3366');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '611320e0-1e56-5e61-8d2a-0243dac46b71','Radiation mode','An orthogonal set of surface velocity patterns, obtained as the eigenvectors of the radiation resistance matrix, that radiate sound power independently of one another, each with its own radiation efficiency (eigenvalue). Unlike structural mode shapes, radiation modes diagonalize the sound-power problem, so total radiated power is the sum of independent modal contributions. They reveal which surface motions radiate efficiently and are widely used in active structural-acoustic control and in interpreting reconstructed surface velocity.','These are surface motion patterns that radiate on their own. Each one sends out power independently. Each has its own radiating strength. They differ from a structure''s vibration shapes. They show which motions make sound efficiently.','Decompose radiated power into independent, efficiency-ranked components, showing which surface motions actually produce far-field sound.','Used in structural-acoustic control and in analyzing reconstructed surface velocity to target the efficiently radiating motions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Radiation efficiency','Surface velocity reconstruction','Sound power','Vibroacoustic reconstruction','Radiated sound field']::text[],ARRAY['Confusing radiation modes with structural mode shapes','Assuming a large vibration always radiates strongly','Ignoring frequency dependence of the modes']::text[],ARRAY['Ranking which surface motions radiate power','Designing structural-acoustic control','Interpreting reconstructed velocity by efficiency']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '611320e0-1e56-5e61-8d2a-0243dac46b71','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='611320e0-1e56-5e61-8d2a-0243dac46b71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='611320e0-1e56-5e61-8d2a-0243dac46b71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8515da81-b0ad-5af6-8db9-d549eeae8460','Vibroacoustic reconstruction','Reconstruction that links a structure''s surface vibration to its radiated sound, using acoustic measurements to recover surface normal velocity and then radiated pressure, intensity, and power, or vice versa. It couples structural dynamics with acoustic radiation so that noise can be traced back to the vibrating mechanism, and it draws on NAH, boundary-element, and equivalent-source methods to establish the vibration-to-sound relationship on real components.','This ties a part''s shaking to the sound it makes. It uses sound data to find how the surface moves. Then it works out the radiated sound and power. So noise is traced to its vibrating cause. It joins structure and sound in one picture.','Connects structural vibration and acoustic radiation, letting measured sound reveal the vibrating source and its radiated power.','Used in noise and vibration engineering to link a component''s motion to its noise output for targeted redesign.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Surface velocity reconstruction','Radiation mode','Radiated sound field','Near-field acoustical holography','Boundary integral method']::text[],ARRAY['Assuming all vibration radiates equally as sound','Ignoring fluid loading on the structure','Separating structure and acoustics that are actually coupled']::text[],ARRAY['Linking panel vibration to radiated noise','Tracing machine noise to a vibrating part','Guiding damping from vibration-to-sound maps']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibroacoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8515da81-b0ad-5af6-8db9-d549eeae8460','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8515da81-b0ad-5af6-8db9-d549eeae8460') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8515da81-b0ad-5af6-8db9-d549eeae8460');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12144933-c5e2-53b5-80b0-fc2c33c8b534','Source contribution map','A spatial visualization that shows how much each region of a source surface contributes to a chosen output, such as sound power or the pressure at a specific receiver, computed from a reconstruction. Rather than plotting raw surface velocity or intensity, it weights each area by its actual contribution to the target quantity, so it directly ranks the regions responsible for the radiated or received sound and guides where noise-control effort will pay off.','This map shows which parts of a source matter most. It ranks each area by how much sound it adds. It can target total power or a listener''s spot. It points to the worst offenders. That shows where to focus fixes.','Ranks source regions by their real contribution to a target output, directing noise-control effort to the areas that matter.','Presented in NAH and array software to show engineers which panels or zones drive a product''s noise.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-source reconstruction','Supersonic acoustic intensity','Radiation mode','Sound-intensity reconstruction','Radiated sound field']::text[],ARRAY['Reading surface velocity as if it were contribution','Ignoring which output the map is weighted toward','Assuming the brightest spot is always the fix target']::text[],ARRAY['Ranking panels driving cabin noise','Targeting a fix to a receiver location','Prioritizing noise-control effort']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source contribution map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12144933-c5e2-53b5-80b0-fc2c33c8b534','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12144933-c5e2-53b5-80b0-fc2c33c8b534') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12144933-c5e2-53b5-80b0-fc2c33c8b534');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba9a9178-a9b8-5e79-a294-bb6ff5cdfa3a','Surface velocity reconstruction','The recovery of the normal (out-of-plane) velocity distribution over a vibrating source surface from acoustic near-field measurements, a central output of NAH and boundary/equivalent-source methods. Because normal surface velocity drives acoustic radiation, reconstructing it identifies exactly which parts of a structure move and how strongly, linking measured sound to the underlying vibration and feeding radiated-power and intensity calculations.','This finds how fast a surface moves in and out. It uses nearby sound measurements. Surface motion is what makes sound. So this shows which parts vibrate most. It links the measured sound to the shaking surface.','Recovers the vibration pattern that drives radiation, tying measured acoustics to the mechanical motion of the source surface.','Used to see which regions of a panel or housing vibrate, guiding damping, stiffening, or design changes.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Source plane','Particle-velocity reconstruction','Radiation mode','Vibroacoustic reconstruction','Near-field acoustical holography']::text[],ARRAY['Confusing surface normal velocity with acoustic particle velocity in the field','Ignoring regularization and getting noisy velocity maps','Assuming high velocity always means high radiation']::text[],ARRAY['Mapping which panel areas vibrate','Guiding where to add damping','Feeding velocity into a radiated-power estimate']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface velocity reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba9a9178-a9b8-5e79-a294-bb6ff5cdfa3a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba9a9178-a9b8-5e79-a294-bb6ff5cdfa3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba9a9178-a9b8-5e79-a294-bb6ff5cdfa3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4422b41f-459b-5be4-b69b-e8515e59b2b6','Pressure reconstruction','The computation of the sound-pressure distribution on a plane or surface other than the one measured, obtained by propagating the measured hologram data to the target location within a reconstruction method. It is the most direct NAH output and can be evaluated closer to the source (back-propagation) or farther away (forward propagation), providing pressure maps used for visualization, level prediction, and as an input to intensity and power calculations.','This works out sound pressure at a new surface. It uses the measured near-field data. You can find pressure closer to or farther from the source. It gives pressure maps for many uses. It also feeds intensity and power results.','Provides pressure maps at chosen surfaces from measured data, serving as the base output for visualization and further intensity or power analysis.','Used to predict pressure at a target plane and to build intensity images from reconstructed pressure and velocity.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Particle-velocity reconstruction','Sound-intensity reconstruction','Forward propagation','Reconstruction plane','Sound-field reconstruction']::text[],ARRAY['Back-propagating pressure without regularization','Assuming reconstructed pressure is exact at all planes','Ignoring aperture limits on the pressure map']::text[],ARRAY['Predicting pressure at a target plane','Building an intensity map from reconstructed pressure','Visualizing the field between measured points']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4422b41f-459b-5be4-b69b-e8515e59b2b6','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4422b41f-459b-5be4-b69b-e8515e59b2b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4422b41f-459b-5be4-b69b-e8515e59b2b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6540f968-4146-59ef-bdd4-e781de50a7c1','Particle-velocity reconstruction','The estimation of the acoustic particle-velocity field from measured or reconstructed pressure, using the linearized Euler relation that ties particle velocity to the pressure gradient, or from direct velocity measurements. Because particle velocity is a vector and emphasizes the near-field, evanescent content, reconstructing it is essential for computing sound intensity and for characterizing energy flow close to a source.','This finds how fast air particles move in the field. It comes from the pressure''s slope in space. A basic physics law links the two. Velocity is needed to get intensity. It also shows near-field energy flow.','Provides the particle-velocity field needed for intensity and energy-flow analysis, derived from the pressure gradient or measured directly.','Used with reconstructed pressure to compute intensity maps and to study near-field energy flow around a source.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Pressure reconstruction','Sound-intensity reconstruction','Particle-velocity NAH','Complex acoustic intensity','Euler equation']::text[],ARRAY['Estimating a gradient from too-coarse a grid','Confusing acoustic particle velocity with surface velocity','Ignoring noise amplification when differentiating pressure']::text[],ARRAY['Deriving velocity from a pressure map','Computing intensity from p and u','Studying near-field energy flow']::text[],'advanced','u = − (1 / (iωρ₀)) ∇p   (linearized Euler relation)','The acoustic particle velocity equals the negative pressure gradient divided by i times the angular frequency times the air density.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6540f968-4146-59ef-bdd4-e781de50a7c1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6540f968-4146-59ef-bdd4-e781de50a7c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6540f968-4146-59ef-bdd4-e781de50a7c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9825cfe-4187-5e6f-8ced-ade5220acbd9','Sound-intensity reconstruction','The computation of the acoustic intensity vector field, the time-averaged product of pressure and particle velocity, from reconstructed pressure and velocity, mapping the magnitude and direction of net acoustic energy flow. Active intensity gives the radiated energy transport used to locate and rank sources and to compute radiated power by integration over a surface, while the reactive part reveals non-propagating near-field energy.','This maps where sound energy flows and how strongly. It comes from pressure times particle velocity. The result is a vector at each point. It shows the direction of energy flow. Engineers use it to find and rank sources.','Produces intensity maps that reveal energy-flow direction and magnitude, enabling source localization and radiated-power estimation.','Used to image energy flow from a source and to obtain radiated sound power by integrating intensity over a surface.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Complex acoustic intensity','Supersonic acoustic intensity','Particle-velocity reconstruction','Pressure reconstruction','Sound power']::text[],ARRAY['Reporting intensity magnitude without its direction','Confusing active with reactive intensity','Integrating a truncated aperture and misestimating power']::text[],ARRAY['Imaging energy flow from a machine','Estimating radiated power by surface integration','Locating sources from intensity vectors']::text[],'advanced','I = ½ Re{ P U* }   (time-averaged active intensity)','The time-averaged active intensity equals one half the real part of the complex pressure times the conjugate of the complex particle velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-intensity reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9825cfe-4187-5e6f-8ced-ade5220acbd9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9825cfe-4187-5e6f-8ced-ade5220acbd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9825cfe-4187-5e6f-8ced-ade5220acbd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ede9540b-2a03-5716-a852-8ec0cbd6aab0','Far-field prediction from near-field data','The use of measurements taken close to a source to estimate its far-field radiation, directivity, and sound power, by reconstructing the field and forward-propagating (or extracting the propagating wavenumber components) to large distances. Because near-field data captures the full radiating content over a bounded surface, holographic and equivalent-source methods can predict the far-field pattern without a large anechoic range, provided the aperture is adequate and only the propagating components are retained for the far field.','This predicts far-away sound from close-up measurements. You measure near the source, then project outward. Only the truly radiating parts reach the far field. This avoids needing a huge test range. It gives directivity and radiated power.','Lets a compact near-field measurement yield far-field directivity and power, avoiding large anechoic ranges for source characterization.','Used to obtain loudspeaker or machine directivity and radiated power from a near-field scan instead of a far-field arc.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Forward propagation','Propagating wave component','Radiated sound field','Near-field acoustical holography','Directivity']::text[],ARRAY['Keeping evanescent components that do not reach the far field','Using too small an aperture and truncating the pattern','Assuming near-field level scales directly to far-field level']::text[],ARRAY['Getting loudspeaker directivity from a near-field scan','Predicting radiated power without an anechoic range','Estimating far-field pattern of a machine']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field prediction from near-field data');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ede9540b-2a03-5716-a852-8ec0cbd6aab0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ede9540b-2a03-5716-a852-8ec0cbd6aab0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ede9540b-2a03-5716-a852-8ec0cbd6aab0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '244b29e1-62c6-52fc-bffe-675212b60a17','Microphone array','A set of two or more microphones held in a known, fixed geometry so the small differences in arrival time and level between channels can be processed jointly to infer the direction, position, or spatial structure of sound sources. Treating the microphones as spatial samples of the sound field lets array-processing methods such as beamforming form a directional response electronically, without moving any element.','A microphone array is a group of microphones in fixed, known positions. Sound reaches each one at a slightly different time. A computer compares these signals. From the timing it works out where a sound came from. This lets the array listen in a chosen direction without turning.','Provides the spatial samples of the sound field that beamforming and localization methods need to separate sources by direction or position.','Technicians use microphone arrays in acoustic cameras, noise-source mapping, and speech capture, mounting the elements on a frame with calibrated spacing.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Acoustic beamforming','Direction-of-arrival estimation','Phased microphone array','Acoustic source localization']::text[],ARRAY['Assuming more microphones always give a better image regardless of their spacing and layout','Ignoring element calibration, so gain and phase mismatches blur the result','Treating the array as one microphone rather than a set of spatial samples']::text[],ARRAY['Mapping noise on a running machine with a handheld acoustic camera','Locating a rattle in a car cabin with a spherical array','Steering speech pickup toward a talker in a conference room']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '244b29e1-62c6-52fc-bffe-675212b60a17','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='244b29e1-62c6-52fc-bffe-675212b60a17') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='244b29e1-62c6-52fc-bffe-675212b60a17');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bff92a0-d2fb-538b-96d8-813da9f4ca60','Array geometry','The spatial arrangement of the microphone elements — their positions, spacing, and overall aperture — which sets how the array samples the sound field. Geometry governs main-lobe width and therefore resolution, the level and location of sidelobes and grating lobes, the usable frequency range, and susceptibility to spatial aliasing; larger aperture improves resolution while element spacing relative to wavelength controls aliasing.','Array geometry means where the microphones sit and how far apart they are. This layout decides how sharp the sound image is. A wider array can separate sources better. Spacing that is too large creates false images. The layout also sets which frequencies the array handles well.','Determines the array''s resolution, frequency range, and sidelobe behaviour before any processing is applied.','Designers pick a geometry — spacing and aperture — to match the frequency band and standoff distance of a measurement.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Microphone array','Aperture','Spatial aliasing','Grating lobe','Sparse array','Spatial resolution']::text[],ARRAY['Spacing elements more than half a wavelength apart and getting spatial aliasing','Confusing aperture size with the number of elements','Copying a geometry without checking it suits the target frequency range']::text[],ARRAY['Choosing element spacing for a mid-frequency noise survey','Comparing two array layouts for the same imaging task','Widening the aperture to sharpen a low-frequency map']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array geometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bff92a0-d2fb-538b-96d8-813da9f4ca60','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bff92a0-d2fb-538b-96d8-813da9f4ca60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bff92a0-d2fb-538b-96d8-813da9f4ca60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a92ca60b-c8de-5245-8c78-15a4219fcbcc','Planar array','A microphone array whose elements all lie in a single flat plane, used to image sound sources across a two-dimensional field of view facing the array. The planar aperture gives resolution in two lateral directions and is the common layout for acoustic cameras that overlay a source map on an optical image; source distance is assumed or fixed because a single plane resolves direction far better than range.','A planar array has all its microphones on one flat surface. It looks at sources spread across a flat scene. It maps where sound comes from side to side and up and down. Acoustic cameras often use this layout. It does not judge distance well on its own.','Provides two-dimensional source mapping over a scene facing the array, as in acoustic-camera imaging.','Used in handheld and mounted acoustic cameras to overlay a noise map on a photo of a machine or panel.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Acoustic image','Beamforming map','Spatial resolution','Circular array']::text[],ARRAY['Expecting accurate source distance from a single flat array','Using it too close to a source, where near-field effects distort the map','Assuming resolution is the same at every frequency']::text[],ARRAY['Overlaying a noise map on a photo of an electrical cabinet','Imaging a flat panel to find a buzzing component','Scanning a wall to locate an air leak']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a92ca60b-c8de-5245-8c78-15a4219fcbcc','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a92ca60b-c8de-5245-8c78-15a4219fcbcc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a92ca60b-c8de-5245-8c78-15a4219fcbcc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5037263b-91a4-5978-825a-79052ca5c784','Linear array','An array whose microphones are arranged along a single straight line, typically with uniform spacing (a uniform linear array). It resolves source direction in the plane containing the line but is ambiguous about rotation around the array axis, so it estimates one angle such as azimuth rather than a full two-dimensional bearing; element spacing relative to wavelength sets its aliasing-free steering range.','A linear array puts microphones in a straight line. It finds the angle of a sound along that line. It cannot tell top from bottom around its axis. So it gives one direction angle, not a full position. Spacing sets which angles it can scan cleanly.','Provides direction finding or scanning along one axis and serves as a building block for larger arrays.','Used for one-dimensional direction finding and scanning, and as a row within planar and volumetric arrays.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Direction-of-arrival estimation','Steering delay','Spatial aliasing','Angular resolution']::text[],ARRAY['Expecting a full 3D position from a single line of microphones','Ignoring the cone of ambiguity around the array axis','Spacing elements over half a wavelength and steering into aliasing']::text[],ARRAY['Estimating the bearing of a passing vehicle','Scanning across a wall to find the loudest section','Building each row of a larger planar array']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5037263b-91a4-5978-825a-79052ca5c784','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5037263b-91a4-5978-825a-79052ca5c784') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5037263b-91a4-5978-825a-79052ca5c784');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abeada86-bf17-58a7-a747-8732c3065212','Circular array','An array whose microphones are placed on a circle, giving a geometry with rotational symmetry that supports direction finding over a full 360 degrees of azimuth with nearly uniform performance. Circular arrays suit horizontal-plane localization and, with elements on a rigid baffle, underpin some spherical-harmonic and modal beamforming schemes.','A circular array arranges microphones around a ring. Its round shape treats every horizontal direction alike. This helps it find sources all the way around a full circle. It is handy for locating sounds in the horizontal plane. Some 3D methods build on this shape.','Gives uniform azimuth coverage for horizontal-plane localization and modal processing.','Used for 360-degree direction finding and as the base of some modal and spherical beamformers.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Spherical array','Direction-of-arrival estimation','Look direction','Angular resolution']::text[],ARRAY['Assuming a flat ring resolves elevation as well as azimuth','Forgetting that scattering off a baffle changes the response','Using too few elements, which raises sidelobes']::text[],ARRAY['Locating a talker around a conference table','Finding the bearing of noise around a monitoring point','Feeding a modal beamformer from a baffled ring']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Circular array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abeada86-bf17-58a7-a747-8732c3065212','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abeada86-bf17-58a7-a747-8732c3065212') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abeada86-bf17-58a7-a747-8732c3065212');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '003e6eb9-9dbb-55b0-9d0d-0501860f2d8e','Spherical array','A microphone array with elements distributed over the surface of a sphere, usually a rigid one, enabling analysis of the sound field in terms of spherical harmonics and beamforming that can be steered in any three-dimensional direction with orientation-independent behaviour. The sphere''s radius and element count set the usable frequency range and the maximum spherical-harmonic order the array can resolve.','A spherical array spreads microphones over a ball. This shape lets it listen in any 3D direction. Its response is the same whichever way you point it. Special math based on sphere shapes describes the sound field. The ball''s size sets the frequencies it handles.','Enables three-dimensional sound-field capture and steering in any direction using spherical-harmonic (modal) processing.','Used for 3D localization, room and directivity analysis, and cabin noise mapping with rigid-sphere arrays.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Spherical harmonics','3D beamforming','Modal beamforming','Circular array']::text[],ARRAY['Pushing above the frequency where element spacing causes spatial aliasing','Ignoring the harmonic-order limit set by the number of elements','Treating an open-sphere and a rigid-sphere array as equivalent']::text[],ARRAY['Mapping noise sources inside a car cabin in 3D','Measuring the directivity of a loudspeaker','Capturing a room''s sound field for spatial analysis']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '003e6eb9-9dbb-55b0-9d0d-0501860f2d8e','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='003e6eb9-9dbb-55b0-9d0d-0501860f2d8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='003e6eb9-9dbb-55b0-9d0d-0501860f2d8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cf295f1-c23c-5050-ad8b-618c7d83536b','Volumetric array','A three-dimensional microphone arrangement in which elements occupy a volume rather than a line, plane, or shell, giving spatial samples along all three axes. The added depth extent lets the array resolve source range as well as bearing and can suppress front-back and elevation ambiguities that afflict planar or linear layouts, at the cost of more elements and more demanding calibration.','A volumetric array fills a 3D space with microphones, not just a line or flat sheet. Having depth lets it judge distance as well as direction. It also avoids some front-back mix-ups. The trade-off is more microphones. It is also harder to set up and calibrate.','Provides full three-dimensional sampling to resolve range and remove the ambiguities of flat arrays.','Used in research and specialized 3D localization where both range and elevation matter.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Spherical array','3D beamforming','Acoustic source localization','Aperture']::text[],ARRAY['Assuming any 3D scatter of microphones localizes well without careful design','Underestimating the calibration effort for many elements','Confusing a volumetric array with a surface spherical array']::text[],ARRAY['Localizing sources at different depths in a test chamber','Resolving range as well as bearing in a research setup','Removing front-back ambiguity that a flat array cannot']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volumetric array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cf295f1-c23c-5050-ad8b-618c7d83536b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cf295f1-c23c-5050-ad8b-618c7d83536b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cf295f1-c23c-5050-ad8b-618c7d83536b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '041eaaf6-9370-5648-9ddc-b4b57d27ab25','Sparse array','An array that uses fewer elements than a filled, half-wavelength-spaced grid of the same aperture, with element positions chosen so a large aperture and its fine resolution are retained while element count and cost fall. Careful nonuniform placement keeps sidelobes acceptably low despite the thinning; naive thinning instead raises sidelobes and can create grating-lobe-like artefacts.','A sparse array uses fewer microphones than a full grid. The elements are spread out to keep a wide, sharp aperture. This saves cost and hardware. The placement must be chosen with care. Bad spacing raises false side peaks in the image.','Keeps large-aperture resolution while reducing element count and cost through nonuniform placement.','Used in acoustic cameras and antenna-like designs where a full grid would be too costly.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Aperture','Irregular array','Sidelobe','Grating lobe']::text[],ARRAY['Thinning a grid at random and accepting the high sidelobes that follow','Assuming fewer elements always means worse resolution','Ignoring that sparse layouts still need per-element calibration']::text[],ARRAY['Designing a wideband acoustic-camera array on a budget','Keeping resolution while cutting channel count','Optimizing element positions to hold down sidelobes']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sparse array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '041eaaf6-9370-5648-9ddc-b4b57d27ab25','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='041eaaf6-9370-5648-9ddc-b4b57d27ab25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='041eaaf6-9370-5648-9ddc-b4b57d27ab25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a417f980-ed35-57ee-9902-1d66803a47c3','Irregular array','A microphone array whose elements are placed nonuniformly, deliberately breaking the periodic spacing of a regular grid so that grating lobes and spatial-aliasing artefacts are spread into a diffuse sidelobe floor instead of forming strong false images. Irregular geometries trade a slightly higher broadband sidelobe level for the removal of the discrete grating lobes that periodic arrays produce above their aliasing frequency.','An irregular array places microphones unevenly on purpose. Even spacing can create strong false images at high frequencies. Uneven spacing breaks up those false peaks. Instead the errors spread into a low, even background. This keeps the real source clear at high frequencies.','Avoids grating lobes and spatial aliasing by breaking periodic element spacing.','Used in acoustic-camera arrays designed for a wide frequency range without false hot spots.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Array geometry','Sparse array','Grating lobe','Spatial aliasing','Sidelobe']::text[],ARRAY['Believing irregular spacing removes sidelobes rather than reshaping them','Confusing an irregular layout with a random, unoptimized one','Ignoring the raised broadband sidelobe floor it trades for']::text[],ARRAY['Suppressing grating lobes in a high-frequency map','Designing an array to avoid false hot spots','Comparing a grid and an irregular layout for aliasing']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Irregular array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a417f980-ed35-57ee-9902-1d66803a47c3','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a417f980-ed35-57ee-9902-1d66803a47c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a417f980-ed35-57ee-9902-1d66803a47c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f361e365-e08b-5b56-8b54-178702d84b8f','Spatial resolution','The smallest separation between two sound sources at which an array can still show them as distinct in an acoustic image, set mainly by the beamformer main-lobe width. For a planar array imaging a plane at standoff distance L, resolution scales roughly as the wavelength times the standoff divided by the array aperture, so it improves with larger aperture and higher frequency and worsens with distance.','Spatial resolution is how close two sources can be and still look separate. A wider array gives finer detail. Higher-pitched sound also helps. Moving farther away makes detail coarser. In short, resolution gets better with size and frequency.','Quantifies how well an array separates nearby sources in the image.','Technicians expect coarser maps at low frequency and long standoff, and finer maps up close.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Angular resolution','Aperture','Rayleigh criterion','Main lobe','Beamwidth']::text[],ARRAY['Expecting fine detail at low frequencies where the wavelength is large','Ignoring that standoff distance coarsens the resolvable spacing','Confusing resolution with the number of pixels in the display']::text[],ARRAY['Predicting whether two nearby leaks will show as one blob','Choosing a closer standoff to sharpen a map','Explaining why a bass source maps as a broad smear']::text[],'intermediate','R ≈ λ·L / D','The smallest resolvable spacing is about the wavelength times the source distance, divided by the array aperture.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f361e365-e08b-5b56-8b54-178702d84b8f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f361e365-e08b-5b56-8b54-178702d84b8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f361e365-e08b-5b56-8b54-178702d84b8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09d97156-41e4-503d-8375-9b7cacbe00cb','Angular resolution','The smallest angular separation between two sources that an array can distinguish, governed by the beamformer main-lobe width, which for an aperture of size D is on the order of the wavelength divided by the aperture. Angular resolution therefore improves with larger aperture and higher frequency; expressed as a beamwidth it is often quoted at the half-power points of the main lobe.','Angular resolution is the smallest angle between two sources you can still tell apart. A bigger array sees finer angles. Higher-pitched sound also sharpens the angle. It is often given as a beam width. A small array gives a wide, blurry beam.','Quantifies the array''s ability to separate sources by direction.','Used to predict whether two nearby machine parts will appear as one blob or two.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Spatial resolution','Beamwidth','Aperture','Main lobe','Direction-of-arrival estimation']::text[],ARRAY['Assuming resolution is fixed rather than frequency-dependent','Reading the main-lobe peak position as the resolution limit','Forgetting that noise and sidelobes worsen the practical limit']::text[],ARRAY['Estimating whether two motors can be told apart by angle','Comparing beamwidth across frequency bands','Sizing an array to reach a target angular resolution']::text[],'intermediate','Δθ ≈ λ / D  (radians)','The smallest resolvable angle is roughly the wavelength divided by the array aperture, expressed in radians.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angular resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09d97156-41e4-503d-8375-9b7cacbe00cb','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09d97156-41e4-503d-8375-9b7cacbe00cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09d97156-41e4-503d-8375-9b7cacbe00cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '46ded4b3-447e-505d-9b3a-78c6789eef74','Dynamic range of acoustic image','The usable level span in an acoustic map between the strongest displayed source and the weakest source that can still be shown reliably, limited chiefly by the array''s maximum sidelobe level. Sources weaker than the peak by more than this margin are masked by the sidelobes of the dominant source, so a low maximum-sidelobe geometry is needed to reveal quiet sources near loud ones.','Dynamic range is the gap between the loudest and the faintest source a map can show. Side peaks from a loud source can hide quiet ones nearby. So the array''s side-peak level sets this limit. A cleaner array shows fainter sources. This matters when a quiet fault sits near a loud part.','Describes how faint a source can be and still appear beside a dominant one.','Technicians raise the map''s display floor to hide sidelobes, trading away faint-source visibility.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sidelobe','Maximum sidelobe level','Beamforming map','Source power map','Array geometry']::text[],ARRAY['Mistaking a sidelobe of a loud source for a separate quiet source','Setting the display range wider than the array''s sidelobe level supports','Assuming more averaging raises the usable dynamic range without limit']::text[],ARRAY['Trying to see a quiet leak next to a loud fan','Setting a display floor to suppress sidelobe clutter','Choosing an array with lower sidelobes for faint sources']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic range of acoustic image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '46ded4b3-447e-505d-9b3a-78c6789eef74','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='46ded4b3-447e-505d-9b3a-78c6789eef74') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='46ded4b3-447e-505d-9b3a-78c6789eef74');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d80b081-d787-5ff1-af13-4f5eef0f44c5','Acoustic beamforming','The application of array beamforming to airborne sound, in which the signals from a microphone array are time-aligned or phase-aligned and summed for each assumed source direction or location so that sound from the steered point adds coherently while sound from elsewhere partially cancels. Scanning the steering point across a region yields an estimate of source strength versus position, the basis of acoustic-camera imaging and source localization.','Acoustic beamforming combines many microphone signals to listen in one direction. Signals from the chosen spot are lined up in time and added. They reinforce each other. Sound from other directions does not line up and fades. Scanning many directions builds a picture of where sound comes from.','Forms a steerable directional response from a fixed array to locate and map sound sources.','The core method inside acoustic cameras and noise-source mapping tools.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Conventional beamforming','Steered response power','Beamforming map','Steering delay','Acoustic source localization']::text[],ARRAY['Expecting good low-frequency resolution from a small array','Reading sidelobes as extra sources','Ignoring that reflections create ghost sources in the map']::text[],ARRAY['Mapping the loudest region of a running engine','Building a source image by scanning a plane','Finding an air leak on a pressurized panel']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d80b081-d787-5ff1-af13-4f5eef0f44c5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d80b081-d787-5ff1-af13-4f5eef0f44c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d80b081-d787-5ff1-af13-4f5eef0f44c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57bd1b5b-4408-5e85-abe3-acc177dfc703','Beamforming map','A spatial image produced by evaluating a beamformer''s output power at every point of a scan region and displaying the result as a colour or contour map, so peaks mark the estimated locations and relative strengths of sound sources. It is usually overlaid on an optical photograph in an acoustic camera; its detail and sidelobe pattern follow directly from the array geometry and frequency.','A beamforming map is a picture of where sound is strongest. The beamformer is aimed at each point of a scene. Its output power fills in a colour map. Bright spots mark likely sources. It is often laid over a photo of the object.','Visualizes beamformer output power across space to reveal source locations.','The on-screen result a technician reads from an acoustic camera.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Source map','Source power map','Acoustic image','Acoustic beamforming','Scanning plane']::text[],ARRAY['Reading every coloured blob as a real source rather than a sidelobe','Comparing maps at different frequencies without noting resolution changes','Trusting absolute levels without proper calibration']::text[],ARRAY['Overlaying a colour map on a photo of a gearbox','Watching peaks move as the scan frequency changes','Pointing a repair to the brightest region of a map']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamforming map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57bd1b5b-4408-5e85-abe3-acc177dfc703','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57bd1b5b-4408-5e85-abe3-acc177dfc703') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57bd1b5b-4408-5e85-abe3-acc177dfc703');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33303aac-5c2f-5b42-87de-8372662a2fc8','Source map','A display that indicates the estimated positions, and often relative strengths, of the sound sources inferred from array measurements, typically shown as hot spots overlaid on an image of the object under test. A source map may come from beamforming, acoustic holography, or inverse methods; it answers where the sound originates rather than giving a calibrated field value at every point.','A source map shows where sounds are coming from. Hot spots mark the likely sources. It is usually laid over a photo of the object. The map can come from several methods. It tells you the place, not an exact level everywhere.','Communicates inferred source locations to the user.','Used to point a technician straight at the noisy part of a machine or product.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Beamforming map','Source power map','Acoustic image','Acoustic source localization','Near-field acoustic holography']::text[],ARRAY['Assuming the brightest spot is always the true dominant source','Ignoring which method made the map and its limits','Reading position more precisely than the array''s resolution allows']::text[],ARRAY['Marking the noisiest parts on a photo of an appliance','Comparing source maps before and after a fix','Guiding a repair to a mapped hot spot']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33303aac-5c2f-5b42-87de-8372662a2fc8','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33303aac-5c2f-5b42-87de-8372662a2fc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33303aac-5c2f-5b42-87de-8372662a2fc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4e26c25-4501-5e82-97e8-a58912d000e0','Acoustic image','A two- or three-dimensional visual representation of an acoustic quantity — source strength, sound intensity, or pressure — mapped over space and usually overlaid on an optical view of the scene. The acoustic image is the output artefact of imaging methods such as beamforming or holography; its spatial detail is limited by the array aperture and by diffraction, so it is inherently blurrier than the optical image beneath it.','An acoustic image is a picture made from sound instead of light. Colours show how strong the sound is at each place. It is usually shown on top of a normal photo. Sound waves are large, so the picture is blurry. It still shows clearly where sound is loudest.','Turns spatial sound measurements into a picture a user can interpret.','The overlay a technician views on an acoustic camera screen.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Beamforming map','Source map','Spatial resolution','Sound intensity','Acoustic beamforming']::text[],ARRAY['Expecting an acoustic image to be as sharp as the optical photo','Ignoring the frequency at which the image was formed','Treating colour as purely qualitative when it is calibrated']::text[],ARRAY['Viewing a sound overlay on a camera photo of a pump','Explaining why the sound picture looks fuzzy','Selecting a frequency band to sharpen the image']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4e26c25-4501-5e82-97e8-a58912d000e0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4e26c25-4501-5e82-97e8-a58912d000e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4e26c25-4501-5e82-97e8-a58912d000e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52089a20-2e03-5319-8ff9-39941800b8b5','Scanning plane','The virtual surface, usually planar and placed at the assumed distance of the sources, over which a beamformer evaluates its output at a grid of candidate points to build a source map. Choosing the scanning plane''s distance and extent correctly is essential: an incorrect standoff mislocates and defocuses sources, because the steering delays are computed for points on that plane.','The scanning plane is the surface the beamformer searches over. It is usually flat and set at the source''s distance. The beamformer tests many points on it. Setting the wrong distance blurs and misplaces sources. So the plane must match where the object really is.','Defines where in space the beamformer looks for sources.','The operator sets the scanning-plane distance to the measured object standoff before imaging.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Scan grid','Beamforming map','Steering delay','Source power map','Look direction']::text[],ARRAY['Leaving the scan distance at a default that does not match the object','Making the plane too small and clipping real sources','Assuming a flat plane suits a deeply three-dimensional object']::text[],ARRAY['Entering the measured standoff before mapping a panel','Extending the plane to cover a whole machine','Refocusing after mislocated sources reveal a wrong distance']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scanning plane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52089a20-2e03-5319-8ff9-39941800b8b5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52089a20-2e03-5319-8ff9-39941800b8b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52089a20-2e03-5319-8ff9-39941800b8b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2c6df2b-a4d9-5411-835b-ede164074521','Source power map','A beamforming output image in which each scan point is assigned the estimated acoustic source power, or a related level, that the array attributes to that location, so the map''s values approximate how much sound each region radiates. Proper deconvolution or calibration is required before the displayed power is quantitative, because raw beamformer output includes the array''s point-spread function and sidelobes.','A source power map shows how much sound each spot gives off. The beamformer estimates a power value for every point. Brighter means more sound power. Raw maps are smeared by the array''s own pattern. Cleanup steps are needed before the numbers are trusted.','Turns beamformer output into an estimate of radiated power versus location.','Used to rank which parts of a product radiate the most noise.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Beamforming map','Source map','Deconvolution','Point spread function','Steered response power']::text[],ARRAY['Reading raw beamformer power as calibrated source power','Ignoring the point-spread blur before deconvolution','Comparing power across frequencies without matching resolution']::text[],ARRAY['Ranking radiating panels on an appliance by power','Applying deconvolution before quoting source levels','Comparing power maps before and after a design change']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source power map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2c6df2b-a4d9-5411-835b-ede164074521','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2c6df2b-a4d9-5411-835b-ede164074521') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2c6df2b-a4d9-5411-835b-ede164074521');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86cc6418-9d6a-5a02-9520-4ee1796112f8','Steered response power','A localization function formed by steering a beamformer to each candidate location or direction and evaluating its output power, with the peak of this function taken as the source estimate. In its common form the steered power at a direction is the quadratic product of the steering vector with the array cross-spectral (covariance) matrix; the phase-transform-weighted variant, SRP-PHAT, improves robustness in reverberation.','Steered response power aims the beamformer at each possible spot. It then measures the output power there. The spot with the most power is the likely source. Doing this over many spots makes a search surface. The highest peak marks the source.','Provides a scanning objective whose peak locates the source.','Used in talker localization and noise mapping, often as SRP-PHAT in echoey rooms.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Conventional beamforming','Beamforming map','Direction-of-arrival estimation','Cross-spectral matrix','Scan grid']::text[],ARRAY['Picking a sidelobe peak instead of the true main peak','Using plain SRP in strong reverberation where PHAT weighting is needed','Using a scan grid so coarse it steps over the true peak']::text[],ARRAY['Locating a talker in a reverberant room','Scanning a plane to find the loudest machine part','Choosing SRP-PHAT to resist room reflections']::text[],'advanced','P(θ) = wᴴ(θ) R w(θ),  w(θ) = a(θ)/M','The steered power in a direction is the steering vector times the array covariance matrix times the steering vector, giving the output power for that look direction.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steered response power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86cc6418-9d6a-5a02-9520-4ee1796112f8','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86cc6418-9d6a-5a02-9520-4ee1796112f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86cc6418-9d6a-5a02-9520-4ee1796112f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77a3c3f0-bdab-554e-bacc-c76239f1d576','Conventional beamforming','The baseline array method, also called delay-and-sum beamforming, in which each microphone signal is delayed or phase-shifted to compensate the propagation time from the steered point and the channels are summed, so a source at that point adds coherently. Its beam pattern and resolution are fixed by the array geometry and frequency and are independent of the data, making it robust but limited in sidelobe suppression compared with adaptive methods.','Conventional beamforming lines up the microphone signals in time and adds them. Each channel gets a delay to match the chosen direction. A source there adds up strongly. Sound from elsewhere does not line up and shrinks. It is simple and steady but has higher side peaks.','Forms a fixed, data-independent directional response as the baseline for imaging.','The default mode in most acoustic cameras for robust broadband mapping.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic beamforming','Steering delay','Steered response power','MVDR beamforming','Beamforming map']::text[],ARRAY['Expecting adaptive-level sidelobe suppression from a fixed beamformer','Assuming resolution can beat the aperture limit','Forgetting that per-channel delays must match the true geometry']::text[],ARRAY['Making a robust broadband map of a machine','Comparing a fixed beamformer with an adaptive one','Teaching how delay-and-sum builds a directional response']::text[],'intermediate','y(t) = (1/M) Σₘ xₘ(t − τₘ)','The output is the average of the microphone signals after each is delayed by its steering delay, so a source in the look direction adds in phase.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conventional beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77a3c3f0-bdab-554e-bacc-c76239f1d576','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77a3c3f0-bdab-554e-bacc-c76239f1d576') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77a3c3f0-bdab-554e-bacc-c76239f1d576');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4005bd42-f60e-59ad-a75e-32ad45896350','MVDR beamforming','An adaptive beamformer, minimum variance distortionless response, that minimizes total output power while constraining unity gain toward the look direction, so it passes the desired direction undistorted and places nulls on other, interfering sources. The optimal weights use the inverse of the array covariance matrix; performance depends on accurate covariance estimation and steering-vector knowledge, and it degrades under mismatch unless diagonally loaded.','MVDR is a smarter beamformer that adapts to the sound. It keeps full gain on the chosen direction. At the same time it cuts power from other directions. This places nulls on interfering sources. It needs good data and breaks down if the aim is slightly off.','Suppresses interference and sharpens the response beyond a fixed beamformer.','Used where interfering sources must be nulled, given enough data to estimate the covariance.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Capon beamforming','Conventional beamforming','Adaptive beamforming','Direction-of-arrival estimation','Diagonal loading']::text[],ARRAY['Using too few snapshots to estimate the covariance matrix','Ignoring steering-vector mismatch that cancels the wanted source','Skipping diagonal loading and getting an unstable solution']::text[],ARRAY['Nulling a steady interferer while keeping a target source','Comparing adaptive and fixed beamformer resolution','Adding diagonal loading to stabilize a weak-data solution']::text[],'advanced','w = R⁻¹a / (aᴴR⁻¹a)','The weights are the inverse covariance matrix times the steering vector, scaled so the look-direction gain stays at one.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MVDR beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4005bd42-f60e-59ad-a75e-32ad45896350','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4005bd42-f60e-59ad-a75e-32ad45896350') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4005bd42-f60e-59ad-a75e-32ad45896350');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48b840b5-a74e-5df1-a24f-6cc679cabc3d','Capon beamforming','The minimum-variance spectral estimator introduced by Capon, mathematically equivalent to the MVDR beamformer, which forms a high-resolution estimate of source power versus direction as the reciprocal of the steering vector applied to the inverse covariance matrix. Because it adapts to the data, Capon''s method resolves closely spaced sources better than conventional beamforming but is sensitive to covariance-estimation error and steering-vector mismatch.','Capon''s method is the same idea as MVDR. It estimates sound power for each direction. It adapts to the data to sharpen the result. This separates sources that sit close together. It needs good data and an accurate aim to work well.','Gives a high-resolution, data-adaptive power-versus-direction estimate.','Used in high-resolution source localization when data support a good covariance estimate.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['MVDR beamforming','Conventional beamforming','Direction-of-arrival estimation','Cross-spectral matrix','Adaptive beamforming']::text[],ARRAY['Treating Capon and MVDR as different methods rather than equivalent','Trusting sharp peaks when the covariance estimate is poor','Ignoring steering-vector mismatch that biases the estimate']::text[],ARRAY['Separating two closely spaced sources on a map','Comparing Capon peaks with conventional beam peaks','Checking data support before trusting a sharp estimate']::text[],'advanced','P(θ) = 1 / (aᴴ(θ) R⁻¹ a(θ))','The estimated power in a direction is one divided by the steering vector times the inverse covariance matrix times the steering vector.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capon beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48b840b5-a74e-5df1-a24f-6cc679cabc3d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48b840b5-a74e-5df1-a24f-6cc679cabc3d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48b840b5-a74e-5df1-a24f-6cc679cabc3d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd330f45a-8c30-59e5-9662-83c41063472a','ESPRIT','Estimation of Signal Parameters via Rotational Invariance Techniques, a subspace direction-finding method that exploits a translational invariance between two identical, displaced subarrays. The signal subspaces of the two subarrays are related by a rotation whose eigenvalues encode the source directions, so ESPRIT recovers directions of arrival from an eigen-decomposition without scanning a spatial spectrum, at lower cost than a peak-search method.','ESPRIT finds source directions using two matched sets of microphones. The two sets sit a fixed distance apart. Their signals differ by a simple phase shift. That shift depends on the source angle. ESPRIT reads the angles straight from the math, without scanning.','Estimates directions of arrival directly from subspace structure, avoiding a spatial search.','Used for efficient, high-resolution direction finding with a suitable displaced-subarray geometry.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Direction-of-arrival estimation','Subspace method','MUSIC algorithm','Array geometry','Angular resolution']::text[],ARRAY['Applying it without the required matched, displaced subarray structure','Assuming it beats the noise limit at very low signal-to-noise','Overestimating the number of sources it can resolve']::text[],ARRAY['Estimating several source angles without a spatial scan','Using paired subarrays to exploit rotational invariance','Comparing subspace direction finders on the same data']::text[],'advanced','A₂ = A₁Φ,  Φ = diag(e^{jω(Δ·sinθₖ)/c});  θₖ from eig(Φ)','Two identical subarrays displaced by a fixed spacing have array manifolds that differ by a diagonal rotation; each source direction follows from the phase of an eigenvalue of that rotation.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ESPRIT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd330f45a-8c30-59e5-9662-83c41063472a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d330f45a-8c30-59e5-9662-83c41063472a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d330f45a-8c30-59e5-9662-83c41063472a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4d27367-b23f-5d53-b124-d847a761d4e0','Direction-of-arrival estimation','The process of estimating the angular directions from which one or more wavefronts reach an array, using the inter-element phase or time differences captured in the array data. Methods range from beam-scanning and steered-power search to subspace estimators such as MUSIC and ESPRIT; performance is bounded by aperture, signal-to-noise ratio, snapshot count, and source separation relative to the beamwidth.','This method finds the angle that a sound comes from. It uses the tiny time gaps between the mics. Some methods scan each angle for a peak. Others solve for the angles at once. A bigger array and cleaner sound help a lot.','Yields source bearings from array data for localization and tracking.','Used in source localization, tracking, and as a front end to beam steering.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic source localization','Steered response power','MVDR beamforming','ESPRIT','MUSIC algorithm']::text[],ARRAY['Trying to resolve sources closer than the beamwidth allows','Ignoring how few snapshots degrade subspace methods','Confusing a bearing angle with a full source position']::text[],ARRAY['Estimating the bearing of a noise source','Feeding bearings to a beam-steering front end','Tracking a moving source''s angle over time']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direction-of-arrival estimation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4d27367-b23f-5d53-b124-d847a761d4e0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4d27367-b23f-5d53-b124-d847a761d4e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4d27367-b23f-5d53-b124-d847a761d4e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43695731-3db8-5ab1-a7c0-46ca1ccfe639','Acoustic source localization','The determination of the spatial position — direction, and where possible range — of one or more sound sources from measurements made by one or more microphones or arrays. Techniques include time-difference-of-arrival, beamforming and steered-response-power search, and inverse or holographic methods; accuracy depends on array aperture and geometry, bandwidth, signal-to-noise ratio, and the reflections in the acoustic environment.','Acoustic source localization works out where a sound comes from. It uses microphone signals to find direction and sometimes distance. Some methods compare arrival times between microphones. Others scan space for the strongest response. Reflections and noise make the job harder.','Locates sound sources in space for diagnosis, capture, or monitoring.','Used in noise troubleshooting, machine diagnostics, security, and voice capture.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Direction-of-arrival estimation','Steered response power','Time difference of arrival','Acoustic beamforming','Source map']::text[],ARRAY['Assuming a single microphone can localize like an array','Ignoring reflections that create false or shifted source positions','Expecting range accuracy from a small-aperture array']::text[],ARRAY['Finding a rattle inside a running machine','Locating a talker for automatic camera pointing','Tracing an intermittent noise in a room']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43695731-3db8-5ab1-a7c0-46ca1ccfe639','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43695731-3db8-5ab1-a7c0-46ca1ccfe639') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43695731-3db8-5ab1-a7c0-46ca1ccfe639');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39d28acd-1eef-53e3-9418-7b396129b6b7','Spatial filtering','The array-processing operation that discriminates signals by their direction of arrival, passing sound from wanted directions while attenuating sound from others, achieved by weighting and summing the element signals. Beamforming is the classic spatial filter; the shape of the directional response — main lobe, nulls, and sidelobes — is the array''s spatial frequency response, analogous to a temporal filter acting in the angle domain.','Spatial filtering picks sounds by the direction they come from. Wanted directions pass through. Other directions are turned down. It works by weighting and adding the microphone signals. It is like a filter, but for angle instead of pitch.','Separates or enhances sources by direction rather than by frequency.','Used to focus on a talker or a machine part while rejecting off-axis noise.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic beamforming','Look direction','Null steering','Spatial resolution','Array response']::text[],ARRAY['Confusing spatial filtering with ordinary frequency filtering','Expecting sharp nulls from a small or low-frequency array','Ignoring that reflections leak wanted signals in from other directions']::text[],ARRAY['Rejecting off-axis noise while capturing a talker','Steering a null onto a fixed interferer','Isolating one machine part from nearby sources']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial filtering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39d28acd-1eef-53e3-9418-7b396129b6b7','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39d28acd-1eef-53e3-9418-7b396129b6b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39d28acd-1eef-53e3-9418-7b396129b6b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a62a3ac-6929-5899-aa00-f090daed34d9','Virtual microphone','A conceptual microphone realized by a beamformer''s output, which behaves as if a single directional microphone were pointed at a chosen location or direction even though the signal is synthesized from a whole array. The virtual microphone''s directivity, look direction, and even position can be changed in software after capture, unlike a physical microphone fixed at recording time.','A virtual microphone is made by combining an array''s signals. It acts like one microphone aimed at a chosen spot. But no real microphone sits there. Its aim and pattern are set in software. You can even change them after recording.','Gives a steerable, software-defined pickup from a fixed array.','Used to extract a talker or isolate a source from an array recording after the fact.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic beamforming','Look direction','Steering delay','Spatial filtering','Phased microphone array']::text[],ARRAY['Thinking a virtual microphone captures more than the array physically resolves','Assuming perfect isolation rather than partial rejection','Forgetting its quality still depends on array geometry and frequency']::text[],ARRAY['Pulling one talker out of an array recording','Re-aiming pickup in software after capture','Placing several virtual pickups on different sources']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a62a3ac-6929-5899-aa00-f090daed34d9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a62a3ac-6929-5899-aa00-f090daed34d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a62a3ac-6929-5899-aa00-f090daed34d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e9ec4ee-fdac-5079-84ef-9cc9d1b402bc','Steering delay','The time delay applied to an individual microphone channel to compensate the propagation-time difference from a chosen look point, so that after delaying, a signal from that point is aligned across all channels before summing. For a plane wave from a direction given by a unit vector, the delay at an element equals the projection of its position onto that direction divided by the speed of sound.','A steering delay is a small time shift added to one microphone. It cancels the extra travel time from the aimed spot. After the shift, that spot''s signal lines up across channels. Adding them then makes it strong. Each microphone gets its own delay.','Time-aligns element signals for the chosen look direction so they sum coherently.','Computed per element from the geometry and standoff before summing in a beamformer.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Conventional beamforming','Look direction','Steering vector','Scanning plane','Acoustic beamforming']::text[],ARRAY['Using a plane-wave delay when the source is in the near field','Rounding delays too coarsely and smearing high frequencies','Assuming a fixed speed of sound despite temperature changes']::text[],ARRAY['Computing per-channel delays for a chosen look point','Switching to near-field delays for a close source','Correcting delays after a temperature change shifts the speed of sound']::text[],'intermediate','τₘ = (rₘ · û) / c','An element''s steering delay is the dot product of its position and the look-direction unit vector, divided by the speed of sound.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steering delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e9ec4ee-fdac-5079-84ef-9cc9d1b402bc','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e9ec4ee-fdac-5079-84ef-9cc9d1b402bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e9ec4ee-fdac-5079-84ef-9cc9d1b402bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77315538-8e42-55b6-9ef9-3a91da8224cd','Look direction','The direction, or point, toward which a beamformer is currently steered, defining where its main lobe of maximum sensitivity is aimed and hence which source it favours. The look direction sets the steering delays or weights; sources on it add coherently, while the response toward other directions is given by the array''s beam pattern relative to that look direction.','The look direction is where the beamformer is aimed. Its most sensitive spot points that way. Sound from there adds up strongly. The look direction sets each channel''s delay. Changing it re-aims the array.','Specifies the target direction that defines the beamformer''s steering.','The operator or algorithm sets the look direction to the source of interest.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Steering delay','Spatial filtering','Acoustic beamforming','Scan grid','Array response']::text[],ARRAY['Confusing the look direction with the array''s physical facing','Assuming only the look direction contributes to the output','Leaving the look direction fixed while the source moves']::text[],ARRAY['Aiming a beamformer at a chosen talker','Sweeping the look direction across a scan grid','Re-aiming as a tracked source moves']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Look direction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77315538-8e42-55b6-9ef9-3a91da8224cd','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77315538-8e42-55b6-9ef9-3a91da8224cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77315538-8e42-55b6-9ef9-3a91da8224cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ae0278a-a10b-53b8-8ade-1cc7760c3e77','Scan grid','The discrete set of candidate directions or spatial points at which a beamformer evaluates its output to build a source map or steered-response surface. The grid spacing must be fine enough to sample the main lobe so the true peak is not stepped over, while its extent and dimensionality — a two-dimensional plane or a three-dimensional volume — set the mapped region and the computational load.','A scan grid is the list of points the beamformer checks. It aims at each point in turn. The results fill in a map. The points must be close enough to catch the real peak. More points cost more computing time.','Defines the sampling of space over which source estimates are computed.','The operator sets grid extent and spacing to cover the object at adequate resolution.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Scanning plane','Steered response power','Beamforming map','Look direction','Spatial resolution']::text[],ARRAY['Using a grid so coarse it steps over the true peak','Making the grid huge and slowing computation needlessly','Assuming grid spacing finer than the array resolution adds real detail']::text[],ARRAY['Setting grid spacing to sample the main lobe','Extending the grid to cover a whole machine','Trading grid density against computation time']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scan grid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ae0278a-a10b-53b8-8ade-1cc7760c3e77','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ae0278a-a10b-53b8-8ade-1cc7760c3e77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ae0278a-a10b-53b8-8ade-1cc7760c3e77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7cd12bd6-1105-51af-a73e-0e4a35268f54','Array response','The complex, direction- and frequency-dependent output of an array to a unit-amplitude plane wave, equal to the weighted sum of the element responses; its magnitude versus angle is the beam pattern, showing the main lobe, sidelobes, and nulls. The array response is the spatial transfer function of the array-and-weights combination and fully characterizes its directional and spectral selectivity.','The array response tells how strongly the array reacts to each direction. It depends on direction and on frequency. Its size versus angle is the beam pattern. That pattern has a main lobe and side lobes. The weights and layout shape it.','Characterizes the array''s directional and frequency selectivity.','Engineers plot the array response to predict resolution and sidelobe behaviour.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Beam pattern','Sidelobe','Main lobe','Steering vector','Spatial filtering']::text[],ARRAY['Reading the response at one frequency as valid for all frequencies','Ignoring sidelobes when judging selectivity','Confusing the whole array response with a single element''s response']::text[],ARRAY['Plotting the beam pattern before a measurement','Checking sidelobe levels against a target','Comparing array responses across frequency bands']::text[],'advanced','B(θ) = wᴴ a(θ) = Σₘ wₘ* e^{jωτₘ(θ)}','The array response in a direction is the weighted sum of the element steering phases, giving the complex gain toward that direction.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7cd12bd6-1105-51af-a73e-0e4a35268f54','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7cd12bd6-1105-51af-a73e-0e4a35268f54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7cd12bd6-1105-51af-a73e-0e4a35268f54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95e12f53-e9bc-53d2-bb44-15ac6714e5b3','3D beamforming','Beamforming that localizes sources in three-dimensional space, estimating both direction and range, or full three-axis position, rather than a single bearing, typically using a volumetric or spherical array or a planar array scanned over depth. It supports mapping sources onto three-dimensional object models and resolving depth-separated sources that a two-dimensional map would overlap.','3D beamforming locates sound in three dimensions. It finds direction and distance, not just an angle. It usually needs a 3D or spherical array. The result can be laid on a 3D model. It can separate sources that sit at different depths.','Extends imaging from a flat map to full spatial source positions.','Used to map noise onto a 3D model of a car cabin or machine.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Spherical array','Volumetric array','Acoustic beamforming','Scanning plane','Acoustic source localization']::text[],ARRAY['Expecting good depth resolution from a flat, small-aperture array','Assuming a 2D map''s overlaps are resolved without a 3D array','Ignoring the higher computation of a volumetric scan']::text[],ARRAY['Mapping noise onto a 3D model of a cabin','Separating sources at different depths','Scanning a volume rather than a single plane']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='3D beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95e12f53-e9bc-53d2-bb44-15ac6714e5b3','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95e12f53-e9bc-53d2-bb44-15ac6714e5b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95e12f53-e9bc-53d2-bb44-15ac6714e5b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89b912a2-f90b-5703-99da-c5f5ba3c19ff','Moving-source beamforming','Beamforming adapted to sources in motion relative to the array, in which the steering delays and integration are made time-varying to track the changing source position and to remove the Doppler and de-focusing effects that stationary-source processing would suffer. It is used for vehicles, aircraft, and trains passing an array, often combining a motion model with a rotating or scanning focus.','Moving-source beamforming follows a source that is moving. The aim point changes over time to track it. This keeps the image sharp instead of smeared. It also corrects pitch shifts from motion. It suits cars, planes, and trains passing by.','Keeps focus on a source that moves during the measurement.','Used in pass-by tests of vehicles and in aircraft flyover noise studies.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Pass-by noise imaging','Rotating-source beamforming','Doppler effect','Acoustic beamforming','Order tracking beamforming']::text[],ARRAY['Using stationary processing and getting a smeared, mislocated image','Ignoring the Doppler shift of a fast-moving source','Feeding an inaccurate motion path into the focus model']::text[],ARRAY['Imaging a car during a drive-by test','Tracking an aircraft on a flyover','De-smearing a train passing the array']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving-source beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89b912a2-f90b-5703-99da-c5f5ba3c19ff','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89b912a2-f90b-5703-99da-c5f5ba3c19ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89b912a2-f90b-5703-99da-c5f5ba3c19ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ab37546-58d3-59ce-9a6d-f06d389e6722','Order tracking beamforming','Beamforming synchronized to the rotational speed of a machine so that imaging is referenced to shaft orders — harmonics of the rotation rate — rather than to fixed frequencies. Using a tachometer or reference signal, it maps the sources associated with specific orders even as the speed varies, isolating rotation-related noise from broadband or fixed-frequency content.','Order tracking beamforming ties the image to a machine''s turning speed. It follows the shaft''s harmonics, called orders, not fixed pitches. A speed sensor keeps it in step as the machine speeds up or slows. This shows which parts make rotation-related noise. It separates that from steady background sound.','Maps noise tied to specific rotational orders under changing speed.','Used on engines, gearboxes, and rotating machinery with a tachometer reference.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Rotating-source beamforming','Moving-source beamforming','Order analysis','Tachometer','Acoustic beamforming']::text[],ARRAY['Imaging at fixed frequencies and blurring orders when the speed varies','Omitting a reliable tachometer or trigger reference','Confusing a rotational order with a fixed-frequency tone']::text[],ARRAY['Mapping a specific gear order during run-up','Tracking engine orders as speed changes','Separating an order from steady background noise']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Order tracking beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ab37546-58d3-59ce-9a6d-f06d389e6722','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ab37546-58d3-59ce-9a6d-f06d389e6722') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ab37546-58d3-59ce-9a6d-f06d389e6722');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '627c10ca-1371-598f-a6d4-1a0f157631cd','Pass-by noise imaging','Acoustic imaging of a vehicle or object as it moves past a stationary array, combining moving-source beamforming with a known trajectory and speed so that noise sources on the passing object are localized and their contributions quantified. It underlies exterior pass-by noise testing, where source maps reveal which parts — tyres, exhaust, engine — dominate the regulated level.','Pass-by noise imaging maps a vehicle as it drives past microphones. The array tracks the moving car. It shows which parts make the most noise. Tyres, exhaust, and engine can be told apart. It supports the drive-by noise tests carmakers must pass.','Localizes and ranks noise sources on a passing vehicle.','Used in automotive pass-by noise labs and on outdoor test tracks.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Moving-source beamforming','Rotating-source beamforming','Source map','Acoustic beamforming','Tyre noise']::text[],ARRAY['Ignoring the vehicle''s exact speed and path in the focus model','Blaming a single part when tyres and road also contribute','Using too short an aperture for the resolution needed']::text[],ARRAY['Ranking noise sources during a vehicle drive-by','Separating tyre from exhaust noise on a test track','Checking a car against a drive-by noise limit']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pass-by noise imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '627c10ca-1371-598f-a6d4-1a0f157631cd','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='627c10ca-1371-598f-a6d4-1a0f157631cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='627c10ca-1371-598f-a6d4-1a0f157631cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af48c616-a7da-55a8-a92a-e2c72701fe45','Rotating-source beamforming','Beamforming adapted to sources that rotate, such as fan blades, propellers, or tyres, in which the focus follows the angular motion — often in a rotating reference frame locked to the shaft — so that a blade or sector can be imaged without the smearing that fixed-focus processing causes. It is closely tied to order-based analysis of the rotating component.','Rotating-source beamforming follows sound from spinning parts. Fans, propellers, and tyres turn too fast for a fixed image. The focus spins with the part instead. This keeps a blade or section sharp. It is often paired with order analysis.','Images sources that rotate without motion smearing.','Used on fans, propellers, turbines, and rotating tyres.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Order tracking beamforming','Moving-source beamforming','Order analysis','Acoustic beamforming','Source map']::text[],ARRAY['Using a stationary focus and smearing the spinning source','Ignoring the shaft reference needed to lock the rotating frame','Confusing blade-passing tones with unrelated fixed tones']::text[],ARRAY['Imaging one blade of a running fan','Locking the focus to a propeller shaft','Mapping tyre noise around a rotating wheel']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rotating-source beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af48c616-a7da-55a8-a92a-e2c72701fe45','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af48c616-a7da-55a8-a92a-e2c72701fe45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af48c616-a7da-55a8-a92a-e2c72701fe45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebbf07a1-1456-5e49-b685-5722254b179f','Phased array acoustics','The branch of acoustics that uses controlled phase or time relationships across an array of transducers to steer and shape a beam electronically, for either receiving — imaging and localization — or transmitting directional radiation. In airborne sound-source imaging it denotes phased microphone-array techniques; the same principle underlies phased-array ultrasonics and loudspeaker beam steering.','Phased array acoustics steers sound beams by timing, not by moving parts. Each element''s phase is set on purpose. Together they aim a beam in a chosen direction. It works for both listening and sending sound. The same idea appears in ultrasound and steered speakers.','Enables electronic beam steering and shaping with a fixed array.','Seen in microphone-array imaging, steered loudspeaker arrays, and ultrasonic testing.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phased microphone array','Acoustic beamforming','Steering delay','Array response','Look direction']::text[],ARRAY['Assuming it needs physically moving elements to steer','Ignoring spatial aliasing when element spacing is too large','Treating receive and transmit beam patterns as automatically identical']::text[],ARRAY['Steering a beam electronically without moving parts','Relating microphone imaging to ultrasonic phased arrays','Aiming a loudspeaker array by timing']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased array acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebbf07a1-1456-5e49-b685-5722254b179f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebbf07a1-1456-5e49-b685-5722254b179f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebbf07a1-1456-5e49-b685-5722254b179f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd0e4446-c6c9-53d6-9eec-a906155bd1aa','Phased microphone array','A microphone array whose channels are combined with direction-dependent phase or time weightings to beamform, used specifically for acoustic source imaging and localization. The term emphasizes the phased-array operating principle; such arrays are the sensing front end of acoustic cameras and aeroacoustic test facilities, with geometry chosen to control resolution and sidelobes over the frequency band of interest.','A phased microphone array combines many microphones with set time shifts. This lets it aim electronically at sources. It is the sensor behind acoustic cameras. The layout is chosen for good resolution and low side peaks. It is used to image where sound comes from.','Provides the beamforming sensor front end for acoustic imaging.','Used in acoustic cameras and in wind-tunnel aeroacoustic measurements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phased array acoustics','Microphone array','Acoustic beamforming','Array geometry','Beamforming map']::text[],ARRAY['Assuming any microphone cluster is a proper phased array','Ignoring calibration of per-channel phase and gain','Using a geometry unsuited to the target frequency band']::text[],ARRAY['Imaging airframe noise in a wind tunnel','Serving as the sensor in an acoustic camera','Choosing array geometry for a target frequency band']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd0e4446-c6c9-53d6-9eec-a906155bd1aa','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd0e4446-c6c9-53d6-9eec-a906155bd1aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd0e4446-c6c9-53d6-9eec-a906155bd1aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c734bf50-9620-529c-8bb1-5440f0c7fc41','Acoustic array processing','The discipline of jointly processing the signals from multiple acoustic sensors to extract spatial information — source direction and position, source separation and enhancement, or sound-field reconstruction — using methods such as beamforming, subspace direction finding, and inverse imaging. It applies array signal-processing theory to airborne and underwater sound, linking sensor geometry, statistical signal models, and the physics of wave propagation.','Acoustic array processing works with many microphones together. It pulls spatial facts from their combined signals. It can find directions, separate sources, or rebuild a sound field. Beamforming is one of its main tools. It joins array math with how sound travels.','The overarching framework for turning multi-sensor data into spatial acoustic information.','The field a technician draws on for localization, imaging, and array-based noise control.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic beamforming','Direction-of-arrival estimation','Microphone array','Acoustic source localization','Sound-field reconstruction']::text[],ARRAY['Reducing the whole field to a single beamforming method','Ignoring the wave-propagation model behind the algorithms','Assuming more sensors always outweigh good geometry and calibration']::text[],ARRAY['Choosing a method for a localization task','Combining beamforming with inverse imaging','Designing array geometry for a processing goal']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic array processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c734bf50-9620-529c-8bb1-5440f0c7fc41','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c734bf50-9620-529c-8bb1-5440f0c7fc41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c734bf50-9620-529c-8bb1-5440f0c7fc41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93824255-fcd1-50c2-bf66-941eb0fc4722','Acoustic deconvolution','A post-processing class of methods that removes the blurring an array''s point spread function imposes on a beamforming source map. Conventional beamforming yields a ''dirty'' map equal to the true source distribution convolved with the array response, which spreads energy into a main lobe and sidelobes. Deconvolution models this map as the point spread function operating on an unknown non-negative source distribution and inverts that relation, usually iteratively and with constraints, to recover a sharper estimate of the true source positions and strengths.','A microphone array makes a fuzzy sound map. The blur comes from the array itself. Deconvolution undoes that known blur. It leaves a sharper map. Then the real sound sources are easier to see and place.','Turns a smeared beamforming map into a cleaner estimate of where sound is really coming from, improving spatial resolution and reducing sidelobe clutter without changing the array hardware.','Applied in aeroacoustic wind-tunnel tests, pass-by vehicle testing, and machinery noise studies, where engineers run DAMAS, CLEAN-SC, or similar solvers on a beamformer''s cross-spectral output to pinpoint dominant noise sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['DAMAS','CLEAN-SC','Point spread function','Beamformer deblurring','Sidelobe suppression']::text[],ARRAY['Treating the sharpened deconvolved map as raw measured data rather than a model-based estimate','Assuming deconvolution can recover detail below the array''s fundamental resolution limit','Ignoring that a wrong point spread function model injects new artifacts into the result']::text[],ARRAY['Sharpening a wind-tunnel airframe noise map before ranking source strengths','Cleaning sidelobe clutter from a pass-by car acoustic image','Separating two close machinery noise sources on a factory beamforming map']::text[],'advanced','b = A·x,  x ≥ 0','The measured beamformer map equals the point-spread-function matrix multiplied by the unknown non-negative source-power distribution; deconvolution solves for that distribution.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic deconvolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93824255-fcd1-50c2-bf66-941eb0fc4722','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93824255-fcd1-50c2-bf66-941eb0fc4722') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93824255-fcd1-50c2-bf66-941eb0fc4722');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c739db99-c4ac-5872-b049-9aa54f39ded7','DAMAS','Deconvolution Approach for the Mapping of Acoustic Sources, an iterative deconvolution method that removes array point-spread-function effects from a beamforming map. It writes the conventional beamformer output as a linear system in which a point-spread-function matrix relates the measured ''dirty'' map to an unknown distribution of statistically independent source powers. DAMAS solves this system with a non-negative Gauss-Seidel iteration, yielding a high-resolution, low-sidelobe map. It is accurate but computationally heavy because the matrix scales with the square of the number of grid points.','DAMAS cleans up a microphone array''s sound map. It links the fuzzy map to the true sources with a set of equations. Then it solves them step by step. Source strengths must stay positive. The result is a sharp, clean map. But it can be slow on large grids.','Recovers a sharp map of independent source powers from a blurred beamforming image, so weak sources and closely spaced sources become distinguishable.','Used in wind-tunnel airframe and landing-gear noise tests and in engine and vehicle studies to rank noise sources; run on cross-spectral matrices from planar or curved microphone arrays.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic deconvolution','DAMAS2','CLEAN-SC','Point spread function','Non-negative least squares']::text[],ARRAY['Assuming DAMAS scales cheaply, when its cost and memory grow steeply with grid size','Applying it to strongly coherent sources, which violate its independent-source assumption','Stopping the iteration too early and reading a still-blurred map as final']::text[],ARRAY['Mapping airframe noise sources on a wind-tunnel wing model','Ranking dominant noise regions on a scale car in an aeroacoustic tunnel','Resolving two nearby jet noise sources that conventional beamforming merges']::text[],'advanced','A·x = b,  x ≥ 0','A point-spread-function matrix times the unknown vector of source powers equals the measured beamformer map, solved iteratively with all source powers held non-negative.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DAMAS');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c739db99-c4ac-5872-b049-9aa54f39ded7','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c739db99-c4ac-5872-b049-9aa54f39ded7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c739db99-c4ac-5872-b049-9aa54f39ded7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89f7ae47-ef18-53d2-a41f-41bcf15a35b5','DAMAS2','A faster variant of DAMAS that assumes a shift-invariant point spread function, so the blurring becomes a spatial convolution the algorithm can evaluate with fast Fourier transforms. This replaces the large explicit point-spread-function matrix of standard DAMAS with an efficient convolution kernel, cutting computation and memory dramatically. The speed comes at the cost of accuracy where the array response actually varies across the scan plane, which breaks the shift-invariance assumption.','DAMAS2 is a quicker version of DAMAS. It assumes the blur is the same everywhere on the map. That lets it use fast math tricks. So it runs much faster. But the shortcut fails when the blur really changes across the scene.','Gives most of the sharpening benefit of DAMAS at a fraction of the compute cost, enabling deconvolution on large grids or many frequency bins.','Chosen when many frequency bands or large scan grids make full DAMAS impractical, for example quick-turnaround wind-tunnel or drive-by noise mapping.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['DAMAS','Acoustic deconvolution','Point spread function','Sidelobe suppression','CLEAN-SC']::text[],ARRAY['Trusting DAMAS2 across a wide scan plane where the point spread function is not shift-invariant','Expecting identical results to full DAMAS rather than a faster approximation','Ignoring edge errors that the convolution assumption introduces near the map borders']::text[],ARRAY['Processing dozens of frequency bands quickly during a wind-tunnel campaign','Deconvolving a large scan grid where full DAMAS would exhaust memory','Producing fast preliminary source maps between test runs']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DAMAS2');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89f7ae47-ef18-53d2-a41f-41bcf15a35b5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89f7ae47-ef18-53d2-a41f-41bcf15a35b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89f7ae47-ef18-53d2-a41f-41bcf15a35b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1294bd96-80b3-5ca0-89e3-83fe2f1b599a','CLEAN-SC','CLEAN based on Spatial Source Coherence, an iterative deconvolution method that cleans a beamforming map by exploiting the fact that a source''s sidelobes are spatially coherent with its own main lobe. At each step it finds the peak in the current map, identifies the part of the cross-spectral matrix coherent with that peak, subtracts that component''s contribution (main lobe plus sidelobes), and deposits a clean marker at the peak location. Repeating this builds a clean map free of the array''s sidelobe pattern without needing an explicit point spread function model.','CLEAN-SC removes fake side spots from a sound map. A real source and its own side spots move together. The method spots the strongest peak. It strips out everything tied to that peak. Then it marks the true spot. It repeats until the map is clean.','Produces a clean, high-resolution source map by peeling off coherent sidelobes one source at a time, avoiding the need to model or invert the array point spread function.','A standard tool in aeroacoustic wind-tunnel and pass-by testing; widely built into commercial array beamforming software for locating dominant noise sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['CLEAN','DAMAS','Source coherence','Sidelobe suppression','Acoustic deconvolution']::text[],ARRAY['Assuming CLEAN-SC handles strongly coherent multiple sources without a coherent-source extension','Reading the clean-beam markers as physical source sizes rather than located points','Setting the loop gain or stopping rule poorly, so real sources are over- or under-subtracted']::text[],ARRAY['Locating airframe and slat noise sources in a wind-tunnel test','Cleaning sidelobes from a pass-by train or car acoustic map','Separating engine noise sources for a source-ranking report']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CLEAN-SC');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1294bd96-80b3-5ca0-89e3-83fe2f1b599a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1294bd96-80b3-5ca0-89e3-83fe2f1b599a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1294bd96-80b3-5ca0-89e3-83fe2f1b599a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74987643-151d-53a7-9d51-866b1c5bac5f','Coherence CLEAN-SC','An extension of CLEAN-SC aimed at correctly locating mutually coherent sources, which the original method can mislocate because it assumes each cleaned component traces to a single incoherent source. Coherence-based variants use the coherence structure of the cross-spectral matrix to group or separate components that belong to correlated sources, so interfering coherent sources are resolved to their true positions rather than smeared or displaced. The term also appears as C-CLEAN-SC in recent array-processing literature.','Plain CLEAN-SC can misplace sources that are linked in phase. This version fixes that case. It studies how the signals share coherence. Then it groups the linked parts correctly. So coherent sources land in the right spots.','Improves source localization when multiple sources are correlated, a case where standard CLEAN-SC can place a source between the true positions or drop one entirely.','Applied in research and advanced testing where coherent paths matter, such as duct or mirror-image reflections and correlated structural radiators on a test object.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['CLEAN-SC','Coherent source localization','Source coherence','Acoustic deconvolution','DAMAS']::text[],ARRAY['Assuming any CLEAN-SC run already handles coherent sources correctly','Confusing coherent-source grouping with simply adding more iterations','Overlooking that reflections create coherent images that this variant is meant to address']::text[],ARRAY['Locating two correlated structural radiators on a vibrating panel','Handling a source and its coherent floor reflection in a test cell','Resolving correlated noise paths in a research beamforming study']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherence CLEAN-SC');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74987643-151d-53a7-9d51-866b1c5bac5f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74987643-151d-53a7-9d51-866b1c5bac5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74987643-151d-53a7-9d51-866b1c5bac5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '686effe5-aa57-5c90-9f53-71c3c4b50d22','Source coherence','A frequency-dependent measure, between zero and one, of the linear statistical relationship between two signals or between two sources. The magnitude-squared coherence at a frequency is the squared cross-spectral density magnitude divided by the product of the two auto-spectral densities. A value near one means the signals are strongly related (coherent) at that frequency; near zero means they are essentially unrelated (incoherent). In array imaging, whether sources are coherent or incoherent strongly affects how algorithms separate and localize them.','Coherence tells how much two signals move together. It runs from zero to one. One means they are tightly linked. Zero means they are unrelated. It is measured at each frequency. Imaging methods depend heavily on this link.','Quantifies how related two sources or channels are at each frequency, which determines whether beamforming and deconvolution methods can cleanly separate them.','Computed from cross- and auto-spectra in analyzers and array software to check source correlation, validate measurements, and choose the right localization algorithm.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Coherent source localization','Incoherent source localization','CLEAN-SC','Cross-spectral matrix','Source sparsity']::text[],ARRAY['Confusing coherence with correlation in the time domain rather than a per-frequency measure','Expecting high coherence when too few averages make the estimate biased toward one','Assuming low coherence always means noise rather than genuinely independent sources']::text[],ARRAY['Checking whether two microphone channels see the same source','Deciding if sources are coherent before selecting a localization method','Diagnosing a reflection that raises coherence between spaced sensors']::text[],'intermediate','γ²_xy(f) = |G_xy(f)|² / (G_xx(f)·G_yy(f))','Magnitude-squared coherence at a frequency equals the squared magnitude of the cross-spectral density divided by the product of the two auto-spectral densities.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '686effe5-aa57-5c90-9f53-71c3c4b50d22','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='686effe5-aa57-5c90-9f53-71c3c4b50d22') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='686effe5-aa57-5c90-9f53-71c3c4b50d22');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '381d0ad6-96df-5dbb-9d84-6fbdac6695a5','Coherent source localization','The task of locating sound sources whose signals are correlated in phase, such as sources driven by a common mechanism or a source and its reflected images. Correlated wavefronts interfere, so a covariance or cross-spectral matrix loses the rank structure that many high-resolution and deconvolution methods rely on. Specialized techniques, including spatial smoothing, coherent-source CLEAN variants, and covariance-fitting or sparse formulations, are used to restore correct localization of correlated sources.','Some sources are linked in phase. Their waves overlap and interfere. This confuses many imaging methods. Special tricks are needed to place them right. Reflections often create this hard case.','Enables accurate mapping when sources are correlated, preventing the mislocation and dropped sources that standard methods produce under coherence.','Matters in reflective test spaces, duct acoustics, and structural radiation where multiple points move in step, and where reflections act as coherent image sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Coherence CLEAN-SC','Source coherence','Incoherent source localization','Subspace beamforming','Sparse Bayesian learning']::text[],ARRAY['Using a method that assumes independent sources on clearly correlated ones','Forgetting that reflections behave as coherent image sources','Skipping spatial smoothing or a coherent-aware method when rank is lost']::text[],ARRAY['Locating correlated panel vibrations radiating in phase','Handling a direct source plus its coherent wall reflection','Mapping sources fed by one common drive signal']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherent source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '381d0ad6-96df-5dbb-9d84-6fbdac6695a5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='381d0ad6-96df-5dbb-9d84-6fbdac6695a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='381d0ad6-96df-5dbb-9d84-6fbdac6695a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3549530-d2e0-5128-9931-86a0415a2f3f','Incoherent source localization','The task of locating sound sources whose signals are statistically independent, so their powers add without cross terms. Because uncorrelated sources contribute additively to the cross-spectral matrix, most conventional beamforming and deconvolution methods, including DAMAS and CLEAN-SC, are built on this incoherent-source assumption. It is the common and comparatively easy case, in which separate sources appear as distinct additive contributions to the map.','Here the sources are independent. Their signals are not linked. Their powers simply add up. Most standard methods assume this. It is the easier and more common case.','Describes the baseline assumption behind mainstream array imaging, where independent sources add cleanly and can be separated by conventional deconvolution.','Applies to typical noise studies with distinct unrelated sources, such as separate machine components, where DAMAS or CLEAN-SC work as intended.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Coherent source localization','Source coherence','DAMAS','CLEAN-SC','Point-source assumption']::text[],ARRAY['Assuming incoherence holds when strong reflections make sources effectively correlated','Believing added source powers cannot interfere even when coherence is present','Using incoherent-only methods on coherent sources and trusting the result']::text[],ARRAY['Mapping separate, unrelated machine noise sources','Ranking independent airframe noise regions in a tunnel','Standard beamforming of distinct engine and tire noise']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Incoherent source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3549530-d2e0-5128-9931-86a0415a2f3f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3549530-d2e0-5128-9931-86a0415a2f3f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3549530-d2e0-5128-9931-86a0415a2f3f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c3a0811-0529-589a-83c3-69ab55b8e702','Richardson-Lucy deconvolution','An iterative, multiplicative deconvolution method originally from image restoration and adapted to acoustic source mapping. It assumes a non-negative source distribution and a known point spread function, then updates the current estimate by a multiplicative correction formed from the ratio of the measured map to the map reprojected from the current estimate. The multiplicative update inherently preserves non-negativity and, under a Poisson-type model, converges toward a maximum-likelihood source distribution, sharpening the beamforming map over successive iterations.','This method sharpens a blurred map step by step. It compares the measured map to its own guess. The ratio scales the next guess. Values stay positive by design. Each pass makes the map sharper.','Provides a stable, non-negative iterative route to a sharper source map, borrowing a proven image-restoration update rule for acoustic deconvolution.','Used as an alternative deconvolution solver in array imaging when a robust non-negative iterative method is wanted, on beamforming maps with a modeled point spread function.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic deconvolution','DAMAS','Non-negative least squares','Point spread function','Source map regularization']::text[],ARRAY['Running too many iterations, which amplifies noise into speckle artifacts','Using an inaccurate point spread function, which biases the converged map','Assuming fast convergence, when the method often needs many iterations']::text[],ARRAY['Deconvolving a beamforming map with a known array response','Comparing an iterative non-negative solver against DAMAS on the same data','Sharpening a source map where negativity must be avoided']::text[],'advanced','x^(k+1) = x^(k) ⊙ Aᵀ( b ⊘ (A·x^(k)) )','The next source estimate equals the current estimate times the back-projected ratio of the measured map to the map predicted from the current estimate, keeping all values non-negative.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Richardson-Lucy deconvolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c3a0811-0529-589a-83c3-69ab55b8e702','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c3a0811-0529-589a-83c3-69ab55b8e702') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c3a0811-0529-589a-83c3-69ab55b8e702');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6b956d9-9c6a-5078-99b7-3cc82dd139fb','Non-negative least squares','A constrained optimization that finds the vector minimizing the squared error between a linear model and measured data while forcing every solution component to be zero or positive. In acoustic imaging the model matrix encodes the array point spread function or steering responses and the unknown vector holds source powers, which are physically non-negative. The non-negativity constraint both enforces physical realism and acts as a mild regularizer, suppressing spurious negative-going ripple that unconstrained least squares would allow.','This method fits a model to data with least squares. But it never lets a value go negative. Source powers cannot be negative. So the rule fits real physics. It also cleans up false ripple in the answer.','Solves the deconvolution or source-power fit while guaranteeing physically valid, non-negative results, which stabilizes the map and removes impossible negative sources.','Sits at the core of several deconvolution solvers, including DAMAS-type and covariance-fitting approaches, whenever source powers are estimated from array data.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['DAMAS','Acoustic deconvolution','Source map regularization','Compressive beamforming','Richardson-Lucy deconvolution']::text[],ARRAY['Treating it as ordinary least squares and expecting the same closed-form solution','Assuming the non-negativity constraint alone fixes an ill-conditioned problem','Forgetting that the model matrix errors still bias the fitted powers']::text[],ARRAY['Fitting non-negative source powers inside a DAMAS-type solver','Removing impossible negative values from a deconvolved map','Estimating source strengths from a steering-response model']::text[],'intermediate','min_x ||A·x − b||₂²  subject to  x ≥ 0','Choose the source vector that minimizes the squared difference between the model times the vector and the measured data, subject to every element being non-negative.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Non-negative least squares');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6b956d9-9c6a-5078-99b7-3cc82dd139fb','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6b956d9-9c6a-5078-99b7-3cc82dd139fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6b956d9-9c6a-5078-99b7-3cc82dd139fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fe34845-81ea-5995-aa61-cbf6b99ff842','Sparse Bayesian learning','A probabilistic inference framework that recovers a sparse source distribution by placing parameterized priors on the unknowns and learning both the sources and the prior parameters (hyperparameters) from the data. In acoustic imaging it treats grid-point source powers as random variables whose variances are estimated; most variances drive to zero, leaving only a few active grid points. This yields high-resolution maps with strong sidelobe suppression and handles correlated sources and multiple snapshots well, at higher computational cost than simple beamforming.','This method assumes only a few spots hold real sources. It uses probability to find them. It learns which spots matter from the data. Most spots drop to zero. The few strong ones remain. The map comes out sharp and clean.','Delivers a sparse, high-resolution source map by inferring which grid points are truly active, with good behavior for correlated sources and limited data.','Applied in advanced direction-of-arrival and array source-mapping research where resolution and robustness to coherence outweigh the extra computation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Compressive beamforming','Source sparsity','Coherent source localization','Off-grid source localization','Source map regularization']::text[],ARRAY['Assuming sparsity holds when the true source is spatially distributed','Ignoring grid mismatch, which spreads a single off-grid source across cells','Underestimating the compute cost of the iterative hyperparameter updates']::text[],ARRAY['Resolving closely spaced sources with few data snapshots','Mapping correlated sources where beamforming smears','Research localization demanding sub-beamwidth resolution']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sparse Bayesian learning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fe34845-81ea-5995-aa61-cbf6b99ff842','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fe34845-81ea-5995-aa61-cbf6b99ff842') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fe34845-81ea-5995-aa61-cbf6b99ff842');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d1f0f30-23b3-575e-82ed-2c0739de1561','Compressive beamforming','A source-mapping approach that casts localization as a sparse-recovery (compressed-sensing) problem, assuming only a few grid points among many carry real sources. It seeks the source vector that fits the array data while minimizing a sparsity-promoting norm, typically the L1 norm, often through convex optimization. Exploiting sparsity lets it resolve sources below the conventional beamwidth and work with few sensors or snapshots, provided the true sources lie on or near the assumed grid.','This method assumes just a few real sources exist. It picks the simplest map that fits the data. Simplest means fewest active spots. That gives sharp results. It needs the sources to sit near the grid points.','Achieves high resolution from limited data by enforcing sparsity, resolving sources that conventional beamforming would blur together.','Used in array research and some measurement systems for high-resolution localization with few microphones or short recordings, solved with convex or greedy sparse solvers.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Source sparsity','Sparse Bayesian learning','Grid mismatch','Off-grid source localization','Non-negative least squares']::text[],ARRAY['Ignoring grid mismatch, which breaks the sparsity model for off-grid sources','Assuming sparsity when the real field is spatially distributed','Choosing the sparsity weight poorly, over- or under-cleaning the map']::text[],ARRAY['Localizing a few sources with a small microphone array','Recovering high resolution from short data records','Separating sub-beamwidth sources in a research test']::text[],'advanced','min_x ||x||₁  subject to  ||A·x − b||₂ ≤ ε','Find the source vector with the smallest L1 norm whose modeled data stays within a small error tolerance of the measured data, promoting a sparse solution.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compressive beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d1f0f30-23b3-575e-82ed-2c0739de1561','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d1f0f30-23b3-575e-82ed-2c0739de1561') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d1f0f30-23b3-575e-82ed-2c0739de1561');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f461fb62-ede6-5b34-aa68-06488617ff09','Subspace beamforming','A family of high-resolution localization methods that split the array covariance matrix, via eigenvalue decomposition, into a signal subspace spanned by source components and an orthogonal noise subspace. Techniques such as MUSIC scan candidate directions and score each by how orthogonal its steering vector is to the noise subspace, producing sharp peaks at true source directions. These methods resolve closely spaced sources far better than conventional beamforming but assume a known number of mostly incoherent sources and enough data snapshots.','This method splits the data into two parts. One part holds the sources. The other holds noise. True directions do not match the noise part. Testing that gives very sharp peaks. It needs to know how many sources there are.','Provides super-resolution direction finding by separating signal and noise subspaces, sharply resolving sources that conventional beamforming cannot.','Used in direction-of-arrival estimation for microphone and sensor arrays, sonar, and radar, where closely spaced sources must be resolved.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Orthogonal beamforming','High-resolution beamforming','Cross-spectral matrix','Coherent source localization','Source coherence']::text[],ARRAY['Applying it to coherent sources without spatial smoothing, which corrupts the subspaces','Guessing the source count wrong, which splits or merges peaks','Using too few snapshots, so the covariance estimate is unreliable']::text[],ARRAY['Resolving two close sources with a MUSIC direction estimate','Direction finding with a compact microphone array','Separating tightly spaced sources beyond beamforming resolution']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subspace beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f461fb62-ede6-5b34-aa68-06488617ff09','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f461fb62-ede6-5b34-aa68-06488617ff09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f461fb62-ede6-5b34-aa68-06488617ff09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4663d052-88e2-5d09-8c61-db21c80b71fd','Functional beamforming','A nonlinear beamforming method that raises the array cross-spectral matrix to a fractional power before the steered response and then raises the result to the reciprocal power. Using the matrix eigenstructure, this exponent sharpens the main lobe and pushes down sidelobes without an iterative deconvolution, greatly increasing dynamic range and resolution at modest extra cost. The steered response reduces to conventional beamforming when the exponent is one and grows sharper as the exponent increases.','This method reshapes the array data with a power law. A tuning number sets how strong the effect is. It sharpens the main peak. It also pushes side spots way down. It does this in one pass, not many. An exponent of one gives plain beamforming.','Sharpens the map and widens dynamic range directly from the cross-spectral matrix, avoiding the cost and convergence concerns of iterative deconvolution.','Popular in aeroacoustic wind-tunnel testing for quick high-dynamic-range source maps; built into commercial array analysis packages.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Orthogonal beamforming','High-resolution beamforming','Dynamic range enhancement','Sidelobe suppression','Subspace beamforming']::text[],ARRAY['Reading absolute levels off a high-exponent map without accounting for its scaling','Pushing the exponent so high that noise and small errors are exaggerated','Assuming it separates coherent sources like a true deconvolution method']::text[],ARRAY['Making a high-dynamic-range airframe noise map quickly','Boosting contrast between a strong and a weak source','Sharpening a tunnel source map without running DAMAS']::text[],'advanced','B(ξ) = ( wᴴ · C^(1/ν) · w )^ν','The steered response equals the array steering vector applied to the cross-spectral matrix raised to one over the exponent, with the whole quantity then raised to the exponent.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Functional beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4663d052-88e2-5d09-8c61-db21c80b71fd','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4663d052-88e2-5d09-8c61-db21c80b71fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4663d052-88e2-5d09-8c61-db21c80b71fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '98e0c6b6-a820-5e1c-9a8e-72db8576a5c5','Orthogonal beamforming','A high-resolution method that performs an eigenvalue decomposition of the array cross-spectral matrix and beamforms each eigenmode separately, assigning each dominant eigenvalue''s power to the location where its eigenvector-based steered response peaks. Because strong incoherent sources tend to map onto distinct eigenmodes, this cleanly separates and quantifies them with suppressed sidelobes and without iterative deconvolution. It assumes the significant sources are incoherent and their number is small relative to the microphone count.','This method breaks the array data into separate modes. Each strong source lands in its own mode. The method maps each mode on its own. That keeps sources apart with few side spots. It works best for a few independent sources.','Separates and quantifies dominant incoherent sources by beamforming individual eigenmodes, giving clean source levels without an iterative solver.','Used in aeroacoustic and machinery array testing to rank a handful of strong independent sources with reliable level estimates.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Subspace beamforming','Functional beamforming','High-resolution beamforming','Sidelobe suppression','Incoherent source localization']::text[],ARRAY['Applying it when sources are coherent, so eigenmodes mix multiple sources','Assuming each eigenmode always equals exactly one physical source','Choosing too many eigenmodes and mapping noise as false sources']::text[],ARRAY['Ranking a few dominant independent noise sources','Separating two strong sources into distinct eigenmodes','Getting clean level estimates without iterative deconvolution']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Orthogonal beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '98e0c6b6-a820-5e1c-9a8e-72db8576a5c5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='98e0c6b6-a820-5e1c-9a8e-72db8576a5c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='98e0c6b6-a820-5e1c-9a8e-72db8576a5c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '188ce2e7-7373-521a-a466-503825e87b24','High-resolution beamforming','A general label for any array-processing method that resolves sound sources more finely than the conventional delay-and-sum beamformer, whose resolution is limited by array aperture and wavelength and whose maps carry broad main lobes and strong sidelobes. The category spans deconvolution methods such as DAMAS and CLEAN-SC, nonlinear methods such as functional and orthogonal beamforming, subspace methods such as MUSIC, and sparse or Bayesian formulations. All aim to narrow main lobes, suppress sidelobes, and separate closely spaced sources.','Plain beamforming makes wide, blurry spots. High-resolution methods do better. They shrink each spot. They cut the side clutter. So close sources split apart. Many different methods fit under this name.','Names the goal shared by advanced array methods: beating the conventional beamformer''s resolution and dynamic-range limits to locate sources more precisely.','The umbrella a technician selects from when a conventional map is too blurry, choosing DAMAS, CLEAN-SC, functional, or subspace methods to fit the data and budget.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic deconvolution','Functional beamforming','Orthogonal beamforming','Subspace beamforming','DAMAS']::text[],ARRAY['Believing any method beats the physical aperture limit for a single source','Treating all high-resolution methods as interchangeable regardless of source coherence','Trusting sharper maps without checking the assumptions each method requires']::text[],ARRAY['Choosing an advanced method when a conventional map is too blurred','Comparing DAMAS and functional beamforming on the same data','Explaining why closely spaced sources need more than delay-and-sum']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-resolution beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '188ce2e7-7373-521a-a466-503825e87b24','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='188ce2e7-7373-521a-a466-503825e87b24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='188ce2e7-7373-521a-a466-503825e87b24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '656d00a5-9328-5e2d-9657-ffcabf89a7c3','Beamformer deblurring','A plain-language description of acoustic deconvolution: the removal of the array-induced blur from a beamforming source map. The conventional beamformer smears each true source into a main lobe with sidelobes set by the array''s point spread function; deblurring inverts that smearing to recover sharper, better-localized sources. The term is used informally for the practical outcome of running a deconvolution or high-resolution method on a dirty map.','A beamforming map comes out blurry. The blur is caused by the array. Deblurring removes it. The sources then look sharp. It is just a plain name for deconvolution.','Communicates the practical aim of deconvolution in everyday terms: taking a fuzzy source map and making it sharp and readable.','How the benefit of deconvolution is often described to non-specialists when presenting cleaned wind-tunnel or machinery source maps.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic deconvolution','DAMAS','CLEAN-SC','Point spread function','Sidelobe suppression']::text[],ARRAY['Thinking deblurring adds real detail rather than undoing a known blur','Expecting it to fix errors caused by a wrong array model','Assuming it can resolve sources below the array''s physical limit']::text[],ARRAY['Explaining a cleaned source map to a non-specialist audience','Describing the before-and-after of a deconvolution step','Summarizing why a raw beamforming map looks smeared']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamformer deblurring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '656d00a5-9328-5e2d-9657-ffcabf89a7c3','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='656d00a5-9328-5e2d-9657-ffcabf89a7c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='656d00a5-9328-5e2d-9657-ffcabf89a7c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18258052-b59b-5e9f-aab0-39cb7c7a6691','Dynamic range enhancement','The increase in usable contrast, between the strongest true source and the residual background or sidelobe floor, that advanced imaging methods provide over conventional beamforming. Delay-and-sum maps have a limited dynamic range because sidelobes and array response set a high floor that hides weaker sources. Deconvolution, functional beamforming, and sparse methods lower that floor, widening the level span over which real sources remain visible and distinguishable from artifacts.','A plain map has a high noise floor. Weak sources hide under it. Better methods push the floor down. Then weak sources show up. The gap between loud and soft grows. That is the enhanced range.','Widens the level span over which real sources stay visible, revealing weaker sources that a conventional map''s sidelobe floor would bury.','A key benefit cited when choosing functional beamforming or deconvolution for tests that must reveal secondary or low-level noise sources.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Functional beamforming','Sidelobe suppression','Acoustic deconvolution','Map artifact','High-resolution beamforming']::text[],ARRAY['Confusing display color scaling with genuine dynamic-range improvement','Assuming a lower floor is always real rather than sometimes an artifact','Ignoring that pushing range too hard can promote noise into false sources']::text[],ARRAY['Revealing a weak secondary source hidden under sidelobes','Comparing dynamic range of functional beamforming versus delay-and-sum','Setting a map floor to show low-level sources without noise']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic range enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18258052-b59b-5e9f-aab0-39cb7c7a6691','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18258052-b59b-5e9f-aab0-39cb7c7a6691') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18258052-b59b-5e9f-aab0-39cb7c7a6691');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54ecde93-c5fd-5288-b8e1-196ad7ac6ac0','Ghost source','A false apparent source in an acoustic image that does not correspond to a real radiator. Ghost sources arise from array sidelobes, spatial aliasing at high frequency, reflections that act as image sources, coherence between real sources, or deconvolution artifacts. They can mimic genuine hotspots in level and shape, so recognizing and rejecting them is essential to avoid misattributing noise to the wrong location.','A ghost source is a fake spot on the map. No real source is there. It comes from sidelobes, echoes, or aliasing. It can look just like a real source. So it can fool you.','Names the false peaks that array imaging can produce, alerting analysts to verify hotspots before attributing noise to a location.','Watched for when reading any beamforming map; cross-checked by changing frequency, array, or method to see whether a suspected source persists.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['False hotspot','Map artifact','Sidelobe suppression','Spatial aliasing','Acoustic deconvolution']::text[],ARRAY['Reporting a sidelobe or reflection image as a real noise source','Assuming a strong, well-shaped peak must be genuine','Ignoring that high-frequency aliasing creates repeated ghost sources']::text[],ARRAY['Spotting a reflection-induced false source in a hard-walled room','Recognizing aliasing ghosts at high frequency with a coarse array','Checking whether a peak persists across different array setups']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ghost source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54ecde93-c5fd-5288-b8e1-196ad7ac6ac0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54ecde93-c5fd-5288-b8e1-196ad7ac6ac0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54ecde93-c5fd-5288-b8e1-196ad7ac6ac0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '596ef841-87b4-5b6a-8033-dcdd357c4f46','False hotspot','A region of apparently high level in an acoustic source map that does not represent a real dominant source. False hotspots stem from sidelobes, reflections, array-response artifacts, spatial aliasing, or overdriven processing, and they can misdirect noise-control effort toward the wrong part of a structure. Distinguishing false hotspots from true dominant sources is a core skill in interpreting array maps.','A false hotspot is a bright area that fools you. It looks like a strong source. But no real source is there. It comes from echoes or array errors. It can send fixes to the wrong place.','Flags the misleading bright areas in a map so effort is not wasted treating a location that is not actually a dominant source.','Considered whenever ranking sources for noise control, prompting verification before money is spent quieting the indicated region.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Ghost source','Map artifact','Sidelobe suppression','Dynamic range enhancement','Spatial aliasing']::text[],ARRAY['Prioritizing noise-control work on an unverified bright spot','Confusing a sidelobe cluster with a genuine dominant source','Assuming brighter always means a stronger real source']::text[],ARRAY['Questioning a bright area before recommending a costly noise fix','Separating a real dominant source from a sidelobe cluster','Reviewing a map where reflections create a misleading hotspot']::text[],'beginner',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='False hotspot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '596ef841-87b4-5b6a-8033-dcdd357c4f46','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='596ef841-87b4-5b6a-8033-dcdd357c4f46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='596ef841-87b4-5b6a-8033-dcdd357c4f46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d271dfe-8783-5ed4-b6e5-de7e76aa0b80','Map artifact','Any feature in an acoustic source map that comes from the measurement or processing chain rather than from a real source. Artifacts include sidelobes from array geometry, spatial aliasing patterns, edge effects at the scan-region boundary, reflection images, and spurious structure introduced by a deconvolution solver or a mismatched point spread function. Recognizing artifacts is essential so they are not mistaken for genuine acoustic features.','An artifact is a feature the process itself creates. It is not a real source. Array shape, echoes, and math errors all cause them. They can clutter or mislead. You must learn to spot them.','Names the non-physical features a map can contain, reminding analysts to separate processing and array effects from true acoustic sources.','Checked when interpreting maps by varying array, frequency, scan region, or algorithm to see which features are stable and physical.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Ghost source','False hotspot','Sidelobe suppression','Spatial aliasing','Point spread function']::text[],ARRAY['Interpreting a solver-induced ripple as a real source','Ignoring edge effects near the boundary of the scan region','Assuming all bright features are physical without cross-checks']::text[],ARRAY['Identifying edge artifacts at the border of a scan plane','Distinguishing sidelobe patterns from real sources','Recognizing solver ripple in a deconvolved map']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Map artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d271dfe-8783-5ed4-b6e5-de7e76aa0b80','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d271dfe-8783-5ed4-b6e5-de7e76aa0b80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d271dfe-8783-5ed4-b6e5-de7e76aa0b80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7db94812-898e-53d7-b449-7230aac785d9','Sidelobe suppression','The reduction of sidelobes, the secondary response peaks around a source''s main lobe caused by the array''s point spread function, in a beamforming map. Sidelobes raise the map floor, create false features, and mask weaker sources. Suppression is achieved through array design and shading, higher-resolution or nonlinear beamformers, and deconvolution methods that remove the point-spread-function pattern, together improving dynamic range and reducing false sources.','A source makes a main spot plus smaller side spots. The side spots are not real sources. They raise the floor and hide weak sources. Suppression cuts them down. The map then looks cleaner.','Lowers the false side responses around sources, improving dynamic range and making weaker true sources visible.','Pursued through array shading, better array geometry, and deconvolution methods such as CLEAN-SC when maps are cluttered by sidelobes.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Map artifact','Ghost source','Dynamic range enhancement','CLEAN-SC','Acoustic deconvolution']::text[],ARRAY['Confusing a sidelobe with a genuine secondary source','Assuming suppression removes sidelobes without any resolution trade-off','Believing a single array design suppresses sidelobes at all frequencies']::text[],ARRAY['Cleaning a cluttered map so weak sources appear','Choosing array shading to lower the sidelobe floor','Running CLEAN-SC to strip coherent sidelobes']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sidelobe suppression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7db94812-898e-53d7-b449-7230aac785d9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7db94812-898e-53d7-b449-7230aac785d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7db94812-898e-53d7-b449-7230aac785d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12a2405b-309d-5e76-b247-ce3e028371c8','Point-source assumption','The modeling assumption that each acoustic source is an idealized compact point radiator, typically a monopole, located at a single grid position. Most beamforming and deconvolution methods build their steering vectors and point spread functions on this assumption, which simplifies the math and suits many real sources at the wavelengths of interest. It breaks down for spatially extended or distributed sources, where the true radiation cannot be captured by a single point and the resulting map can misrepresent source extent and level.','Many methods treat each source as a single tiny point. That keeps the math simple. It fits many real sources well enough. But some sources are spread out. Then a single point is wrong. The map can mislead.','Underlies the steering and point-spread-function models most array methods use, trading exact source shape for tractable, well-behaved localization.','Implicit whenever a standard beamformer or deconvolution is run; questioned when sources are clearly extended, such as long edges or panels.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Distributed source','Point spread function','Acoustic deconvolution','Source sparsity','DAMAS']::text[],ARRAY['Applying point-source methods to clearly extended sources without caveats','Reading a point estimate as the true physical size of a source','Forgetting that distributed sources spread energy the model cannot place']::text[],ARRAY['Modeling a small leak or tonal source as a single point','Recognizing the assumption''s limits on a long trailing edge','Explaining why an extended panel maps poorly as one point']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Point-source assumption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12a2405b-309d-5e76-b247-ce3e028371c8','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12a2405b-309d-5e76-b247-ce3e028371c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12a2405b-309d-5e76-b247-ce3e028371c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53bfa43f-d2ac-589b-b6da-044588da0262','Distributed source','An acoustic source whose radiation is spread over an extended area, line, or volume rather than concentrated at a single point, such as a vibrating panel, a turbulent boundary layer, or a trailing edge. Distributed sources violate the point-source assumption underlying most beamforming and deconvolution methods, so they can appear on maps as smeared regions, multiple partial peaks, or level estimates that depend on how the extended radiation is binned onto the scan grid.','A distributed source is spread out. It is not one tiny point. A whole panel or edge can radiate. Point-based methods struggle with it. It shows up smeared on the map.','Describes the extended-source case that challenges point-based imaging, guiding careful interpretation of maps that show spread-out radiation.','Encountered with panels, trailing edges, and turbulent flow noise, where analysts interpret extent and integrated level rather than a single peak.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Point-source assumption','Point spread function','Source sparsity','Acoustic deconvolution','Map artifact']::text[],ARRAY['Reading one peak from a distributed source as its complete radiation','Applying sparse methods that assume few points to a spread-out source','Comparing distributed-source levels without a consistent integration region']::text[],ARRAY['Mapping trailing-edge noise along a wing','Interpreting a vibrating panel as extended radiation','Integrating a source region to get a total level']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53bfa43f-d2ac-589b-b6da-044588da0262','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53bfa43f-d2ac-589b-b6da-044588da0262') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53bfa43f-d2ac-589b-b6da-044588da0262');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d147f48-3b73-5e8e-9eec-d9ff5773b2c4','Source sparsity','The assumption that, among many candidate grid locations, only a small number actually radiate significant sound, so the source distribution is sparse. This prior underlies compressive beamforming, sparse Bayesian learning, and related methods, which favor solutions with few active grid points. Sparsity enables high-resolution, low-artifact maps from limited data, but it is a poor model for genuinely distributed sources, where energy is spread across many locations.','Sparsity means only a few spots hold real sources. Most of the grid is silent. Many sharp methods rely on this idea. It gives clean, high-resolution maps. But it fails for spread-out sources.','Provides the prior that lets sparse and compressive methods resolve fine detail from little data by favoring maps with few active sources.','Assumed when applying compressive beamforming or sparse Bayesian learning to well-separated sources; reconsidered when sources are extended.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Compressive beamforming','Sparse Bayesian learning','Distributed source','Off-grid source localization','Point-source assumption']::text[],ARRAY['Forcing a sparse model onto a spatially distributed source','Assuming sparsity guarantees correctness regardless of grid mismatch','Confusing a sparse display threshold with a true sparse source field']::text[],ARRAY['Applying compressive beamforming to a few isolated sources','Deciding sparsity is unsuitable for a broad panel radiator','Setting a sparse prior for high-resolution localization']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source sparsity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d147f48-3b73-5e8e-9eec-d9ff5773b2c4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d147f48-3b73-5e8e-9eec-d9ff5773b2c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d147f48-3b73-5e8e-9eec-d9ff5773b2c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4bfa4fdb-2f98-5771-bed7-1fb4b7590a1e','Grid mismatch','The modeling error that occurs when true source locations fall between the discrete points of the scan grid assumed by an imaging algorithm, also called basis or off-grid mismatch. Because steering vectors and dictionaries are built only for on-grid positions, an off-grid source cannot be represented exactly and instead leaks across several nearby cells. This degrades sparse and high-resolution methods most, biasing estimated positions and levels and spreading a single source into a small cluster.','Imaging uses a grid of test spots. Real sources may sit between spots. Then no single spot fits. The source spreads across nearby cells. This hurts sharp methods. Positions and levels come out biased.','Names the error from discretizing space onto a grid, explaining why off-grid sources smear and why finer grids or off-grid methods are needed.','Considered when choosing grid spacing and when sparse or compressive results show a source spread across adjacent cells instead of one point.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Off-grid source localization','Compressive beamforming','Source sparsity','Sparse Bayesian learning','Source map regularization']::text[],ARRAY['Assuming a finer grid removes mismatch entirely rather than reducing it at higher cost','Reading a mismatch-spread cluster as several real sources','Ignoring mismatch when trusting sparse-method position estimates']::text[],ARRAY['Diagnosing a single source spread across grid cells','Choosing grid spacing for a compressive beamforming run','Deciding to switch to an off-grid method for accuracy']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grid mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4bfa4fdb-2f98-5771-bed7-1fb4b7590a1e','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4bfa4fdb-2f98-5771-bed7-1fb4b7590a1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4bfa4fdb-2f98-5771-bed7-1fb4b7590a1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfb42eb9-b1d5-5499-829a-8bed482ef267','Off-grid source localization','Localization methods designed to place sources at continuous positions rather than snapping them to fixed scan-grid points, thereby avoiding grid mismatch. Approaches include refining an on-grid estimate with local interpolation or gradient steps, jointly estimating source positions and amplitudes, and atomic-norm or gridless formulations that optimize over a continuous position parameter. These methods recover more accurate positions and levels for sources that do not coincide with grid nodes, at added algorithmic complexity.','Grid methods force sources onto fixed spots. Off-grid methods do not. They let a source sit anywhere. They refine or solve for the exact spot. This avoids grid error. But it is more complex to run.','Removes the bias of forcing sources onto grid nodes, giving accurate continuous positions for sources between the scan points.','Used in advanced localization where sub-grid position accuracy matters, refining sparse or subspace estimates to continuous coordinates.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Grid mismatch','Compressive beamforming','Sparse Bayesian learning','Subspace beamforming','Source map regularization']::text[],ARRAY['Assuming a very fine grid is always as good as a true off-grid method','Overlooking the higher compute cost of continuous optimization','Trusting off-grid positions without checking convergence to a local optimum']::text[],ARRAY['Refining a grid estimate to a continuous source position','Localizing a source that falls between scan nodes','Using a gridless method for precise position estimates']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Off-grid source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfb42eb9-b1d5-5499-829a-8bed482ef267','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfb42eb9-b1d5-5499-829a-8bed482ef267') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfb42eb9-b1d5-5499-829a-8bed482ef267');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '193d5569-5792-54ce-8d0c-00be7ede33b0','Source map regularization','The use of added constraints or penalty terms to stabilize the ill-posed inversion that turns a beamforming map into a source distribution. Because deconvolution is sensitive to noise and model error, a regularizer, such as a non-negativity constraint, an L2 (Tikhonov) penalty for smoothness, or an L1 penalty for sparsity, is added to the data-fit term to favor physically plausible solutions. A weight parameter balances fidelity to the measured data against the regularizer, trading resolution against stability and artifact suppression.','Turning a map into sources is an unstable problem. Noise can wreck the answer. Regularization adds a rule to steady it. The rule favors sensible maps. A weight sets the balance. It trades sharpness for stability.','Stabilizes the deconvolution inverse so noise and model error do not produce wild or unphysical maps, steering the solution toward plausible source distributions.','Tuned in deconvolution and sparse solvers by setting the regularization weight and penalty type to balance resolution, stability, and artifact suppression.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Non-negative least squares','Compressive beamforming','Acoustic deconvolution','Grid mismatch','Sparse Bayesian learning']::text[],ARRAY['Setting the weight too high, which over-smooths and blurs real sources','Setting the weight too low, which lets noise dominate the map','Assuming one penalty type suits every source field and dataset']::text[],ARRAY['Tuning a Tikhonov weight to steady a noisy deconvolution','Choosing an L1 penalty to promote a sparse source map','Balancing resolution against stability in a solver setup']::text[],'advanced','min_x ||A·x − b||₂² + λ·Ω(x),  λ > 0','Minimize the data-fit error plus a positive weight times a penalty on the source vector, where the weight balances fidelity to the data against the chosen regularizer.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source map regularization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '193d5569-5792-54ce-8d0c-00be7ede33b0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='193d5569-5792-54ce-8d0c-00be7ede33b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='193d5569-5792-54ce-8d0c-00be7ede33b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd6cd529-9019-5d8a-aeac-710adcdd7560','Schlieren optics','An optical technique that renders otherwise invisible refractive-index gradients in a transparent medium as variations in image brightness. A point or slit light source is collimated through the test region and refocused, and a knife edge (or graded colour filter) placed at that focus intercepts rays that have been angularly deflected by index gradients; the resulting cut-off maps the first spatial derivative of refractive index into intensity. Because index tracks density, and thus pressure and temperature, the method reveals density gradients from sound, shocks, heat, and mixing.','Schlieren optics makes tiny changes in air or water show up as light and dark. Light passes through the test area and bends where the density changes. A sharp edge blocks some of the bent light. This turns small density changes into a clear picture. It is often used to see heat, shocks, and sound.','Converts small, invisible refractive-index (density) gradients into visible contrast, letting researchers see and record flows, shocks, and acoustic disturbances an ordinary camera cannot capture.','Used in wind-tunnel and laboratory work to image shock waves, jets, thermal plumes, and, with sensitive setups, sound and ultrasound fields; technicians align the source, mirrors or lenses, and knife edge for best sensitivity.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Shadowgraphy','Refractive-index gradient','Background-oriented schlieren','Knife-edge cutoff','Density-gradient visualization','Acoustic schlieren']::text[],ARRAY['Confusing schlieren, sensitive to the first derivative of index, with shadowgraphy, sensitive to the second','Assuming image brightness equals absolute density rather than its gradient','Setting the knife-edge cutoff too little or too much, losing sensitivity or clipping the image']::text[],ARRAY['Visualizing a shock wave around a model in a wind tunnel','Imaging a heated plume rising from a component','Making an ultrasonic beam visible in a water tank']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Schlieren optics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd6cd529-9019-5d8a-aeac-710adcdd7560','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd6cd529-9019-5d8a-aeac-710adcdd7560') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd6cd529-9019-5d8a-aeac-710adcdd7560');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6aeee261-7e9c-5e36-a606-4fa782ed8998','Acoustic schlieren','The application of schlieren imaging to sound fields, in which the periodic density (and hence refractive-index) variations of an acoustic wave deflect probing light and appear as intensity modulation. Because sound produces very small index changes, acoustic schlieren typically images higher-intensity or higher-frequency fields such as ultrasound, and often uses stroboscopic or pulsed illumination phase-locked to the sound to freeze or average the oscillating pattern. The recorded brightness maps the acoustic density gradient integrated along the light path.','Acoustic schlieren uses schlieren optics to make sound visible. A sound wave squeezes and stretches the medium, changing its density. That change bends light, which the setup turns into a picture. Sound bends light only a little, so strong or high-frequency sound works best. Flashing the light in step with the sound freezes the pattern.','Lets researchers see the shape, direction, and structure of a sound field directly, rather than probing it point by point with a microphone or hydrophone.','Used to visualize ultrasonic transducer beams, standing waves, and diffraction in water tanks; the image reveals beam width, side lobes, and focusing that guide transducer design and testing.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Schlieren optics','Ultrasonic schlieren imaging','Acousto-optic effect','Ultrasound beam visualization','Acoustic shadowgraphy']::text[],ARRAY['Expecting audible-range sound in air to image easily, when its index change is usually too small','Reading brightness as sound pressure rather than as a path-integrated gradient','Forgetting to phase-lock the light, which blurs the oscillating field']::text[],ARRAY['Imaging a medical ultrasound transducer''s beam in a water tank','Checking the focal region of a focused ultrasound source','Teaching how sound diffracts around an edge']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic schlieren');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6aeee261-7e9c-5e36-a606-4fa782ed8998','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6aeee261-7e9c-5e36-a606-4fa782ed8998') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6aeee261-7e9c-5e36-a606-4fa782ed8998');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3dfbc61b-a5fc-5b59-adbb-cc0b3b28e325','Ultrasonic schlieren imaging','Schlieren visualization specifically of ultrasonic fields, most commonly in water or tissue-mimicking media where the acousto-optic interaction is strong enough to modulate transmitted light. The ultrasound''s pressure oscillation acts as a phase grating (the Raman-Nath or Debye-Sears regime) that diffracts the probe beam; a schlieren stop then converts the deflection into an image of beam shape, focusing, and interference. Pulsed or stroboscopic light resolves the wave''s spatial structure at megahertz frequencies.','This is schlieren imaging aimed at ultrasound, usually in water. Ultrasound makes a fast pressure pattern that acts like a grating. That grating bends the light passing through it. The system turns the bending into a picture of the beam. Because the sound is fast, the light is pulsed to freeze it.','Provides a full-field, real-time picture of an ultrasonic beam so its width, focus, and side structure can be seen and measured without scanning a hydrophone through the field.','Used in transducer manufacturing and quality control to check beam alignment and focusing, and in labs to study diffraction, standing waves, and nonlinear beam distortion in water.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic schlieren','Acousto-optic effect','Raman-Nath diffraction','Ultrasound beam visualization','Hydrophone']::text[],ARRAY['Treating the bright pattern as an exact pressure map instead of a path-integrated projection','Ignoring the Raman-Nath limit, where strong sound produces multiple diffraction orders','Using continuous light, which averages out the moving wave']::text[],ARRAY['Verifying the focus of a therapy transducer in water','Studying how an ultrasonic beam bends around an obstacle','Comparing measured and modeled beam profiles']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic schlieren imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3dfbc61b-a5fc-5b59-adbb-cc0b3b28e325','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3dfbc61b-a5fc-5b59-adbb-cc0b3b28e325') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3dfbc61b-a5fc-5b59-adbb-cc0b3b28e325');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23d59012-3158-51e9-9b2f-d3b48a935b9b','Pulsed schlieren imaging','A schlieren configuration that uses short light pulses, or a stroboscopic source, rather than continuous illumination, so a rapidly changing or oscillating refractive-index field is effectively frozen in each exposure. Pulse duration sets the temporal resolution; synchronising the pulse to a periodic driver such as an ultrasound transducer, spark, or moving shock captures a chosen phase, and stepping the delay builds a time-resolved sequence. It is essential for imaging high-frequency acoustic and ultrasonic fields whose motion would otherwise blur.','Pulsed schlieren lights the scene with very short flashes instead of steady light. Each flash is so brief that fast motion looks frozen. Matching the flash to a repeating source captures one moment of the wave. Changing the timing builds a movie of the motion. This is needed for fast sound and ultrasound.','Freezes fast, oscillating, or transient density fields so their instantaneous structure and time evolution can be imaged without motion blur.','Used to image ultrasonic haptic and levitation fields, spark and shock events, and megahertz transducer beams; technicians set pulse width and trigger delay to capture the phase of interest.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Schlieren optics','Stroboscopic illumination','Ultrasonic schlieren imaging','Acoustic levitation field imaging','High-speed imaging']::text[],ARRAY['Using too long a pulse, which blurs the fast field','Assuming one frame shows the whole cycle rather than a single phase','Failing to synchronise the flash to the source, giving random phases']::text[],ARRAY['Capturing one phase of a 40 kHz levitation field','Freezing a shock wave from a spark source','Building a phase-stepped movie of an ultrasound beam']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulsed schlieren imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23d59012-3158-51e9-9b2f-d3b48a935b9b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23d59012-3158-51e9-9b2f-d3b48a935b9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23d59012-3158-51e9-9b2f-d3b48a935b9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b085604-c276-509f-aba9-fd84462e648b','Pocket schlieren','A compact, low-cost schlieren or background-oriented schlieren (BOS) implementation built around a smartphone or similarly portable camera, intended to bring density-gradient visualization out of the optical laboratory. It typically relies on the phone''s high-resolution sensor and computational BOS processing, which tracks the apparent displacement of a textured background, rather than on precision mirrors and knife edges, trading ultimate sensitivity for portability, low cost, and ease of use in teaching and field settings.','Pocket schlieren is a schlieren setup small enough to carry, often using a phone. Instead of large mirrors, it watches a patterned background through moving air. Software measures how the pattern seems to shift. That shift reveals changes in density. It makes the method cheap and easy for classrooms.','Makes density-gradient and simple sound or heat visualization accessible without a full optical bench, supporting education, demonstration, and portable field measurement.','Used in classrooms and outreach to show thermal plumes, breath, and jets, and by researchers wanting a quick portable check of a flow before a full lab study.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Background-oriented schlieren','Schlieren optics','Density-gradient visualization','Optical flow BOS','Consecutive frame subtraction']::text[],ARRAY['Expecting bench-schlieren sensitivity from a phone setup','Forgetting that BOS needs a textured background and good lighting','Confusing the processed displacement map with a direct pressure image']::text[],ARRAY['Demonstrating a rising heat plume in a classroom','Field-checking a jet or exhaust flow with a phone','Introducing students to BOS before lab work']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pocket schlieren');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b085604-c276-509f-aba9-fd84462e648b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b085604-c276-509f-aba9-fd84462e648b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b085604-c276-509f-aba9-fd84462e648b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39ade700-e6d8-52f9-8b98-74fa9ab82137','Density-gradient visualization','A family of optical methods, including schlieren, shadowgraphy, and interferometry, that render spatial variations in fluid density visible by exploiting the dependence of refractive index on density. Rather than measuring density directly, these techniques respond to its spatial derivative (first derivative for schlieren, second for shadowgraphy) or to the integrated index (interferometry), producing images in which brightness or fringe pattern encodes where and how sharply density changes across the field.','This is any method that makes changes in a fluid''s density visible. Density changes bend light because they change how fast light travels. Different methods respond to the change in different ways. Schlieren reacts to how fast density changes across space. The picture shows where density rises or falls, not its exact value.','Turns invisible density structure, from heat, flow, shocks, or sound, into an image, enabling qualitative and quantitative study of fields that carry no visible marker.','Central to aerodynamics, combustion, and acoustics labs for imaging shocks, plumes, mixing, and sound; the chosen method depends on whether the gradient, its slope, or the integrated index matters.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Schlieren optics','Acoustic shadowgraphy','Refractive-index gradient','Laser interferometry','Background-oriented schlieren']::text[],ARRAY['Reading the image as absolute density instead of its gradient','Mixing up which derivative schlieren versus shadowgraphy shows','Assuming any change in a transparent medium is visible regardless of its magnitude']::text[],ARRAY['Imaging fuel-air mixing in a burner','Visualizing a shock on a wind-tunnel model','Comparing schlieren and shadowgraph views of the same jet']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Density-gradient visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39ade700-e6d8-52f9-8b98-74fa9ab82137','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39ade700-e6d8-52f9-8b98-74fa9ab82137') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39ade700-e6d8-52f9-8b98-74fa9ab82137');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e87c134c-4099-5876-a7df-d9c8bd9bf541','Refractive-index gradient','The spatial rate of change of a medium''s refractive index. For gases it follows the Gladstone-Dale relation, n minus one equals a constant times density, making the index gradient proportional to the density gradient. Light passing through such a gradient is refracted, bending toward higher-index regions; the angular deflection is proportional to the transverse index gradient integrated along the ray path. This quantity is the physical basis of schlieren, shadowgraph, and BOS imaging.','A refractive-index gradient is how quickly a medium bends light from place to place. In a gas, the index rises with density in a simple, near-linear way. So a change in density means a change in index. Light bends toward the denser, higher-index side. Schlieren and related methods work by sensing this bending.','Provides the measurable link between an invisible density (or pressure, temperature) field and the deflection of light that imaging methods exploit to visualize the field.','Technicians use it to reason about sensitivity and calibration: knowing the index-density relation lets schlieren and BOS images be turned into quantitative density or pressure maps.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Gladstone-Dale relation','Density-gradient visualization','Schlieren optics','Background-oriented schlieren','Refraction']::text[],ARRAY['Assuming the index change is large, when in air it is only parts per thousand','Forgetting the deflection depends on the path-integrated gradient, not a single point','Applying the gas Gladstone-Dale constant to liquids without adjustment']::text[],ARRAY['Calibrating a schlieren system for quantitative density','Estimating how much a beam bends across a shock','Converting a BOS displacement field into density']::text[],'intermediate','n − 1 = k·ρ  ⇒  dn/dx = k·(dρ/dx)','The refractive index minus one equals the Gladstone-Dale constant times density; so the index gradient equals that constant times the density gradient.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Refractive-index gradient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e87c134c-4099-5876-a7df-d9c8bd9bf541','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e87c134c-4099-5876-a7df-d9c8bd9bf541') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e87c134c-4099-5876-a7df-d9c8bd9bf541');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5e85c9a-ecd5-5e7c-aae9-3e212b4a7ee6','Optical flow BOS','A background-oriented schlieren analysis that estimates the apparent displacement of a textured background between a reference (undisturbed) image and a distorted image using optical-flow algorithms, which solve for a dense per-pixel motion field under a brightness-constancy assumption. The recovered displacement field is proportional to the line-of-sight-integrated refractive-index gradient, and can be inverted, for example by Poisson solving or tomography, to reconstruct the density or pressure field.','BOS looks at a patterned background through disturbed air or water. Optical flow is a method that measures how each part of the pattern seems to move. It compares a clear image with a distorted one. The measured shift maps the bending of light. That shift can then be turned into a density picture.','Provides a dense, whole-field estimate of background displacement in BOS, replacing sparse cross-correlation windows with per-pixel motion for finer spatial detail.','Used in BOS post-processing to extract high-resolution deflection fields from high-speed footage of jets, shocks, and sound, especially where fine gradients must be resolved.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Background-oriented schlieren','Consecutive frame subtraction','Optical flow','Refractive-index gradient','Density-gradient visualization']::text[],ARRAY['Trusting optical flow where the brightness-constancy assumption fails, as with large shifts or lighting changes','Using it on low-texture backgrounds that give no reliable motion','Skipping the inversion step and treating displacement as density']::text[],ARRAY['Extracting a dense deflection field from BOS video of a jet','Resolving fine gradients near a shock','Feeding displacement into a density reconstruction']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical flow BOS');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5e85c9a-ecd5-5e7c-aae9-3e212b4a7ee6','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5e85c9a-ecd5-5e7c-aae9-3e212b4a7ee6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5e85c9a-ecd5-5e7c-aae9-3e212b4a7ee6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fa2dc9d-b39f-5a61-ba1e-1005f9eb9138','Consecutive frame subtraction','An image-processing step, used in some schlieren, BOS, and high-speed visualization workflows, in which each frame is subtracted from a neighbouring frame (or a running reference) to isolate the time-varying part of the scene. By removing static background and slowly varying illumination, it emphasises moving wavefronts, oscillating acoustic fields, and transient gradients, improving the visibility of small changes at the cost of suppressing steady structure.','This method subtracts one video frame from the next. Whatever stays the same cancels out. Whatever moves or changes stands out. It helps reveal a moving wave or a fast sound field. The trade-off is that steady features disappear.','Isolates the dynamic, changing component of a visualization so faint moving disturbances are not lost against a bright static background.','Applied to high-speed schlieren and BOS footage to bring out propagating acoustic wavefronts, shock motion, or oscillating fields that are hard to see in raw frames.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Optical flow BOS','Background-oriented schlieren','Background subtraction','High-speed imaging','Schlieren optics']::text[],ARRAY['Losing genuine steady structure that actually mattered','Amplifying camera noise along with real motion','Assuming the difference image shows absolute amplitude rather than change between frames']::text[],ARRAY['Highlighting a moving wavefront in high-speed schlieren','Isolating an oscillating ultrasound field from a static tank','Cleaning slow lighting drift from a sequence']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Consecutive frame subtraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fa2dc9d-b39f-5a61-ba1e-1005f9eb9138','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fa2dc9d-b39f-5a61-ba1e-1005f9eb9138') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fa2dc9d-b39f-5a61-ba1e-1005f9eb9138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7898ca9a-7b8d-578b-8265-b21769c16bb9','Acoustic shadowgraphy','A shadowgraph technique applied to acoustic disturbances, in which light casts a shadow whose brightness variations respond to the second spatial derivative of refractive index, and hence of density. Unlike schlieren, shadowgraphy needs no knife edge or precise focus; regions where the density gradient itself changes sharply, such as shock fronts and wavefront edges, appear as bright and dark bands. It is simple and robust but less sensitive to gentle gradients than schlieren.','Shadowgraphy makes sound visible as light and dark shadows. Light shines through the medium onto a screen or sensor. Where the density bends light unevenly, the shadow brightens or darkens. It reacts most to sharp changes, like a wave''s edge or a shock. It is simpler than schlieren but shows gentle changes less well.','Provides a simple, robust way to reveal acoustic wavefronts and shocks, especially sharp fronts, without the alignment demands of a schlieren stop.','Used to image shock waves, blast fronts, and strong acoustic pulses; a common teaching and field method because it needs only a bright point source and a screen or camera.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Schlieren optics','Density-gradient visualization','Sonic-boom visualization','Refractive-index gradient','Shock wave']::text[],ARRAY['Confusing shadowgraphy, the second derivative, with schlieren, the first derivative','Expecting strong contrast from smooth, gentle gradients','Assuming shadow brightness gives absolute pressure']::text[],ARRAY['Imaging a blast or shock front in air','Showing a strong acoustic pulse in a demonstration','Comparing shadowgraph and schlieren views of a shock']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic shadowgraphy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7898ca9a-7b8d-578b-8265-b21769c16bb9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7898ca9a-7b8d-578b-8265-b21769c16bb9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7898ca9a-7b8d-578b-8265-b21769c16bb9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '653d462f-a782-536e-9f31-8365b474e642','Laser interferometry','An optical measurement in which a laser beam is split into a reference and a probe path, and their recombination produces interference fringes whose shifts reveal changes in optical path length. In acoustics it senses the small refractive-index (density) change of a sound field or the physical displacement of a vibrating surface, giving quantitative, non-contact measurement of the integrated index or of nanometre-scale motion. Configurations include Mach-Zehnder, Michelson, and laser Doppler vibrometry.','Laser interferometry splits a laser into two beams and recombines them. The beams form a striped pattern of light and dark. When one path changes length, the stripes shift. Sound or vibration changes that path very slightly. Measuring the shift gives a precise, no-contact reading.','Provides precise, non-contact measurement of tiny density changes or surface motion, serving as both a quantitative sound-field probe and a vibration sensor.','Used as a laser Doppler vibrometer to measure loudspeaker and structural vibration, and in Mach-Zehnder form to quantify an acoustic pressure or index field without disturbing it.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Laser Doppler vibrometry','Mach-Zehnder interferometer','Refractive-index gradient','Acousto-optic effect','Optical acoustic sensing']::text[],ARRAY['Assuming it needs no vibration isolation, when stray motion swamps the signal','Confusing surface-vibration and index-change measurements, which sense different things','Ignoring the two-pi fringe ambiguity when the path change is large']::text[],ARRAY['Measuring loudspeaker cone motion with a vibrometer','Quantifying an ultrasound field''s pressure optically','Checking panel vibration without adding mass']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '653d462f-a782-536e-9f31-8365b474e642','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='653d462f-a782-536e-9f31-8365b474e642') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='653d462f-a782-536e-9f31-8365b474e642');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '715ae6e9-8305-59c4-95a5-6a48473c8434','Pressure-gradient image','A visualization whose pixel values represent the spatial gradient of acoustic pressure, or the closely related density gradient, rather than the pressure amplitude itself. Because gradient-based optical methods such as schlieren respond to the derivative of the field, their raw output is inherently a pressure- or density-gradient image; recovering absolute pressure requires spatial integration and calibration. Such images emphasise wavefront edges and regions of rapid change.','A pressure-gradient image shows how fast sound pressure changes across space. It does not show the pressure value at each point. Edges of waves, where pressure changes quickly, stand out brightly. Methods like schlieren naturally make this kind of image. To get real pressure, you must process the gradient further.','Represents where an acoustic field changes most rapidly, which is what gradient-sensitive optical methods actually record, and highlights wavefronts and boundaries.','Guides interpretation of raw schlieren and BOS output, where technicians must remember they see a gradient and integrate or calibrate before quoting pressure levels.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Refractive-index gradient','Schlieren optics','Density-gradient visualization','Background-oriented schlieren','Acoustic pressure']::text[],ARRAY['Reading gradient brightness as sound pressure level','Forgetting that integration and calibration are needed for absolute values','Assuming zero brightness means zero pressure rather than zero gradient']::text[],ARRAY['Interpreting a raw schlieren frame of a wave','Explaining why wavefront edges look brightest','Deciding whether to integrate a gradient map into pressure']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-gradient image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '715ae6e9-8305-59c4-95a5-6a48473c8434','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='715ae6e9-8305-59c4-95a5-6a48473c8434') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='715ae6e9-8305-59c4-95a5-6a48473c8434');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1db8efe-8c6f-5dcf-80fb-497876d8d7b4','Sonic-boom visualization','The use of schlieren, shadowgraph, or background-oriented schlieren methods to image the shock-wave system produced by an object moving at supersonic speed, whose coalescing pressure waves form the N-wave heard as a sonic boom. Ground-to-air BOS, using the sun or a patterned background, and laboratory schlieren both render the oblique shocks and their angles, supporting study of boom generation and of low-boom aircraft shaping.','This means making the shock waves from a supersonic object visible. A fast object pushes air into sharp pressure waves. These waves cause the sound heard as a sonic boom. Schlieren and BOS methods turn the invisible shocks into a picture. Engineers use it to study and reduce booms.','Reveals the shape, position, and strength of supersonic shock waves so their contribution to boom loudness can be studied and reduced.','Used in wind tunnels and in flight tests, such as air-to-air BOS against the sun, to image aircraft shocks and validate low-boom designs.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic shadowgraphy','Schlieren optics','Background-oriented schlieren','Shock wave','Mach cone']::text[],ARRAY['Confusing the visualized shock with the audible boom itself','Assuming brightness equals boom loudness','Forgetting the image is a path-integrated projection of a three-dimensional shock system']::text[],ARRAY['Imaging shocks on a supersonic wind-tunnel model','Air-to-air BOS of an aircraft against the sun','Validating a low-boom fuselage shape']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic-boom visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1db8efe-8c6f-5dcf-80fb-497876d8d7b4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1db8efe-8c6f-5dcf-80fb-497876d8d7b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1db8efe-8c6f-5dcf-80fb-497876d8d7b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa27f384-fdcc-59b4-842b-8f0706deb969','Acoustic beam-profile imaging','Measurement and display of the spatial distribution of an acoustic field across a beam, including its width, focal region, side lobes, and symmetry, obtained either optically (schlieren, interferometry) or by scanning a hydrophone or needle probe through the field and mapping the recorded pressure. The result characterises how energy is distributed in space, which is central to transducer specification and to exposure assessment.','This means mapping the shape of a sound beam. It shows how wide the beam is and where it focuses. It also shows side lobes and whether the beam is even. The map comes from optics or from moving a small sensor through the field. It tells engineers how the sound energy spreads.','Characterises how an acoustic transducer distributes energy in space, needed for design, quality control, and exposure or safety evaluation.','Used in transducer quality control and medical-device testing to verify focal depth, beam width, and side-lobe levels against specification.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Ultrasound beam visualization','Hydrophone','Acoustic schlieren','Beam width','Side lobe']::text[],ARRAY['Assuming a single-plane scan captures a full three-dimensional beam','Overlooking side lobes that carry stray energy','Confusing the minus-six-decibel beam width with the full energy distribution']::text[],ARRAY['Verifying the focal depth of a therapy transducer','Mapping side lobes of an imaging array','Comparing a measured beam to its design']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic beam-profile imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa27f384-fdcc-59b4-842b-8f0706deb969','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa27f384-fdcc-59b4-842b-8f0706deb969') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa27f384-fdcc-59b4-842b-8f0706deb969');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae3d42c1-bdc6-57da-afa0-e6dbbd72c9e4','Ultrasound beam visualization','Techniques that make the spatial field of an ultrasonic transducer visible, including optical schlieren in water, hydrophone scanning, and optical tomography. The visualization reveals the beam''s near-field structure, focusing, steering, and diffraction, and is used to confirm that a transducer produces the intended field before deployment.','This means making an ultrasound beam visible. Ultrasound is silent and invisible to the eye. Optical or sensor methods turn its field into a picture. The picture shows how the beam focuses, steers, and spreads. It confirms a transducer works as intended.','Confirms and characterises the field of an ultrasonic transducer so its focusing, steering, and uniformity can be checked against design.','Used in manufacturing quality control, research, and teaching to inspect medical, industrial, and haptic ultrasound beams, often via schlieren in a water tank.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Ultrasonic schlieren imaging','Acoustic beam-profile imaging','Hydrophone','Phased-array ultrasound focusing','Acoustic schlieren']::text[],ARRAY['Treating a water-tank image as identical to behaviour in tissue','Ignoring nonlinear distortion at high drive levels','Assuming the eye-visible pattern is the exact pressure field']::text[],ARRAY['Inspecting an imaging probe''s beam in water','Checking electronic steering of a phased array','Demonstrating ultrasound focusing in a lab']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasound beam visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae3d42c1-bdc6-57da-afa0-e6dbbd72c9e4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae3d42c1-bdc6-57da-afa0-e6dbbd72c9e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae3d42c1-bdc6-57da-afa0-e6dbbd72c9e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9068a222-7753-5dd8-89f7-7f29c35afbb5','HIFU field visualization','Imaging of the field produced by a high-intensity focused ultrasound (HIFU) source, concerned with locating the focal spot, mapping intensity and side lobes, and observing time-dependent and nonlinear effects such as shock formation, cavitation, and heating. Methods include schlieren, hydrophone scanning, thermochromic or tissue-mimicking phantoms, and ultrasound or MR thermometry, chosen to capture the very high pressures and rapid dynamics involved.','HIFU is very strong focused ultrasound used to heat or destroy tissue. Visualizing its field shows where the energy focuses. It also shows side lobes, heating, and bubble effects. Special methods are needed because the sound is so intense. This helps keep the treatment safe and accurate.','Locates and characterises the intense focal region and its dynamics so HIFU therapy can be targeted safely and effectively.','Used in therapy-device development and quality control to verify focal position and intensity, and to study cavitation and heating in tissue-mimicking phantoms.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Focused acoustic beam','Acoustic beam-profile imaging','Cavitation','Ultrasound beam visualization','Acoustic radiation-force field']::text[],ARRAY['Assuming the focus in water matches the focus in tissue, which absorbs and shifts it','Ignoring cavitation and nonlinear shock formation at the focus','UNSAFE: exposing hands or eyes to a HIFU focal region, or driving the transducer without proper acoustic loading']::text[],ARRAY['Verifying focal position before a HIFU treatment plan','Studying cavitation at the focus in a phantom','Mapping intensity to check for hot side lobes']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HIFU field visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9068a222-7753-5dd8-89f7-7f29c35afbb5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9068a222-7753-5dd8-89f7-7f29c35afbb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9068a222-7753-5dd8-89f7-7f29c35afbb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '960f45ac-2ccb-5693-8ed4-4c136d98dbce','Acoustic levitation field imaging','Visualization of the standing-wave ultrasonic pressure field used to trap particles or droplets in acoustic levitation, revealing the nodes and antinodes where the acoustic radiation force holds objects. Methods include pulsed or stroboscopic schlieren, which images the periodic density field, and hydrophone or optical mapping; the images confirm node spacing of half a wavelength, field symmetry, and stability of the trap.','Acoustic levitation uses strong sound to hold small objects in mid-air. It works because a standing sound wave has still points that trap them. Imaging the field shows where these trapping points sit. Pulsed schlieren can freeze and picture the field. This confirms the trap is stable and correctly spaced.','Confirms the structure and stability of the standing-wave trap in acoustic levitation so trapping points and their spacing can be checked and tuned.','Used in levitation-rig development to verify node spacing and symmetry, and to diagnose why particles drift or drop.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Dynamic levitation trap visualization','Acoustic radiation-force field','Standing wave','Pulsed schlieren imaging','Ultrasonic haptics field imaging']::text[],ARRAY['Confusing pressure nodes with the actual trapping points, which depend on radiation force and particle type','Assuming a single image shows the oscillating field''s full cycle','Ignoring that node spacing is half a wavelength, not a full wavelength']::text[],ARRAY['Checking node spacing in a levitation rig','Diagnosing why a levitated droplet drifts','Imaging a standing wave between two transducers']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic levitation field imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '960f45ac-2ccb-5693-8ed4-4c136d98dbce','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='960f45ac-2ccb-5693-8ed4-4c136d98dbce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='960f45ac-2ccb-5693-8ed4-4c136d98dbce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25a8d620-ab7c-5e24-90d0-490e01da7dce','Ultrasonic haptics field imaging','Visualization of the airborne ultrasound field generated by a phased array to create mid-air tactile sensations, where focal points and modulated patterns are steered to stimulate the skin. Imaging, typically pulsed or stroboscopic schlieren or hydrophone mapping, reveals focal position, spatial pattern, and how the array''s phase control shapes the field, supporting design and calibration of mid-air haptic displays.','Some devices use focused ultrasound in air to create a sense of touch. You feel it without touching anything solid. Imaging the field shows where the array focuses the sound. It also shows how the pattern moves and changes. This helps designers place and shape the touch points.','Reveals where and how an airborne-ultrasound haptic array focuses energy so tactile focal points and patterns can be designed and calibrated.','Used in mid-air haptics development to verify focal position and steering, and to study how modulation creates a perceivable touch sensation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phased-array ultrasound focusing','Acoustic radiation-force field','Pulsed schlieren imaging','Acoustic levitation field imaging','Mid-air haptics']::text[],ARRAY['Assuming the felt point is exactly the pressure peak, ignoring modulation and skin response','Overlooking side lobes that waste energy or cause stray sensation','Treating one schlieren frame as the whole modulated cycle']::text[],ARRAY['Verifying a haptic array''s focal point in the air','Studying how modulation frequency affects the felt sensation','Mapping side lobes of a mid-air haptic device']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic haptics field imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25a8d620-ab7c-5e24-90d0-490e01da7dce','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25a8d620-ab7c-5e24-90d0-490e01da7dce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25a8d620-ab7c-5e24-90d0-490e01da7dce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53d652a3-da47-5b6d-838e-9efeef328d21','Dynamic levitation trap visualization','Imaging of time-varying acoustic traps in which the phase and amplitude of a transducer array are updated in real time to move, rotate, or reconfigure levitated particles. Because the trap itself changes, high-speed pulsed or stroboscopic imaging, or synchronised hydrophone mapping, is needed to capture the evolving pressure field and confirm that trap points follow the intended trajectory without losing the particle.','Some acoustic traps move the trapped object around. The array changes its sound pattern quickly to shift the trap. Visualizing this needs fast, frozen images at each moment. The images show the trap points moving as planned. This confirms the particle is carried smoothly and not dropped.','Confirms that a reconfigurable acoustic trap moves particles along the intended path by imaging the changing field over time.','Used in research on acoustic manipulation and displays to verify particle handling, rotation, and multi-point trapping as the field is updated.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic levitation field imaging','Acoustic holographic trap','Phased-array ultrasound focusing','Acoustic radiation-force field','Pulsed schlieren imaging']::text[],ARRAY['Assuming a static image captures a moving trap','Updating the field too fast for the particle to follow, causing it to drop','Confusing the imaged field with the actual force on the particle']::text[],ARRAY['Tracking a moving trap in a particle-manipulation rig','Imaging rotation of a levitated object','Debugging why fast trap motion drops the particle']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic levitation trap visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53d652a3-da47-5b6d-838e-9efeef328d21','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53d652a3-da47-5b6d-838e-9efeef328d21') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53d652a3-da47-5b6d-838e-9efeef328d21');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b1858a1-7f2d-53e9-b49b-e2ceb923c5f2','Holographic acoustic field','A sound field generated or reconstructed by encoding a target spatial amplitude and phase distribution into a source, in direct analogy with optical holography. A passive acoustic hologram, such as a 3-D-printed phase plate, or an active phased array imposes a designed phase, and sometimes amplitude, profile on an emitted wave so that at a chosen plane or volume the field reconstructs the desired pattern: an image, a set of focal points, or a trapping landscape.','A holographic acoustic field is a sound field shaped to form a chosen pattern. It works like a hologram, but with sound instead of light. A special plate or an array sets the phase of the wave. As the wave travels, it builds the target pattern. This can make images, focal points, or traps.','Lets a single source create a complex, predetermined sound pattern, replacing many individually controlled elements with one designed phase profile.','Used to make 3-D-printed acoustic holograms for particle assembly, targeted ultrasound, and haptic patterns, and to program phased arrays for shaped fields.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic hologram','Phase plate','Acoustic wavefront shaping','Phased-array ultrasound focusing','Acoustic holographic trap']::text[],ARRAY['Assuming a hologram reconstructs perfectly everywhere rather than at its design plane','Ignoring amplitude errors when only phase is controlled','Forgetting that a passive hologram works for one frequency and geometry']::text[],ARRAY['Printing an acoustic hologram to assemble particles into a shape','Programming an array to form a target field','Focusing ultrasound through a skull with a designed phase plate']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic acoustic field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b1858a1-7f2d-53e9-b49b-e2ceb923c5f2','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b1858a1-7f2d-53e9-b49b-e2ceb923c5f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b1858a1-7f2d-53e9-b49b-e2ceb923c5f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e92e79c9-db7f-51d2-991b-1b5f5815c117','Acoustic wavefront shaping','The deliberate control of the phase and amplitude across a wavefront, via phased arrays, metasurfaces, phase plates, or holograms, to synthesise a desired downstream field such as a focus, a steered beam, a vortex, or a multi-point pattern. By setting the emitted phase profile so contributions add constructively where wanted, wavefront shaping generalises focusing and steering to arbitrary field design.','Wavefront shaping means controlling the shape of a sound wave as it leaves a source. You set the timing, or phase, across the source surface. The parts of the wave then add up to form a target field. This can make a focus, a steered beam, or a complex pattern. Arrays, metasurfaces, and holograms all do this.','Provides general control over where and how acoustic energy concentrates, enabling focusing, steering, and arbitrary field patterns from one aperture.','Used in medical ultrasound, mid-air haptics, particle manipulation, and communications to place acoustic energy precisely and adaptively.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phased-array ultrasound focusing','Holographic acoustic field','Acoustic metasurface','Phase plate','Acoustic phase mask']::text[],ARRAY['Assuming perfect shaping despite element spacing, aberration, and bandwidth limits','Controlling phase but ignoring amplitude, which limits pattern fidelity','Confusing steering, which moves a beam, with full field synthesis']::text[],ARRAY['Focusing ultrasound through an aberrating layer','Steering a haptic focal point in air','Designing a multi-focus therapy field']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic wavefront shaping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e92e79c9-db7f-51d2-991b-1b5f5815c117','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e92e79c9-db7f-51d2-991b-1b5f5815c117') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e92e79c9-db7f-51d2-991b-1b5f5815c117');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76c0f23b-d76a-51b3-930a-ddb23ad2c028','Phase plate','A passive element of spatially varying thickness, or sound speed, that imposes a designed position-dependent phase delay on a transmitted acoustic wave, thereby shaping the wavefront. Where the wave passes through more, or slower, material it is delayed more; the local phase shift equals two pi over the wavelength, times the index minus one, times the thickness, where the index is the ratio of the surrounding sound speed to the plate''s. Stacking the required delays across the aperture encodes a lens, hologram, or arbitrary phase profile.','A phase plate is a shaped piece of material that delays sound. Thicker or slower parts hold the wave back more. This changes the wave''s timing across its width. By designing the thickness, you shape the wavefront. It can act like a lens or a hologram.','Encodes a fixed, designed phase profile into a passing wave, giving passive, low-cost wavefront shaping without active electronics.','Used as 3-D-printed acoustic holograms and lenses for focusing, imaging, and particle assembly at a single design frequency.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic phase mask','Holographic lens','Holographic acoustic field','Acoustic metasurface','Acoustic wavefront shaping']::text[],ARRAY['Assuming one plate works across a wide band, when it is designed for one frequency','Ignoring absorption and impedance mismatch that reduce transmission','Treating thickness as setting amplitude rather than phase']::text[],ARRAY['3-D printing a plate to focus ultrasound','Encoding an image into a transmitted field','Building a passive acoustic lens']::text[],'intermediate','Δφ = (2π/λ)·(n − 1)·d,  n = c₀/c_plate','The phase shift equals two pi over the wavelength, times the index minus one, times the plate thickness; the index is the surrounding sound speed divided by the plate''s sound speed.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase plate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76c0f23b-d76a-51b3-930a-ddb23ad2c028','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76c0f23b-d76a-51b3-930a-ddb23ad2c028') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76c0f23b-d76a-51b3-930a-ddb23ad2c028');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b581548-6e6a-56a3-94d1-ab93685a376a','Acoustic phase mask','A patterned, spatially discretised element, often a grid of cells with differing depth, sound speed, or path length, that imposes a position-dependent phase shift on a wave to encode a hologram or shaped field. Conceptually a discretised phase plate, a phase mask quantises the target phase profile into fabricable pixels, trading some fidelity for manufacturability and, in reconfigurable forms, for programmability.','A phase mask is a patterned plate that shifts a sound wave''s phase cell by cell. Each cell delays the wave by a set amount. Together the cells encode a target pattern. It is like a pixelated phase plate. Some versions can be reprogrammed.','Encodes a designed phase pattern in discrete, fabricable pixels so holograms and shaped fields can be manufactured or, in active forms, reconfigured.','Used to build acoustic holograms and metasurface elements for focusing, beam shaping, and particle patterning.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phase plate','Holographic lens','Acoustic metasurface','Holographic acoustic field','Diffractive acoustic element']::text[],ARRAY['Assuming fine pixels are free, when cell size limits the finest spatial detail','Ignoring quantisation error from coarse phase steps','Confusing a passive mask with an actively steered array']::text[],ARRAY['Designing a pixelated acoustic hologram','Fabricating a metasurface phase pattern','Encoding multiple focal points into one element']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic phase mask');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b581548-6e6a-56a3-94d1-ab93685a376a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b581548-6e6a-56a3-94d1-ab93685a376a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b581548-6e6a-56a3-94d1-ab93685a376a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bab99024-3bd6-564b-945d-91d18a454900','Holographic lens','An acoustic element that focuses or images sound by imposing a radially varying phase profile, like a diffractive or Fresnel lens, rather than by a bulk curved refracting body. For a chosen focal length and wavelength, the required phase at each radius brings all contributions into phase at the focus. Implemented as a phase plate, Fresnel zone plate, or metasurface, it enables thin, flat, or multifunction focusing.','A holographic lens focuses sound using a phase pattern, not a curved lens. It delays each ring of the wave by the right amount. All parts then arrive together at the focus. This lets the lens be thin and flat. It can also focus at more than one point.','Focuses or images sound with a thin, designed phase profile, replacing bulky curved lenses and enabling multi-focus or shaped focusing.','Used for compact ultrasound focusing, through-skull therapy correction, and flat acoustic imaging elements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phase plate','Fresnel zone plate','Focused acoustic beam','Acoustic metasurface','Holographic acoustic field']::text[],ARRAY['Assuming it focuses over a wide band, when the phase profile suits one design frequency','Ignoring higher diffraction orders that steal energy','Confusing phase-timing focusing with refraction by a curved body']::text[],ARRAY['Designing a flat lens to focus ultrasound','Correcting focus through the skull','Making a multi-focus therapy element']::text[],'advanced','φ(r) = −(2π/λ)·(√(r² + f²) − f)','The phase at a given radius equals minus two pi over the wavelength, times the square root of radius squared plus focal length squared, minus the focal length.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic lens');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bab99024-3bd6-564b-945d-91d18a454900','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bab99024-3bd6-564b-945d-91d18a454900') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bab99024-3bd6-564b-945d-91d18a454900');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47b7e1eb-019f-567b-8f14-23902a7fa871','Diffractive acoustic element','A sound-shaping component that works by diffraction from a designed wavelength- or sub-wavelength-scale structure, such as gratings, zone plates, or patterned apertures, rather than by refraction through a bulk medium. By controlling how the structure re-radiates an incident wave, it steers, focuses, splits, or otherwise shapes the field. Periodic versions send energy into discrete diffraction orders whose angles are set by the period, the wavelength, and the order number.','A diffractive acoustic element shapes sound by bending it around a fine pattern. The pattern splits or redirects the wave into set directions. This is diffraction, not simple refraction. Gratings and zone plates are examples. They can focus, steer, or split a beam.','Steers, focuses, or splits sound using a patterned structure, enabling thin, flat, and multifunction elements that bulk refraction cannot easily provide.','Used as zone-plate lenses, beam splitters, and metasurface gratings in ultrasound and audio-frequency devices.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Fresnel zone plate','Acoustic metasurface','Holographic lens','Acoustic phase mask','Negative refraction acoustics']::text[],ARRAY['Assuming a single diffraction direction, when periodic structures create multiple orders','Expecting broadband behaviour from a frequency-tuned pattern','Confusing diffraction by a pattern with refraction through a lens']::text[],ARRAY['Designing a zone-plate ultrasound lens','Splitting a beam with an acoustic grating','Building a flat diffractive focusing element']::text[],'intermediate','d·sin θ_m = m·λ','The grating period times the sine of the diffraction angle equals the order number times the wavelength.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffractive acoustic element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47b7e1eb-019f-567b-8f14-23902a7fa871','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47b7e1eb-019f-567b-8f14-23902a7fa871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47b7e1eb-019f-567b-8f14-23902a7fa871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8f0e199-389f-510f-ad52-3aabc5ddec7f','Negative refraction acoustics','Refraction in an acoustic metamaterial whose effective parameters cause a wave to bend to the same side of the surface normal as the incident wave, the opposite of ordinary media, corresponding to a negative effective refractive index. It arises when the effective mass density and effective bulk modulus are simultaneously negative, so the phase velocity opposes the direction of energy flow. It enables flat superlenses, sub-diffraction focusing, and unusual beam steering.','Normally sound bends one way when it enters a new material. In some engineered materials it bends the opposite way. This is called negative refraction. It happens when the material''s effective density and stiffness are both negative. It allows flat lenses and very sharp focusing.','Enables acoustic focusing and lensing beyond ordinary limits, including flat superlenses and sub-wavelength focusing, by giving a medium a negative effective index.','Explored in metamaterial lenses and imaging devices aiming for resolution finer than the classic diffraction limit.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic metamaterial','Effective mass density','Acoustic superlens','Diffractive acoustic element','Negative effective modulus']::text[],ARRAY['Assuming negative refraction violates energy conservation, when energy still flows forward','Confusing negative phase velocity with backward energy transport','Expecting it from ordinary materials rather than engineered metamaterials']::text[],ARRAY['Designing a flat acoustic superlens','Studying sub-diffraction focusing in a metamaterial','Demonstrating reversed bending at a metamaterial interface']::text[],'advanced','n = c₀/c_p ;  n < 0 when ρ_eff < 0 and B_eff < 0','The effective index equals the reference sound speed divided by the phase speed; it is negative when the effective density and effective bulk modulus are both negative.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Negative refraction acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8f0e199-389f-510f-ad52-3aabc5ddec7f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8f0e199-389f-510f-ad52-3aabc5ddec7f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8f0e199-389f-510f-ad52-3aabc5ddec7f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53cc6df4-a6bd-52e7-82d5-a4d16d81a222','Acoustic orbital angular momentum','A property of an acoustic vortex beam whose wavefront spirals around the propagation axis, carrying orbital angular momentum characterised by an integer topological charge. The complex pressure carries an azimuthal phase term that winds through an integer multiple of two pi around the axis, producing a helical wavefront and a central phase singularity where amplitude vanishes; the beam can exert a torque on absorbing or scattering objects, enabling rotational manipulation.','Some sound beams twist as they travel, like a corkscrew. This twist carries a kind of rotational momentum. A whole number, the charge, sets how many times the wave winds. The center of the beam is silent. Such a beam can spin small objects it hits.','Provides a rotational degree of freedom in a sound field, letting a beam carry and transfer torque for spinning and manipulating particles.','Used in acoustic tweezers and manipulation to rotate particles, and studied for communication channels that multiplex on the amount of twist.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic vortex beam','Bessel acoustic beam','Acoustic radiation-force field','Topological charge','Acoustic holographic trap']::text[],ARRAY['Confusing orbital angular momentum, a helical wavefront, with spin from polarization, which sound lacks','Assuming the beam center is a pressure peak rather than a null','Thinking any focused beam carries a twist']::text[],ARRAY['Rotating a trapped particle with a vortex beam','Multiplexing data on beams of different charge','Imaging the central null of a vortex field']::text[],'advanced','p(r,θ,z) ∝ exp(i·ℓ·θ)','The complex pressure varies with the azimuthal angle as the exponential of the imaginary unit times the topological charge times the angle.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic orbital angular momentum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53cc6df4-a6bd-52e7-82d5-a4d16d81a222','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53cc6df4-a6bd-52e7-82d5-a4d16d81a222') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53cc6df4-a6bd-52e7-82d5-a4d16d81a222');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd023a0f4-cfe2-55dd-9b25-d85091499a15','Bessel acoustic beam','An acoustic field whose transverse amplitude profile follows a Bessel function, giving a central lobe surrounded by concentric rings and the property of being non-diffracting over an extended range: the central lobe resists spreading far beyond a comparable Gaussian beam. Ideal Bessel beams require infinite aperture and energy, so real beams are quasi-Bessel; higher-order (vortex) versions also carry orbital angular momentum through an azimuthal phase term.','A Bessel acoustic beam has a bright center ringed by circles. Its central spot stays narrow for a long distance. That is why it is called non-diffracting. A perfect one is impossible, so real beams only approximate it. Higher-order versions also twist as they travel.','Provides a beam whose narrow core resists spreading over an extended range, useful where a tight, long, stable focus is wanted.','Used in ultrasound imaging and manipulation for extended depth of field, and in particle handling for long trapping regions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic orbital angular momentum','Airy acoustic beam','Focused acoustic beam','Non-diffracting beam','Acoustic vortex beam']::text[],ARRAY['Believing a Bessel beam never spreads, when real finite ones eventually do','Ignoring the energy carried in the outer rings','Assuming its core holds more total energy than a focused beam']::text[],ARRAY['Extending depth of field in ultrasound imaging','Trapping particles along a long beam core','Comparing Bessel and focused beam spreading']::text[],'advanced','p(r,θ,z) ∝ J_ℓ(k_r·r)·exp(i·ℓ·θ)·exp(i·k_z·z)','The pressure varies radially as an order-ell Bessel function of the radial wavenumber times radius, with an azimuthal phase term and an axial propagation term.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bessel acoustic beam');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd023a0f4-cfe2-55dd-9b25-d85091499a15','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d023a0f4-cfe2-55dd-9b25-d85091499a15') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d023a0f4-cfe2-55dd-9b25-d85091499a15');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd8d4e06-7021-54ef-86b7-5bddd1552879','Airy acoustic beam','A structured acoustic field whose transverse profile follows an Airy function, giving it two signature properties: transverse self-acceleration, in which the main lobe follows a curved, roughly parabolic trajectory as it propagates, and self-healing, in which the profile partially reconstructs after an obstruction. Like Bessel beams, ideal Airy beams are non-physical, requiring infinite energy; truncated finite versions retain the bending and self-healing over a limited range.','An Airy acoustic beam bends sideways as it travels, following a curve. It is not pushed; it curves on its own. It can also partly rebuild itself after hitting an obstacle. A perfect version is impossible, so real ones curve only for a while. Its shape follows a special math function called the Airy function.','Provides a beam that curves around obstacles and self-heals, useful for steering energy along a bent path or past a blockage.','Explored for clearing particles along curved paths, and for delivering ultrasound around obstacles in imaging and manipulation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Bessel acoustic beam','Non-diffracting beam','Acoustic wavefront shaping','Self-healing beam','Focused acoustic beam']::text[],ARRAY['Thinking the beam''s energy really accelerates sideways, when the pattern bends but momentum is conserved','Expecting unlimited bending from a real, finite beam','Assuming self-healing restores the full field perfectly']::text[],ARRAY['Steering particles along a curved path','Delivering ultrasound around an obstacle','Demonstrating self-healing after a blocker']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airy acoustic beam');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd8d4e06-7021-54ef-86b7-5bddd1552879','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd8d4e06-7021-54ef-86b7-5bddd1552879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd8d4e06-7021-54ef-86b7-5bddd1552879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1001797e-bf2f-52c2-ac7a-d92232dc3135','Focused acoustic beam','An acoustic field converged toward a focal region by a curved source, lens, or phased array, producing elevated pressure and intensity near the focus and lower levels elsewhere. The focal size scales with wavelength and with the source''s f-number, its focal length divided by aperture; tighter focusing, meaning a lower f-number, gives a smaller, more intense focal spot, bounded by the diffraction limit of roughly one wavelength.','A focused acoustic beam brings sound to a small, intense spot. A curved source, lens, or array makes the waves meet there. The spot is strongest at the focus and weak elsewhere. A wider source focuses to a smaller spot. The spot cannot be smaller than about one wavelength.','Concentrates acoustic energy into a small region so it can act locally, heating, imaging, or applying force, while sparing surrounding areas.','Central to medical imaging and therapy such as HIFU and lithotripsy, industrial cleaning, and particle manipulation, where focal placement and size are designed to specification.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Phased-array ultrasound focusing','HIFU field visualization','Holographic lens','F-number','Acoustic radiation-force field']::text[],ARRAY['Assuming the focus can be made arbitrarily small, when diffraction limits it to about a wavelength','Ignoring absorption that shifts and weakens the focus in tissue','Confusing focal intensity gain with total power, which is unchanged']::text[],ARRAY['Setting focal depth for a therapy transducer','Choosing an f-number for a target spot size','Focusing ultrasound to move a particle']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Focused acoustic beam');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1001797e-bf2f-52c2-ac7a-d92232dc3135','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1001797e-bf2f-52c2-ac7a-d92232dc3135') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1001797e-bf2f-52c2-ac7a-d92232dc3135');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6631dbf8-1617-593d-90ea-8ed299db245f','Phased-array ultrasound focusing','Electronic focusing and steering of an ultrasonic field by driving each element of a transducer array with an individually controlled time delay, or phase, so emitted wavelets arrive in phase at a chosen focal point. The delay for each element compensates its path-length difference to the focus; changing the delay law moves the focus or steers the beam without moving the array, and receive-side delays likewise focus incoming echoes.','A phased array is a grid of small ultrasound sources. Each one is fired at a slightly different time. The waves then meet in phase at one chosen point. Changing the timing moves that point. This steers and focuses the beam with no moving parts.','Provides fast, electronic control of where an ultrasound beam focuses and points, replacing mechanical scanning and enabling adaptive focusing.','Standard in medical ultrasound imaging and therapy and in industrial non-destructive testing, where beams are steered and focused in real time.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Focused acoustic beam','Acoustic wavefront shaping','Beam steering','Time delay','Ultrasound beam visualization']::text[],ARRAY['Ignoring grating lobes when element spacing exceeds about half a wavelength','Assuming steering is unlimited rather than bounded by element directivity','Confusing transmit focusing with dynamic receive focusing']::text[],ARRAY['Steering an imaging beam across tissue','Setting delays to focus at a target depth','Non-destructive testing of a weld with a phased array']::text[],'intermediate','Δt_n = (|r_n − r_f| − R₀) / c','Each element''s delay equals its distance to the focus minus a common reference distance, divided by the sound speed.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased-array ultrasound focusing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6631dbf8-1617-593d-90ea-8ed299db245f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6631dbf8-1617-593d-90ea-8ed299db245f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6631dbf8-1617-593d-90ea-8ed299db245f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f21c3f6c-c15b-50c2-944f-27d0eaff408f','Time-reversal acoustics','A focusing method exploiting the time-reversal invariance of the lossless wave equation: a wave from a source is recorded by an array of transducers, time-reversed, and re-emitted, so it retraces its path and converges back onto the original source location, even through complex or scattering media. Scattering and reverberation improve rather than degrade the refocusing, because they add independent paths that the reversed field recombines coherently.','The wave equation works the same forwards and backwards in time. Time-reversal acoustics uses this fact. An array records a sound, flips it in time, and plays it back. The wave then travels back and refocuses on the original spot. Echoes and scattering actually help it focus better.','Focuses acoustic energy back onto a source or target through unknown, complex, or scattering media without needing to model them.','Used in medical therapy such as focusing through bone, non-destructive testing, underwater communication, and lithotripsy targeting.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Time-reversal mirror','Phase conjugation','Acoustic wavefront shaping','Reverberation','Phased-array ultrasound focusing']::text[],ARRAY['Assuming it needs a known medium, when its strength is working through unknown ones','Believing scattering hurts focusing, when it usually helps','Confusing time reversal with a simple echo']::text[],ARRAY['Focusing ultrasound through the skull','Locating and focusing on a flaw in a solid','Refocusing a signal in a reverberant channel']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-reversal acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f21c3f6c-c15b-50c2-944f-27d0eaff408f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f21c3f6c-c15b-50c2-944f-27d0eaff408f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f21c3f6c-c15b-50c2-944f-27d0eaff408f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27adbc84-d760-5264-9994-78fa0101e2b8','Time-reversal mirror','The array of transducers and associated electronics that implements time-reversal focusing: each element records the incoming pressure, the signals are reversed in time, and each element re-emits its reversed signal so the array synthesises a converging, time-reversed wavefront. A closed arrangement surrounding the medium approximates an ideal time-reversal cavity; practical mirrors use a limited aperture and still refocus well in reverberant or scattering conditions.','A time-reversal mirror is the array that does time-reversal focusing. Each element listens and records the sound arriving. The recordings are flipped in time. Then each element replays its flipped signal. Together they send a wave back to the source.','Physically realises time-reversal focusing, turning a recorded field into a re-emitted, converging wave that refocuses on the original source.','Used in therapy and imaging arrays, non-destructive testing, and underwater acoustics to refocus energy through complex media.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Time-reversal acoustics','Phase conjugation','Phased-array ultrasound focusing','Time-reversal cavity','Acoustic wavefront shaping']::text[],ARRAY['Assuming a small mirror focuses as well as a surrounding one','Confusing the mirror hardware with the time-reversal principle','Expecting perfect refocusing despite losses and limited aperture']::text[],ARRAY['Building an array to focus through bone','Refocusing on a defect in a metal part','Concentrating sound in a reverberant tank']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-reversal mirror');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27adbc84-d760-5264-9994-78fa0101e2b8','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27adbc84-d760-5264-9994-78fa0101e2b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27adbc84-d760-5264-9994-78fa0101e2b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7665f6c-771c-5eae-b3f2-510bdd6c432c','Phase conjugation','The generation of a wave whose spatial phase is the complex conjugate of an incoming wave''s, so the conjugated wave retraces the incident path and converges back toward the source. For a single-frequency (narrowband) field it is the frequency-domain equivalent of time reversal: reversing the sign of the phase at each point is equivalent to reversing time for a monochromatic wave. Acoustic phase conjugation is realised with parametric or active nonlinear arrays.','Phase conjugation flips the phase of a wave at every point. The new wave then travels back the way the original came. It refocuses on the source, much like time reversal. For a single-frequency sound, the two ideas are the same. It can be done with special nonlinear devices.','Refocuses a single-frequency wave back onto its source by reversing its spatial phase, providing the narrowband counterpart of time reversal.','Used in ultrasonic focusing and imaging through distorting media, and studied with nonlinear acoustic materials that conjugate a wave.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Time-reversal acoustics','Time-reversal mirror','Acoustic wavefront shaping','Parametric array','Wavefront reversal']::text[],ARRAY['Confusing narrowband phase conjugation with broadband time reversal, which handles full waveforms','Assuming any phase change conjugates a wave','Ignoring that real devices conjugate over a limited bandwidth']::text[],ARRAY['Focusing a single-frequency beam through a distorting layer','Comparing conjugation and time reversal','Using a nonlinear medium to conjugate ultrasound']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase conjugation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7665f6c-771c-5eae-b3f2-510bdd6c432c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7665f6c-771c-5eae-b3f2-510bdd6c432c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7665f6c-771c-5eae-b3f2-510bdd6c432c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47965c50-4045-5973-a1c1-05e7d6ef6040','Acoustic holographic trap','A holographically shaped acoustic field engineered to create one or more potential wells that trap particles, droplets, or small objects via the acoustic radiation force. A hologram, either a passive phase plate or a programmable array, sculpts the pressure and its gradients so stable trapping points, lines, or shaped landscapes form; the trap geometry can be static or, with an active array, reconfigured to move and assemble objects.','An acoustic holographic trap is a shaped sound field that holds objects. The field is designed so certain points push objects inward. Those points act like small wells that trap particles. A printed plate or an array can make the field. An array can also move the traps around.','Uses a designed holographic field to create stable trapping points for contactless holding, positioning, and assembly of small objects.','Used in contactless handling, micro-assembly, tissue engineering, and levitation to position particles, cells, or droplets by sound alone.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Holographic acoustic field','Acoustic radiation-force field','Acoustic levitation field imaging','Dynamic levitation trap visualization','Acoustic tweezers']::text[],ARRAY['Confusing pressure nodes with true trap points, which depend on particle properties','Assuming any shaped field traps stably without checking the force balance','Ignoring heating and streaming at high drive levels']::text[],ARRAY['Assembling cells into a pattern with sound','Trapping a droplet in mid-air','Reconfiguring traps to move particles']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic holographic trap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47965c50-4045-5973-a1c1-05e7d6ef6040','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47965c50-4045-5973-a1c1-05e7d6ef6040') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47965c50-4045-5973-a1c1-05e7d6ef6040');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f73d01a-2d89-5a66-906e-cc3addf5b3ef','Acoustic radiation-force field','The spatial distribution of the time-averaged force that an acoustic field exerts on particles or interfaces, arising from the nonlinear transfer of momentum as sound is scattered or absorbed. For a small particle in an inviscid fluid the force derives from the gradient of the Gor''kov potential; that potential depends on the local pressure and velocity amplitudes and on the particle''s density and compressibility relative to the medium. The field''s structure sets where particles are pushed and trapped.','Sound carries momentum, so it can push on objects. The acoustic radiation force is this steady push. Across a field, the push varies from place to place. For a small particle, the force points down the slope of a potential. Where the potential is lowest, particles collect and are trapped.','Describes and predicts where a sound field pushes and holds particles, underpinning acoustic levitation, trapping, and manipulation.','Used to design levitators, acoustic tweezers, and microfluidic cell sorters, and to predict where particles gather in a field.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Gor''kov potential','Acoustic levitation field imaging','Acoustic holographic trap','Acoustic streaming field','Standing wave']::text[],ARRAY['Confusing the steady radiation force with the oscillating acoustic pressure','Applying small-particle Gor''kov theory to objects larger than a wavelength','Ignoring acoustic streaming, which competes with the force on small particles']::text[],ARRAY['Predicting trap points in a levitator','Designing a cell-sorting acoustofluidic chip','Explaining why particles collect at pressure nodes']::text[],'advanced','F = −∇U  (U = Gor''kov potential)','The radiation force on a small particle equals the negative gradient of the Gor''kov acoustic potential.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic radiation-force field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f73d01a-2d89-5a66-906e-cc3addf5b3ef','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f73d01a-2d89-5a66-906e-cc3addf5b3ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f73d01a-2d89-5a66-906e-cc3addf5b3ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e05541e7-da7e-59a3-bc17-187283986d75','Acoustic streaming field','The steady, time-averaged fluid flow generated by a sound field through the dissipation of acoustic momentum, either in the bulk (Eckart streaming, driven by attenuation of an intense beam) or near boundaries (Rayleigh or Schlichting streaming, driven in the viscous boundary layer). The streaming field is a second-order nonlinear effect whose velocity pattern depends on sound intensity, attenuation, and geometry; it transports heat and mass and can compete with the radiation force on small particles.','Strong sound can push a fluid into a steady flow. This flow is called acoustic streaming. It comes from sound losing energy in the fluid or near walls. The flow pattern depends on the sound''s strength and the geometry. It can stir a fluid, move heat, and disturb trapped particles.','Describes the steady flow that intense sound drives in a fluid, which mixes, transports heat and mass, and influences particle motion in acoustofluidic systems.','Exploited for micro-mixing, pumping, and heat transfer in acoustofluidic and ultrasonic devices, and accounted for as a disturbance in trapping and levitation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Eckart streaming','Rayleigh streaming','Acoustic radiation-force field','Acoustofluidics','Cavitation microstreaming']::text[],ARRAY['Confusing steady streaming with the oscillating acoustic particle velocity','Assuming streaming is negligible, when it can dominate small-particle motion','Overlooking that boundary and bulk streaming follow different patterns']::text[],ARRAY['Designing micro-mixing in an acoustofluidic chip','Explaining unwanted flow in a levitation trap','Using streaming to enhance heat transfer']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic streaming field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e05541e7-da7e-59a3-bc17-187283986d75','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e05541e7-da7e-59a3-bc17-187283986d75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e05541e7-da7e-59a3-bc17-187283986d75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b18de252-7d2c-5c93-a37d-b0dad1744a44','Vibroacoustic imaging','Measurement and visualization approach that links the vibration of a structure''s surface to the sound it radiates, mapping surface motion such as displacement, velocity, or acceleration together with the resulting acoustic field so that the structural sources of radiated noise can be identified. It combines vibration data, acoustic data, and often a radiation model to show how mechanical motion of a body is converted into airborne sound.','Vibroacoustic imaging links a surface''s shaking to the sound it makes. Sensors or lasers measure how the surface moves. A model then shows how that motion makes sound. It joins vibration data and sound data in one picture. Engineers use it to find the parts that cause noise.','Connects a structure''s mechanical vibration to its radiated sound so engineers can locate and rank the surface areas responsible for noise.','Used in automotive, aerospace, and appliance noise work to trace radiated sound back to vibrating panels, using scanning vibrometers and microphone arrays.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Structural-acoustic coupling map','Radiation efficiency map','Surface velocity map','Laser vibrometer scan map','Nearfield acoustic holography']::text[],ARRAY['Assuming every strongly vibrating area radiates strong sound while ignoring its radiation efficiency','Treating the vibration field and the sound field as independent rather than causally linked','Forgetting that the phase between surface regions controls how efficiently they radiate']::text[],ARRAY['Identifying which body panels radiate booming noise into a car cabin','Diagnosing a rattling appliance cover that radiates tonal noise','Linking gearbox housing vibration to an airborne whine']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibroacoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b18de252-7d2c-5c93-a37d-b0dad1744a44','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b18de252-7d2c-5c93-a37d-b0dad1744a44') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b18de252-7d2c-5c93-a37d-b0dad1744a44');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9df213b7-1a3b-5e10-b7b6-ef0b84433366','Vibration mode shape','The characteristic spatial deflection pattern a structure adopts when it vibrates at one of its natural frequencies, describing the relative amplitude and phase of motion at every point on the structure for that mode. Each mode shape is an eigenvector of the structure''s equations of motion; nodes are locations of zero motion and antinodes are locations of maximum motion, and the shape is defined only up to an arbitrary scale factor.','A mode shape shows how a structure bends when it rings at one natural frequency. Some spots move a lot and some stay still. The still spots are called nodes. The moving peaks are called antinodes. Each natural frequency has its own shape.','Describes how a structure deforms at each resonance, revealing where motion peaks and where it stays still so vibration and noise problems can be understood.','Read from modal tests or simulations to place sensors, choose damping or stiffening locations, and avoid exciting problem modes on panels, frames, and instrument bodies.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Modal analysis visualization','Experimental modal analysis','Operational modal analysis','Plate mode visualization','Frequency response function']::text[],ARRAY['Reading mode-shape amplitude as an absolute motion size rather than a relative, scale-free pattern','Confusing the mode shape with the operating deflection shape measured under a real load','Assuming a point that is a node for one mode stays still at every frequency']::text[],ARRAY['Mapping the first bending mode of a loudspeaker cabinet panel','Choosing where to add a brace by finding a mode''s antinode','Explaining why a bracket cracks when a resonance is excited']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibration mode shape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9df213b7-1a3b-5e10-b7b6-ef0b84433366','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9df213b7-1a3b-5e10-b7b6-ef0b84433366') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9df213b7-1a3b-5e10-b7b6-ef0b84433366');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df47b22d-22df-5959-b3a8-81ffef70f4c0','Modal analysis visualization','The graphical presentation of a structure''s modal parameters — natural frequencies, damping ratios, and mode shapes — extracted from measured or simulated dynamic response. Typical displays include animated mode-shape deflections, stability diagrams used to separate genuine physical modes from computational ones, and frequency-response overlays, giving an interpretable view of how a structure resonates across frequency.','Modal analysis pictures show how a structure shakes. They plot its natural frequencies, damping, and mode shapes. Mode shapes often appear as short movies. Other plots help sort real modes from noise. This makes the results easier to read.','Turns extracted modal parameters into pictures and animations so engineers can interpret which resonances matter and how the structure moves at each.','Standard output of modal-test software and finite-element post-processors, used in design reviews to compare test with simulation and to plan vibration fixes.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Vibration mode shape','Experimental modal analysis','Operational modal analysis','Frequency response function','Finite element acoustic model']::text[],ARRAY['Trusting an animated mode without checking damping and stability diagrams for spurious modes','Comparing test and model shapes without a correlation metric such as the modal assurance criterion','Reading a colour map as stress when it actually shows displacement']::text[],ARRAY['Reviewing animated bending and torsion modes of a chassis','Using a stability diagram to reject computational poles','Comparing measured and simulated modes before sign-off']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal analysis visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df47b22d-22df-5959-b3a8-81ffef70f4c0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df47b22d-22df-5959-b3a8-81ffef70f4c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df47b22d-22df-5959-b3a8-81ffef70f4c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b48da9c4-ddfa-5abe-b023-311ebe403f6e','Experimental modal analysis','The process of determining a structure''s modal parameters — natural frequencies, damping ratios, and mode shapes — from measured frequency response functions obtained with a known, controlled excitation such as an instrumented hammer or shaker and measured response at many points. Curve-fitting algorithms extract the modes from the set of measured functions; both the input force and the output response must be measured.','Experimental modal analysis finds a structure''s resonances from real tests. You hit or shake it with a known force. Sensors record how it responds. Software compares the input and output to find the modes. It needs both the force and the motion measured.','Gives an experimentally validated set of natural frequencies, damping, and mode shapes to check models, diagnose problems, and support design decisions.','Performed with impact hammers or shakers and accelerometers on car bodies, aircraft parts, machinery, and instruments to build or validate dynamic models.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Operational modal analysis','Frequency response function','Vibration mode shape','Modal analysis visualization','Transfer path analysis']::text[],ARRAY['UNSAFE: driving a shaker or fixture past its rated force or stroke, risking mechanical failure and injury','Assuming the measured force is clean without checking for hammer double-hits or low coherence','Measuring too few response points so mode shapes are aliased or incomplete']::text[],ARRAY['Running a roving-hammer test of a panel to map its mode shapes','Shaker-testing an aircraft component during ground vibration testing','Validating a finite-element model against measured modes']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Experimental modal analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b48da9c4-ddfa-5abe-b023-311ebe403f6e','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b48da9c4-ddfa-5abe-b023-311ebe403f6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b48da9c4-ddfa-5abe-b023-311ebe403f6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c364971-1a40-5470-bd29-2bdfe48bfcca','Operational modal analysis','A method that estimates a structure''s modal parameters from its response to unmeasured operational or ambient excitation, without a controlled, measured input force. It assumes the unknown excitation is broadband and approximately random, so output-only algorithms can extract natural frequencies, damping, and mode shapes from response measurements alone; the resulting mode shapes are typically obtained without an absolute mass scaling.','Operational modal analysis finds resonances while a structure is in use. It uses only the measured motion, not the forces. Those forces might be wind, traffic, or running machinery. The method assumes the forces are broad and random. The mode shapes come out without a true scale.','Lets engineers extract modal parameters from large or in-service structures where applying and measuring a controlled force is impractical.','Used on bridges, buildings, wind turbines, and running vehicles, capturing response with accelerometers while normal operation or ambient forces provide the excitation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Experimental modal analysis','Vibration mode shape','Modal analysis visualization','Operational transfer path analysis','Frequency response function']::text[],ARRAY['Assuming mode shapes are mass-scaled when output-only results are usually unscaled','Treating a strong harmonic from rotating machinery as if it were a structural mode','Trusting damping estimates, which are less reliable than in controlled tests']::text[],ARRAY['Estimating a bridge''s modes from traffic and wind response','Tracking a wind turbine''s modes during operation','Finding a building''s modes from ambient vibration']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Operational modal analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c364971-1a40-5470-bd29-2bdfe48bfcca','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c364971-1a40-5470-bd29-2bdfe48bfcca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c364971-1a40-5470-bd29-2bdfe48bfcca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97498923-2460-5cea-bd82-a7f5769750aa','Finite element acoustic model','A numerical model that discretizes a fluid volume, and often the surrounding structure, into many small elements and solves the governing acoustic wave or Helmholtz equation at the element nodes to predict sound pressure and, when coupled to a structural mesh, vibration fields. It suits interior or bounded-domain problems where the whole volume of interest is meshed, and its results are visualized as pressure or velocity field maps.','A finite element acoustic model splits a space into many tiny cells. It solves the sound equations across all those cells. This predicts sound pressure through the whole volume. It works best for closed spaces like a car cabin. The output is shown as colour field maps.','Predicts sound and coupled vibration fields inside bounded spaces so designers can study resonances and noise before building hardware.','Used to model cabin acoustics, mufflers, and small enclosures, often coupled to a structural mesh to study how panels drive interior sound.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Boundary element acoustic model','Cavity mode visualization','Cabin acoustic mode map','Structural-acoustic coupling map','Modal analysis visualization']::text[],ARRAY['Using too coarse a mesh for the highest frequency, so short wavelengths are under-resolved','Applying finite elements to large open radiation problems better suited to boundary methods','Ignoring fluid-structure coupling when the panels and cavity interact strongly']::text[],ARRAY['Predicting boom modes inside a car cabin','Designing a muffler''s transmission loss','Studying the internal resonances of a small enclosure']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite element acoustic model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97498923-2460-5cea-bd82-a7f5769750aa','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97498923-2460-5cea-bd82-a7f5769750aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97498923-2460-5cea-bd82-a7f5769750aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ccfb907-2e34-5e48-b759-a103e0513e4d','Boundary element acoustic model','A numerical model that solves the acoustic problem by discretizing only the boundary surfaces of a body rather than the surrounding fluid volume, using a boundary integral form of the Helmholtz equation to compute radiation and scattering into an unbounded exterior domain. Because only surfaces are meshed and the radiation condition is satisfied automatically, it is efficient for exterior radiation problems driven by known surface velocities.','A boundary element acoustic model meshes only the surfaces, not the air around them. It solves how those surfaces radiate or scatter sound. It handles open, unbounded spaces well. It needs fewer elements than a full volume mesh. Engineers use it for outward sound radiation.','Efficiently predicts how a vibrating body radiates sound into open space, needing only its surface to be meshed.','Used to predict exterior noise radiation from engines, gearboxes, and machinery housings, often driven by surface velocities from a structural model.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Finite element acoustic model','Radiation efficiency map','Surface velocity map','Normal velocity map','Structural-acoustic coupling map']::text[],ARRAY['Ignoring non-uniqueness problems at certain frequencies without a CHIEF or Burton-Miller remedy','Meshing surfaces too coarsely for the highest frequency of interest','Using boundary elements for interior volume problems better suited to finite elements']::text[],ARRAY['Predicting radiated sound power from a gearbox housing','Computing sound scattering around a microphone or a head','Ranking exterior noise from a vibrating machine cover']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary element acoustic model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ccfb907-2e34-5e48-b759-a103e0513e4d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ccfb907-2e34-5e48-b759-a103e0513e4d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ccfb907-2e34-5e48-b759-a103e0513e4d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71d98f55-ec15-59ac-8308-623567a11a1e','Energy flow analysis','The study and visualization of how vibrational or acoustic energy travels through and between the parts of a system, tracing power from sources through transmission paths to sinks. In structures it uses time-averaged power-flow (intensity) fields; at higher frequencies statistical energy analysis represents subsystems by their energy levels and the power exchanged between them, revealing dominant transmission routes and where energy dissipates.','Energy flow analysis tracks how vibration energy moves through a system. It follows power from where it starts to where it fades. It shows the main paths the energy takes. It also shows where the energy turns into heat. This helps find the best place to block noise.','Reveals the routes by which vibrational and acoustic energy travels from sources to receivers, so the strongest paths can be targeted for control.','Used with structural-intensity techniques and statistical energy analysis to plan damping and isolation in vehicles, ships, and buildings.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Structural intensity map','Acoustic intensity vector map','Transfer path analysis','Statistical energy analysis','Structural-acoustic coupling map']::text[],ARRAY['Confusing energy that is stored and returned with energy that actually flows and dissipates','Applying low-frequency deterministic methods where high-frequency statistical methods fit better','Ignoring that measured intensity needs accurate phase between the sensors']::text[],ARRAY['Mapping power flow from an engine mount into a chassis','Using statistical energy analysis for high-frequency cabin noise','Finding where vibration energy leaves a panel through its edges']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energy flow analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71d98f55-ec15-59ac-8308-623567a11a1e','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71d98f55-ec15-59ac-8308-623567a11a1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71d98f55-ec15-59ac-8308-623567a11a1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38d72899-11e6-56dc-a0ee-33300ad29ab8','Structural intensity map','A vector field map of structural intensity, the time-averaged flow of vibrational power per unit cross-sectional area through a solid structure. At each point the intensity vector equals the negative time-averaged product of the internal stress components and the corresponding velocity, so the arrows show the direction and magnitude of vibrational energy transport through plates, beams, and shells.','A structural intensity map shows vibration power flowing through a solid part. Arrows point the way the energy travels. Longer arrows mean more power flows there. It is found from stress and velocity together. Engineers use it to trace energy from source to sink.','Shows the direction and size of vibrational power flow inside a structure, revealing transmission paths and energy sinks that a plain vibration map misses.','Measured from arrays of accelerometers or from scanning vibrometry to see how energy travels across panels and where damping treatments will intercept it.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic intensity vector map','Energy flow analysis','Surface velocity map','Mobility map','Transfer path analysis']::text[],ARRAY['Confusing structural intensity in the solid with the acoustic intensity radiated into the air','Poor phase accuracy between sensors giving the wrong flow direction','Assuming the largest vibration amplitude marks the largest power flow']::text[],ARRAY['Tracing power flow across a vibrating floor panel','Finding the energy path into a damping patch','Locating a hidden vibration source by following the arrows']::text[],'advanced','I_i = -⟨σ_ij · v_j⟩','Structural intensity in a direction equals the negative time-average of the product of the stress components acting there and the velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structural intensity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38d72899-11e6-56dc-a0ee-33300ad29ab8','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38d72899-11e6-56dc-a0ee-33300ad29ab8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38d72899-11e6-56dc-a0ee-33300ad29ab8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a649fe9-a467-5017-abbc-b06a0836788b','Acoustic intensity vector map','A vector field map of acoustic intensity, the time-averaged flow of sound power per unit area in a fluid. At each measurement point the intensity vector equals the time average of the product of the acoustic pressure and the particle velocity, so the arrows show the direction and magnitude of net sound-energy flow, letting sources be separated from sinks and reflections.','An acoustic intensity map shows sound power moving through the air. Arrows point where the sound energy flows. Longer arrows mean more power in that spot. It comes from pressure and air motion together. This helps point to the real sound source.','Shows where sound energy actually flows and how strongly, letting engineers locate radiating sources and tell them apart from background and reflections.','Measured with two-microphone or probe-based intensity systems to map sound power from machines and to find leaks, following standardized sound-power methods.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Structural intensity map','Sound intensity probe','Radiation efficiency map','Energy flow analysis','Nearfield acoustic holography']::text[],ARRAY['Confusing sound pressure level with intensity, which also needs particle velocity and phase','Phase mismatch between the microphones causing large intensity errors','Measuring intensity in a strong reactive nearfield without proper care']::text[],ARRAY['Mapping the sound power radiated by a running pump','Finding a noise leak in a machine enclosure','Separating a source from a nearby reflecting wall']::text[],'intermediate','I = ⟨p · u⟩','Sound intensity equals the time-average of the product of the acoustic pressure and the particle velocity at a point.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic intensity vector map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a649fe9-a467-5017-abbc-b06a0836788b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a649fe9-a467-5017-abbc-b06a0836788b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a649fe9-a467-5017-abbc-b06a0836788b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9eb13bd-b6e3-5a04-b0f3-c303db3fc9f1','Surface velocity map','A spatial map of the vibration velocity measured across a structure''s surface, showing the amplitude and often the phase of surface motion at each scanned point for a given frequency or operating condition. It is commonly built from scanning laser Doppler vibrometry or dense accelerometer arrays and forms the input to radiated-sound and radiation-efficiency calculations.','A surface velocity map shows how fast each spot on a surface vibrates. Bright areas move fast and dark areas move slowly. It is measured point by point, often with a scanning laser. It can also show the phase of the motion. It feeds sound-radiation calculations.','Provides the point-by-point surface motion needed to see vibration patterns and to predict how a surface radiates sound.','Produced by scanning vibrometers on panels, loudspeaker cones, and brake discs to reveal operating deflection shapes and feed radiation models.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Normal velocity map','Laser vibrometer scan map','Radiation efficiency map','Vibration mode shape','Operating deflection shape']::text[],ARRAY['Reading a velocity map at one frequency as the true mode shape without checking damping and phase','Ignoring the direction along which the sensor is actually sensitive','Sampling the surface too coarsely so short-wavelength patterns are missed']::text[],ARRAY['Mapping a loudspeaker cone''s break-up at high frequency','Measuring a panel''s operating deflection under a shaker','Checking a brake disc for squeal-related motion']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface velocity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9eb13bd-b6e3-5a04-b0f3-c303db3fc9f1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9eb13bd-b6e3-5a04-b0f3-c303db3fc9f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9eb13bd-b6e3-5a04-b0f3-c303db3fc9f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '478b15eb-262f-5737-a399-768b9e1981fa','Normal velocity map','A spatial map of the component of a surface''s vibration velocity directed normal, or perpendicular, to the surface at each point on the structure. Because only the out-of-plane normal motion of a surface compresses the adjacent fluid, the normal velocity distribution is the quantity that drives sound radiation and is the required input to acoustic radiation and holography calculations.','A normal velocity map shows only the motion straight out of a surface. That perpendicular motion is what pushes on the air. Sideways motion does not make sound directly. So this map is the one that predicts radiation. It is taken point by point across the surface.','Isolates the perpendicular surface motion that actually pushes the surrounding air, giving the correct input for predicting radiated sound.','Extracted from vibrometer or array data and fed into boundary-element or holography tools to predict how a panel radiates.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Surface velocity map','Radiation efficiency map','Boundary element acoustic model','Nearfield acoustic holography','Laser vibrometer scan map']::text[],ARRAY['Using the total surface speed instead of just the perpendicular part when predicting radiation','Forgetting that in-plane motion radiates very little sound on its own','Misaligning the measurement axis with the true surface normal']::text[],ARRAY['Feeding a panel''s normal velocity into a radiation model','Comparing the normal motion of two panel designs','Building a holography input from scanned surface data']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normal velocity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '478b15eb-262f-5737-a399-768b9e1981fa','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='478b15eb-262f-5737-a399-768b9e1981fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='478b15eb-262f-5737-a399-768b9e1981fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a8037d2-efd0-5bd0-b37a-c38efe1df1a2','Mobility map','A map of mechanical mobility, the frequency-dependent ratio of a structure''s vibration velocity response to the applied force, displayed over position or frequency. Mobility is a complex quantity equal to velocity divided by force and is the inverse of mechanical impedance; mapping it shows where a structure responds most readily to excitation and how that response varies with frequency.','A mobility map shows how easily each spot moves when pushed. Mobility is velocity divided by the force that causes it. High mobility means the spot moves a lot per unit force. It changes with frequency and peaks at resonances. It is the opposite of impedance.','Shows how readily a structure moves per unit applied force across position and frequency, guiding where to inject or isolate vibration.','Derived from frequency response measurements to choose mounting points, design vibration isolators, and match sources to structures.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Frequency response function','Mechanical impedance','Vibration mode shape','Surface velocity map','Structural intensity map']::text[],ARRAY['Confusing mobility with its inverse, mechanical impedance','Ignoring that mobility is complex, with both a magnitude and a phase','Picking a mount point at a mobility peak instead of a low-mobility node']::text[],ARRAY['Choosing a low-mobility spot to mount a heavy compressor','Comparing the mobility of a stiffened and a plain panel','Matching an engine mount to the body''s mobility']::text[],'advanced','Y(ω) = v(ω) / F(ω)','Mechanical mobility equals the vibration velocity divided by the applied force, as a function of frequency.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mobility map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a8037d2-efd0-5bd0-b37a-c38efe1df1a2','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a8037d2-efd0-5bd0-b37a-c38efe1df1a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a8037d2-efd0-5bd0-b37a-c38efe1df1a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe73c2bf-cc4f-54dc-98b4-65e671c1786c','Frequency response function','A complex, frequency-dependent function describing the ratio of a linear time-invariant system''s steady-state output response to its input excitation, as a function of frequency. In vibration work it is typically the ratio of a measured response spectrum — displacement, velocity, or acceleration — to the input force spectrum, capturing both magnitude and phase and forming the basic data from which modal parameters are extracted.','A frequency response function shows how a system reacts across frequency. It is the output divided by the input at each frequency. It has both a size and a phase. Peaks appear at the system''s resonances. Engineers fit these curves to find the modes.','Captures how a linear system responds to excitation at every frequency, serving as the core measurement for modal analysis and system identification.','Measured with analyzers from hammer or shaker tests on structures, and used to characterize filters, transducers, and rooms.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Experimental modal analysis','Mobility map','Vibration mode shape','Transfer path analysis','Coherence function']::text[],ARRAY['Trusting a function where coherence is low, which signals noise or nonlinearity','Confusing the function with a simple spectrum of the output alone','Mixing up response types such as accelerance, mobility, and receptance']::text[],ARRAY['Measuring a panel''s accelerance from a hammer test','Extracting modes from a set of measured functions','Checking coherence before trusting a measured function']::text[],'intermediate','H(ω) = X(ω) / F(ω)','A frequency response function equals the complex output response spectrum divided by the input excitation spectrum at each frequency.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency response function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe73c2bf-cc4f-54dc-98b4-65e671c1786c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe73c2bf-cc4f-54dc-98b4-65e671c1786c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe73c2bf-cc4f-54dc-98b4-65e671c1786c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '553758c3-65df-5c2d-bdb4-a7178df56775','Transfer path analysis','An engineering method that quantifies and visualizes how energy from one or more sources reaches a receiver location through multiple structural and airborne paths, by combining measured path forces or velocities with measured transfer functions from each path to the receiver. The receiver response is decomposed into the summed contributions of individual paths, ranking which paths dominate at each frequency.','Transfer path analysis finds how noise reaches a target spot. It follows many paths from source to receiver. Each path''s share is measured and added up. This shows which paths matter most. Engineers then fix the loudest paths first.','Breaks a receiver''s noise or vibration into the separate paths that carry it, so the dominant paths can be identified and treated.','Used in vehicle refinement to rank engine, road, and airborne paths into the cabin using force, accelerance, and transfer-function measurements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Operational transfer path analysis','Panel contribution map','Frequency response function','Energy flow analysis','Structural-acoustic coupling map']::text[],ARRAY['Mounting sensors so cross-coupling between paths corrupts the decomposition','Assuming paths add without accounting for their relative phase','Missing an important path so its energy is wrongly assigned to others']::text[],ARRAY['Ranking structure-borne against airborne engine noise into a cabin','Finding which mount transmits the most road noise','Deciding which path to isolate first']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer path analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '553758c3-65df-5c2d-bdb4-a7178df56775','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='553758c3-65df-5c2d-bdb4-a7178df56775') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='553758c3-65df-5c2d-bdb4-a7178df56775');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2c69d51-11d6-5aee-80a0-23afd18ed3ce','Operational transfer path analysis','A fast, response-only variant of transfer path analysis that estimates path contributions to a receiver from operational responses measured at the same time at reference and target points, using transmissibility relations rather than separately measured forces and transfer functions. It trades some accuracy and physical rigor for speed and can be biased by crosstalk or by unmeasured paths that are correlated with the measured references.','Operational transfer path analysis ranks noise paths using only running data. It skips the slow force and transfer measurements. It relates responses at reference and target points. This makes it fast to apply. But it can be fooled by paths that move together.','Provides a quick path-contribution ranking from operating measurements alone, avoiding the labour of classical transfer path analysis.','Used for rapid troubleshooting on running vehicles and machines, placing reference sensors near sources and a target sensor at the receiver.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Transfer path analysis','Panel contribution map','Operational modal analysis','Frequency response function','Energy flow analysis']::text[],ARRAY['Treating correlated references as independent paths, which biases the result','Assuming operational results match rigorous classical transfer path analysis','Choosing too few references to represent all the real paths']::text[],ARRAY['Quickly ranking noise paths on a running powertrain','Screening candidate paths before a full transfer path study','Troubleshooting an intermittent booming noise on the road']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Operational transfer path analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2c69d51-11d6-5aee-80a0-23afd18ed3ce','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2c69d51-11d6-5aee-80a0-23afd18ed3ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2c69d51-11d6-5aee-80a0-23afd18ed3ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6063c8c1-10c0-5edc-adc4-9609777dbc8b','Panel contribution map','A visualization that ranks and displays how much each panel or surface region of an enclosure contributes to the sound pressure at a chosen receiver point, usually computed by combining each panel''s normal velocity with an acoustic transfer function from that panel to the receiver. Contributions can be positive or negative, since panels vibrating out of phase can subtract from the total.','A panel contribution map shows how much each panel adds to the noise at a listener spot. Each panel''s motion is weighted by how well it reaches that spot. Panels are then ranked by their share. Some panels can even cancel others. This points to the panels worth treating.','Ranks the surface regions of an enclosure by their share of the noise at a receiver, guiding where treatment will cut noise the most.','Used in vehicle interior noise work to rank floor, firewall, and roof panels for booming noise using coupled vibration and acoustic models.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Transfer path analysis','Normal velocity map','Radiation efficiency map','Cabin acoustic mode map','Structural-acoustic coupling map']::text[],ARRAY['Ignoring negative contributions from out-of-phase panels when summing the total','Ranking panels by vibration alone without the acoustic transfer to the receiver','Assuming the biggest panel always contributes the most sound']::text[],ARRAY['Ranking cabin panels for a low-frequency boom','Deciding which panel to stiffen or damp first','Explaining why treating one panel raised noise elsewhere']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Panel contribution map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6063c8c1-10c0-5edc-adc4-9609777dbc8b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6063c8c1-10c0-5edc-adc4-9609777dbc8b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6063c8c1-10c0-5edc-adc4-9609777dbc8b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '124d82ac-ba3b-5d0a-9fa1-d9a4aa018b61','Radiation efficiency map','A map of radiation efficiency across a structure or across frequency, where radiation efficiency is the dimensionless ratio of the sound power actually radiated by a vibrating surface to the power that an equal-area rigid piston vibrating with the same mean-square normal velocity would radiate. It shows which areas or frequencies convert surface vibration into sound effectively and is central to explaining why strong vibration does not always mean loud sound.','A radiation efficiency map shows how well vibration turns into sound. It compares the real sound power to that of an ideal piston. A value near one means the area radiates sound well. A low value means it barely makes sound. It explains why some shaking is quiet.','Shows how effectively each area or frequency of a vibrating surface radiates sound, separating strong vibration from strong noise.','Computed from surface velocity and radiated power in noise control to decide whether to reduce vibration or disrupt efficient radiation, especially near the critical frequency.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Surface velocity map','Normal velocity map','Critical frequency','Acoustic intensity vector map','Boundary element acoustic model']::text[],ARRAY['Assuming high vibration always means high radiated sound while ignoring low radiation efficiency','Overlooking that radiation efficiency rises sharply near the critical frequency','Confusing radiation efficiency with the radiation resistance it derives from']::text[],ARRAY['Explaining why a strongly vibrating panel is quiet below its critical frequency','Choosing between damping and stiffening for a radiating panel','Mapping efficiency across frequency for a flat plate']::text[],'advanced','σ = W_rad / (ρ₀ c S ⟨v_n²⟩)','Radiation efficiency equals the radiated sound power divided by the product of air density, the speed of sound, the surface area, and the mean-square normal velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation efficiency map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '124d82ac-ba3b-5d0a-9fa1-d9a4aa018b61','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='124d82ac-ba3b-5d0a-9fa1-d9a4aa018b61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='124d82ac-ba3b-5d0a-9fa1-d9a4aa018b61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dedfca2a-9bd1-5e0e-a880-f555765d74d5','Acoustic modal participation','A measure, in coupled structural-acoustic or room analysis, of how strongly each acoustic or structural mode contributes to the sound pressure at a point or to the total radiated or received field for a given excitation. The response is expressed as a weighted sum over modes, and each mode''s participation factor gives the amplitude and phase with which that mode enters the sum, revealing which resonances dominate.','Acoustic modal participation shows how much each mode adds to the sound. The total field is a sum of mode contributions. Each mode enters with its own size and phase. A large participation means that mode dominates. This reveals which resonance controls the noise.','Reveals which acoustic or structural modes dominate the sound at a point, so control effort targets the modes that matter.','Used in cabin and room analysis to see which cavity modes drive a boom, guiding placement of absorption, dampers, or tuned absorbers.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Cavity mode visualization','Cabin acoustic mode map','Structural-acoustic coupling map','Modal analysis visualization','Finite element acoustic model']::text[],ARRAY['Adding modal contributions without their phase, so cancellation between modes is missed','Assuming the mode nearest in frequency always participates the most','Ignoring structural modes that couple strongly into the acoustic field']::text[],ARRAY['Finding which cavity mode drives a 60 Hz cabin boom','Ranking modes before placing an absorber','Explaining a pressure peak by its dominant mode']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic modal participation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dedfca2a-9bd1-5e0e-a880-f555765d74d5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dedfca2a-9bd1-5e0e-a880-f555765d74d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dedfca2a-9bd1-5e0e-a880-f555765d74d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a3e2ad6-fbb6-5ace-98c9-44a5c6f22ff1','Structural-acoustic coupling map','A visualization of how strongly a structure''s vibration modes couple to the acoustic modes of an adjacent fluid volume, quantifying the spatial matching between surface normal-velocity patterns and acoustic-mode pressure patterns. Strong coupling occurs where a structural mode shape and an acoustic mode shape overlap well, so the map shows which structural-acoustic mode pairs exchange energy efficiently and drive interior noise.','A coupling map shows how a structure''s shaking links to a room''s sound modes. Coupling is strong when their shapes match in space. Well-matched pairs trade energy easily. Poorly matched pairs barely interact. This shows which pairings drive the noise.','Shows which structural and acoustic modes match well enough to exchange energy, explaining how panel vibration drives cavity sound.','Used in vehicle and aircraft cabin design to pick which panel or cavity mode to detune, damp, or reshape to break a strong coupling.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic modal participation','Cavity mode visualization','Cabin acoustic mode map','Panel contribution map','Finite element acoustic model']::text[],ARRAY['Assuming matched frequencies alone give strong coupling while ignoring the spatial shape match','Treating the structure and the cavity separately when they interact strongly','Forgetting that a nodal-line mismatch makes two modes couple weakly']::text[],ARRAY['Detuning a panel mode away from a strongly coupled cavity mode','Explaining a cabin boom from a coupled panel-cavity pair','Choosing where to add absorption to weaken a coupling']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structural-acoustic coupling map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a3e2ad6-fbb6-5ace-98c9-44a5c6f22ff1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a3e2ad6-fbb6-5ace-98c9-44a5c6f22ff1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a3e2ad6-fbb6-5ace-98c9-44a5c6f22ff1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e943a3a-46e9-59ba-88ce-088ad755e094','Cavity mode visualization','The graphical display of the acoustic resonances, or standing-wave pressure patterns, of an enclosed fluid volume, showing the spatial distribution of sound pressure for each cavity mode at its natural frequency. Pressure antinodes and nodal surfaces are mapped, revealing where sound pressure peaks and cancels inside the cavity, typically from measurement or finite-element results.','Cavity mode visualization shows the sound resonances inside a closed space. Each mode is a standing-wave pressure pattern. Some spots always have high pressure and some near zero. It shows where sound builds up in the volume. Engineers use it to fix boomy spaces.','Shows where sound pressure peaks and cancels for each resonance of an enclosed volume, so problem modes can be located and treated.','Used for rooms, vehicle cabins, and duct systems to see low-frequency standing waves and place absorption, bass traps, or resonators.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Cabin acoustic mode map','Acoustic modal participation','Finite element acoustic model','Structural-acoustic coupling map','Room mode']::text[],ARRAY['Confusing acoustic cavity modes with the structural modes of the walls','Assuming absorption placed at a pressure node does much good','Ignoring that low modes are widely spaced and dominate at low frequency']::text[],ARRAY['Locating a room''s axial mode pressure peaks','Placing a bass trap at a pressure antinode','Mapping duct resonances before adding a silencer']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavity mode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e943a3a-46e9-59ba-88ce-088ad755e094','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e943a3a-46e9-59ba-88ce-088ad755e094') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e943a3a-46e9-59ba-88ce-088ad755e094');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af0b9973-9ffd-5df8-8dc1-b6d5cc686699','Cabin acoustic mode map','A specific application of cavity mode visualization to the enclosed interior of a vehicle, aircraft, or similar cabin, mapping the sound-pressure patterns of the interior''s low-frequency acoustic modes. It shows where interior pressure peaks for each cabin resonance, information used to explain and control low-frequency boom and to relate interior noise to specific cabin modes.','A cabin acoustic mode map shows the sound resonances inside a vehicle. Each map marks where interior pressure peaks and dips. Low-frequency modes cause the deep boom you feel. It links seats and ears to specific modes. Engineers use it to cut interior boom.','Shows the low-frequency pressure patterns inside a cabin so boom-causing modes can be linked to seating positions and controlled.','Used in automotive and aircraft noise work to relate a boom at the driver''s ear to a cabin mode and to place absorption or tuned dampers.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Cavity mode visualization','Acoustic modal participation','Structural-acoustic coupling map','Panel contribution map','Finite element acoustic model']::text[],ARRAY['Treating cabin modes as fixed while seats, occupants, and trim shift them','Ignoring the coupling between the cabin cavity and the flexible body panels','Assuming a listener''s ear sits at a pressure node when it may sit at an antinode']::text[],ARRAY['Linking a 45 Hz boom to a front-to-back cabin mode','Placing absorption for a specific cabin resonance','Explaining why a rear-seat boom differs from the front']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cabin acoustic mode map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af0b9973-9ffd-5df8-8dc1-b6d5cc686699','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af0b9973-9ffd-5df8-8dc1-b6d5cc686699') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af0b9973-9ffd-5df8-8dc1-b6d5cc686699');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c1bc47d-166e-54cd-8bc9-e160a46912d6','Membrane mode visualization','The display of the vibration mode shapes of a membrane — a thin, flexible sheet whose restoring force comes from applied tension rather than bending stiffness — showing the nodal-line patterns and antinodes for each natural frequency. Ideal membrane modes, such as those of a circular drumhead, follow the two-dimensional wave equation and are described by patterns of radial and circumferential nodal lines.','Membrane mode visualization shows how a stretched sheet vibrates. Tension, not stiffness, pulls it back to rest. Each mode has its own pattern of still lines. A drumhead is a common example. The still lines are called nodal lines.','Shows the natural vibration patterns of tension-supported sheets, explaining their tuning and how they radiate sound.','Applied to drumheads, condenser microphone and loudspeaker diaphragms, and pressure sensors to understand tuning and break-up patterns.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Plate mode visualization','Vibration mode shape','Modal analysis visualization','Surface velocity map','Shell mode visualization']::text[],ARRAY['Treating a membrane like a stiff plate, whose restoring force is bending not tension','Assuming membrane modes are evenly spaced like a string''s harmonics','Ignoring how tension and mass together set the mode frequencies']::text[],ARRAY['Explaining a drumhead''s nodal patterns with sand figures','Studying a microphone diaphragm''s first few modes','Visualising the break-up of a thin loudspeaker diaphragm']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membrane mode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c1bc47d-166e-54cd-8bc9-e160a46912d6','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c1bc47d-166e-54cd-8bc9-e160a46912d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c1bc47d-166e-54cd-8bc9-e160a46912d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8594b361-76f3-569b-bc42-96209e9a05dc','Plate mode visualization','The display of the vibration mode shapes of a plate — a flat structural element whose restoring force comes from bending stiffness — showing the nodal-line patterns and relative motion for each natural frequency. Plate modes depend on the plate''s dimensions, thickness, material, and boundary conditions, and are classically revealed by nodal-line, or Chladni, patterns.','Plate mode visualization shows how a flat panel vibrates. A plate springs back through its bending stiffness. Each mode has its own pattern of still lines. Sand on a vibrating plate traces those lines. The way the edges are held strongly shapes the modes.','Shows the natural bending-vibration patterns of flat panels, guiding where to stiffen, damp, or brace to control vibration and sound.','Applied to instrument soundboards, machine covers, and vehicle panels to find mode shapes and choose brace or damping locations.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Membrane mode visualization','Shell mode visualization','Vibration mode shape','Radiation efficiency map','Surface velocity map']::text[],ARRAY['Confusing a plate''s stiffness-controlled modes with a membrane''s tension-controlled modes','Ignoring how edge conditions, such as clamped against free, shift the modes','Assuming thickness matters little when it strongly sets bending stiffness']::text[],ARRAY['Mapping Chladni patterns on a guitar top plate','Placing a brace at a machine cover''s antinode','Comparing the modes of a clamped and a free panel']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plate mode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8594b361-76f3-569b-bc42-96209e9a05dc','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8594b361-76f3-569b-bc42-96209e9a05dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8594b361-76f3-569b-bc42-96209e9a05dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c1f8e58-2c3c-54ee-818f-5e0b7cc9ceda','Shell mode visualization','The display of the vibration mode shapes of a shell — a curved thin-walled structure whose stiffness combines bending and in-plane membrane action because of its curvature — showing the coupled circumferential and axial deformation patterns for each natural frequency. Curvature couples bending and stretching, giving shells a denser and more complex modal behaviour than flat plates.','Shell mode visualization shows how a curved thin wall vibrates. Curvature mixes bending with stretching. This gives more modes packed close together. Pipes, tanks, and car bodies act like shells. The modes have both a ring pattern and a length pattern.','Shows the coupled bending-and-stretching vibration patterns of curved structures, which behave differently from flat plates.','Applied to pipes, ducts, pressure vessels, aircraft fuselages, and vehicle bodies to understand vibration and radiated noise.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Plate mode visualization','Vibration mode shape','Modal analysis visualization','Structural intensity map','Radiation efficiency map']::text[],ARRAY['Treating a curved shell like a flat plate and missing the curvature coupling','Assuming shell modes are widely spaced when they are often dense','Ignoring the circumferential mode order when identifying a mode']::text[],ARRAY['Identifying the ovalling modes of a pipe','Studying fuselage vibration and the resulting cabin noise','Mapping the coupled modes of a tank wall']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shell mode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c1f8e58-2c3c-54ee-818f-5e0b7cc9ceda','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c1f8e58-2c3c-54ee-818f-5e0b7cc9ceda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c1f8e58-2c3c-54ee-818f-5e0b7cc9ceda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67037a79-cf79-5f95-9b36-d07f06e10b5c','Laser vibrometer scan map','A spatial map of surface vibration produced by scanning laser Doppler vibrometry, in which a laser beam is steered in turn to many points on a surface and the Doppler shift of the reflected light is used to measure the velocity along the beam at each point without contact. The grid of measurements, referenced to a shared excitation or trigger, is assembled into a full-field map or animation of the surface''s operating deflection or mode shapes.','A laser vibrometer scan map measures surface vibration with a moving laser beam. The beam visits many points one after another. It reads each point''s speed from the light''s frequency shift. No sensor needs to touch the surface. The points combine into a full vibration picture.','Builds a dense, non-contact map of how a surface vibrates, capturing mode shapes and operating deflection shapes without loading the structure with sensors.','Used to scan loudspeaker cones, brake discs, panels, and small or hot parts where mounting accelerometers would be impractical or would add mass.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Surface velocity map','Normal velocity map','Vibration mode shape','Operating deflection shape','Experimental modal analysis']::text[],ARRAY['Assuming the scan is instantaneous when points are actually measured in sequence and tied together by a trigger','Forgetting that the laser reads velocity along the beam, mostly out-of-plane motion','Scanning a poorly reflective surface without treating it, which degrades the signal']::text[],ARRAY['Scanning a loudspeaker cone to see its break-up modes','Measuring a hot brake disc without contact sensors','Mapping a lightweight panel where accelerometers would add mass']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser vibrometer scan map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67037a79-cf79-5f95-9b36-d07f06e10b5c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67037a79-cf79-5f95-9b36-d07f06e10b5c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67037a79-cf79-5f95-9b36-d07f06e10b5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc42f829-52eb-59e2-a289-aac243c080fd','Sound-pressure map','A spatial representation of acoustic pressure, or the derived sound pressure level, over a line, surface, or region of a sound field, in which measured or reconstructed pressure values are plotted at their spatial coordinates and rendered as a colour- or contour-coded field. It depicts how the scalar pressure amplitude varies from point to point at a given frequency or in a given band, and forms the base data layer from which many other acoustic maps and derived quantities are computed.','A sound-pressure map shows how strong a sound is at each point in space. Colour or shading marks the pressure level. Bright spots mean high pressure. Dark spots mean low pressure. It is a picture of where sound is strong or weak.','It reveals where acoustic pressure is high or low across a region, so sources, hot spots, and quiet zones can be identified at a glance rather than probed one point at a time.','Engineers build sound-pressure maps from microphone-array scans or simulation to study room modes, loudspeaker coverage, machinery noise, and pressure uniformity in test chambers.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Iso-SPL contour','Isobaric contour','Sound-intensity map','Sound pressure level','Acoustic energy-density map']::text[],ARRAY['Treating a pressure map as an energy-flow map, when pressure is a scalar and carries no direction','Comparing maps taken at different frequencies as if they showed the same field','Ignoring that pressure near a reflecting surface is boosted by the reflection']::text[],ARRAY['Mapping standing-wave pressure patterns inside a small room','Checking pressure uniformity across a microphone calibration chamber','Visualising loudspeaker coverage across an audience plane']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-pressure map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc42f829-52eb-59e2-a289-aac243c080fd','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc42f829-52eb-59e2-a289-aac243c080fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc42f829-52eb-59e2-a289-aac243c080fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9dd7e95f-c07e-5957-85e0-01df3a0e0ad7','Sound-intensity map','A spatial map of acoustic intensity, the time-averaged product of sound pressure and acoustic particle velocity, showing both the magnitude and the direction of net acoustic energy flow at each point on a line, surface, or volume. Because intensity is a vector, such a map encodes direction with arrows or streamlines and magnitude with colour, distinguishing it from a scalar pressure map and allowing sources and sinks of acoustic energy to be located.','A sound-intensity map shows how sound energy flows through space. Each point has a strength and a direction. Arrows or colours show which way the energy moves. It helps find where sound is coming from. This is different from a pressure map.','It locates and ranks real sources of radiated sound energy and shows the paths that energy takes, which a scalar pressure map cannot do because pressure has no direction.','Technicians use intensity maps from p-p or p-u probes to find leaks in enclosures, rank noise sources on machines, and measure radiated sound power in the field.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Active-intensity map','Reactive-intensity map','Vector intensity probe','Sound-pressure map','Particle-velocity map']::text[],ARRAY['Confusing intensity with pressure or with sound pressure level','Forgetting that intensity is a vector with direction, not just a magnitude','Trusting intensity readings where the reactive near field dominates, which biases the estimate']::text[],ARRAY['Ranking noise sources on a running engine','Locating an air leak that radiates sound from a sealed cabinet','Measuring the sound power of a machine on a factory floor']::text[],'advanced','I = ⟨p·u⟩','Sound intensity equals the time average of sound pressure multiplied by acoustic particle velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-intensity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9dd7e95f-c07e-5957-85e0-01df3a0e0ad7','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9dd7e95f-c07e-5957-85e0-01df3a0e0ad7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9dd7e95f-c07e-5957-85e0-01df3a0e0ad7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb10c006-5cd7-5f89-bbb8-7be98cd8ebe9','Particle-velocity map','A spatial map of the acoustic particle velocity, the small oscillatory velocity of the medium''s fluid particles about their rest position as a sound wave passes, plotted as a vector field over a line, surface, or volume. Particle velocity is tied to the pressure gradient through the linearised momentum (Euler) equation, so the map is either measured directly with a particle-velocity sensor or derived from closely spaced pressure measurements, and it supplies the velocity term needed to compute intensity and energy density.','A particle-velocity map shows how fast and which way air particles move. Sound makes air particles wiggle back and forth. The map draws this motion at each point. It is not the speed of sound. It is the tiny motion the wave creates.','It supplies the velocity part of the sound field, which combined with pressure gives intensity and energy density and reveals the direction of local air motion.','Engineers capture particle velocity with p-u probes or Microflown-type sensors to compute intensity, study near-field radiation, and validate reconstruction models.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-intensity map','Vector intensity probe','Pressure-gradient microphone array','Acoustic energy-density map','Sound-pressure map']::text[],ARRAY['Confusing particle velocity with the speed of sound, which is the wave''s propagation speed','Assuming particle velocity is always in phase with pressure, which is false in the near field','Treating it as a scalar when it is a vector quantity']::text[],ARRAY['Deriving intensity from pressure and velocity in an anechoic test','Mapping near-field velocity close to a vibrating panel','Feeding measured velocity into a holographic reconstruction']::text[],'advanced','u = −(1/ρ₀) ∫ ∇p dt','Acoustic particle velocity equals the negative pressure gradient divided by the medium density, integrated over time.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb10c006-5cd7-5f89-bbb8-7be98cd8ebe9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb10c006-5cd7-5f89-bbb8-7be98cd8ebe9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb10c006-5cd7-5f89-bbb8-7be98cd8ebe9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ef9fa78-5008-5ce2-a51a-512821a53992','Acoustic energy-density map','A spatial map of acoustic energy density, the acoustic energy stored per unit volume of the medium, comprising a potential part associated with the squared pressure and a kinetic part associated with the squared particle velocity. Rendered over a line, surface, or volume, it shows where acoustic energy is concentrated regardless of its direction of flow, and because it combines pressure and velocity information it is less sensitive to standing-wave nulls than a pressure-only map.','An energy-density map shows how much sound energy sits in each small volume of space. It adds the pressure part and the motion part together. Bright areas hold lots of energy. It does not show which way energy moves. It shows how much is stored there.','It measures how much acoustic energy is packed into each region, giving a fuller picture than pressure alone and staying steadier at standing-wave nulls where pressure drops to zero.','Energy-density sensing guides active noise control and low-frequency room measurements, where microphones sitting at pressure nulls would otherwise miss the field.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-pressure map','Particle-velocity map','Sound-intensity map','Reactive-intensity map','Acoustic potential energy']::text[],ARRAY['Assuming energy density shows direction, when it is a scalar with no flow direction','Using squared pressure alone and ignoring the kinetic term','Confusing energy density with intensity, which is an energy flux']::text[],ARRAY['Placing energy-density sensors for active noise control in a cabin','Measuring low-frequency room response without pressure-null problems','Comparing stored energy across zones of a reverberant room']::text[],'advanced','w = p²/(2ρ₀c²) + ½ρ₀|u|²','Acoustic energy density equals the potential energy from squared pressure plus the kinetic energy from squared particle velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic energy-density map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ef9fa78-5008-5ce2-a51a-512821a53992','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ef9fa78-5008-5ce2-a51a-512821a53992') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ef9fa78-5008-5ce2-a51a-512821a53992');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78db6241-d482-5d74-b1e9-f99287909fec','Acoustic phase map','A spatial map that displays the phase of an acoustic quantity, usually the sound pressure, relative to a reference such as a source signal or a fixed sensor, across a line, surface, or region at a single frequency. By showing how phase advances or lags from point to point, it reveals the direction and curvature of wavefronts, standing-wave structure, and regions where the field is in or out of step, complementing the amplitude information carried by a pressure or intensity map.','A phase map shows the timing of a sound wave at each point. Phase tells you where you are in the wave''s cycle. Points with the same phase are in step. The map shows how wavefronts move and bend. It works at one frequency at a time.','It exposes wavefront shape, propagation direction, and standing-wave patterns that amplitude maps hide, so timing relationships across the field can be read directly.','Phase maps help diagnose comb filtering, check driver alignment in arrays, and study wavefront curvature in holography and beamforming.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Equal-phase contour','Sound-pressure map','Acoustic holography','Wavefront','Phase']::text[],ARRAY['Reading absolute phase as meaningful without a stated reference','Ignoring phase wrapping, where values jump between plus and minus 180 degrees','Comparing phase across different frequencies as if directly equivalent']::text[],ARRAY['Checking wavefront alignment across a line-array plane','Diagnosing standing-wave phase structure in a room','Studying phase in a holographic reconstruction']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic phase map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78db6241-d482-5d74-b1e9-f99287909fec','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78db6241-d482-5d74-b1e9-f99287909fec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78db6241-d482-5d74-b1e9-f99287909fec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6ff48be-6427-52b6-88f5-3c3396d468ff','Equal-phase contour','A line or surface connecting all points in a sound field that share the same acoustic phase at a given instant and frequency, effectively tracing a wavefront. Equal-phase contours are everywhere perpendicular to the local direction of propagation of a travelling wave, and their spacing and curvature encode wavelength and wavefront shape, making them a compact way to visualise how sound propagates through a mapped region.','An equal-phase contour links points that are all at the same moment in the wave''s cycle. It traces one wavefront. The wave travels at right angles to this line. The spacing shows the wavelength. It is a way to draw how sound spreads out.','It marks wavefronts directly, so propagation direction and wavelength can be read from the geometry of the contours instead of from numbers.','These contours appear in simulation plots and holographic reconstructions used to study how wavefronts spread from sources or bend around obstacles.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic phase map','Wavefront','Isobaric contour','Wavelength','Sound-intensity map']::text[],ARRAY['Confusing an equal-phase contour with an equal-pressure contour, which coincide only in special cases','Assuming the contours are always evenly spaced, which fails near sources','Forgetting that they are defined at a single frequency']::text[],ARRAY['Tracing wavefronts radiating from a small source','Visualising diffraction around a barrier edge','Reading wavelength from contour spacing in a simulation']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equal-phase contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6ff48be-6427-52b6-88f5-3c3396d468ff','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6ff48be-6427-52b6-88f5-3c3396d468ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6ff48be-6427-52b6-88f5-3c3396d468ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ee52f1f-43c8-59c1-9e9e-f5a7aef039b5','Isobaric contour','A line or surface joining points of equal acoustic pressure amplitude within a mapped sound field. Analogous to isobars on a weather chart, isobaric contours summarise the spatial structure of the pressure field, with closely spaced contours indicating steep pressure gradients and widely spaced contours indicating gentle variation; they are a common way to render a sound-pressure map as level curves rather than as a filled colour field.','An isobaric contour links points that have the same sound pressure. It works like the lines on a weather map. Lines close together mean pressure changes fast. Lines far apart mean it changes slowly. It is one way to draw a pressure map.','It turns a pressure field into readable level curves, showing gradients and shapes at a glance rather than as a dense grid of numbers.','Isobaric contours appear in room-mode plots, chamber-uniformity checks, and simulation output where pressure structure must be read quickly.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Iso-SPL contour','Sound-pressure map','Equal-phase contour','Acoustic pressure','Pressure gradient']::text[],ARRAY['Assuming isobaric contours (linear pressure) and iso-SPL contours (decibel level) are unrelated, when for RMS pressure they coincide and differ only in scaling','Reading contour lines as energy flow, which pressure does not show','Assuming equal spacing implies a linear field']::text[],ARRAY['Drawing pressure level curves for a room mode','Checking pressure uniformity in a calibration chamber','Rendering simulation pressure as contour lines']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isobaric contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ee52f1f-43c8-59c1-9e9e-f5a7aef039b5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ee52f1f-43c8-59c1-9e9e-f5a7aef039b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ee52f1f-43c8-59c1-9e9e-f5a7aef039b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd094777f-e9c1-58a3-a9d4-ceed2fd88d84','Iso-SPL contour','A contour line or surface connecting points at which the sound pressure level, expressed in decibels relative to the standard reference pressure of 20 micropascals, is equal. Iso-SPL contours are the decibel-scaled counterpart of isobaric contours and are widely used to display loudspeaker coverage, noise-exposure zones, and level uniformity, where equal-level curves such as a minus 6 decibel coverage boundary carry direct engineering meaning.','An iso-SPL contour links points with the same sound pressure level in decibels. It is drawn on a decibel scale. Engineers use it to show speaker coverage. A common one marks where the level has dropped by six decibels. It maps where sound is equally loud.','It marks equal-level boundaries in decibels, letting engineers define coverage edges and exposure zones that map directly onto specifications.','Iso-SPL contours define loudspeaker coverage angles, noise-map exposure bands, and level-uniformity limits in venue and workplace assessments.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Isobaric contour','Sound pressure level','Sound-pressure map','Coverage angle','Noise map']::text[],ARRAY['Forgetting the decibel scale, so a small level change hides a large pressure change','Confusing an SPL contour with an energy-flow map','Ignoring the frequency or weighting the level was measured with']::text[],ARRAY['Plotting a loudspeaker''s minus 6 decibel coverage boundary','Drawing workplace noise-exposure zones','Checking level uniformity across an audience area']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Iso-SPL contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd094777f-e9c1-58a3-a9d4-ceed2fd88d84','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d094777f-e9c1-58a3-a9d4-ceed2fd88d84') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d094777f-e9c1-58a3-a9d4-ceed2fd88d84');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97f06548-83df-543b-9207-db5af064cb18','Active-intensity map','A map of the active component of sound intensity, the time-averaged net flow of acoustic energy per unit area, corresponding to energy that actually propagates away from sources and is radiated or dissipated. In a harmonic field it equals one-half the real part of the product of complex pressure and the conjugate of particle velocity, and mapping it isolates true energy transport from the oscillating, non-propagating reactive part, making it the quantity used for sound-power and source-location work.','An active-intensity map shows the sound energy that really travels away. This is the part that leaves the source and carries off. Arrows show its flow and direction. It ignores energy that just sloshes back and forth. It is the part used to measure sound power.','It isolates genuine propagating energy flow from the standing near-field part, which is exactly what sound-power measurement and source ranking require.','Active intensity underlies ISO sound-power-by-intensity surveys and source-ranking scans over machinery and enclosures.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-intensity map','Reactive-intensity map','Vector intensity probe','Sound power','Particle-velocity map']::text[],ARRAY['Confusing active intensity with the total or the reactive field','Trusting active intensity in a strong near field without checking the pressure-intensity index','Reading its sign without noting the chosen positive direction']::text[],ARRAY['Measuring machine sound power over a surface','Ranking the radiating panels of a gearbox','Separating true radiation from near-field storage']::text[],'advanced','I_a = ½ Re{p̂ û*} = ⟨p(t)u(t)⟩','Active intensity is the time-averaged product of pressure and particle velocity, equal to half the real part of pressure times the conjugate of velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active-intensity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97f06548-83df-543b-9207-db5af064cb18','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97f06548-83df-543b-9207-db5af064cb18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97f06548-83df-543b-9207-db5af064cb18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7494296a-3afc-5aa9-b16d-ff3f486d2fa7','Reactive-intensity map','A map of the reactive component of sound intensity, the oscillatory exchange of acoustic energy that surges back and forth without net transport, dominant in the near field of sources and around standing waves. In a harmonic field it equals one-half the imaginary part of the product of complex pressure and the conjugate of particle velocity, and mapping it highlights regions of strong stored, non-radiating energy where active-intensity estimates become unreliable.','A reactive-intensity map shows sound energy that sloshes back and forth. This energy does not travel away. It builds up close to a source. The map marks where this near-field energy is strong. Here normal intensity readings can be wrong.','It reveals near-field, non-propagating energy, warning where active-intensity measurements are biased and helping characterise the near field of sources.','Reactive intensity flags near-field zones in holography and intensity surveys, guiding probe placement and error checks.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Active-intensity map','Sound-intensity map','Near field','Particle-velocity map','Pressure-intensity index']::text[],ARRAY['Mistaking reactive intensity for real energy transport, which it is not','Ignoring strong reactive fields that bias active-intensity results','Assuming it vanishes in every free field, which fails near sources']::text[],ARRAY['Mapping the strong near field of a small loudspeaker','Checking where standing waves store energy','Deciding a safe probe distance for an intensity survey']::text[],'advanced','J = ½ Im{p̂ û*}','Reactive intensity equals half the imaginary part of complex pressure multiplied by the conjugate of particle velocity.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reactive-intensity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7494296a-3afc-5aa9-b16d-ff3f486d2fa7','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7494296a-3afc-5aa9-b16d-ff3f486d2fa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7494296a-3afc-5aa9-b16d-ff3f486d2fa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b386ca8-1caa-505a-984a-4a53ae307b0c','Vector intensity probe','A measurement device that resolves sound intensity as a vector by capturing acoustic pressure together with particle velocity, or the pressure gradient, along one or more axes at the same time. Two-microphone pressure-pressure (p-p) probes estimate velocity from the finite-difference pressure gradient between closely spaced microphones, while pressure-velocity (p-u) probes combine a pressure microphone with a dedicated particle-velocity sensor; multi-axis versions yield the full three-dimensional intensity vector for mapping energy flow.','A vector intensity probe measures both sound pressure and air motion. From these it works out sound energy flow and its direction. One type uses two close microphones. Another type adds a motion sensor to a microphone. Three-axis versions give flow in every direction.','It provides the paired pressure and velocity data needed to compute intensity as a directional vector, enabling source location and sound-power measurement.','Field engineers scan p-p or p-u probes over surfaces to rank noise sources and measure sound power to ISO 9614.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-intensity map','Pressure-gradient microphone array','Particle-velocity map','Active-intensity map','Pressure-intensity index']::text[],ARRAY['Ignoring the finite-difference error that limits the usable high-frequency range of a p-p probe','Using the wrong microphone spacer for the frequency range of interest','Neglecting phase mismatch between channels, which biases the intensity']::text[],ARRAY['Scanning a probe over a machine to map energy flow','Selecting microphone spacing for a target frequency band','Measuring sound power in situ on a factory floor']::text[],'advanced','I = ⟨p·u⟩  (p-u);  u_r ≈ −(1/ρ₀)∫(p₂−p₁)/Δr dt  (p-p)','A p-u probe forms intensity from measured pressure and velocity, while a p-p probe estimates velocity from the pressure difference between two spaced microphones.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vector intensity probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b386ca8-1caa-505a-984a-4a53ae307b0c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b386ca8-1caa-505a-984a-4a53ae307b0c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b386ca8-1caa-505a-984a-4a53ae307b0c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b123bcc4-71bb-561a-b1a2-bab7ee7e2a04','Pressure-gradient microphone array','An arrangement of two or more closely spaced pressure microphones that estimates the acoustic pressure gradient, and hence particle velocity and intensity, from the finite differences between microphone signals. Because the linearised momentum equation ties the pressure gradient to particle velocity, such an array recovers directional information from pressure-only sensors; the microphone spacing sets both the low-frequency phase-accuracy limit and the high-frequency finite-difference error bound.','This array uses two or more close microphones. It compares their pressures to find how pressure changes across the gap. From that change it works out air motion and energy flow. The spacing of the microphones sets the usable frequency range. Wrong spacing adds error.','It extracts direction and velocity from ordinary pressure microphones, forming the sensing basis of two-microphone intensity probes and directional arrays.','The p-p technique is built into intensity probes and gradient microphones used for sound-power and source-location work.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Vector intensity probe','Particle-velocity map','Sound-intensity map','Pressure gradient','Finite-difference approximation']::text[],ARRAY['Choosing a spacer too large, which raises finite-difference error at high frequency','Choosing a spacer too small, which worsens phase-mismatch error at low frequency','Assuming the estimate holds beyond the array''s valid frequency band']::text[],ARRAY['Building a two-microphone intensity probe','Selecting spacer length for a measurement band','Recovering direction from a pressure-only array']::text[],'advanced','u_r ≈ −(1/ρ₀) ∫ (p₂ − p₁)/Δr dt','Radial particle velocity is approximated from the pressure difference between two microphones, divided by their spacing and the medium density, integrated over time.','2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-gradient microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b123bcc4-71bb-561a-b1a2-bab7ee7e2a04','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b123bcc4-71bb-561a-b1a2-bab7ee7e2a04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b123bcc4-71bb-561a-b1a2-bab7ee7e2a04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96e283a2-3d21-5575-bf37-d7b806c8567c','3D sound-field map','A representation of one or more acoustic quantities such as pressure, intensity, particle velocity, or energy density, reconstructed throughout a three-dimensional region rather than on a single line or plane. Built from volumetric scans, microphone arrays, or holographic and model-based reconstruction, it lets the field be inspected on arbitrary slices, isosurfaces, or projections, capturing spatial structure that a single-plane map cannot show.','A 3D sound-field map shows sound through a whole volume of space. It is not limited to one flat plane. You can slice it any way you like. This reveals structure a flat map would miss. It can show pressure, energy, or flow.','It captures the full spatial structure of a field so behaviour above, below, and around a plane can be studied from any viewpoint.','3D maps come from array or holography systems used to study room fields, source radiation, and spatial-audio rendering.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Volumetric acoustic map','Acoustic holography','Volumetric scan','Sound-intensity map','Sound-field reconstruction']::text[],ARRAY['Assuming a single plane captures the whole field','Over-trusting regions between sparse measurement points','Ignoring that reconstruction quality falls off away from the measured data']::text[],ARRAY['Reconstructing a room field for spatial audio','Studying 3D radiation from a complex source','Inspecting field slices around a seated listener']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='3D sound-field map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96e283a2-3d21-5575-bf37-d7b806c8567c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96e283a2-3d21-5575-bf37-d7b806c8567c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96e283a2-3d21-5575-bf37-d7b806c8567c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2267776-b7ad-536e-a344-9ccb2ac2b788','Volumetric acoustic map','A three-dimensional dataset that assigns an acoustic quantity to each small volume element, or voxel, within a region, forming a volume rendering of the sound field. Closely related to a 3D sound-field map, the term stresses the voxel-based, filled-volume representation suited to volume rendering, isosurface extraction, and slicing, as opposed to data defined only on surfaces or lines.','A volumetric acoustic map fills a 3D space with sound values. Each tiny cube of space gets its own value. Together they build a solid picture of the field. You can slice it or peel back layers. It is like a 3D image made of sound.','It stores the field as filled volume elements, supporting volume rendering, isosurfaces, and slicing for detailed 3D inspection.','Volumetric maps appear in array-imaging and simulation tools that render sound fields as sliceable 3D volumes.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['3D sound-field map','Volumetric scan','Voxel','Acoustic holography','Sound-field reconstruction']::text[],ARRAY['Confusing a filled voxel volume with a surface-only map','Assuming voxel values are all directly measured rather than interpolated','Overlooking the heavy data and processing demands of dense volumes']::text[],ARRAY['Rendering a measured field as a sliceable volume','Extracting isosurfaces of equal level in 3D','Storing simulation output as voxel data']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volumetric acoustic map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2267776-b7ad-536e-a344-9ccb2ac2b788','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2267776-b7ad-536e-a344-9ccb2ac2b788') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2267776-b7ad-536e-a344-9ccb2ac2b788');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b92fea6d-947d-55b7-a204-4715c6dfa67b','Tomographic acoustic reconstruction','The reconstruction of a spatial distribution of an acoustic property, such as source strength, sound speed, or attenuation, from many acoustic measurements taken along different paths or directions, by inverting the relationship between the field and those projections. Drawing on the same inverse-problem mathematics as computed tomography, it combines many partial views into a single interior image and depends on adequate angular coverage and regularisation to be well posed.','This method builds an inside picture of sound from many views. It measures sound along many different paths. Then it combines the paths into one image. The idea is like a medical CT scan. It needs many angles to work well.','It recovers interior acoustic properties that cannot be measured directly, by mathematically combining many through-paths into one image.','It is used in ocean and atmospheric acoustic tomography and in ultrasound imaging to map sound speed or source distributions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic tomography','Acoustic computer tomography','Inverse problem','Sound-field reconstruction','Projection']::text[],ARRAY['Expecting a good image from too few viewing angles','Ignoring the need for regularisation in an ill-posed inversion','Assuming straight ray paths when refraction bends them']::text[],ARRAY['Mapping ocean sound speed from many acoustic paths','Imaging a flame''s temperature field acoustically','Reconstructing a source distribution from array data']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tomographic acoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b92fea6d-947d-55b7-a204-4715c6dfa67b','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b92fea6d-947d-55b7-a204-4715c6dfa67b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b92fea6d-947d-55b7-a204-4715c6dfa67b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3f06b74-b21a-527e-9f3e-68ee1dc1ab06','Acoustic tomography','An imaging and remote-sensing technique that infers the internal structure of a medium, or the distribution of sources, by measuring how sound propagates through it along many paths, typically using travel time, amplitude, or phase to reconstruct fields such as temperature, flow, or sound speed. Established forms include ocean acoustic tomography, atmospheric acoustic tomography, and industrial process tomography, all exploiting the dependence of propagation on the medium''s properties.','Acoustic tomography uses sound to see inside something. Sound travels through a medium along many paths. Its travel time or strength reveals what is inside. This can map temperature, flow, or sound speed. Oceans and the air are studied this way.','It turns measurable propagation effects like travel time into maps of a medium''s hidden internal properties over large or hard-to-reach regions.','Ocean acoustic tomography tracks temperature and currents, while similar methods map furnace temperature and duct flow.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Tomographic acoustic reconstruction','Acoustic computer tomography','Time of flight','Sound speed','Inverse problem']::text[],ARRAY['Confusing it with reflection imaging such as sonar or ultrasound B-mode','Assuming straight paths when sound refracts through gradients','Underestimating how many paths good coverage needs']::text[],ARRAY['Monitoring ocean temperature over long ranges','Measuring gas temperature across a furnace','Estimating flow in a large duct from sound timing']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3f06b74-b21a-527e-9f3e-68ee1dc1ab06','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3f06b74-b21a-527e-9f3e-68ee1dc1ab06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3f06b74-b21a-527e-9f3e-68ee1dc1ab06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6bc09185-41ea-5b2f-b3ce-7d0aa59cb079','Acoustic computer tomography','The acoustic counterpart of X-ray computed tomography, in which many acoustic projection measurements taken around or across a region are processed by computed-tomography reconstruction algorithms, such as filtered back-projection or algebraic iterative methods, to form a cross-sectional or volumetric image of an acoustic property. The name stresses the use of CT-style computational reconstruction applied to acoustic rather than X-ray data.','This is a CT scan that uses sound instead of X-rays. It takes many sound readings around a region. A computer combines them into a cross-section image. It borrows the maths of medical CT scanners. The result is a slice-by-slice picture.','It applies proven CT reconstruction algorithms to acoustic data, producing cross-sectional images of properties like sound speed or temperature.','It appears in process tomography, thermometry, and research ultrasound systems that image sound speed or temperature fields.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic tomography','Tomographic acoustic reconstruction','Filtered back-projection','Sound speed','Inverse problem']::text[],ARRAY['Assuming acoustic paths are straight like X-rays, when sound refracts','Expecting clean images from sparse angular coverage','Ignoring diffraction, which ray-based CT maths does not model']::text[],ARRAY['Imaging temperature across an industrial process','Reconstructing sound-speed slices in a test tank','Research ultrasound sound-speed tomography']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic computer tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6bc09185-41ea-5b2f-b3ce-7d0aa59cb079','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6bc09185-41ea-5b2f-b3ce-7d0aa59cb079') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6bc09185-41ea-5b2f-b3ce-7d0aa59cb079');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3012bde-3d64-5ad0-869d-5d3c27de9007','Thermoacoustic imaging','An imaging method in which pulsed electromagnetic energy, often radio-frequency or microwave radiation, is absorbed by a target, causing rapid thermal expansion that launches acoustic ultrasonic waves whose detected signals are reconstructed into an image of the absorbing structures. It combines electromagnetic absorption contrast with ultrasonic spatial resolution and is closely related to photoacoustic imaging, differing mainly in the wavelength of the exciting radiation.','Thermoacoustic imaging makes sound from pulses of energy. A quick energy pulse heats a target a tiny bit. The target expands fast and gives off sound waves. Sensors catch the sound and build an image. It often uses microwaves to excite the target.','It converts a material''s energy absorption into detectable sound, joining strong electromagnetic contrast with the fine spatial detail of ultrasound.','It is studied for biomedical imaging such as breast and tissue diagnostics using microwave-induced ultrasound.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Optoacoustic imaging','Photoacoustic imaging','Ultrasound imaging','Thermal expansion','Acoustic reconstruction']::text[],ARRAY['Confusing the microwave excitation of thermoacoustics with the laser light used in photoacoustics','Assuming the sound comes from an external source rather than from the heated target','Ignoring that image quality depends on the acoustic reconstruction step']::text[],ARRAY['Microwave-induced imaging of biological tissue','Research breast-imaging systems','Mapping energy absorption inside a sample']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermoacoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3012bde-3d64-5ad0-869d-5d3c27de9007','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3012bde-3d64-5ad0-869d-5d3c27de9007') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3012bde-3d64-5ad0-869d-5d3c27de9007');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '383e4050-8e34-535e-97ad-792f155da083','Optoacoustic imaging','An imaging technique, synonymous in most usage with photoacoustic imaging, in which pulsed or modulated light is absorbed by a target and the resulting transient thermoelastic expansion generates ultrasonic waves that are detected and reconstructed into an image of optical absorption. The term optoacoustic is favoured in much of the engineering and European literature, while photoacoustic is common in the biomedical field; both describe light-in, sound-out imaging.','Optoacoustic imaging uses light to make sound. A light pulse is absorbed inside a target. The target warms and expands in a flash. That expansion sends out sound waves. Sensors detect the sound and form an image.','It maps where light is absorbed inside a sample by reading the sound that absorption generates, blending optical contrast with ultrasonic resolution.','It supports biomedical imaging of blood and tissue and materials testing, using laser-induced ultrasound.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Photoacoustic imaging','Thermoacoustic imaging','Ultrasound imaging','Thermoelastic expansion','Acoustic reconstruction']::text[],ARRAY['Treating optoacoustic and photoacoustic as different methods, when they are the same','Confusing the light excitation with the microwave excitation of thermoacoustics','Assuming it images light scattering rather than light absorption']::text[],ARRAY['Imaging blood vessels with laser-induced ultrasound','Mapping absorbers in a tissue phantom','Non-destructive testing of a coated sample']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optoacoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '383e4050-8e34-535e-97ad-792f155da083','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='383e4050-8e34-535e-97ad-792f155da083') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='383e4050-8e34-535e-97ad-792f155da083');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce5a8b75-8233-5fb3-8937-4eda37352dec','Needle hydrophone map','A high-resolution map of an acoustic pressure field, typically an ultrasonic field in water or a tissue-mimicking medium, built by scanning a needle hydrophone, a miniature piezoelectric sensor with a very small active element, point by point through the field. The small element gives fine spatial resolution and wide bandwidth suited to characterising focused ultrasound and transducer beams, at the cost of lower sensitivity and possible spatial-averaging error if the element is not small enough.','A needle hydrophone map charts an underwater sound field in fine detail. A needle hydrophone is a tiny pressure sensor. It moves through the field point by point. Its small tip captures fine detail. This is used to check ultrasound beams.','It characterises ultrasonic fields with fine spatial detail, mapping focus, beam shape, and pressure for transducer and safety assessment.','Needle hydrophones scan the output of medical and industrial ultrasound transducers to verify focus and pressure levels.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Hydrophone','Raster scan','Planar scan','Sound-pressure map','Scan resolution']::text[],ARRAY['Using an element too large for the frequency, which spatially averages and blurs the field','Ignoring the hydrophone''s calibration and directivity','Overlooking low sensitivity that hurts the signal-to-noise ratio']::text[],ARRAY['Mapping the focus of a therapy ultrasound transducer','Verifying diagnostic-probe output for safety','Characterising a focused ultrasound beam in a water tank']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Needle hydrophone map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce5a8b75-8233-5fb3-8937-4eda37352dec','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce5a8b75-8233-5fb3-8937-4eda37352dec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce5a8b75-8233-5fb3-8937-4eda37352dec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51114a9b-e0d8-5988-863e-9a3feb51231f','Planar scan','A measurement procedure in which a sensor, or a field quantity, is sampled at points lying on a single plane, commonly a regular grid, to build a two-dimensional map of the field over that plane. Planar scanning is the standard acquisition geometry for planar nearfield acoustic holography and for many intensity and pressure surveys, where the measurement plane is placed close to and parallel with the source or surface of interest.','A planar scan measures sound across a flat plane. The sensor samples many points on that plane. Usually the points sit on a regular grid. This builds a 2D map of the field. It is common in holography and surveys.','It gathers field data on a defined plane, providing the gridded input needed for planar holography and surface intensity or pressure maps.','Planar scans over loudspeakers, panels, and machines feed nearfield holography and sound-power measurements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Raster scan','Volumetric scan','Scan resolution','Acoustic holography','Measurement aperture']::text[],ARRAY['Placing the plane too far from the source, which weakens near-field detail','Under-sampling the grid so that short wavelengths alias','Making the scanned plane too small and truncating the field']::text[],ARRAY['Scanning a plane in front of a loudspeaker for holography','Gridding an intensity survey over a machine face','Sampling a plane near a vibrating panel']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51114a9b-e0d8-5988-863e-9a3feb51231f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51114a9b-e0d8-5988-863e-9a3feb51231f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51114a9b-e0d8-5988-863e-9a3feb51231f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f40d3a0-6c6e-5516-af16-4c07957975f0','Raster scan','A point-by-point scanning pattern in which measurement positions are visited in ordered rows and columns, sweeping line by line across a plane or surface much as an image is scanned, to assemble a spatial map. In acoustic field mapping a single sensor is moved through the raster grid, or a synthetic aperture is stepped, trading acquisition time for spatial coverage; the row and column spacing sets the resolution and the highest spatial frequency captured.','A raster scan moves through points in neat rows and columns. It sweeps line by line, like scanning a page. One sensor visits each point in turn. The visited points build up a map. Row spacing sets the detail level.','It gives an orderly, complete way to cover a surface with one moving sensor, ensuring even sampling for a spatial map.','Raster scanning drives single-probe field mapping in holography rigs, hydrophone tanks, and automated scanners.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Planar scan','Volumetric scan','Scan resolution','Needle hydrophone map','Measurement aperture']::text[],ARRAY['Spacing rows too coarsely, which aliases fine detail','Assuming the field stayed steady over a long scan when it actually drifted','Confusing the raster acquisition path with the final image resolution']::text[],ARRAY['Stepping a hydrophone across a tank in rows','Automated scan of a source plane for holography','Building a 2D map with one moving microphone']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Raster scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f40d3a0-6c6e-5516-af16-4c07957975f0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f40d3a0-6c6e-5516-af16-4c07957975f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f40d3a0-6c6e-5516-af16-4c07957975f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '846b074d-b8f5-5c39-b783-2668713841f7','Volumetric scan','A measurement procedure that samples a field quantity at points distributed throughout a three-dimensional region, for example across a stack of parallel planes or on a 3D grid, to build a volumetric map of the sound field. Volumetric scanning multiplies acquisition time relative to a single plane but captures how the field varies with depth, supporting volume rendering, slicing, and full three-dimensional reconstruction.','A volumetric scan samples sound all through a 3D space. It measures many points at different depths. Often it stacks several flat scans together. This captures how the field changes with depth. It builds a full 3D map.','It records the field throughout a volume, capturing depth variation that a single plane misses and feeding 3D reconstruction.','Volumetric scans in water tanks and array rigs produce 3D field data for research and transducer characterisation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Planar scan','Raster scan','Volumetric acoustic map','3D sound-field map','Scan resolution']::text[],ARRAY['Underestimating the long time a dense 3D scan takes','Letting the field or the source drift during a slow scan','Under-sampling in depth so that layers are missed']::text[],ARRAY['Stacking plane scans to map a 3D beam','Sampling a volume around a source in a tank','Building 3D data for volume rendering']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volumetric scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '846b074d-b8f5-5c39-b783-2668713841f7','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='846b074d-b8f5-5c39-b783-2668713841f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='846b074d-b8f5-5c39-b783-2668713841f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89fb893a-1dae-5257-96bc-b08a2f0d5009','Scan resolution','The spatial step size between adjacent measurement points in a scanned acoustic map, that is the grid spacing, which sets the finest spatial detail the map can represent and, through the spatial sampling theorem, the highest spatial frequency or shortest wavelength that can be captured without aliasing. Finer resolution improves detail and reduces spatial aliasing but increases the number of points and the acquisition time.','Scan resolution is the gap between measurement points. A small gap captures fine detail. A large gap misses it and can cause errors. Finer scans need many more points. So they take much longer to run.','It fixes the smallest detail a scan can resolve and whether short wavelengths alias, trading detail against measurement time.','Engineers set scan resolution from the highest frequency of interest to avoid spatial aliasing in holography and hydrophone maps.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Planar scan','Raster scan','Spatial aliasing','Interpolation artifact','Measurement aperture']::text[],ARRAY['Choosing spacing wider than half the shortest wavelength, which causes spatial aliasing','Assuming interpolation can restore detail the sampling never captured','Trading away resolution for speed without checking the frequency limit']::text[],ARRAY['Setting grid spacing for a high-frequency holography scan','Choosing hydrophone step size for a focused beam','Balancing detail against total scan time']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scan resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89fb893a-1dae-5257-96bc-b08a2f0d5009','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89fb893a-1dae-5257-96bc-b08a2f0d5009') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89fb893a-1dae-5257-96bc-b08a2f0d5009');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e78a095-87e7-577c-afaf-2eaaec16fcd0','Interpolation artifact','A false or misleading feature in a reconstructed acoustic map that arises from interpolating between sparse or insufficiently sampled measurement points rather than from the true field. When the measurement grid under-samples the spatial variation, interpolation can invent smooth structure, blur real detail, or produce spatial aliasing and ringing, so apparent features must be checked against the sampling density before they are trusted.','An interpolation artifact is fake detail in a sound map. It appears when points are too far apart. The software guesses the values between them. Those guesses can invent structure that is not real. Always check the map against the sampling.','Naming this error reminds analysts that filled-in map detail may be invented, guarding against reading artifacts as real acoustic features.','Analysts watch for interpolation artifacts when rendering sparse holography or hydrophone data as smooth colour maps.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Scan resolution','Spatial aliasing','Sound-field reconstruction','Raster scan','Edge effect']::text[],ARRAY['Trusting smooth detail between widely spaced points as if it were measured','Blaming the sensor for structure the interpolation created','Assuming finer interpolation adds real information rather than a guess']::text[],ARRAY['Rendering a coarse holography grid as a smooth image','Spotting false hot spots between sparse points','Deciding whether a feature is real or interpolated']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interpolation artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e78a095-87e7-577c-afaf-2eaaec16fcd0','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e78a095-87e7-577c-afaf-2eaaec16fcd0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e78a095-87e7-577c-afaf-2eaaec16fcd0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '090ccd6b-8d53-5939-98aa-be916ec9aaf4','Measurement aperture','The finite spatial extent, that is the size and shape of the region actually covered by sensors or measurement points, over which a sound field is sampled. In array processing and acoustic holography the measurement aperture governs spatial resolution and, for reconstruction, must be large enough to capture the significant part of the field; its finite size is the origin of aperture-related errors such as truncation and edge effects.','The measurement aperture is the area your sensors actually cover. A bigger aperture captures more of the sound field. It also sharpens the spatial detail you can resolve. If it is too small, parts of the field are missed. That causes errors later.','It sets how much of the field is captured and the resolution achievable, and it must be sized to contain the field''s significant energy.','Engineers size the measurement aperture in holography and array work to cover the source and limit truncation error.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Aperture truncation','Edge effect','Planar scan','Acoustic holography','Scan resolution']::text[],ARRAY['Making the aperture too small so field energy spills outside it','Confusing aperture size with grid resolution, which are separate things','Assuming a small aperture can still resolve widely spread sources']::text[],ARRAY['Sizing a scan area to cover a whole loudspeaker','Choosing array extent for a holography measurement','Deciding coverage for a source larger than the sensor grid']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '090ccd6b-8d53-5939-98aa-be916ec9aaf4','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='090ccd6b-8d53-5939-98aa-be916ec9aaf4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='090ccd6b-8d53-5939-98aa-be916ec9aaf4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56c721b1-1bab-529f-8bfb-0517a2c3501f','Aperture truncation','The error introduced when a sound field is measured over a finite aperture that is too small to contain the field''s significant amplitude, so the reconstruction effectively multiplies the true field by a spatial window and loses the energy outside the measured region. In nearfield acoustic holography this truncation causes leakage in the wavenumber domain and degrades the reconstructed field, and it is mitigated by enlarging the aperture or applying spatial windowing and extrapolation.','Aperture truncation is an error from measuring too small an area. The field does not stop at the edge of your sensors. Cutting it off there loses real information. The reconstruction then goes wrong. A larger area or windowing reduces the error.','The concept explains why an undersized measurement region corrupts reconstruction, guiding engineers to size apertures and apply windowing.','Holography practitioners enlarge the scan or apply spatial windows to curb aperture-truncation errors near source edges.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Measurement aperture','Edge effect','Spatial windowing','Acoustic holography','Spectral leakage']::text[],ARRAY['Assuming the field is negligible just past the measured edge','Skipping the spatial windowing that would ease the truncation','Blaming sensor noise for errors caused by too small an aperture']::text[],ARRAY['Reconstructing a source wider than the scanned plane','Applying a spatial window to holography data','Diagnosing edge errors from an undersized scan']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aperture truncation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56c721b1-1bab-529f-8bfb-0517a2c3501f','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56c721b1-1bab-529f-8bfb-0517a2c3501f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56c721b1-1bab-529f-8bfb-0517a2c3501f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '874840ef-e336-57c7-8b10-3022d0e9a30d','Edge effect','A reconstruction artifact concentrated near the boundary of a finite measurement region, where the abrupt truncation of the sampled field and the reduced neighbourhood of data points cause errors, distortion, or spurious features in the reconstructed acoustic quantity. In nearfield acoustic holography edge effects appear as elevated errors and ringing along the perimeter of the measurement plane, and are commonly reduced with spatial windowing, aperture extension, or by disregarding a border margin of the result.','An edge effect is an error near the border of a scan. Data runs out at the edge of the measured area. That sudden cutoff distorts the result there. So the outer rim of a map is less reliable. Engineers often ignore or window the edges.','It flags that results along a measurement boundary are least trustworthy, prompting windowing, aperture extension, or trimming of the border.','Analysts discount or window the outer rows of holography and scan maps, where edge errors gather.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Aperture truncation','Measurement aperture','Spatial windowing','Acoustic holography','Interpolation artifact']::text[],ARRAY['Trusting values at the very edge of a reconstructed map','Confusing edge effects with real features near a source boundary','Skipping the windowing that would suppress them']::text[],ARRAY['Ignoring the border rows of a holography reconstruction','Windowing scan data to tame perimeter ringing','Spotting ringing along the edges of a map']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Edge effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '874840ef-e336-57c7-8b10-3022d0e9a30d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='874840ef-e336-57c7-8b10-3022d0e9a30d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='874840ef-e336-57c7-8b10-3022d0e9a30d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6229a38-f35b-5114-bb70-5e621295d471','Sound-intensity video','A time sequence of sound-intensity or sound-pressure-level maps rendered as successive video frames, letting the changing spatial distribution of acoustic energy across a scene be watched over time. Each frame assigns a colour to the estimated acoustic level for each pixel direction, typically produced by an acoustic camera that pairs a microphone array and beamforming with an optical camera.','A sound-intensity video shows where sound is loud in a scene. Each frame is a colour map of sound level. Warmer colours mark louder spots. Playing the frames in order shows how the sound moves. It works like a heat map for noise over time.','Lets people see, not just hear, how sound energy spreads and shifts, so moving or on-and-off noise sources are easy to spot and track.','Used with acoustic cameras to locate rattles, leaks, or noisy parts on machines, vehicles, and production lines during noise troubleshooting.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic camera','Beamforming','Acoustic map sequence','Sound intensity','Sound pressure level']::text[],ARRAY['Reading the colours as true sound-pressure level at the object rather than a beamforming estimate for a direction','Assuming fine detail at low frequencies, where array resolution is actually poor','UNSAFE: relying on the video alone and skipping hearing protection near high-level sources']::text[],ARRAY['Filming a running engine to find which panel radiates the most noise','Tracking a moving squeak along a conveyor','Documenting a noise complaint over a full work cycle']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-intensity video');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6229a38-f35b-5114-bb70-5e621295d471','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6229a38-f35b-5114-bb70-5e621295d471') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6229a38-f35b-5114-bb70-5e621295d471');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2afe892-880e-57da-9856-1551898f5728','Acoustic map sequence','An ordered series of acoustic maps computed at successive time windows, forming the frame sequence of a sound-field video. Each map shows estimated acoustic level or intensity over a spatial grid, usually from microphone-array beamforming or near-field holography, and playing the sequence reveals how sources start, stop, and move.','An acoustic map sequence is a set of sound maps in time order. Each map shows where sound comes from at one moment. Put together, they act like the frames of a movie. The movie shows sound sources turning on, off, and moving. It is the sound version of video frames.','Turns single still acoustic maps into a time record, so changing and short-lived sources can be studied instead of only steady ones.','Produced by acoustic cameras and array software to review transient events, cycle-by-cycle machine noise, or vehicle pass-by tests.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic camera','Beamforming','Sound-intensity video','Beamformed acoustic frame','Acoustic map']::text[],ARRAY['Confusing frame rate with acoustic time resolution, which is set by the analysis window length','Assuming every frame is independent when temporal smoothing links them','Treating low-frequency frames as sharp despite poor array resolution']::text[],ARRAY['Reviewing brake squeal frame by frame during a test drive','Studying a valve that clicks only at certain times','Comparing noise maps across one machine cycle']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic map sequence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2afe892-880e-57da-9856-1551898f5728','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2afe892-880e-57da-9856-1551898f5728') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2afe892-880e-57da-9856-1551898f5728');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1c89565-a336-5016-b77b-481253f4363a','Audio-visual acoustic map','An acoustic source or intensity map spatially registered to an optical camera image of the same scene, so estimated sound levels are overlaid on the visible objects that produce them. Alignment relies on calibration between the microphone array and the camera, letting a viewer read which pictured object matches a hot spot in the acoustic map.','An audio-visual acoustic map lays a sound map over a normal photo. Hot colours sit on the objects making the sound. This shows at a glance what is noisy. The array and camera must be lined up first. Then the sound map matches the picture.','Links measured sound to the real objects in view, so users can name the noise source instead of guessing from a colour blob alone.','A standard acoustic-camera output for noise inspections, where an overlay shows a leaking joint or loud component on the live camera image.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Acoustic camera','Beamforming','Acoustic map','Sound-intensity video','Array-camera calibration']::text[],ARRAY['Trusting the overlay when array-to-camera calibration is off, placing hot spots on the wrong object','Forgetting the map is a direction estimate, so reflections can appear as false sources','Assuming depth is known when the overlay is only a 2D projection']::text[],ARRAY['Overlaying a leak map on a photo of a pressurised pipe','Pointing an acoustic camera at a facade to find noisy units','Showing a client which machine part is loudest on screen']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual acoustic map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1c89565-a336-5016-b77b-481253f4363a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1c89565-a336-5016-b77b-481253f4363a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1c89565-a336-5016-b77b-481253f4363a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86e91d81-8894-5bb4-b8cf-b823286ac0b1','Beamformed acoustic frame','A single spatial image of acoustic energy produced by applying array beamforming to one short time window of multichannel microphone data. For each look direction or pixel, the beamformer combines the microphone signals with direction-dependent delays and weights to estimate arriving sound level, yielding one frame that can stand alone or become part of an acoustic video.','A beamformed acoustic frame is one sound picture from a mic array. The array listens in many directions at once. For each direction it estimates how loud sound is. Those values form a single image. Many such frames in a row make a sound video.','Provides the basic still image of an acoustic camera, turning raw multichannel audio into a viewable map of where sound arrives from.','Computed inside acoustic-camera software; a technician captures a frame to locate a dominant noise source at an instant.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Beamforming','Microphone array','Acoustic camera','Delay-and-sum','Acoustic map sequence']::text[],ARRAY['Expecting sharp images at low frequency, where a small array gives coarse resolution','Mistaking beamformer sidelobes for extra real sources','Assuming the colour equals sound level at the object rather than a steered estimate']::text[],ARRAY['Grabbing one frame to spot the loudest point on an idling motor','Checking array aim before recording a full sequence','Comparing frames from two microphone positions']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamformed acoustic frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86e91d81-8894-5bb4-b8cf-b823286ac0b1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86e91d81-8894-5bb4-b8cf-b823286ac0b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86e91d81-8894-5bb4-b8cf-b823286ac0b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '850c341f-d554-50d7-a622-4d8d5671bea9','Acoustic scene grounding','The task of linking sounds in an audio or audio-visual recording to their locations, objects, or regions within the represented scene, so heard events are tied to where and what produced them. It generalises visual sound-source localisation by associating acoustic content with spatial and semantic elements of the scene rather than only a pixel location.','Acoustic scene grounding ties a sound to its place in a scene. It answers where the sound is and what made it. A dog bark gets linked to the dog on screen. This joins hearing with seeing. It helps a system understand a scene, not just label it.','Gives machine perception a spatial and object-level anchor for sound, supporting systems that must know which thing in a scene is making noise.','Used in audio-visual learning research and robotics to point a camera or robot at a talker, alarm, or machine that is producing sound.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-source grounding','Audio-visual localization','Object-sound association','Multimodal scene understanding','Sound event localization and detection']::text[],ARRAY['Assuming the loudest region is always the correct source when reflections mislead','Grounding to the most visually striking object instead of the true source','Confusing scene-level grounding with simple whole-clip sound classification']::text[],ARRAY['Linking a squeak in a video to the specific wheel shown','A robot orienting toward the person who spoke','Tagging which appliance an alarm sound belongs to']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic scene grounding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '850c341f-d554-50d7-a622-4d8d5671bea9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='850c341f-d554-50d7-a622-4d8d5671bea9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='850c341f-d554-50d7-a622-4d8d5671bea9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2eea3247-d19b-590d-8423-314c048a81f5','Multimodal scene understanding','A class of machine-perception tasks in which a model combines two or more sensory modalities, such as vision, audio, and spatial acoustic data, to interpret a scene more completely than any single modality allows. The model fuses complementary cues to answer questions about objects, events, and their relationships, for example identifying and localising a noise source that vision alone cannot disambiguate.','Multimodal scene understanding uses more than one sense at once. A model may mix video, sound, and other cues. Together these tell a fuller story than one sense alone. It can spot an object and the sound it makes. This helps answer richer questions about a scene.','Lets systems resolve ambiguity by cross-checking modalities, so cues missing from one sensor can be supplied by another.','Underlies audio-visual assistants, robotics, and captioning systems that must reason jointly over what is seen and heard in a scene.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Multimodal learning','Audio-visual localization','Vision-language model','Sensor fusion','Acoustic scene grounding']::text[],ARRAY['Assuming more modalities always help, even when one is noisy or poorly aligned','Fusing modalities without proper time alignment, which corrupts joint cues','Treating an early-preprint accuracy gain as a settled, general result']::text[],ARRAY['Answering questions about a video using both its images and its sound','A robot combining sight and hearing to find a caller','Adding spatial acoustic maps to a video model to locate noise']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multimodal scene understanding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2eea3247-d19b-590d-8423-314c048a81f5','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2eea3247-d19b-590d-8423-314c048a81f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2eea3247-d19b-590d-8423-314c048a81f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd80d3edc-c4b9-5620-8096-412292979588','Sound-source grounding','The task of associating a given sound with the specific object, location, or event that produced it within a visual or spatial scene, typically by predicting the region of an image or space responsible for the audio. It is closely related to visual sound-source localisation and provides the object-level link between an acoustic signal and its origin.','Sound-source grounding finds what made a sound. It ties the audio to a spot in the image. A voice is linked to the mouth on screen. The model marks the region that is the source. This connects the sound to its real origin.','Provides the mapping from an audio signal to its cause in the scene, a building block for separation, tracking, and audio-visual reasoning.','Used in audio-visual deep-learning systems to highlight the pixels or object producing a sound, aiding captioning, editing, and robot attention.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Audio-visual localization','Acoustic scene grounding','Object-sound association','Audio-visual source separation','Visual sound-source localization']::text[],ARRAY['Grounding to a co-occurring but silent object that only correlates with the sound','Assuming one sound has one source when several may overlap','Confusing grounding with classifying the sound''s category']::text[],ARRAY['Highlighting which instrument is playing in a band video','Linking an off-camera cue to the visible object that caused it','Marking the speaking person in a group video']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-source grounding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd80d3edc-c4b9-5620-8096-412292979588','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d80d3edc-c4b9-5620-8096-412292979588') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d80d3edc-c4b9-5620-8096-412292979588');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7095eda0-d477-5aad-a242-e64f72014dea','Object-sound association','The learned correspondence between visual objects and the sounds they characteristically produce, letting a model match a sounding object in an image to the corresponding audio and vice versa. Often trained from the natural co-occurrence of audio and video, it underpins tasks such as audio-visual correspondence, localisation, and separation.','Object-sound association matches things to the sounds they make. A guitar is paired with a strumming sound. Models learn this from many videos. Then they can tell which object fits a sound. It links seeing an object with hearing it.','Supplies the cross-modal knowledge that a given object and a given sound belong together, enabling later localisation and separation.','Learned by self-supervised audio-visual models from unlabeled video, then reused for tagging, retrieval, and sound-source localisation.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Audio-visual correspondence','Sound-source grounding','Audio-visual localization','Audio-visual source separation','Self-supervised learning']::text[],ARRAY['Learning background correlations instead of the true sounding object','Assuming every visible object is a sound source','Expecting associations to transfer to objects never seen in training']::text[],ARRAY['Matching a barking sound to the dog in a clip','Retrieving video of an object from its sound','Pretraining a model on unlabeled video for later tasks']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Object-sound association');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7095eda0-d477-5aad-a242-e64f72014dea','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7095eda0-d477-5aad-a242-e64f72014dea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7095eda0-d477-5aad-a242-e64f72014dea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc8e50e2-15e5-5355-966c-d5882058ca33','Audio-visual source separation','A source-separation approach that isolates individual sound sources from a mixture by exploiting synchronised visual information alongside the audio. Visual cues such as the appearance or motion of a sounding object guide the model in assigning mixture energy to each source, improving separation over audio-only methods, especially for overlapping speakers or instruments.','Audio-visual source separation splits mixed sounds apart. It uses the video as well as the audio. Seeing a mouth or an instrument helps pick out its sound. This works better than using audio alone. It shines when sounds overlap.','Improves separation of overlapping sources by adding visual guidance, helping decide which sound belongs to which visible object.','Used to isolate a chosen speaker or instrument in video, for dialogue clean-up, captioning, and remixing multi-source recordings.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Source separation','Audio-visual localization','Object-sound association','Speech enhancement','Blind source separation']::text[],ARRAY['Assuming vision always helps, even when the sounding object is off-screen or occluded','Confusing it with audio-only blind separation','Expecting perfect separation when several similar sources overlap']::text[],ARRAY['Isolating one speaker at a noisy table using their lip motion','Separating one instrument from a band recording','Cleaning dialogue in film using the on-screen talker']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual source separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc8e50e2-15e5-5355-966c-d5882058ca33','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc8e50e2-15e5-5355-966c-d5882058ca33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc8e50e2-15e5-5355-966c-d5882058ca33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56814795-45f4-54d2-902e-6cd21992ee6c','Audio-visual localization','The task of determining the spatial location of a sound source using both audio and visual information, typically predicting the image region or scene direction from which a sound originates. Correlating audio with synchronised video lets models localise sources without dedicated spatial audio, and adding array or spatial cues sharpens the estimate.','Audio-visual localization finds where a sound comes from. It uses the video and the audio together. The model marks the spot in the image that is the source. Matching sound to motion reveals the location. It links what is heard to where it is seen.','Locates sounding objects in a scene by fusing modalities, supporting attention, tracking, and downstream separation.','Used in robotics, surveillance, and video analysis to point at or box the object making a sound, often from ordinary video.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Sound-source grounding','Audio-visual source separation','Object-sound association','Direction of arrival','Multimodal scene understanding']::text[],ARRAY['Localising a moving but silent object that merely correlates with the sound','Relying on mono audio, which lacks direction, without visual cues','Ignoring off-screen sources that produce no visual evidence']::text[],ARRAY['Boxing the person who is speaking in a meeting video','A robot turning toward a caller','Finding which on-screen object triggered a sound']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56814795-45f4-54d2-902e-6cd21992ee6c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56814795-45f4-54d2-902e-6cd21992ee6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56814795-45f4-54d2-902e-6cd21992ee6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '598bc0f7-9c0d-5ffe-9c76-7100a60ffb9d','Acoustic saliency map','A visualization that highlights the parts of an acoustic input most responsible for a model''s output, produced by interpretability methods such as gradient- or perturbation-based attribution. In audio models it marks the time, frequency, or spatial regions whose change most affects the prediction, giving an explanation of what the network attended to.','An acoustic saliency map shows which parts of a sound mattered most. It marks the moments or bands that drove the model''s answer. Bright areas had the biggest effect. It is a way to explain an audio model. It shows what the network relied on.','Explains and debugs audio models by revealing which input regions drive a decision, exposing whether the model uses meaningful cues.','Used by researchers to check audio classifiers, spotting when a model keys on noise or artefacts instead of the true sound.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Saliency map','Spectrogram saliency map','Acoustic attention map','Model interpretability','Grad-CAM']::text[],ARRAY['Reading saliency as proof of cause rather than correlation with the output','Comparing maps across methods that define importance differently','Assuming bright regions are always meaningful']::text[],ARRAY['Checking why a sound classifier flagged a clip','Debugging a model that keys on background hum','Explaining a detector''s decision to reviewers']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic saliency map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '598bc0f7-9c0d-5ffe-9c76-7100a60ffb9d','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='598bc0f7-9c0d-5ffe-9c76-7100a60ffb9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='598bc0f7-9c0d-5ffe-9c76-7100a60ffb9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c01ae7a-da58-5417-adc9-a619ca91ba87','Spectrogram saliency map','An interpretability overlay on a spectrogram that highlights the time-frequency bins most influential on a model''s prediction, computed by attribution methods such as saliency gradients or class-activation mapping. It shows which spectral events and time instants the network relied on, using the spectrogram as the image the model effectively sees.','A spectrogram saliency map marks the key spots on a spectrogram. A spectrogram shows sound by time and pitch. The map brightens the bins that swayed the model. It shows which sounds mattered for the answer. It explains audio models that read spectrograms.','Localises a model''s evidence in the time-frequency plane, making audio-classifier decisions inspectable on a familiar spectrogram view.','Used to validate spectrogram-based classifiers, revealing whether they focus on the target event or on unrelated bands.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Spectrogram','Saliency map','Acoustic saliency map','Grad-CAM','Model interpretability']::text[],ARRAY['Treating highlighted bins as ground-truth causes rather than attributions','Ignoring that spectrogram settings change which bins appear important','Assuming the map transfers to a model trained on raw audio']::text[],ARRAY['Explaining a bird-call classifier''s decision','Checking a cough detector for spurious cues','Teaching students how a network reads a spectrogram']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectrogram saliency map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c01ae7a-da58-5417-adc9-a619ca91ba87','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c01ae7a-da58-5417-adc9-a619ca91ba87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c01ae7a-da58-5417-adc9-a619ca91ba87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65cddb63-e4fc-5dd8-8115-51e0fb086583','Acoustic attention map','A visualization of the attention weights a neural network assigns across an acoustic input, showing which time frames, frequency bands, directions, or spatial locations the model emphasises when forming its representation. Unlike post-hoc saliency, it reads the model''s internal attention mechanism directly, often from transformer-style layers.','An acoustic attention map shows where a model focuses in sound. Modern models weigh some parts more than others. The map draws those weights over time or frequency. Bright areas got more attention. It comes straight from inside the model.','Exposes the internal focus of attention-based audio models, aiding interpretation and comparison of how models weight input regions.','Inspected in transformer audio models to see which frames or bands drive a task, guiding debugging and model design.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Attention mechanism','Acoustic saliency map','Spectrogram saliency map','Transformer','Model interpretability']::text[],ARRAY['Equating high attention with true importance or causation','Confusing internal attention weights with post-hoc saliency','Reading a single head''s map as the whole model''s behaviour']::text[],ARRAY['Viewing which frames a speech transformer attends to','Comparing attention across model layers','Diagnosing a model that ignores the target band']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic attention map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65cddb63-e4fc-5dd8-8115-51e0fb086583','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65cddb63-e4fc-5dd8-8115-51e0fb086583') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65cddb63-e4fc-5dd8-8115-51e0fb086583');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65f697cf-3c8c-5c1b-97ce-b5e4e1af8b6a','Spatial audio embedding','A learned vector representation that encodes the spatial properties of sound, such as source direction, distance, or the layout of a sound field, into a compact feature space usable by downstream models. Trained from multichannel, ambisonic, or binaural audio, it captures spatial structure that a single-channel embedding would discard.','A spatial audio embedding is a learned code for where sound is. It stores direction and distance as numbers. Models build it from multi-mic or 3D audio. Other models then use this code. It keeps the space of the sound, not just its content.','Compresses spatial cues into features a network can reuse, letting models reason about direction and layout without raw multichannel input.','Used in spatial audio tasks like direction estimation, scene classification, and audio-visual localisation built on multichannel recordings.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Embedding','Ambisonics','Binaural audio','Direction of arrival','Representation learning']::text[],ARRAY['Assuming a mono embedding can hold spatial information','Ignoring that microphone geometry shapes the learned space','Expecting the embedding to transfer across different array setups']::text[],ARRAY['Feeding array features to a direction-of-arrival model','Pretraining on ambisonic audio for scene tasks','Combining spatial audio codes with video features']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial audio embedding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65f697cf-3c8c-5c1b-97ce-b5e4e1af8b6a','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65f697cf-3c8c-5c1b-97ce-b5e4e1af8b6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65f697cf-3c8c-5c1b-97ce-b5e4e1af8b6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09ec7c14-fb1c-5529-af00-45273a624fc9','Acoustic feature map','An intermediate representation inside a neural network processing audio, formed by convolving learned filters over an input such as a spectrogram or waveform to produce a grid of activations. Each channel of the feature map responds to a particular learned acoustic pattern, and stacked feature maps form the hierarchy a model uses to build higher-level audio features.','An acoustic feature map is a layer''s output inside an audio network. Filters slide over the sound input and react to patterns. Each map shows where a pattern appears. Deeper layers build on earlier maps. They turn raw sound into useful features.','Holds the network''s learned intermediate features, the stepping stones between raw audio and a final decision.','Encountered when designing or inspecting audio CNNs, where feature-map activations reveal what filters detect at each layer.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Feature map','Convolutional neural network','Spectrogram','Representation learning','Activation']::text[],ARRAY['Confusing a feature map with the final output or a saliency map','Assuming each channel maps to a human-nameable concept','Ignoring that input framing changes the learned features']::text[],ARRAY['Inspecting early-layer filters of an audio CNN','Debugging why a network misses a sound pattern','Teaching how convolution builds audio features']::text[],'intermediate',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic feature map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09ec7c14-fb1c-5529-af00-45273a624fc9','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09ec7c14-fb1c-5529-af00-45273a624fc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09ec7c14-fb1c-5529-af00-45273a624fc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a2d2d8c-3edc-5dcf-8211-4df431415e96','Latent acoustic field','A compact, learned internal representation of a spatial sound field held within a neural network, from which acoustic quantities such as pressure or impulse responses at query positions can be decoded. Related to neural acoustic field models, it stores the field implicitly in network weights or latent codes rather than as an explicit grid of measured values.','A latent acoustic field is a hidden model of a sound space. The network stores the field as learned numbers. From it, the model can predict sound at new points. It is not a direct set of measurements. It packs the sound field into the model.','Encodes a continuous sound field in a form a network can query, enabling prediction of sound at unmeasured positions.','Used in neural sound-field and acoustic rendering research to synthesise room responses or spatial audio at new listener positions.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Neural acoustic field','Latent representation','Sound field','Implicit neural representation','Neural acoustic reconstruction']::text[],ARRAY['Treating the latent field as directly measured data rather than a learned model','Assuming it generalises far beyond the trained space or scene','Confusing the latent code with an explicit pressure grid']::text[],ARRAY['Predicting a room impulse response at a new seat','Rendering spatial audio for a moving listener','Interpolating a measured sound field between microphones']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Latent acoustic field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a2d2d8c-3edc-5dcf-8211-4df431415e96','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a2d2d8c-3edc-5dcf-8211-4df431415e96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a2d2d8c-3edc-5dcf-8211-4df431415e96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b33a26b-501e-5ff3-9b71-60cccb3120fe','Neural acoustic reconstruction','The use of neural networks to reconstruct a sound field or source distribution from limited or indirect acoustic measurements, learning a mapping from sparse sensor data to a denser field or to equivalent sources. It replaces or augments classical inverse methods, offering data-driven regularisation for ill-posed reconstruction problems such as holography and spatial upsampling.','Neural acoustic reconstruction rebuilds a sound field with a network. It starts from a few measurements. The network fills in the sound between sensors. This solves a hard, underspecified problem. Learned patterns guide the missing parts.','Provides learned priors for ill-posed sound-field reconstruction, improving estimates where classical inversion is unstable or data is sparse.','Applied to near-field holography, sparse microphone arrays, and sound-field upsampling to estimate full fields from few sensors.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Data-driven NAH','Physics-informed acoustic learning','Sound field reconstruction','Neural acoustic field','Inverse problem']::text[],ARRAY['Assuming the network invents valid data where no measurement constrains it','Trusting reconstructions outside the training distribution','Ignoring that sensor layout limits what can be recovered']::text[],ARRAY['Reconstructing a vibrating panel''s field from few microphones','Upsampling a sparse array measurement','Estimating a source map from hologram data']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Neural acoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b33a26b-501e-5ff3-9b71-60cccb3120fe','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b33a26b-501e-5ff3-9b71-60cccb3120fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b33a26b-501e-5ff3-9b71-60cccb3120fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb9deccb-ae0b-5fd0-9442-d30ecd2b10a1','Physics-informed acoustic learning','A modelling approach that constrains neural networks with the governing physics of sound, most often the Helmholtz or wave equation, by adding physics-based residuals to the training loss or embedding physical operators in the architecture. This enforces physically consistent solutions and reduces the data needed, and it has been applied to near-field acoustic holography and sound-field reconstruction.','Physics-informed acoustic learning teaches a network the rules of sound. Sound obeys known wave equations. The training makes the model respect those rules. This keeps its answers physical. It also needs less measured data.','Injects known acoustic physics as a constraint, improving accuracy and generalisation while cutting the amount of training data required.','Used in near-field holography and sound-field reconstruction to produce physically consistent fields from sparse measurements.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Physics-informed neural network','Data-driven NAH','Neural acoustic reconstruction','Helmholtz equation','Wave equation']::text[],ARRAY['Assuming the physics loss alone guarantees a correct fit to real data','Weighting the physics and data terms poorly, so one dominates','Applying a wrong or oversimplified equation for the setting']::text[],ARRAY['Reconstructing a source field with a wave-equation constraint','Training from few measurements using physics regularisation','Improving holography accuracy on unseen sources']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Physics-informed acoustic learning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb9deccb-ae0b-5fd0-9442-d30ecd2b10a1','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb9deccb-ae0b-5fd0-9442-d30ecd2b10a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb9deccb-ae0b-5fd0-9442-d30ecd2b10a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7864d6b-9268-5c0c-a535-dc4102920a7c','Complex-valued CNN acoustic reconstruction','Sound-field or source reconstruction performed with convolutional neural networks that operate on complex-valued acoustic data, representing pressure as magnitude and phase (real and imaginary parts) throughout the network. Keeping computations complex preserves the phase relationships essential to acoustic inverse problems, and such networks have been applied to near-field acoustic holography.','This method rebuilds sound fields with a special neural network. Sound data has both size and phase. The network keeps both as complex numbers. Phase carries where and when sound arrives. Holding on to it helps rebuild the field correctly.','Preserves acoustic phase inside the network, so reconstruction respects the complex pressure that ordinary real-valued models would distort.','Applied in near-field holography research to reconstruct complex pressure or source fields from measured hologram data.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Complex-valued neural network','Data-driven NAH','Near-field acoustic holography','Neural acoustic reconstruction','Phase']::text[],ARRAY['Discarding phase by feeding only magnitude to a real-valued network','Assuming complex layers behave exactly like real ones','Ignoring that phase wrapping complicates training']::text[],ARRAY['Reconstructing complex pressure over a source surface','Comparing complex and real networks for holography','Recovering phase-sensitive source maps from array data']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex-valued CNN acoustic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7864d6b-9268-5c0c-a535-dc4102920a7c','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7864d6b-9268-5c0c-a535-dc4102920a7c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7864d6b-9268-5c0c-a535-dc4102920a7c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08b6ba0a-ba75-59ef-9eb7-6437524ae955','Data-driven NAH','Near-field acoustic holography in which the inverse mapping from measured hologram pressures to the reconstructed source field is learned from data, typically with neural networks or other machine-learning models, rather than obtained solely by classical regularised inversion. Learned priors improve conditioning of the ill-posed inverse problem and can handle complex geometries and sparse measurements.','Data-driven NAH rebuilds a source''s sound field using learned models. Classic holography solves hard equations directly. Here a network learns the mapping from examples. This copes better with few sensors and odd shapes. It is machine learning applied to holography.','Replaces or aids fragile classical inversion with learned mappings, stabilising reconstruction and handling geometries that traditional methods struggle with.','Used in vibro-acoustic and noise research to reconstruct source vibration or radiation from array measurements over a surface.','Advanced Acoustic Imaging & Sound-Field Reconstruction',ARRAY['Near-field acoustic holography','Neural acoustic reconstruction','Physics-informed acoustic learning','Equivalent source method','Inverse problem']::text[],ARRAY['Assuming the learned model generalises to sources unlike the training set','Trusting reconstructions beyond the measured aperture','Ignoring that classical physics still bounds what data can recover']::text[],ARRAY['Reconstructing an engine cover''s surface velocity','Mapping radiation from a loudspeaker cabinet','Handling a curved source where classical NAH struggles']::text[],'advanced',NULL,NULL,'2193b2b3-b629-4127-a8b3-d71bf077ca3d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Data-driven NAH');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08b6ba0a-ba75-59ef-9eb7-6437524ae955','2193b2b3-b629-4127-a8b3-d71bf077ca3d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08b6ba0a-ba75-59ef-9eb7-6437524ae955') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08b6ba0a-ba75-59ef-9eb7-6437524ae955');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6cb78a6-a90f-52ce-98f9-9e060def6c02','Ultrasound imaging','Medical imaging modality that transmits short pulses of high-frequency sound, typically 1 to 20 MHz, into tissue and forms images from the amplitude and timing of echoes returned at acoustic-impedance boundaries. Depth is inferred from echo round-trip time using a nominal soft-tissue sound speed near 1540 m/s, and lateral information from the steered or scanned beam direction, producing real-time cross-sectional images.','Ultrasound imaging sends sound pulses into the body. The sound is far too high for people to hear. Tissue boundaries bounce echoes back to the probe. The machine times each echo to find its depth. It builds a live picture from the returning sound.','Lets clinicians see soft-tissue structure and motion in real time without ionising radiation, using reflected sound to map anatomy and blood flow.','Used for obstetric scans, abdominal and cardiac exams, vascular studies, and image-guided needle procedures on cart-based or handheld scanners.','Medical, Hearing & Clinical Acoustics',ARRAY['B-mode ultrasound','M-mode ultrasound','Acoustic impedance','Pulse-echo principle','Ultrasound transducer']::text[],ARRAY['Assuming the machine measures true depth directly rather than inferring it from a fixed assumed sound speed','Believing higher frequency is always better while ignoring its shallower penetration','Confusing image brightness with tissue density rather than with echo strength at a boundary']::text[],ARRAY['Performing a fetal growth scan in an obstetric clinic','Guiding a needle during an ultrasound-guided biopsy','Assessing gallstones during an abdominal examination']::text[],'beginner',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasound imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6cb78a6-a90f-52ce-98f9-9e060def6c02','f9e9fa38-e692-44c0-92da-653529165c7c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6cb78a6-a90f-52ce-98f9-9e060def6c02') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6cb78a6-a90f-52ce-98f9-9e060def6c02');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99163db9-f2c9-53ca-b42a-519da5926712','B-mode ultrasound','Two-dimensional grayscale ultrasound display in which each pixel brightness encodes the amplitude of the echo received from the corresponding location, with position set by beam direction and echo return time. Many scan lines swept across the field of view are assembled into a cross-sectional tomographic image, refreshed at frame rates high enough to show motion.','B-mode makes the standard grey ultrasound picture. Each dot''s brightness shows how strong its echo was. Strong reflectors look bright and weak ones look dark. Many scan lines are joined into one slice. The scanner repeats this to show live movement.','Provides the anatomical grayscale map most clinical ultrasound relies on, turning echo strength across a plane into a viewable cross-section.','Default mode for measuring organs, spotting cysts and masses, and giving the background image over which Doppler and measurements are placed.','Medical, Hearing & Clinical Acoustics',ARRAY['Ultrasound imaging','M-mode ultrasound','Acoustic impedance','Time gain compensation','Ultrasound transducer']::text[],ARRAY['Reading brightness as an absolute tissue property rather than relative echo amplitude affected by gain and TGC','Mistaking acoustic shadowing or enhancement artefacts for real anatomy','Assuming a dark region is always fluid without checking through-transmission']::text[],ARRAY['Measuring liver size on a grayscale abdominal image','Characterising a breast lump as cystic or solid','Setting overall gain and TGC for an even grayscale image']::text[],'beginner',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='B-mode ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99163db9-f2c9-53ca-b42a-519da5926712','f9e9fa38-e692-44c0-92da-653529165c7c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99163db9-f2c9-53ca-b42a-519da5926712') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99163db9-f2c9-53ca-b42a-519da5926712');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf928000-2f89-5373-9794-bfd4154c5ba3','M-mode ultrasound','Ultrasound display that repeatedly samples echoes along a single stationary scan line and plots their depth positions against time, giving a high-temporal-resolution trace of moving structures. The vertical axis represents depth along the line and the horizontal axis represents time, so rapidly moving reflectors draw characteristic motion curves.','M-mode looks along just one line into the body. It records that line over and over in time. Depth runs up the screen and time runs across it. Moving parts draw wavy lines on the trace. It captures fast motion very precisely.','Gives very high time resolution along one line so fast, repetitive motion, such as heart-wall or valve movement, can be timed and measured.','Used in echocardiography to measure chamber dimensions and valve timing, and in fetal cardiac scanning to document the heartbeat.','Medical, Hearing & Clinical Acoustics',ARRAY['B-mode ultrasound','Ultrasound imaging','Echocardiography','Temporal resolution','Scan line']::text[],ARRAY['Trying to read spatial anatomy from an M-mode trace, which shows only one line over time','Misaligning the cursor off the structure of interest, distorting measured dimensions','Confusing the time axis with a distance axis']::text[],ARRAY['Measuring left-ventricular wall thickness in an echo exam','Documenting fetal heart rate on a motion trace','Timing mitral-valve leaflet movement']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='M-mode ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf928000-2f89-5373-9794-bfd4154c5ba3','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf928000-2f89-5373-9794-bfd4154c5ba3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf928000-2f89-5373-9794-bfd4154c5ba3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f64e64b-5772-596d-8428-b13c2b24b014','Color Doppler','Ultrasound mode that estimates the mean Doppler frequency shift of echoes from moving scatterers, chiefly red blood cells, within a region of interest and overlays it as colour on the B-mode image. Colour hue and shade encode flow direction and mean velocity relative to the beam, computed by autocorrelation of the received phase across an ensemble of transmitted pulses.','Color Doppler shows moving blood as colour on the scan. It measures how flow shifts the echo''s pitch. One colour means flow toward the probe. Another means flow away from it. The colours sit on top of the grey image.','Reveals the presence, direction, and rough speed of blood flow, letting clinicians find vessels, flow disturbances, and abnormal shunts quickly.','Used to assess carotid and limb vessels, detect valve regurgitation, and confirm blood flow in organs and transplants.','Medical, Hearing & Clinical Acoustics',ARRAY['Power Doppler','Doppler ultrasound','Pulsed-wave Doppler','Aliasing','B-mode ultrasound']::text[],ARRAY['Interpreting colour as true speed while ignoring the strong dependence on beam-to-flow angle','Mistaking aliasing for flow reversal when the velocity scale is set too low','Assuming absence of colour proves no flow rather than checking gain and scale settings']::text[],ARRAY['Checking a carotid artery for turbulent flow','Detecting mitral regurgitation on an echocardiogram','Confirming perfusion in a transplanted kidney']::text[],'intermediate','f_D = 2·f_0·v·cosθ / c','The Doppler frequency shift equals twice the transmitted frequency times the scatterer speed and the cosine of the beam-to-flow angle, divided by the speed of sound.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Color Doppler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f64e64b-5772-596d-8428-b13c2b24b014','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f64e64b-5772-596d-8428-b13c2b24b014') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f64e64b-5772-596d-8428-b13c2b24b014');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6559a503-7b97-55a8-9df9-d620c1d02b04','Power Doppler','Doppler mode that maps the integrated power, or amplitude, of the Doppler signal rather than its mean frequency, so displayed colour reflects the quantity of moving scatterers present rather than their velocity or direction. It is largely angle-independent and free of aliasing, giving higher sensitivity to slow and low-volume flow at the cost of velocity and direction information.','Power Doppler shows how much blood is moving, not how fast. It adds up the strength of the flow signal. It does not show flow direction. It finds weak, slow flow very well. This makes small vessels easier to see.','Maximises sensitivity to slow or faint flow and small vessels, trading away direction and speed data for a stronger, angle-tolerant signal.','Used to show organ perfusion, inflammation in joints, and tiny tumour vessels where velocity mapping is too weak.','Medical, Hearing & Clinical Acoustics',ARRAY['Color Doppler','Doppler ultrasound','Microvascular imaging','B-mode ultrasound','Aliasing']::text[],ARRAY['Expecting Power Doppler to show flow direction or velocity, which it deliberately discards','Raising gain until noise fills the image and mimics flow','Treating strong colour as fast flow rather than as more moving scatterers']::text[],ARRAY['Grading synovial inflammation in a rheumatology scan','Showing perfusion in a suspected tumour','Detecting slow flow in a small testicular vessel']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Power Doppler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6559a503-7b97-55a8-9df9-d620c1d02b04','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6559a503-7b97-55a8-9df9-d620c1d02b04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6559a503-7b97-55a8-9df9-d620c1d02b04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ba91a97-0abb-535a-8307-224dc1b0c53d','Elastography','Family of ultrasound techniques that image the mechanical stiffness of tissue by measuring its response to an applied stress, either external compression in strain elastography or an internally generated shear wave in shear-wave elastography. Strain methods show relative deformation, while shear-wave methods estimate quantitative elastic moduli from the propagation speed of shear waves through the tissue.','Elastography maps how stiff or soft tissue is. It watches how tissue moves when pushed. Stiff tissue deforms less than soft tissue. Some methods track shear waves passing through. Their speed reveals the tissue''s stiffness.','Adds a stiffness dimension to imaging, because many diseases such as fibrosis and some tumours change tissue elasticity before other signs appear.','Used to stage liver fibrosis, characterise breast and thyroid nodules, and assess muscle and tendon stiffness.','Medical, Hearing & Clinical Acoustics',ARRAY['Acoustic radiation force impulse','Shear wave','Young''s modulus','Strain imaging','B-mode ultrasound']::text[],ARRAY['Comparing stiffness values across different systems as if scales and units were identical','UNSAFE: relying on radiation-force push pulses without regard to the tissue-heating output limits set by regulators and the applicable safety standard','Applying too much probe pressure in strain mode, which biases the measured stiffness']::text[],ARRAY['Estimating liver fibrosis stage non-invasively','Assessing whether a breast lesion is stiff and suspicious','Measuring Achilles tendon stiffness in sports medicine']::text[],'advanced','E = 3·ρ·c_s²','In shear-wave elastography, Young''s modulus equals three times the tissue density times the square of the shear-wave propagation speed, assuming a nearly incompressible elastic medium.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elastography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ba91a97-0abb-535a-8307-224dc1b0c53d','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ba91a97-0abb-535a-8307-224dc1b0c53d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ba91a97-0abb-535a-8307-224dc1b0c53d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '949af5ec-fd91-516e-bf69-b2f6685911a5','Acoustic radiation force impulse','Ultrasound technique that applies a short, high-intensity focused pushing pulse to displace tissue at the focus by acoustic radiation force, then tracks the resulting micron-scale displacement or the shear wave it launches to infer local stiffness. The radiation force arises from momentum transfer as the pushing beam is absorbed and scattered along its path.','This method uses a strong sound pulse to nudge tissue. The push comes from the sound''s own momentum. The machine watches how far the tissue moves. It also tracks waves that spread sideways. Softer tissue moves more than stiff tissue.','Generates a controlled internal force so stiffness can be probed at depth without an external squeeze, underpinning shear-wave elastography.','Used to measure liver and other organ stiffness and to produce point or two-dimensional shear-wave stiffness maps on clinical scanners.','Medical, Hearing & Clinical Acoustics',ARRAY['Elastography','Shear wave','Radiation force','Tissue displacement','Thermal index']::text[],ARRAY['Assuming the push pulse moves tissue by heating rather than by momentum transfer','UNSAFE: repeating high-intensity push pulses without observing the thermal- and mechanical-index output limits defined by the applicable safety standard','Reading a single stiffness value without checking measurement depth and reliability indicators']::text[],ARRAY['Quantifying liver stiffness at a set focal depth','Building a shear-wave stiffness map of a thyroid nodule','Assessing displacement to distinguish stiff from soft tissue']::text[],'advanced','F = 2·α·I / c','The acoustic radiation force per unit volume equals twice the absorption coefficient times the local time-averaged intensity, divided by the speed of sound.','f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic radiation force impulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '949af5ec-fd91-516e-bf69-b2f6685911a5','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='949af5ec-fd91-516e-bf69-b2f6685911a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='949af5ec-fd91-516e-bf69-b2f6685911a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b436d89-734b-5fa0-ad7f-4db0bdc507da','Photoacoustic tomography','Hybrid imaging method in which nanosecond pulses of light are absorbed by tissue chromophores, causing rapid thermoelastic expansion that launches broadband ultrasound waves detected by transducers around the sample and reconstructed into images of optical absorption. It combines optical-absorption contrast with the deeper penetration and resolution of ultrasound detection.','This method shines quick light pulses into tissue. Absorbing molecules heat and expand a tiny bit. That fast expansion makes ultrasound waves. Sensors catch these waves around the body. A computer rebuilds a picture of what absorbed the light.','Reveals optical-absorption contrast, such as haemoglobin and oxygenation, at depths and resolutions optical imaging alone cannot reach, by letting sound carry the signal out.','Used in research and emerging clinical systems to map blood vessels, oxygen saturation, and tumours in breast, skin, and small-animal studies.','Medical, Hearing & Clinical Acoustics',ARRAY['Thermoacoustic tomography','Optical absorption','Thermoelastic expansion','Ultrasound imaging','Image reconstruction']::text[],ARRAY['Confusing photoacoustic optical-absorption contrast with the acoustic-impedance contrast of ordinary ultrasound','UNSAFE: exposing tissue or eyes to pulsed-laser fluence above the maximum permissible exposure defined by the laser-safety standard','Assuming image depth is unlimited when optical fluence falls off steeply with depth']::text[],ARRAY['Mapping tumour blood vessels in a preclinical study','Imaging blood-oxygen saturation in superficial tissue','Combining photoacoustic and B-mode views on one system']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b436d89-734b-5fa0-ad7f-4db0bdc507da','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b436d89-734b-5fa0-ad7f-4db0bdc507da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b436d89-734b-5fa0-ad7f-4db0bdc507da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ebf165e-19d2-5f29-97fe-4a5b58257db4','Thermoacoustic tomography','Imaging method closely related to photoacoustics in which short pulses of microwave or radio-frequency energy, rather than light, are absorbed by tissue and produce thermoelastic pressure waves detected and reconstructed into images of the electromagnetic absorption distribution. Because microwave and RF energy penetrate deeper than light, it can probe absorption contrast at greater depth.','This method uses microwave or radio pulses instead of light. Tissue absorbs the energy and warms a tiny bit. The quick warming makes it expand and emit sound. Sensors record that sound around the body. A computer turns the signals into an image.','Maps how tissue absorbs microwave or RF energy, which tracks water and ion content, at depths beyond the reach of light-based photoacoustics.','Explored for breast imaging and functional studies where microwave absorption contrast between tissues is diagnostically useful.','Medical, Hearing & Clinical Acoustics',ARRAY['Photoacoustic tomography','Thermoelastic expansion','Microwave absorption','Image reconstruction','Ultrasound imaging']::text[],ARRAY['Treating it as identical to photoacoustics rather than driven by microwave or RF energy instead of light','UNSAFE: applying microwave or RF energy above the specific-absorption-rate limits defined by the relevant safety standard','Assuming the acoustic detection differs from photoacoustic systems when the readout is essentially the same']::text[],ARRAY['Researching microwave-contrast breast imaging','Comparing RF-driven and light-driven acoustic images','Detecting water-content differences at depth']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermoacoustic tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ebf165e-19d2-5f29-97fe-4a5b58257db4','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ebf165e-19d2-5f29-97fe-4a5b58257db4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ebf165e-19d2-5f29-97fe-4a5b58257db4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '625e6738-69cb-5afb-99dd-7b8fd18f8739','HIFU focal field','The concentrated acoustic field at the focus of a high-intensity focused ultrasound source, where converging energy produces intensities high enough to raise temperature rapidly and, above threshold, induce cavitation, enabling non-invasive thermal ablation of a small target volume while intervening tissue is comparatively spared. The focal region is typically a small cigar-shaped volume set by transducer geometry and frequency.','HIFU focuses strong ultrasound to a tiny spot. At that spot the sound becomes very intense. It can heat target tissue enough to destroy it. Tissue along the path is largely spared. Doctors use this to treat without cutting.','Delivers destructive acoustic energy to a defined internal target for therapy, concentrating power at the focus so surrounding tissue receives far less.','Used to ablate uterine fibroids, prostate tissue, and some tumours, and for MR- or ultrasound-guided therapy planning.','Medical, Hearing & Clinical Acoustics',ARRAY['Cavitation map','Passive acoustic mapping','Thermal ablation','Focused ultrasound','Acoustic intensity']::text[],ARRAY['Confusing therapeutic HIFU intensities with the far lower levels used for diagnostic imaging','UNSAFE: delivering focused-ultrasound therapy without dosimetry, targeting, and thermal monitoring, and without observing the exposure limits set by the treatment protocol and standards','Assuming only the focus is affected while ignoring pre-focal heating and beam-path safety']::text[],ARRAY['Planning non-invasive ablation of a uterine fibroid','Monitoring focal temperature during MR-guided HIFU','Targeting a small tumour volume for thermal therapy']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HIFU focal field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '625e6738-69cb-5afb-99dd-7b8fd18f8739','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='625e6738-69cb-5afb-99dd-7b8fd18f8739') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='625e6738-69cb-5afb-99dd-7b8fd18f8739');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6aacb5c3-fd85-5a33-8648-540c551b9303','Cavitation map','A spatial display of acoustic cavitation activity, generated by localising the broadband or harmonic acoustic emissions that oscillating or collapsing bubbles radiate under intense ultrasound. Such maps monitor where cavitation occurs during therapy, distinguishing stable, sustained-oscillation activity from inertial, violent-collapse activity by their emission signatures.','A cavitation map shows where bubbles form and collapse. Intense ultrasound can create tiny bubbles in tissue. These bubbles give off their own sound. Sensors locate that sound to build a map. It shows where cavitation is happening during treatment.','Lets clinicians and researchers see and control cavitation during therapy, since cavitation can either enhance treatment or dangerously extend tissue damage.','Used to monitor and guide cavitation-mediated therapies, confirming activity stays within the intended target region.','Medical, Hearing & Clinical Acoustics',ARRAY['Passive cavitation imaging','Passive acoustic mapping','HIFU focal field','Inertial cavitation','Mechanical index']::text[],ARRAY['Assuming all cavitation is identical rather than distinguishing stable from inertial activity','UNSAFE: driving ultrasound to induce cavitation without monitoring, since uncontrolled inertial cavitation can cause unintended tissue damage','Treating the mechanical index as a guaranteed cavitation threshold rather than an indicative safety indicator defined by standards']::text[],ARRAY['Monitoring bubble activity during focused-ultrasound therapy','Confirming cavitation stays inside the target volume','Distinguishing stable from collapse cavitation by their emissions']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6aacb5c3-fd85-5a33-8648-540c551b9303','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6aacb5c3-fd85-5a33-8648-540c551b9303') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6aacb5c3-fd85-5a33-8648-540c551b9303');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd90134a0-46fd-5d48-9f11-5864ceeb43d8','Passive cavitation imaging','A receive-only technique that forms images of cavitation activity by beamforming the acoustic emissions radiated by bubbles onto a spatial map, without transmitting imaging pulses of its own. Using an array to listen, it localises and characterises cavitation in space and time, often separating harmonic from broadband emissions to classify bubble behaviour.','This method only listens for cavitation sound. It sends no imaging pulses itself. Bubbles under intense ultrasound emit their own noise. An array captures that noise from many angles. The system maps where the cavitation came from.','Provides real-time spatial feedback on cavitation during therapy by passively listening, avoiding interference between imaging and therapy pulses.','Used in focused-ultrasound and drug-delivery research to confirm and locate cavitation and to gate or halt exposure.','Medical, Hearing & Clinical Acoustics',ARRAY['Passive acoustic mapping','Cavitation map','Ultrasound phased array','Inertial cavitation','HIFU focal field']::text[],ARRAY['Confusing passive cavitation imaging, which only receives, with active pulse-echo imaging','UNSAFE: using cavitation-based therapy without passive monitoring, allowing undetected inertial cavitation and off-target damage','Assuming perfect localisation despite the coarser resolution of passive receive-only beamforming']::text[],ARRAY['Localising cavitation during a drug-delivery experiment','Gating therapy exposure when broadband emissions appear','Mapping bubble activity without disturbing therapy pulses']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive cavitation imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd90134a0-46fd-5d48-9f11-5864ceeb43d8','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d90134a0-46fd-5d48-9f11-5864ceeb43d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d90134a0-46fd-5d48-9f11-5864ceeb43d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d791897-4d1f-5be2-ab6b-5b49e9b25d90','Passive acoustic mapping','A beamforming approach that reconstructs the spatial distribution of acoustic source activity, typically cavitation, purely from emissions received on an array, without active transmission. It is the algorithmic basis of passive cavitation imaging, using time-exposure or frequency-domain beamforming to map where and how strongly sources emit during an exposure window.','Passive acoustic mapping locates sound sources by listening only. It never sends out a pulse. It uses an array to catch emitted sound. Timing across the array points to each source. This builds a map of where sound is made.','Supplies the beamforming method that turns received emissions into a source-location map, enabling monitoring of cavitation and other emitters during therapy.','Used to guide and verify focused-ultrasound and cavitation therapies and in research on bubble dynamics in tissue-mimicking phantoms.','Medical, Hearing & Clinical Acoustics',ARRAY['Passive cavitation imaging','Cavitation map','Beamforming','Ultrasound phased array','Acoustic emission imaging']::text[],ARRAY['Treating passive acoustic mapping and active imaging as the same, though one only receives','UNSAFE: performing cavitation-enhanced therapy without acoustic monitoring, risking undetected inertial cavitation and tissue injury','Expecting spatial resolution equal to active imaging from a passive method']::text[],ARRAY['Mapping cavitation sources during focused-ultrasound therapy','Studying bubble activity in a tissue-mimicking phantom','Verifying emissions originate from the intended focal region']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive acoustic mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d791897-4d1f-5be2-ab6b-5b49e9b25d90','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d791897-4d1f-5be2-ab6b-5b49e9b25d90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d791897-4d1f-5be2-ab6b-5b49e9b25d90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30cfdc66-f94c-5a24-a5a7-30e572721cf2','Acoustic emission imaging','The localisation and imaging of transient elastic waves emitted by rapid internal energy release, such as crack growth, impacts, leaks, or bubble collapse, using an array or network of sensors together with arrival times or beamformed emissions to place each source in space. Unlike pulse-echo imaging it is passive, mapping sources that radiate sound on their own.','This method images things that make their own sound. Cracks, impacts, leaks, and bubbles all emit brief waves. Several sensors pick up each burst. The system compares arrival times or beamforms them. That locates and pictures where the sound began.','Turns spontaneous acoustic emissions into a spatial picture of active sources, so where damage or activity is occurring can be seen, not just detected.','Used to monitor cavitation in therapy and to locate cracks, leaks, and partial discharge in structural and industrial testing.','Medical, Hearing & Clinical Acoustics',ARRAY['Passive acoustic mapping','Acoustic emission source localization','Passive cavitation imaging','Beamforming','AE event']::text[],ARRAY['Confusing passive emission imaging with active pulse-echo imaging that transmits its own pulses','Assuming every detected burst is a real source rather than a reflection or electrical noise','Ignoring how uncertain wave speed degrades source-location accuracy']::text[],ARRAY['Imaging cavitation activity during therapy','Locating an active crack in a pressure vessel','Mapping a leak''s position from its emitted sound']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic emission imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30cfdc66-f94c-5a24-a5a7-30e572721cf2','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30cfdc66-f94c-5a24-a5a7-30e572721cf2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30cfdc66-f94c-5a24-a5a7-30e572721cf2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '991e0ab8-6a11-53bf-9984-93df9fd2de78','Ultrasound phased array','A transducer made of many small elements whose individual transmit and receive signals are time-delayed, or phased, to steer and focus the ultrasound beam electronically without moving the probe. By varying the delay pattern, the system sweeps and focuses the beam across the field, enabling real-time 2-D imaging and, in NDT, flexible inspection angles.','A phased array has many tiny sound elements. Each one fires with a small time delay. The delays steer and focus the beam. No part of the probe has to move. This lets the beam scan quickly and focus at will.','Enables electronic beam steering and focusing, giving fast, flexible imaging and inspection from a fixed, compact transducer.','Used in cardiac and general medical probes and in industrial phased-array ultrasonic testing of welds and components.','Medical, Hearing & Clinical Acoustics',ARRAY['Synthetic aperture ultrasound','Beamforming','Full-matrix capture','Beam steering','Ultrasound transducer']::text[],ARRAY['Assuming physical parts move, when steering is purely electronic time delays','Overlooking grating lobes that arise when element spacing is too large','Confusing electronic focusing with a fixed mechanical lens']::text[],ARRAY['Steering the beam in a cardiac sector scan','Inspecting a weld at several angles without moving the probe','Focusing at multiple depths on one image']::text[],'intermediate',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasound phased array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '991e0ab8-6a11-53bf-9984-93df9fd2de78','f9e9fa38-e692-44c0-92da-653529165c7c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='991e0ab8-6a11-53bf-9984-93df9fd2de78') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='991e0ab8-6a11-53bf-9984-93df9fd2de78');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af07174f-05e6-58a2-b878-6ed8d73ae578','Synthetic aperture ultrasound','An imaging approach that transmits from a limited aperture, often a single element or subaperture, records echoes on many receive elements, and coherently combines data from multiple transmit events to synthesise the focusing of a much larger aperture. This yields dynamic focus on both transmit and receive at every image point, improving resolution and uniformity at the cost of processing and, potentially, frame rate.','This method builds a big virtual probe from small ones. It fires from a small spot many times. Each shot is recorded on many elements. The data are then combined in the computer. This focuses sharply at every point in the image.','Achieves ideal focusing everywhere by combining many transmissions in software, rather than relying on a single fixed transmit focus.','Used in advanced medical research systems and in NDT reconstruction such as the total focusing method for uniform, high-resolution images.','Medical, Hearing & Clinical Acoustics',ARRAY['Full-matrix capture','Total focusing method','Ultrasound phased array','Beamforming','Image reconstruction']::text[],ARRAY['Expecting a single transmission to give the full synthetic-aperture image','Ignoring the heavy data and computation the coherent combination requires','Assuming motion during the many transmissions does not blur the result']::text[],ARRAY['Reconstructing a high-resolution research ultrasound image','Applying the total focusing method to weld inspection','Improving focus uniformity across the whole image depth']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synthetic aperture ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af07174f-05e6-58a2-b878-6ed8d73ae578','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af07174f-05e6-58a2-b878-6ed8d73ae578') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af07174f-05e6-58a2-b878-6ed8d73ae578');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '421d5352-6747-5c27-95ff-40418a123612','Full-matrix capture','An ultrasonic data-acquisition scheme in which each array element transmits in turn while all elements receive, capturing the complete set of transmit-receive element-pair signals for a given probe position. This full dataset contains all the information the array can gather and is the input for advanced reconstruction such as the total focusing method.','This records every element pair in the array. One element sends while all elements listen. This repeats until each element has sent. The result is a complete set of signals. Software can then focus this data anywhere.','Captures the maximally complete array dataset so images can be reconstructed with focusing at every point, rather than a single fixed focus.','Used in advanced phased-array NDT to feed total-focusing-method imaging of welds, forgings, and composites.','Medical, Hearing & Clinical Acoustics',ARRAY['Total focusing method','Ultrasound phased array','Synthetic aperture ultrasound','Time-of-flight diffraction','Array element']::text[],ARRAY['Confusing full-matrix capture, a data acquisition, with the total focusing method, a reconstruction','Underestimating the large data volume as element count grows','Assuming full-matrix capture alone gives an image without a focusing algorithm']::text[],ARRAY['Acquiring full array data on a weld for later imaging','Storing element-pair signals for offline reconstruction','Feeding captured data into a total-focusing image']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Full-matrix capture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '421d5352-6747-5c27-95ff-40418a123612','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='421d5352-6747-5c27-95ff-40418a123612') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='421d5352-6747-5c27-95ff-40418a123612');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88b8e31f-cde5-5296-96fe-414606610b6e','Total focusing method','A post-processing imaging algorithm that uses full-matrix-capture data to synthetically focus at every pixel of a defined region by summing, for each pixel, the contributions of all transmit-receive element pairs with the appropriate time delays. Because it focuses everywhere, it is often treated as a reference-quality reconstruction for resolution and defect characterisation in phased-array NDT.','This focuses the image at every single point. It uses the full set of element-pair signals. For each pixel it adds the right delayed signals. This gives sharp focus across the whole area. It is prized for finding and sizing small flaws.','Delivers focusing at every image point from recorded array data, maximising resolution and consistency for defect detection and sizing.','Used in advanced weld and component inspection to characterise cracks, porosity, and small defects with high resolution.','Medical, Hearing & Clinical Acoustics',ARRAY['Full-matrix capture','Synthetic aperture ultrasound','Ultrasound phased array','Beamforming','Defect sizing']::text[],ARRAY['Treating the method and full-matrix capture as interchangeable, when one is the reconstruction and the other the data','Assuming a wrong assumed wave speed will not distort the focused image','Expecting valid focusing outside the region actually reconstructed']::text[],ARRAY['Sizing a crack tip in a critical weld','Imaging porosity in a forged component','Reconstructing a high-resolution flaw image from captured data']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total focusing method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88b8e31f-cde5-5296-96fe-414606610b6e','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88b8e31f-cde5-5296-96fe-414606610b6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88b8e31f-cde5-5296-96fe-414606610b6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bebe7234-f576-5405-96f1-a6259bb5e800','Acoustic microscopy','The use of very high-frequency ultrasound, from tens of megahertz to several gigahertz, to image the microscopic surface and subsurface structure of materials at resolutions approaching those of optical microscopy. Contrast comes from local variations in acoustic impedance and elastic properties, allowing visualisation of features such as delaminations, voids, and grain structure not visible optically.','Acoustic microscopy images tiny features with sound. It uses very high ultrasound frequencies. Higher frequency gives finer detail. Contrast comes from how stiff and dense regions are. It can see flaws hidden below a surface.','Provides microscale, often subsurface, imaging based on elastic and impedance contrast, revealing internal defects optical microscopy cannot.','Used to inspect microelectronic packages, bonded interfaces, and materials for delaminations, cracks, and voids.','Medical, Hearing & Clinical Acoustics',ARRAY['Scanning acoustic microscope','Acoustic impedance','Ultrasound imaging','Delamination','High-frequency transducer']::text[],ARRAY['Assuming ever-higher frequency is free, when penetration falls sharply as frequency rises','Confusing acoustic-impedance contrast with the optical contrast of light microscopy','Expecting deep imaging from gigahertz probes that penetrate only microns']::text[],ARRAY['Inspecting a semiconductor package for delamination','Imaging a bonded interface for voids','Examining the subsurface microstructure of a material']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic microscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bebe7234-f576-5405-96f1-a6259bb5e800','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bebe7234-f576-5405-96f1-a6259bb5e800') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bebe7234-f576-5405-96f1-a6259bb5e800');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c5ce321-4479-5574-bb93-8ad8248b93ae','Scanning acoustic microscope','An instrument that forms an acoustic-microscopy image by mechanically raster-scanning a focused high-frequency ultrasound beam across a sample and recording the reflected or transmitted signal at each point. Focus is usually achieved with an acoustic lens coupled through a fluid, and depth-selective time gating lets specific internal layers, such as a bond line, be imaged.','This microscope moves a focused sound beam over a sample. It records the echo at each point. Point by point it builds an image. A fluid couples the sound into the part. Time gating lets it look at a chosen depth.','Implements acoustic microscopy in practice, scanning a focused beam to map internal and surface features at a selected depth.','Used widely in electronics failure analysis to find delaminations, cracks, and voids in chip packages and bonded assemblies.','Medical, Hearing & Clinical Acoustics',ARRAY['Acoustic microscopy','Acoustic lens','Acoustic impedance','Time gating','Delamination']::text[],ARRAY['Forgetting that a coupling fluid is needed to carry the high-frequency sound into the sample','Setting the depth gate wrong and imaging the wrong internal layer','Assuming surface roughness does not degrade the focused image']::text[],ARRAY['Finding delamination in a plastic-encapsulated chip','Gating to image a specific bond line in a package','Screening bonded parts for internal voids']::text[],'advanced',NULL,NULL,'f9e9fa38-e692-44c0-92da-653529165c7c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scanning acoustic microscope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c5ce321-4479-5574-bb93-8ad8248b93ae','f9e9fa38-e692-44c0-92da-653529165c7c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c5ce321-4479-5574-bb93-8ad8248b93ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c5ce321-4479-5574-bb93-8ad8248b93ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3d636bf-3e5b-5b43-95fd-a11b62057b47','Acoustic emission source localization','The process of computing the position of an acoustic-emission source within a structure from the differences in arrival time of its stress-wave burst at multiple sensors, combined with an assumed or measured wave velocity. For a known sensor geometry, arrival-time differences at three or more sensors define intersecting loci that fix the source location.','This finds where a sound burst started in a structure. Several sensors sit on the part. A crack or impact sends a wave to each one. The wave reaches nearer sensors first. Comparing these times pins down the source.','Converts arrival-time data from a sensor array into the physical location of active damage, so inspectors know where to look.','Used to locate growing cracks, leaks, and impacts in pressure vessels, pipelines, tanks, and bridges during acoustic-emission monitoring.','Ultrasonics, NDT & Industrial Inspection',ARRAY['AE hit','AE event','Acoustic emission imaging','Time difference of arrival','Wave velocity']::text[],ARRAY['Using a single fixed wave speed when velocity varies with material, mode, and geometry','Ignoring wave reflections and multiple modes that corrupt arrival-time picks','Assuming two sensors can locate a source that needs three or more']::text[],ARRAY['Locating an active crack on a pressure vessel','Pinpointing a leak position on a storage tank','Tracking impact-damage sources on a bridge']::text[],'advanced','Δd = c · Δt','The difference in source-to-sensor distance for a sensor pair equals the wave propagation speed times the difference in arrival times measured at the two sensors.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic emission source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3d636bf-3e5b-5b43-95fd-a11b62057b47','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3d636bf-3e5b-5b43-95fd-a11b62057b47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3d636bf-3e5b-5b43-95fd-a11b62057b47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1456f60-0e08-5930-984f-f30241455d75','AE hit','In acoustic-emission testing, a hit is a single detected acoustic-emission signal at one sensor that crosses the detection threshold, from which parameters such as amplitude, duration, rise time, and counts are measured. A hit is the basic unit of AE data at an individual channel, before hits from multiple channels are grouped into events.','A hit is one detected acoustic-emission signal. It happens when a sensor''s signal passes a set level. The system then measures that burst. It records size, length, and other features. Hits are the basic pieces of AE data.','Defines the elementary detected unit of acoustic emission, giving the countable, measurable signal from which all higher-level AE analysis is built.','Used to count activity and extract signal features during structural monitoring and pressure-vessel testing.','Ultrasonics, NDT & Industrial Inspection',ARRAY['AE event','AE amplitude map','Acoustic emission source localization','Threshold','AE count']::text[],ARRAY['Confusing a hit at one sensor with an event, which groups hits from several sensors','Setting the threshold so low that background noise is logged as hits','Comparing hit counts without noting the threshold and sensor settings used']::text[],ARRAY['Counting hits during a pressure-vessel test','Extracting amplitude and duration from each hit','Setting a threshold to reject background noise']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE hit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1456f60-0e08-5930-984f-f30241455d75','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1456f60-0e08-5930-984f-f30241455d75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1456f60-0e08-5930-984f-f30241455d75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7d9e8a5-f7af-59bd-b025-438515103aaa','AE event','A grouping of acoustic-emission hits, recorded on one or more sensors within a short time window, that are attributed to a single physical source occurrence such as one crack-growth increment. Where several sensors detect the same emission, their hits are combined into one event, which can then be located and classified.','An event is one real source occurrence. It gathers the hits that came from it. Several sensors may catch the same burst. Those hits are grouped into a single event. This event can then be located and studied.','Consolidates related hits into one physical occurrence so activity is counted by source rather than by every sensor trigger.','Used to tally genuine source activity, drive source location, and track damage progression in monitored structures.','Ultrasonics, NDT & Industrial Inspection',ARRAY['AE hit','Acoustic emission source localization','AE event density map','AE amplitude map','Crack growth']::text[],ARRAY['Treating each sensor hit as a separate event and overcounting activity','Using too wide a grouping window and merging unrelated sources','Assuming every event equals real damage rather than a benign source']::text[],ARRAY['Grouping multi-sensor hits into located events','Counting events to gauge crack activity','Separating true events from noise during a test']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7d9e8a5-f7af-59bd-b025-438515103aaa','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7d9e8a5-f7af-59bd-b025-438515103aaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7d9e8a5-f7af-59bd-b025-438515103aaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8b78f3d-0262-5512-9654-dab0505e9924','AE amplitude map','A spatial visualisation in which located acoustic-emission sources or events are plotted and coloured or sized by their signal amplitude, showing where the strongest emissions arise across a structure. It combines source location with amplitude data to highlight regions of high-energy activity that may indicate significant damage.','This map shows where strong AE signals come from. Each located source is placed on the structure. Its colour or size shows its amplitude. Big, bright spots mark strong emissions. These often point to the most active damage.','Reveals where the most energetic acoustic emissions occur, helping inspectors focus on the most likely damage sites.','Used to prioritise inspection of high-amplitude regions on vessels, tanks, and pipework after AE monitoring.','Ultrasonics, NDT & Industrial Inspection',ARRAY['AE event density map','Acoustic emission source localization','AE hit','AE event','Amplitude']::text[],ARRAY['Assuming high amplitude always means severe damage, ignoring source type and distance','Forgetting that attenuation lowers amplitude from distant sources','Reading the map without checking sensor coverage across the structure']::text[],ARRAY['Highlighting high-energy zones on a pressure vessel','Prioritising follow-up inspection of strong-emission areas','Comparing amplitude patterns across load steps']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE amplitude map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8b78f3d-0262-5512-9654-dab0505e9924','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8b78f3d-0262-5512-9654-dab0505e9924') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8b78f3d-0262-5512-9654-dab0505e9924');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d0f88f4-9bf1-5b9d-99f1-480cc2e2d259','AE event density map','A visualisation that maps the concentration of located acoustic-emission events per unit area or volume across a structure, revealing clusters where activity is most frequent. Unlike an amplitude map, it emphasises how often sources occur in each region rather than how strong each one is.','This map shows where AE events happen most often. It counts located events in each area. Crowded areas are shaded to stand out. Clusters reveal the busiest damage zones. It focuses on how often, not how strong.','Exposes spatial clusters of frequent activity so inspectors can identify concentrated or growing damage regions.','Used to spot active crack colonies or corrosion zones on tanks, vessels, and pipelines during monitoring.','Ultrasonics, NDT & Industrial Inspection',ARRAY['AE amplitude map','Acoustic emission source localization','AE event','AE hit','Damage clustering']::text[],ARRAY['Confusing event density, how often, with amplitude, how strong','Reading dense clusters as severe without checking event amplitudes and types','Ignoring uneven sensor coverage that biases the apparent density']::text[],ARRAY['Finding a crack colony on a storage tank','Mapping active corrosion zones on a vessel','Watching a cluster grow over successive tests']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE event density map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d0f88f4-9bf1-5b9d-99f1-480cc2e2d259','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d0f88f4-9bf1-5b9d-99f1-480cc2e2d259') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d0f88f4-9bf1-5b9d-99f1-480cc2e2d259');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1348136f-05c8-5332-b77a-4fe7e984d5e1','Leak localization','The acoustic detection and location of leaks in compressed-air, gas, or vacuum systems by sensing the high-frequency, often ultrasonic, turbulent noise a leak generates and tracing it to its source with a directional sensor or sensor array. Ultrasonic methods work because gas escaping through a small orifice produces broadband high-frequency sound that falls off sharply with distance, aiding localisation.','This finds and locates leaks by their sound. Escaping gas hisses, much of it too high to hear. A directional sensor points toward the source. The signal grows stronger as you near the leak. This pinpoints where gas is escaping.','Locates energy-wasting and hazardous leaks quickly by their acoustic signature, without shutting systems down or probing everywhere by hand.','Used in plant maintenance to find compressed-air, gas, and vacuum leaks, and to check seals on doors, windows, and enclosures.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Ultrasonic leak imaging','Airborne ultrasound','Acoustic camera','Compressed-air system','Leak rate']::text[],ARRAY['Assuming a louder leak is always the largest, when frequency content and distance also matter','UNSAFE: approaching a high-pressure gas or steam leak directly, since escaping jets and toxic or flammable gas are hazardous','Mistaking background machinery ultrasound for the leak source']::text[],ARRAY['Surveying a plant for compressed-air leaks','Locating a vacuum-system leak on a process line','Checking a cleanroom door seal for leakage']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leak localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1348136f-05c8-5332-b77a-4fe7e984d5e1','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1348136f-05c8-5332-b77a-4fe7e984d5e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1348136f-05c8-5332-b77a-4fe7e984d5e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3b9339a-3b4e-5a7b-89cf-0bfc4e6b9d3e','Ultrasonic leak imaging','The use of an acoustic-camera array to detect the high-frequency airborne noise of a gas or pressure leak and overlay its localised position as a heat-map on a visual image of the scene. Beamforming across the microphone array turns the leak''s ultrasonic emission into a coloured overlay that pinpoints the source on a photograph of the equipment.','This method makes a picture of a leak''s sound. A microphone array listens for high-frequency hiss. Beamforming finds the direction it comes from. The result is coloured onto a camera photo. The bright spot marks the leak''s location.','Turns invisible leak noise into an on-screen image, letting technicians spot and document leaks quickly from a distance.','Used with handheld acoustic cameras to survey compressed-air lines, valves, and fittings and to record leak locations for repair.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Leak localization','Acoustic camera','Beamforming','Airborne ultrasound','Acoustic troubleshooting map']::text[],ARRAY['Trusting the overlay position without allowing for reflections off nearby surfaces','Assuming the brightest spot is the only leak while quieter ones go unimaged','UNSAFE: relying on imaging alone near pressurised or toxic-gas systems instead of following safe-approach procedures']::text[],ARRAY['Imaging a compressed-air leak at a pipe fitting','Documenting leak locations during an energy audit','Scanning a valve bank for escaping gas']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic leak imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3b9339a-3b4e-5a7b-89cf-0bfc4e6b9d3e','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3b9339a-3b4e-5a7b-89cf-0bfc4e6b9d3e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3b9339a-3b4e-5a7b-89cf-0bfc4e6b9d3e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eed69904-f6d0-5e49-b979-7e5c01ec631e','Partial discharge acoustic imaging','The localisation of partial-discharge activity, small electrical breakdowns within or across insulation in high-voltage equipment, by detecting the acoustic and ultrasonic pulses each discharge radiates and mapping them onto the equipment with a directional sensor or array. Acoustic methods complement electrical partial-discharge detection by pinpointing the physical discharge site.','Partial discharge is a tiny spark inside insulation. Each spark makes a short sound pulse. Sensors catch these high-frequency pulses. Beamforming or scanning locates them. This shows where insulation is breaking down.','Locates insulation defects in energised high-voltage gear by their acoustic emissions, so faults are found before they cause failure.','Used on switchgear, transformers, cables, and insulators to find partial discharge during condition monitoring.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Corona discharge acoustic imaging','Airborne ultrasound','Acoustic camera','Partial discharge','Acoustic emission source localization']::text[],ARRAY['Assuming acoustic location alone confirms severity without an electrical measurement','Missing discharges shielded inside metal enclosures that block the sound path','UNSAFE: working close to energised high-voltage equipment without the required electrical-safety clearances and procedures']::text[],ARRAY['Locating partial discharge in air-insulated switchgear','Finding an insulation defect at a cable termination','Confirming a discharge site during condition monitoring']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Partial discharge acoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eed69904-f6d0-5e49-b979-7e5c01ec631e','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eed69904-f6d0-5e49-b979-7e5c01ec631e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eed69904-f6d0-5e49-b979-7e5c01ec631e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ed8c611-7517-5ffa-8802-b004b492a04e','Corona discharge acoustic imaging','The detection and localisation of corona, the ionisation of air around high-voltage conductors, by imaging the ultrasonic noise it emits, typically with an acoustic camera whose array beamforms the corona''s high-frequency emission onto a picture of the equipment. Corona radiates strong airborne ultrasound, making it well suited to array-based acoustic imaging from a safe distance.','Corona is air breaking down around high-voltage lines. It gives off a steady high-frequency hiss. An acoustic camera locates that sound. The result is coloured onto a photo. This shows corona sites from a safe distance.','Reveals corona activity, which wastes energy and damages insulation, by its ultrasonic signature so it can be found and corrected.','Used on power lines, insulators, and substations to spot corona and surface tracking from ground level.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Partial discharge acoustic imaging','Acoustic camera','Airborne ultrasound','Corona discharge','Beamforming']::text[],ARRAY['Confusing corona with internal partial discharge, though both may occur together','Assuming no corona is present when weather and voltage strongly affect its intensity','UNSAFE: approaching energised high-voltage lines or apparatus instead of imaging from a safe stand-off distance']::text[],ARRAY['Scanning transmission-line insulators for corona','Finding surface tracking on a substation bushing','Surveying overhead lines from ground level']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Corona discharge acoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ed8c611-7517-5ffa-8802-b004b492a04e','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ed8c611-7517-5ffa-8802-b004b492a04e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ed8c611-7517-5ffa-8802-b004b492a04e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ca14fb6-df3f-51bf-934a-4e8ab9e03001','Bearing-fault acoustic imaging','The localisation and imaging of noise radiated by defective rolling-element or journal bearings, using acoustic arrays or ultrasonic sensors to detect the characteristic high-frequency impacts and friction a fault produces and to place the source on the machine. Early bearing faults emit repetitive high-frequency bursts whose location and rate help identify the affected bearing and defect type.','Failing bearings make telltale high-frequency noise. Tiny defects strike as parts roll over them. Sensors or arrays catch these bursts. Locating the sound points to the bad bearing. This warns of failure early.','Detects and locates bearing defects early from their acoustic signature, supporting condition-based maintenance before breakdown.','Used in predictive maintenance to survey motors, pumps, and gearboxes and to isolate which bearing is failing.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Gear-mesh noise map','NVH source visualization','Acoustic camera','Envelope analysis','Condition monitoring']::text[],ARRAY['Confusing bearing-fault frequencies with gear-mesh or electrical noise on the same machine','Relying on overall level instead of the repetitive high-frequency signature','UNSAFE: reaching near rotating shafts and couplings to place sensors without proper machine guarding and lockout']::text[],ARRAY['Isolating a failing motor bearing in a pump set','Screening a gearbox for early bearing damage','Prioritising a bearing replacement from acoustic evidence']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bearing-fault acoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ca14fb6-df3f-51bf-934a-4e8ab9e03001','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ca14fb6-df3f-51bf-934a-4e8ab9e03001') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ca14fb6-df3f-51bf-934a-4e8ab9e03001');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72619a02-0a34-511c-8b8d-fa2b10c9d5df','Gear-mesh noise map','A visualisation of the acoustic radiation associated with gear meshing, mapping where and at what frequencies a gearbox radiates the tones produced as gear teeth engage. Gear-mesh noise appears at the tooth-engagement, or mesh, frequency and its harmonics and sidebands, and the map localises the radiating regions on the housing.','Meshing gear teeth make a whining noise. It occurs at the tooth-meshing rate and its multiples. A map shows where the housing radiates this sound. It also shows which frequencies dominate. This guides noise and fault diagnosis.','Shows where and at what frequencies gear noise radiates, helping engineers diagnose gear condition and reduce whine.','Used in gearbox NVH work to trace whine, check tooth condition, and target damping or design fixes.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Bearing-fault acoustic imaging','NVH source visualization','Mesh frequency','Acoustic camera','Sideband']::text[],ARRAY['Confusing gear-mesh tones and their sidebands with unrelated bearing frequencies','Assuming the loudest housing area is the source rather than a radiating panel','Ignoring sidebands that reveal modulation from a faulty tooth']::text[],ARRAY['Tracing gear whine on a transmission housing','Linking sidebands to a damaged gear tooth','Targeting damping treatment on a noisy gearbox']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gear-mesh noise map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72619a02-0a34-511c-8b8d-fa2b10c9d5df','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72619a02-0a34-511c-8b8d-fa2b10c9d5df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72619a02-0a34-511c-8b8d-fa2b10c9d5df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd071c7b-87ff-5bdc-bf59-71bc755691d5','Tire-noise acoustic holography','The application of near-field acoustic holography to tyre noise, in which sound pressure is measured on a surface close to the rolling tyre and back-propagated to reconstruct the sound field and radiating sources on the tyre and contact patch. It reveals how tread pattern, air pumping, and structural vibration contribute to radiated tyre noise.','This maps the noise a rolling tyre makes. Microphones sit just off the tyre surface. Their data are computed back to the tyre. This shows which parts radiate sound. It links tread and contact effects to the noise.','Localises and quantifies tyre noise sources so designers can cut rolling noise from the tread and structure.','Used in automotive and tyre NVH labs to study pass-by and rolling noise and to guide quieter tread designs.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Near-field acoustic holography','NVH source visualization','Pass-by acoustic camera measurement','Engine-noise source map','Sound field reconstruction']::text[],ARRAY['Placing the measurement surface too far away, which blurs the near-field reconstruction','Assuming tread pattern is the only source and ignoring air pumping and structural modes','Neglecting ground reflections that distort the reconstructed field']::text[],ARRAY['Mapping radiating zones on a rolling tyre','Comparing tread designs for rolling noise','Studying contact-patch air-pumping noise']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tire-noise acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd071c7b-87ff-5bdc-bf59-71bc755691d5','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd071c7b-87ff-5bdc-bf59-71bc755691d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd071c7b-87ff-5bdc-bf59-71bc755691d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8afa7c3-8956-58e6-9ad8-50f7e20e6b9a','Engine-noise source map','An acoustic image that localises the dominant noise-radiating regions of a running engine, produced with a microphone array and beamforming or holography to show which components and surfaces radiate most at given frequencies. It separates contributions from combustion, valvetrain, intake, exhaust, and structural panels.','This map shows where an engine''s noise comes from. A microphone array listens to the running engine. Processing points to the loudest parts. Different colours mark different frequencies. Engineers see which components to quiet.','Pinpoints the main engine noise sources by location and frequency, directing noise-reduction effort to the parts that matter.','Used in powertrain NVH development to rank noise sources and validate covers, mounts, and design changes.','Ultrasonics, NDT & Industrial Inspection',ARRAY['NVH source visualization','Acoustic camera','Beamforming','Near-field acoustic holography','Gear-mesh noise map']::text[],ARRAY['Reading a beamforming map at low frequency, where resolution is too coarse to separate sources','Assuming the brightest spot radiates most power without weighting by area','Ignoring reflections in the test cell that create false sources']::text[],ARRAY['Ranking noise sources on a running engine','Validating an acoustic cover''s benefit','Separating intake from structural engine noise']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Engine-noise source map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8afa7c3-8956-58e6-9ad8-50f7e20e6b9a','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8afa7c3-8956-58e6-9ad8-50f7e20e6b9a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8afa7c3-8956-58e6-9ad8-50f7e20e6b9a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cbc3483e-a56c-501d-b1a3-b27c4e3ec75c','Aeroacoustic source map','An acoustic image that localises noise sources arising from unsteady fluid flow, such as turbulence, jets, fans, airfoils, and propellers, typically using a microphone array and beamforming to place flow-noise sources in space and frequency. It is central to identifying where and how aerodynamic noise is generated.','This map shows where flowing air makes noise. Turbulence, jets, and blades all create sound. A microphone array captures it. Processing locates each source. Engineers use this to make machines quieter.','Identifies where aerodynamic flow generates noise, guiding quieter design of fans, blades, and vehicles.','Used in wind tunnels and field tests to study fan, propeller, airfoil, and vehicle flow noise.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Wind-tunnel acoustic imaging','Beamforming','Flyover noise imaging','Acoustic camera','Aeroacoustics']::text[],ARRAY['Assuming flow noise comes from a fixed point when sources are often distributed and moving','Using low frequencies where array resolution cannot separate sources','Ignoring flow over the array itself, which adds self-noise']::text[],ARRAY['Locating fan-blade noise in a duct','Studying airfoil trailing-edge noise','Mapping propeller sources in flight tests']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aeroacoustic source map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cbc3483e-a56c-501d-b1a3-b27c4e3ec75c','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cbc3483e-a56c-501d-b1a3-b27c4e3ec75c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cbc3483e-a56c-501d-b1a3-b27c4e3ec75c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a7304ec-7360-56a7-b99c-f775f5fc96ac','Wind-tunnel acoustic imaging','The use of microphone-array beamforming inside an aerodynamic test facility to localise and quantify noise sources on models such as wings, landing gear, and vehicles under controlled flow. It requires an acoustically treated open-jet or lined tunnel and processing that accounts for flow-induced convection and array self-noise.','This images noise sources inside a wind tunnel. A model sits in controlled airflow. A microphone array listens through the flow. Beamforming maps where noise is made. Special tunnels reduce background noise.','Lets engineers find and rank aerodynamic noise sources on models under realistic flow before building full prototypes.','Used in aerospace and automotive aeroacoustics to test wings, landing gear, mirrors, and full vehicles.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Aeroacoustic source map','Beamforming','Flyover noise imaging','Acoustic camera','Anechoic wind tunnel']::text[],ARRAY['Ignoring flow convection and refraction that shift apparent source positions','Testing in a hard-walled tunnel whose reflections swamp the sources','Assuming model-scale results transfer to full scale without correction']::text[],ARRAY['Mapping landing-gear noise on a scale model','Ranking mirror and A-pillar noise on a car','Testing a wing section for trailing-edge noise']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-tunnel acoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a7304ec-7360-56a7-b99c-f775f5fc96ac','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a7304ec-7360-56a7-b99c-f775f5fc96ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a7304ec-7360-56a7-b99c-f775f5fc96ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e69b1b9-b23d-5db1-99a0-e358bf92178c','Flyover noise imaging','The localisation of noise sources on an aircraft during an actual flyover, using a ground-based microphone array and moving-source beamforming that tracks the aircraft and removes the Doppler shift to place sources on the airframe and engines. It reveals real in-flight source contributions for certification support and noise reduction.','This maps where a passing aircraft''s noise comes from. A ground array records it flying over. Processing follows the moving aircraft. It corrects for the Doppler shift. The result shows engine and airframe sources.','Identifies real in-flight noise sources on aircraft for certification support and community-noise reduction.','Used in aircraft noise campaigns to separate engine, high-lift, and gear noise during approach and departure.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Pass-by acoustic camera measurement','Aeroacoustic source map','Wind-tunnel acoustic imaging','Beamforming','Doppler shift']::text[],ARRAY['Neglecting Doppler correction, which smears moving-source locations','Assuming a static array analysis suffices for a fast-moving source','Ignoring atmospheric refraction and ground reflection over the long path']::text[],ARRAY['Separating engine and airframe noise on approach','Supporting an aircraft noise-certification test','Mapping high-lift-device noise during a flyover']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flyover noise imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e69b1b9-b23d-5db1-99a0-e358bf92178c','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e69b1b9-b23d-5db1-99a0-e358bf92178c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e69b1b9-b23d-5db1-99a0-e358bf92178c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb33c3a0-3297-58c1-8bcd-08bd98bcc214','Pass-by acoustic camera measurement','The use of a stationary microphone array to localise noise sources on a moving vehicle as it passes, applying moving-source beamforming with Doppler compensation to image source contributions during the pass-by. It links measured pass-by noise levels to the specific sources responsible.','This images noise from a vehicle driving past. A fixed microphone array records the pass. Processing follows the moving vehicle. It corrects for the Doppler shift. The map shows which parts are loudest.','Connects standardised pass-by noise levels to their actual sources, so engineers know what to quiet.','Used in vehicle noise testing to break pass-by noise into tyre, engine, exhaust, and body contributions.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Flyover noise imaging','Tire-noise acoustic holography','NVH source visualization','Beamforming','Doppler shift']::text[],ARRAY['Skipping Doppler and motion compensation, which blurs the moving source','Assuming one microphone can localise sources that need an array','Ignoring reflections from the test-track surface']::text[],ARRAY['Breaking down a car''s pass-by noise by source','Comparing tyre versus exhaust contribution at speed','Supporting a regulatory pass-by noise test']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pass-by acoustic camera measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb33c3a0-3297-58c1-8bcd-08bd98bcc214','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb33c3a0-3297-58c1-8bcd-08bd98bcc214') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb33c3a0-3297-58c1-8bcd-08bd98bcc214');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a762945e-657d-5c1f-9ec0-34ff81eb666d','Brake-squeal source map','An acoustic image that localises the source of brake squeal, the high-frequency noise produced by friction-induced, often self-excited, vibration of brake components, using an array to place the radiating region on the brake assembly. It helps link squeal to specific pads, rotors, or caliper modes.','Brake squeal is a loud high-pitched noise. It comes from vibration as pads grip the rotor. An array locates where the sound radiates. This points to the pad, rotor, or caliper. Engineers use it to stop the squeal.','Localises the parts radiating brake squeal so damping, materials, or geometry changes can target the real source.','Used in brake NVH testing on dynamometers and vehicles to diagnose and cure squeal complaints.','Ultrasonics, NDT & Industrial Inspection',ARRAY['NVH source visualization','Buzz-squeak-rattle','Acoustic camera','Self-excited vibration','Rattle-source localization']::text[],ARRAY['Treating squeal as random when it is usually a self-excited resonance','Assuming only the pad is at fault while rotor and caliper modes contribute','Chasing squeal by ear without localising the true radiating component']::text[],ARRAY['Locating the source of a brake-squeal complaint','Testing pad materials for squeal on a dynamometer','Linking squeal to a caliper resonance']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brake-squeal source map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a762945e-657d-5c1f-9ec0-34ff81eb666d','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a762945e-657d-5c1f-9ec0-34ff81eb666d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a762945e-657d-5c1f-9ec0-34ff81eb666d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ede2066-88ea-5900-b7b3-a97b5220c1bd','Rattle-source localization','The identification of the location of rattle, an intermittent impact noise from loose or clearance-driven contact between components, using microphone arrays or probes to trace the noise to the offending joint or part under vibration or excitation. Rattles are transient and load-dependent, so localisation often uses controlled excitation on a shaker or road input.','A rattle is a loose part knocking as things vibrate. It comes and goes with motion. Arrays or probes trace the sound. This finds the loose joint or clip. Then it can be tightened or damped.','Finds the exact loose or clearance-driven source of a rattle so it can be fixed, rather than guessed at.','Used in vehicle and appliance NVH to hunt down squeak-and-rattle complaints on shakers and test drives.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Buzz-squeak-rattle','NVH source visualization','Brake-squeal source map','Acoustic camera','Squeak-and-rattle testing']::text[],ARRAY['Searching for a rattle at steady state when it appears only under specific excitation','Assuming the loudest spot is the source rather than a nearby radiating panel','Fixing one rattle while missing others excited at different frequencies']::text[],ARRAY['Tracing a dashboard rattle on a shaker table','Finding a loose trim clip during a road test','Locating an appliance rattle at a specific speed']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rattle-source localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ede2066-88ea-5900-b7b3-a97b5220c1bd','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ede2066-88ea-5900-b7b3-a97b5220c1bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ede2066-88ea-5900-b7b3-a97b5220c1bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e9eba11-b195-5a47-8f43-8eab98f298d1','Buzz-squeak-rattle','The category of transient, annoyance-driven noises in vehicles and products, buzzes, squeaks, and rattles, that arise from friction and impact at interfaces, and the associated source-localisation testing used to find and eliminate them. This work combines subjective evaluation with array or probe localisation under representative excitation.','This stands for buzz, squeak, and rattle. These are small annoying noises in cars and products. Buzzes and squeaks come from rubbing parts. Rattles come from loose parts knocking. Engineers locate and remove them.','Names and structures the effort to find and eliminate friction- and impact-driven annoyance noises that hurt perceived quality.','Used across automotive interior and product development to test, locate, and design out squeak-and-rattle issues.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Rattle-source localization','NVH source visualization','Brake-squeal source map','Squeak-and-rattle testing','Acoustic camera']::text[],ARRAY['Treating it as one noise instead of distinct friction and impact mechanisms','Evaluating it only by ear without locating the source','Testing without representative excitation, so intermittent noises never appear']::text[],ARRAY['Screening a car interior for squeaks and rattles','Locating a buzz at a specific engine order','Designing out a recurring trim rattle']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buzz-squeak-rattle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e9eba11-b195-5a47-8f43-8eab98f298d1','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e9eba11-b195-5a47-8f43-8eab98f298d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e9eba11-b195-5a47-8f43-8eab98f298d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d5e0eeb-5bd8-5e48-8d6a-4e5cc000947b','NVH source visualization','The general practice of imaging noise, vibration, and harshness sources on a machine or vehicle by combining acoustic-array or vibration measurements with beamforming, holography, or transfer-path methods to show where and how disturbances are generated and radiated. It underpins the diagnosis and reduction of unwanted sound and vibration across products.','This covers noise, vibration, and harshness. The practice shows where these come from. Arrays and sensors capture sound and vibration. Processing maps the sources onto the product. Engineers then target the worst ones.','Provides the overarching toolset for locating and ranking noise and vibration sources so refinement effort is spent where it counts.','Used throughout automotive, appliance, and machinery development to diagnose and reduce NVH complaints.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Acoustic troubleshooting map','Beamforming','Near-field acoustic holography','Buzz-squeak-rattle','Transfer path analysis']::text[],ARRAY['Assuming one method fits all frequencies, when beamforming and holography suit different ranges','Locating a source without ranking its contribution at the receiver','Confusing where sound radiates with where it is actually generated']::text[],ARRAY['Ranking cabin noise sources in a vehicle','Diagnosing an appliance vibration complaint','Guiding refinement of a noisy machine']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='NVH source visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d5e0eeb-5bd8-5e48-8d6a-4e5cc000947b','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d5e0eeb-5bd8-5e48-8d6a-4e5cc000947b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d5e0eeb-5bd8-5e48-8d6a-4e5cc000947b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d3795d3-6a5b-59e0-80ec-198720981c90','Acoustic troubleshooting map','A practical acoustic image, usually from a handheld acoustic camera, that overlays localised sound sources onto a photo of equipment so a technician can see at a glance where unwanted noise, leaks, or faults originate. It is an applied, field-oriented use of array beamforming for maintenance and diagnostics rather than laboratory analysis.','This is a picture that shows where noise comes from. A handheld camera listens and looks at once. It colours the loud spots onto the photo. A technician sees the problem instantly. It speeds up field diagnosis.','Gives maintenance staff an immediate visual of where sound, leaks, or faults arise, speeding practical troubleshooting.','Used in the field to find leaks, electrical discharge, and noisy components quickly with a portable acoustic camera.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Acoustic camera','Leak localization','NVH source visualization','Ultrasonic leak imaging','Beamforming']::text[],ARRAY['Trusting the coloured overlay without allowing for reflections and secondary sources','Assuming the map gives absolute levels rather than relative source strength','Using too low a frequency band, which blurs the source location']::text[],ARRAY['Finding a noisy component on a production line','Locating a compressed-air leak during a plant walk','Spotting electrical discharge on outdoor equipment']::text[],'beginner',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic troubleshooting map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d3795d3-6a5b-59e0-80ec-198720981c90','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d3795d3-6a5b-59e0-80ec-198720981c90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d3795d3-6a5b-59e0-80ec-198720981c90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36a63710-3049-5d56-a88b-3f9d2d524d73','Seismoacoustics','The combined study of elastic waves in solid Earth (seismic waves) and acoustic waves in the atmosphere and oceans (infrasound and hydroacoustic waves), together with the coupling between these media at ground, air, and water interfaces. Seismoacoustics treats a natural or man-made source, such as an eruption, landslide, meteor, or explosion, as radiating energy into more than one medium at once, and uses co-recorded ground motion and pressure signals to detect, locate, and characterise that source.','Seismoacoustics is the joint study of ground shaking and sound. It links waves in rock, air, and water. One event can make all three at once. Scientists record them together to learn about the source. This helps find and identify quakes, eruptions, and blasts.','It exploits the fact that many Earth processes radiate into the ground, the air, and the sea simultaneously, so that comparing the different wave types constrains the source better than any single sensor could.','Monitoring agencies co-locate seismometers with infrasound or hydrophone sensors to discriminate earthquakes from explosions, track eruptions, and study bolides, using arrival-time and energy comparisons across the media.','Geologic & Seismoacoustics',ARRAY['Infrasound','Hydroacoustics','Seismoacoustic wavefield','Ground-coupled acoustic wave','T phase']::text[],ARRAY['Treating seismoacoustics as only ground motion, when it deliberately spans ground, air, and water','Assuming seismic and acoustic arrivals from one source line up in time, when their very different wave speeds separate them','Confusing the coupling of energy between media with simple sensor cross-talk']::text[],ARRAY['Discriminating an underground explosion from a natural earthquake using combined records','Tracking a volcanic eruption with paired seismic and infrasound stations','Characterising a fireball entering the atmosphere from its air and ground signals']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismoacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36a63710-3049-5d56-a88b-3f9d2d524d73','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36a63710-3049-5d56-a88b-3f9d2d524d73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36a63710-3049-5d56-a88b-3f9d2d524d73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65a28744-b7b2-56b5-814d-83b50493785c','Seismoacoustic wavefield','The total space- and time-varying field of both elastic ground motion and acoustic pressure produced by a source and its interactions with the ground surface and atmosphere. It comprises body and surface seismic waves in the solid, acoustic and infrasonic waves in the air or water, and the interface-coupled phases that convert energy between solid and fluid. The wavefield is described jointly by the elastodynamic equations in the solid and the acoustic wave equation in the fluid, matched by continuity of traction and displacement at the boundary.','A wavefield is the whole pattern of waves spreading from a source. The seismoacoustic wavefield holds both ground waves and sound waves. It fills the rock and the air or sea at the same time. Some energy crosses from one to the other at the surface. Studying the full field tells us how the source moved.','It provides a single framework in which ground and airborne or waterborne energy from one event are modelled together, so that phase conversions at interfaces are treated as part of one physical field rather than separate problems.','Researchers simulate the coupled field to predict how an explosion or eruption appears on seismometers and infrasound sensors, and to invert real records for source depth, size, and mechanism.','Geologic & Seismoacoustics',ARRAY['Seismoacoustics','Elastic wave','Ground-coupled acoustic wave','Wavefield','Infrasound']::text[],ARRAY['Modelling the ground and the air as unconnected, ignoring the energy that couples across the surface','Assuming the field is dominated by body waves, when surface and interface waves often carry most energy at range','Forgetting that fluid supports only compressional waves while the solid also carries shear waves']::text[],ARRAY['Simulating the coupled ground and air response to a surface explosion','Inverting joint records for the depth of a shallow seismic source','Explaining why an air wave appears on a buried geophone']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismoacoustic wavefield');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65a28744-b7b2-56b5-814d-83b50493785c','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65a28744-b7b2-56b5-814d-83b50493785c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65a28744-b7b2-56b5-814d-83b50493785c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41d4597d-40e0-5c55-9ae4-f758b4966ac2','Seismoacoustic receiver','A sensor or co-located sensor group that records both ground motion and acoustic pressure, typically a seismometer paired with an infrasound microbarometer or a hydrophone. The receiver captures the ground and fluid parts of the seismoacoustic wavefield at one site with a common time base, so that seismic and acoustic arrivals from the same source can be compared directly in time, amplitude, and waveform.','A seismoacoustic receiver senses ground shaking and sound at one spot. It usually pairs a seismometer with an air or water sound sensor. Both share one clock. That lets us line up the ground and sound signals from an event. The pair reveals more than either sensor alone.','It supplies the paired ground and acoustic channels needed to tell wave types apart, since a signal that appears on the seismometer but not the pressure sensor, or the reverse, points to different source paths.','Field teams deploy co-located seismometer and microbarometer packages at volcanoes and test sites, using shared GPS timing to separate seismic, air-coupled, and infrasound arrivals during analysis.','Geologic & Seismoacoustics',ARRAY['Microbarometer','Seismometer','Hydrophone station','Infrasonic array','Seismoacoustic data fusion']::text[],ARRAY['Assuming one sensor type can capture the whole wavefield, when both ground and pressure channels are needed','Neglecting precise shared timing, which is essential for comparing arrivals across sensors','Placing the pressure sensor and seismometer far apart so their records no longer share a source path']::text[],ARRAY['Installing a seismometer and microbarometer package on a volcano flank','Timing seismic and infrasound arrivals from a quarry blast','Separating an air wave from a ground wave at a monitoring site']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismoacoustic receiver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41d4597d-40e0-5c55-9ae4-f758b4966ac2','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41d4597d-40e0-5c55-9ae4-f758b4966ac2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41d4597d-40e0-5c55-9ae4-f758b4966ac2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e6d5702-1c4d-5269-9e42-1d56e4f357b1','Seismoacoustic data fusion','The joint processing of seismic and acoustic records to detect, locate, classify, or characterise a source more reliably than either data type alone. Fusion methods combine differing wave speeds, propagation paths, and signal features across ground, air, and water sensors, using arrival-time association, cross-correlation, energy partitioning, or statistical and machine-learning classifiers to link signals to a common source and reject uncorrelated noise.','Data fusion blends seismic and sound records into one analysis. Each sensor sees the event in its own way. Combining them makes detection and location more sure. It also helps tell one kind of source from another. The blend beats using either data type alone.','It raises detection confidence and location accuracy by requiring that signals agree across independent media, which suppresses false alarms from noise that appears in only one data type.','Treaty-monitoring and volcano systems fuse seismic, infrasound, and hydroacoustic streams to confirm events, estimate source type and location, and cut false detections in automatic pipelines.','Geologic & Seismoacoustics',ARRAY['Seismoacoustics','Seismoacoustic receiver','Hydroacoustic monitoring','Infrasonic array','Induced seismicity']::text[],ARRAY['Fusing channels without correcting for the very different travel times of seismic and acoustic waves','Assuming more sensors always help, when poorly timed or uncalibrated channels can add noise','Treating agreement in one narrow feature as proof of a common source']::text[],ARRAY['Confirming a suspected explosion by matching seismic and infrasound detections','Classifying eruption styles from combined ground and air signals','Reducing false alarms in an automatic monitoring pipeline']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismoacoustic data fusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e6d5702-1c4d-5269-9e42-1d56e4f357b1','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e6d5702-1c4d-5269-9e42-1d56e4f357b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e6d5702-1c4d-5269-9e42-1d56e4f357b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '608eac19-681f-5b97-b306-0747fc39b0c7','Ground-coupled acoustic wave','A seismic signal generated when an atmospheric acoustic or infrasonic wave travelling along the ground surface loads the ground and induces elastic motion recorded by a seismometer. Because it propagates at the speed of sound in air, roughly 340 metres per second, it arrives far later than direct seismic phases and appears as an air-to-ground converted arrival. It is common after explosions, eruptions, sonic booms, and bolides.','Sound in the air can press on the ground as it passes. This makes the ground move a little. A seismometer then records the passing sound. Because sound in air is slow, this wave arrives late. It shows up after explosions, eruptions, and sonic booms.','It marks the conversion of airborne acoustic energy into ground motion, letting analysts recognise an air-wave arrival on a seismometer and use its slow apparent speed to identify atmospheric sources.','Analysts spot ground-coupled air waves on seismic records of quarry blasts, eruptions, and meteors by their air-speed move-out, and use them to confirm an atmospheric source or estimate its location.','Geologic & Seismoacoustics',ARRAY['Infrasound','Air-coupled Rayleigh wave','Seismoacoustic wavefield','Volcano infrasound','Microbarom']::text[],ARRAY['Mistaking a slow air-coupled arrival for a genuine seismic body-wave phase','Assuming it travels at seismic speeds, when it moves at the speed of sound in air','Overlooking that its timing points to an atmospheric rather than a buried source']::text[],ARRAY['Identifying an air wave on a seismometer after a quarry blast','Confirming a meteor entry from a late ground-coupled arrival','Explaining a delayed seismic pulse following a volcanic explosion']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground-coupled acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '608eac19-681f-5b97-b306-0747fc39b0c7','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='608eac19-681f-5b97-b306-0747fc39b0c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='608eac19-681f-5b97-b306-0747fc39b0c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '59ad083c-b09c-58a2-bd4e-d626e11a2640','Volcano infrasound','Low-frequency atmospheric sound, generally below the roughly 20 hertz limit of human hearing, radiated by volcanic activity such as explosions, degassing, jetting, and magma movement at or near the vent. Its waveform, amplitude, and spectrum relate to vent processes and eruption vigour, and it propagates through the atmosphere to be recorded by microbarometers and infrasound arrays, often together with seismic signals.','Volcanoes make sound too low for people to hear. This is called volcano infrasound. Explosions, gas blasts, and moving magma all make it. The sound carries clues about what the vent is doing. Special pressure sensors record it from a safe distance.','It provides a direct atmospheric record of vent activity that complements seismic data, since infrasound comes mainly from processes at or just above the surface rather than from deep within the edifice.','Volcano observatories run infrasound sensors near active vents to detect explosions in real time, estimate eruption size, and separate surface activity from deep seismic sources for early warning.','Geologic & Seismoacoustics',ARRAY['Infrasound','Infrasonic array','Microbarometer','Volcanic tremor','Ground-coupled acoustic wave']::text[],ARRAY['Assuming volcano infrasound is audible, when it lies mostly below the range of human hearing','Attributing all vent signals to the ground, when infrasound often reveals surface activity the seismometer misses','UNSAFE: approaching an active vent to place an infrasound sensor without assessing gas, ballistic, and eruption hazards']::text[],ARRAY['Detecting an explosive eruption in real time from a nearby array','Estimating eruption vigour from infrasound amplitude','Separating surface degassing from deep tremor at an active volcano']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volcano infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '59ad083c-b09c-58a2-bd4e-d626e11a2640','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='59ad083c-b09c-58a2-bd4e-d626e11a2640') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='59ad083c-b09c-58a2-bd4e-d626e11a2640');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07c22b00-6ac2-5ecd-9e1e-eae6075c6534','Infrasonic array','A spatial cluster of infrasound sensors, spaced from tens to hundreds of metres apart, whose signals are combined to detect coherent low-frequency sound and measure its back-azimuth and apparent (trace) velocity across the array. By exploiting the time delays of a plane wave across the elements, the array separates a coherent signal from incoherent wind and ambient noise and points back toward the source.','An infrasonic array is a group of sound sensors spread over the ground. The same wave hits each sensor at a slightly different time. From those tiny delays, the array finds the wave direction and speed. Working together, the sensors pull weak sound out of the wind noise. This shows where the sound came from.','It turns several sensors into a directional instrument, using coherence across elements to detect faint infrasound and estimate where it came from, which a single sensor cannot do.','Treaty-monitoring and volcano networks operate infrasound arrays to detect distant explosions and eruptions, reporting back-azimuth and trace velocity that feed source location and event association.','Geologic & Seismoacoustics',ARRAY['Infrasound','Microbarometer','Volcano infrasound','Back-azimuth','Beamforming']::text[],ARRAY['Confusing back-azimuth from one array with a full location, which needs several arrays or added data','Ignoring wind noise reduction, which is essential for array elements to stay coherent','Spacing elements wrongly for the target frequencies, degrading the array response']::text[],ARRAY['Measuring the direction of a distant explosion from delays across elements','Detecting eruption infrasound above local wind noise','Associating array detections to locate an atmospheric source']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasonic array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07c22b00-6ac2-5ecd-9e1e-eae6075c6534','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07c22b00-6ac2-5ecd-9e1e-eae6075c6534') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07c22b00-6ac2-5ecd-9e1e-eae6075c6534');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab8319fe-5273-524a-b163-ab22530bdb31','Microbarometer','A high-sensitivity barometric sensor that measures very small, rapid fluctuations of atmospheric pressure associated with infrasound, resolving changes far below a pascal over a band from below one hertz up to about twenty hertz. Field microbarometers are usually fitted with wind-noise-reducing pipe or porous-hose spatial filters and are deployed as elements of infrasound arrays for volcano, atmospheric, and treaty monitoring.','A microbarometer measures tiny, fast changes in air pressure. These changes are the infrasound we cannot hear. The sensor is very sensitive and reacts quickly. Pipes or hoses around it cut down wind noise. It is the basic element of an infrasound array.','It converts faint pressure fluctuations into a recordable signal so that infrasound from explosions, eruptions, and the ocean can be measured and analysed.','Monitoring stations deploy microbarometers with wind-noise filters as array elements, feeding continuous pressure data into infrasound detection and location processing.','Geologic & Seismoacoustics',ARRAY['Infrasound','Infrasonic array','Microbarom','Volcano infrasound','Wind-noise reduction']::text[],ARRAY['Confusing a microbarometer with an ordinary weather barometer, which is far too slow and coarse','Deploying it without wind-noise filtering, which swamps the infrasound with turbulence','Assuming it senses ground motion, when it responds only to air pressure']::text[],ARRAY['Recording infrasound from a distant eruption at an array element','Measuring microbaroms generated by ocean storms','Detecting a bolide shock wave in the atmosphere']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microbarometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab8319fe-5273-524a-b163-ab22530bdb31','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab8319fe-5273-524a-b163-ab22530bdb31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab8319fe-5273-524a-b163-ab22530bdb31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96a6f8fd-e86c-58f5-842b-ecfe8f36c23d','Microbarom','A persistent, near-monochromatic atmospheric infrasound signal centred near 0.2 hertz, radiated by the nonlinear interaction of opposing ocean surface waves of similar frequency over the open sea. The generation mechanism mirrors that of secondary ocean microseisms, so the microbarom frequency sits at roughly twice the ocean swell frequency. Microbaroms form a continuous background on infrasound arrays and are used to study ocean-atmosphere coupling and to calibrate array response.','Microbaroms are a steady hum of infrasound from the sea. They come from ocean waves moving against each other. Their pitch is about one cycle every five seconds. This sits near twice the swell frequency. Infrasound arrays hear this ocean hum all the time.','It represents the dominant natural infrasound background from the oceans, useful as a persistent reference for testing array performance and for studying how the sea couples energy into the atmosphere.','Infrasound analysts recognise the steady near-0.2 hertz microbarom band on array records, use it to check sensor and array response, and track ocean-storm sources by its back-azimuth.','Geologic & Seismoacoustics',ARRAY['Infrasound','Secondary microseism','Microbarometer','Infrasonic array','Ocean-atmosphere coupling']::text[],ARRAY['Confusing microbaroms in the air with microseisms in the ground, though both share an ocean-wave origin','Assuming the microbarom frequency equals the swell frequency, when it is about twice as high','Treating the persistent microbarom band as instrument noise rather than a real signal']::text[],ARRAY['Identifying the steady ocean-generated band on an infrasound array','Using microbaroms to verify array response over time','Tracking a marine storm from microbarom back-azimuth']::text[],'advanced','f_air ≈ 2·f_wave','The microbarom frequency is approximately twice the frequency of the generating ocean surface waves.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microbarom');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96a6f8fd-e86c-58f5-842b-ecfe8f36c23d','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96a6f8fd-e86c-58f5-842b-ecfe8f36c23d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96a6f8fd-e86c-58f5-842b-ecfe8f36c23d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4b74f8a-70d6-5bb4-aa7c-6ab2b6e55b89','Microseism','A persistent, low-amplitude ground vibration, mostly in the roughly 0.05 to 0.5 hertz band, generated by ocean waves and their interaction with the sea floor and coasts. Microseisms form the dominant ambient seismic noise on continents and are divided into primary microseisms, at the ocean swell frequency, and stronger secondary microseisms, at about twice that frequency. They travel largely as surface waves and are recorded worldwide on broadband seismometers.','Microseisms are a faint, steady shaking of the ground. Ocean waves far away cause them. They are the main background noise on seismometers. Their motion is slow, a few cycles per minute to a few per second. This hum never fully stops.','It is the main natural seismic background, both a noise source that limits detection of small earthquakes and a signal that carries information about ocean-wave activity and Earth structure.','Seismologists filter microseisms out when hunting small earthquakes, but also use them in ambient-noise methods to image the crust and to monitor ocean-storm energy.','Geologic & Seismoacoustics',ARRAY['Secondary microseism','Microbarom','Surface wave','Seismic ambient noise','Ambient-noise tomography']::text[],ARRAY['Treating microseisms only as unwanted noise, when they are also a useful signal for imaging','Confusing primary and secondary microseisms, which sit at different frequencies','Assuming they come from local sources, when distant ocean storms often dominate']::text[],ARRAY['Filtering ocean noise to detect a small local earthquake','Using ambient microseisms to image crustal structure','Linking a rise in microseism energy to an offshore storm']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microseism');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4b74f8a-70d6-5bb4-aa7c-6ab2b6e55b89','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4b74f8a-70d6-5bb4-aa7c-6ab2b6e55b89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4b74f8a-70d6-5bb4-aa7c-6ab2b6e55b89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20952710-6a77-5e84-875f-7fa60d8a544f','Secondary microseism','The stronger band of ocean-generated ground noise, centred near 0.1 to 0.3 hertz, produced by the nonlinear interaction of ocean surface waves travelling in opposing directions with similar frequency, as described by Longuet-Higgins. This interaction creates a pressure fluctuation at twice the wave frequency that does not decay with depth, coupling efficiently into the sea floor. The secondary microseism therefore appears at about double the ocean swell frequency and dominates the global microseism spectrum.','The secondary microseism is the loudest part of ocean ground noise. It comes from waves that meet head-on and interact. This makes a pressure beat at twice the wave rate. That beat reaches the sea floor and shakes it. It sits near twice the swell frequency.','It explains the strongest peak in ambient seismic noise and links that peak physically to opposing ocean waves, giving a tool to study both storms and the solid Earth.','Researchers track secondary microseism strength to monitor ocean-wave interaction and storm activity, and use its steady surface waves for ambient-noise imaging of the crust.','Geologic & Seismoacoustics',ARRAY['Microseism','Microbarom','Seismic ambient noise','Surface wave','Ambient-noise tomography']::text[],ARRAY['Thinking it occurs at the swell frequency, when it appears at about twice that frequency','Confusing it with the weaker primary microseism generated near coasts','Assuming a single wave train causes it, when opposing waves are required']::text[],ARRAY['Explaining the dominant peak in a seismic noise spectrum','Monitoring ocean-wave interaction from onshore seismometers','Supplying surface waves for ambient-noise tomography']::text[],'advanced','f_seis ≈ 2·f_wave','The secondary microseism frequency is approximately twice the frequency of the interacting ocean surface waves.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Secondary microseism');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20952710-6a77-5e84-875f-7fa60d8a544f','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20952710-6a77-5e84-875f-7fa60d8a544f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20952710-6a77-5e84-875f-7fa60d8a544f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '829900a6-8503-571a-b6a3-da7c09dc36ae','Hydroacoustics','The study and use of sound in water, especially the propagation of acoustic waves through the ocean and their generation by natural and man-made sources. In Earth monitoring it focuses on low-frequency sound trapped in the deep ocean sound channel, where efficient long-range propagation lets a few sensors detect underwater earthquakes, volcanic activity, ice events, and explosions across entire ocean basins.','Hydroacoustics is the study of sound in water. Sound travels very far in the deep ocean. A natural sound channel traps and guides it. So a few sensors can hear events across a whole ocean. This is used to watch quakes, volcanoes, and blasts at sea.','It provides the physical basis for listening to the oceans, since water carries low-frequency sound over thousands of kilometres far more efficiently than the solid Earth carries seismic waves.','Ocean-monitoring programmes use hydroacoustics to detect and locate undersea earthquakes, eruptions, iceberg breakup, and explosions using sparse hydrophone and T-phase stations.','Geologic & Seismoacoustics',ARRAY['Hydrophone station','Hydroacoustic monitoring','SOFAR channel','T phase','T-phase station']::text[],ARRAY['Assuming sound behaves the same in water as in air, when it travels far faster and farther in water','Overlooking the deep sound channel that guides low-frequency energy over long ranges','Confusing hydroacoustic waves in water with seismic waves in the sea floor']::text[],ARRAY['Detecting an undersea eruption from a distant hydrophone','Locating an underwater explosion across an ocean basin','Tracking iceberg breakup by its radiated sound']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydroacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '829900a6-8503-571a-b6a3-da7c09dc36ae','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='829900a6-8503-571a-b6a3-da7c09dc36ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='829900a6-8503-571a-b6a3-da7c09dc36ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e25c42b3-58c8-5ee3-bc59-d5a19ba4790e','Hydroacoustic monitoring','The continuous surveillance of the oceans using underwater sound to detect, locate, and identify events such as underwater explosions, earthquakes, volcanic activity, and ice noise. It relies on the deep sound channel for long-range propagation and combines moored hydrophone stations with land-based T-phase stations. It is a core technology of nuclear-test-ban verification, where a sparse global network can cover the world''s oceans.','Hydroacoustic monitoring listens to the oceans all the time. It uses underwater sound sensors and coastal stations. The deep sound channel carries signals a long way. This lets a small network watch every ocean. It helps verify bans on nuclear tests.','It gives global reach with few sensors by using efficient ocean sound propagation, so that underwater explosions and natural events can be detected and located for treaty verification and hazard studies.','Verification networks operate hydrophone and T-phase stations whose detections are combined to locate and classify undersea sources, distinguishing explosions from earthquakes and marine noise.','Geologic & Seismoacoustics',ARRAY['Hydroacoustics','Hydrophone station','T-phase station','T phase','Seismoacoustic data fusion']::text[],ARRAY['Assuming dense coverage is needed, when the sound channel lets sparse stations span oceans','Confusing hydroacoustic detections with land seismic detections without checking the propagation path','Ignoring marine mammal and shipping noise that can mimic or mask signals']::text[],ARRAY['Verifying a suspected underwater explosion for treaty compliance','Locating an undersea earthquake from combined stations','Separating whale or ship noise from a genuine source']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydroacoustic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e25c42b3-58c8-5ee3-bc59-d5a19ba4790e','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e25c42b3-58c8-5ee3-bc59-d5a19ba4790e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e25c42b3-58c8-5ee3-bc59-d5a19ba4790e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1bb11df-44a2-5af1-b8a6-801d169f30d9','Hydrophone station','A monitoring installation of one or more hydrophones moored at or near the depth of the ocean sound channel to record low-frequency underwater sound. Because the sound channel guides energy with little loss, such a station detects distant explosions, earthquakes, and ice and volcanic events across an ocean basin. Stations are usually deployed as small groups or triplets so that signal direction can be estimated.','A hydrophone station is an underwater listening post. Its sensors hang near the deep sound channel. There they catch faint sound from far away. Sensors are often set in small groups. This lets analysts find the sound direction.','It places sensors where the ocean guides sound most efficiently, so a single station can monitor a vast area and, in groups, indicate where a signal came from.','Ocean-monitoring networks moor hydrophone triplets in the sound channel; their timed arrivals feed detection, direction estimation, and basin-wide source location.','Geologic & Seismoacoustics',ARRAY['Hydrophone','Hydroacoustic monitoring','SOFAR channel','T-phase station','T phase']::text[],ARRAY['Placing a hydrophone outside the sound channel, sharply reducing its detection range','Assuming one hydrophone gives direction, when a group or triplet is needed','Ignoring mooring motion and current noise that contaminate low-frequency records']::text[],ARRAY['Mooring a hydrophone triplet at sound-channel depth','Detecting a distant undersea eruption from a single station','Estimating source direction from a hydrophone group']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrophone station');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1bb11df-44a2-5af1-b8a6-801d169f30d9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1bb11df-44a2-5af1-b8a6-801d169f30d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1bb11df-44a2-5af1-b8a6-801d169f30d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b0e0192-eb4a-5d06-8c21-6aa0e2116ef7','T-phase station','A land-based seismic station, typically on a steep-sided island or coast, sited to record T phases, the water-borne acoustic energy that converts back into seismic ground motion where the ocean sound channel meets a slope. Such stations extend hydroacoustic monitoring onto land, offering a lower-cost alternative to moored hydrophones by capturing ocean sound after it couples into the solid Earth at the shoreline.','A T-phase station is a seismometer set near a steep coast. It records ocean sound that turns back into ground motion at the slope. This water-borne sound is called the T phase. Such stations extend ocean listening onto land. They cost less than deep moored sensors.','It captures ocean-channel sound cheaply on land by using the natural conversion of water-borne energy into ground motion at steep slopes, complementing moored hydrophones.','Verification and tsunami programmes place seismometers on steep islands to record T phases from undersea earthquakes and explosions, adding coverage where hydrophones are absent.','Geologic & Seismoacoustics',ARRAY['T phase','Hydrophone station','Hydroacoustic monitoring','SOFAR channel','Seismoacoustics']::text[],ARRAY['Assuming a T-phase station records pure water sound, when it senses ground motion converted at the slope','Siting it on a shallow, gentle coast where conversion is weak','Treating the converted T phase as a normal seismic body-wave arrival']::text[],ARRAY['Recording a T phase from an undersea earthquake on a steep island','Adding land coverage to an ocean-monitoring network','Confirming an offshore explosion from a coastal seismometer']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='T-phase station');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b0e0192-eb4a-5d06-8c21-6aa0e2116ef7','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b0e0192-eb4a-5d06-8c21-6aa0e2116ef7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b0e0192-eb4a-5d06-8c21-6aa0e2116ef7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1ee554e-c282-50b1-b823-35b471d0d9d7','T phase','The tertiary seismic phase, a water-borne acoustic wave that travels through the ocean sound channel at about 1.5 kilometres per second and converts to and from seismic energy at the source or at a slope near the receiver. Named as the third arrival after the primary and secondary seismic phases, it is slow because it propagates as sound in water, and it is a key phase for locating undersea earthquakes and explosions.','The T phase is a sound wave that travels through the ocean. It moves at the speed of sound in water, about 1.5 kilometres per second. This is slow next to normal seismic waves. So it arrives third, after the P and S phases. It helps locate undersea quakes and blasts.','It carries source energy over long ocean paths at water sound speed, giving a distinctive slow arrival that helps detect and locate undersea events beyond the reach of body-wave seismology.','Analysts pick T-phase arrivals on hydrophones and coastal seismometers to locate submarine earthquakes, volcanic events, and explosions, using their water-speed travel times.','Geologic & Seismoacoustics',ARRAY['T-phase station','Hydroacoustics','SOFAR channel','P-wave','S-wave']::text[],ARRAY['Treating the T phase as a seismic body wave, when it travels as sound in water','Using seismic wave speeds for its travel time instead of the water sound speed','Assuming it is present for every event, when a good water path and conversion are required']::text[],ARRAY['Locating a submarine earthquake from T-phase arrival times','Confirming an undersea explosion by its slow water-borne phase','Distinguishing a T phase from body-wave arrivals on a record']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='T phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1ee554e-c282-50b1-b823-35b471d0d9d7','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1ee554e-c282-50b1-b823-35b471d0d9d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1ee554e-c282-50b1-b823-35b471d0d9d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e2ae43c-afe2-532a-8d8b-5ea143377911','Rock acoustic emission','Transient elastic waves released within rock as stored strain energy is suddenly relieved by microcracking, frictional slip, or pore collapse under stress. These high-frequency bursts, often in the kilohertz to megahertz range in the laboratory, are the small-scale equivalent of earthquakes and are recorded by piezoelectric sensors. Their rate, energy, and amplitude patterns track the progressive damage and approaching failure of a rock sample or rock mass.','Stressed rock makes tiny cracking sounds as it starts to fail. These bursts of sound are called acoustic emissions. They are like very small earthquakes inside the rock. Sensors on the rock record each burst. Their rate and strength warn that failure is near.','It reveals internal cracking before visible fracture, so that the buildup toward failure in rock can be tracked in the laboratory and in the field.','Rock-mechanics labs and mine or slope monitors record acoustic emissions with piezoelectric sensors to study damage, forecast failure, and assess stability under load.','Geologic & Seismoacoustics',ARRAY['Microcrack acoustic emission','AE event rate','AE energy','Microseismic event','Acoustic-emission hypocenter']::text[],ARRAY['Confusing acoustic emission with audible sound, when most of it is far above human hearing','Assuming a steady emission rate means stability, when accelerating rates warn of failure','UNSAFE: entering a mine or slope showing rapidly rising acoustic emission without a stability assessment']::text[],ARRAY['Recording microcracking as a rock sample is loaded to failure','Monitoring a mine wall for rising emission before collapse','Assessing slope stability from acoustic emission trends']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rock acoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e2ae43c-afe2-532a-8d8b-5ea143377911','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e2ae43c-afe2-532a-8d8b-5ea143377911') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e2ae43c-afe2-532a-8d8b-5ea143377911');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb76ebaa-9e30-5b66-addc-16207f11372a','Microcrack acoustic emission','Acoustic emission generated by the nucleation and growth of individual microcracks in stressed rock, each rapid crack extension radiating a high-frequency elastic pulse. Because a single microcrack is the smallest failure unit, this emission underlies bulk acoustic-emission activity, and the collective statistics of many microcrack events, such as their locations, rates, and size distribution, describe how damage localises before macroscopic fracture.','Rock fails one tiny crack at a time. Each new crack sends out a small pulse of sound. This is microcrack acoustic emission. Many such pulses together track growing damage. As cracks cluster, they mark where the rock will break.','It ties measured emissions to the basic physical event of a single cracking, letting researchers connect laboratory signals to the fracture process at grain scale.','Laboratory studies locate and count microcrack emissions to map how cracks cluster and to test models of rock strength, damage, and the approach to failure.','Geologic & Seismoacoustics',ARRAY['Rock acoustic emission','AE event rate','AE amplitude distribution','Acoustic-emission hypocenter','Microseismic event']::text[],ARRAY['Treating each emission as a large fracture, when it marks a single small crack','Ignoring clustering of microcrack locations, which signals where failure will localise','Assuming one sensor suffices, when several are needed to locate the tiny sources']::text[],ARRAY['Mapping microcrack locations during a rock-strength test','Studying how cracks cluster before a sample fails','Validating a damage model against emission statistics']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microcrack acoustic emission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb76ebaa-9e30-5b66-addc-16207f11372a','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb76ebaa-9e30-5b66-addc-16207f11372a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb76ebaa-9e30-5b66-addc-16207f11372a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87b1cf9f-187a-57f8-b36c-f6de838ad087','AE event rate','The number of discrete acoustic-emission events detected per unit time in a stressed rock sample or rock mass. As a time series it tracks the pace of internal cracking: a rising or accelerating event rate signals growing damage and impending failure, while a falling rate indicates stabilisation. It is one of the primary quantities used to interpret acoustic-emission monitoring and to forecast rock failure.','AE event rate counts how many cracking bursts happen each second or minute. A rising count means cracking is speeding up. That warns the rock is heading toward failure. A steady or falling count means it is settling. This makes the rate a simple failure warning.','It condenses emission activity into a single trend that reveals whether damage is accelerating or stabilising, giving an accessible warning signal for failure.','Monitoring systems plot acoustic-emission event rate over time and raise alerts when it accelerates, guiding decisions on rock samples, mine walls, and slopes.','Geologic & Seismoacoustics',ARRAY['Rock acoustic emission','AE energy','AE amplitude distribution','Microseismic monitoring','Microcrack acoustic emission']::text[],ARRAY['Reading a high but steady rate as dangerous, when acceleration is the key warning','Ignoring detection threshold changes that alter the counted rate','UNSAFE: dismissing a sharply accelerating event rate near an excavation instead of clearing personnel']::text[],ARRAY['Alerting when emission rate accelerates during a load test','Watching a mine wall for a surge in event rate','Comparing event-rate trends across slope sensors']::text[],'intermediate','R = dN/dt','The acoustic-emission event rate equals the change in cumulative event count divided by the change in time.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE event rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87b1cf9f-187a-57f8-b36c-f6de838ad087','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87b1cf9f-187a-57f8-b36c-f6de838ad087') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87b1cf9f-187a-57f8-b36c-f6de838ad087');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a794280-22d7-50bd-847e-800389cce241','AE energy','A measure of the energy carried by an acoustic-emission event, commonly taken as proportional to the integral of the squared signal amplitude over the event duration at a sensor. It scales with the size of the underlying cracking or slip and, summed over many events, gives the cumulative emission energy whose growth tracks the total damage accumulated in a stressed rock. It is a core quantity for comparing event sizes and interpreting failure.','AE energy measures how strong a cracking burst is. It comes from squaring the signal and adding it up over the burst. A bigger crack gives more energy. Adding energy over many events tracks total damage. This lets us compare small and large bursts.','It gives a size measure for emission events that relates to the physical energy released, allowing large and small cracking to be ranked and total damage to be summed.','Analysts compute per-event energy and cumulative energy from acoustic-emission records to gauge event size, follow damage growth, and compare tests or field sites.','Geologic & Seismoacoustics',ARRAY['Rock acoustic emission','AE event rate','AE amplitude distribution','Acoustic-emission hypocenter','Microcrack acoustic emission']::text[],ARRAY['Equating peak amplitude with energy, when energy integrates the whole squared waveform','Comparing energies without accounting for sensor distance and attenuation','Ignoring the detection threshold, which biases the smallest counted energies']::text[],ARRAY['Ranking emission events by energy during a load test','Tracking cumulative emission energy as damage grows','Comparing emission energy release between two rock samples']::text[],'intermediate','E ∝ ∫ A(t)² dt','The acoustic-emission energy is proportional to the time integral of the squared signal amplitude over the event.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE energy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a794280-22d7-50bd-847e-800389cce241','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a794280-22d7-50bd-847e-800389cce241') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a794280-22d7-50bd-847e-800389cce241');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c8802d8-799d-5564-803f-2e350424a3f4','AE amplitude distribution','The statistical distribution of peak amplitudes, or equivalently magnitudes, of acoustic-emission events, typically following a power law analogous to the Gutenberg-Richter frequency-magnitude relation for earthquakes. Its slope, often reported as a b-value, reflects the relative proportion of large to small events: a high slope indicates dominance of small cracks under low stress, while a decreasing slope toward failure signals a shift to larger events as damage localises.','Small cracking bursts happen far more often than large ones. The amplitude distribution shows this pattern. Its slope tells how many big events there are versus small. A steep slope means mostly small cracks. The slope often drops just before the rock fails.','It characterises the mix of large and small events in one number, the slope, which changes systematically with stress and damage and so serves as a failure indicator.','Rock-mechanics and mine-monitoring studies fit the amplitude distribution and track its slope, watching for a decrease that warns of a shift toward larger events near failure.','Geologic & Seismoacoustics',ARRAY['Rock acoustic emission','AE energy','AE event rate','Gutenberg-Richter relation','Microcrack acoustic emission']::text[],ARRAY['Fitting the slope without correcting for the detection threshold that truncates small events','Assuming a fixed slope, when it evolves as stress and damage change','Reading a single distribution as static rather than tracking how its slope moves over time']::text[],ARRAY['Tracking the distribution slope as a sample nears failure','Comparing amplitude distributions between low and high stress','Detecting a shift toward larger events in a monitored rock mass']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE amplitude distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c8802d8-799d-5564-803f-2e350424a3f4','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c8802d8-799d-5564-803f-2e350424a3f4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c8802d8-799d-5564-803f-2e350424a3f4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72000261-fff1-58c7-9709-b46cc70f8080','Acoustic-emission hypocenter','The located source point in three dimensions of an individual acoustic-emission event, found by inverting the arrival times of the emitted elastic wave at several sensors given a model of wave speed in the rock. As the acoustic-emission analogue of an earthquake hypocenter, mapping many such points over time reveals how microcracking nucleates and migrates, showing where damage concentrates and how a fracture or fault zone develops.','Each cracking burst starts at one point inside the rock. The acoustic-emission hypocenter is that point in three dimensions. It is found from when the pulse reaches each sensor. Mapping many points shows where cracks gather. This reveals how a fracture grows.','It converts arrival-time data into source locations, so the spatial pattern and migration of microcracking can be imaged rather than only counted.','Laboratory and field studies locate acoustic-emission hypocenters to map fracture growth, image developing fault zones, and monitor how damage spreads around excavations.','Geologic & Seismoacoustics',ARRAY['Rock acoustic emission','Microcrack acoustic emission','Hypocenter','Microseismic event','Microseismic monitoring']::text[],ARRAY['Locating events with too few sensors, giving poorly constrained positions','Using a wrong or oversimplified velocity model, which biases the locations','Treating scattered locations as noise instead of looking for migration and clustering']::text[],ARRAY['Mapping fracture growth in a loaded rock sample','Imaging a developing fault zone from located events','Tracking damage migration around a tunnel']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-emission hypocenter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72000261-fff1-58c7-9709-b46cc70f8080','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72000261-fff1-58c7-9709-b46cc70f8080') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72000261-fff1-58c7-9709-b46cc70f8080');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0f86ed0-086c-51a9-a363-0accec8dcb35','Microseismic monitoring','The continuous recording and analysis of very small earthquakes, usually of magnitude below about two and often negative, to track subsurface deformation and fracturing. Using arrays of sensitive geophones or seismometers at the surface or in boreholes, it detects, locates, and characterises microseismic events in near real time. It is widely used to follow hydraulic fracturing, reservoir and mine deformation, and induced seismicity.','Microseismic monitoring listens for very tiny earthquakes underground. These are far too small for people to feel. Sensitive sensors at the surface or in boreholes record them. Their locations show where the rock is cracking or moving. It is used in energy operations and mines.','It makes invisible subsurface fracturing observable by locating swarms of tiny events, so operators can see where deformation and fluid effects are occurring underground.','Energy and mining operations run geophone arrays to map microseismic events during hydraulic fracturing, reservoir production, and mining, guiding operations and managing induced seismicity.','Geologic & Seismoacoustics',ARRAY['Microseismic event','Induced seismicity','Passive seismic monitoring','Acoustic-emission hypocenter','Hypocenter']::text[],ARRAY['Confusing microseismic monitoring with large-earthquake seismology, when it targets far smaller events','Trusting locations without a well-calibrated velocity model','Ignoring that surface noise can hide the smallest events']::text[],ARRAY['Mapping fracture growth during a hydraulic fracturing stage','Tracking deformation around a producing reservoir','Monitoring a mine for hazardous rock movement']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microseismic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0f86ed0-086c-51a9-a363-0accec8dcb35','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0f86ed0-086c-51a9-a363-0accec8dcb35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0f86ed0-086c-51a9-a363-0accec8dcb35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dd6f23b-43eb-5016-8409-833994fef3b0','Microseismic event','A very small earthquake, typically of magnitude below about two and often of negative magnitude, caused by slip or fracturing on a small patch of rock. Bridging laboratory acoustic emission and felt earthquakes in scale, microseismic events are detected only by sensitive instruments. Their locations, times, and magnitudes reveal where and how the subsurface is deforming, whether naturally or in response to human activity.','A microseismic event is a tiny earthquake. It comes from a small patch of rock slipping or cracking. It is too weak for anyone to feel. Only sensitive sensors can catch it. Where and when these happen shows how the ground is moving.','It is the basic detected unit of microseismic monitoring, whose location, size, and timing carry the information used to map subsurface deformation.','Analysts detect, locate, and size microseismic events to image fracture networks, follow reservoir and mine changes, and study induced seismicity.','Geologic & Seismoacoustics',ARRAY['Microseismic monitoring','Induced seismicity','Rock acoustic emission','Hypocenter','Passive seismic monitoring']::text[],ARRAY['Confusing a microseismic event with a felt earthquake, when it is far too small to feel','Assuming negative magnitudes are errors, when very small events routinely have them','Reporting a location without stating its uncertainty']::text[],ARRAY['Detecting a swarm of tiny events during fracturing','Sizing microseismic events to estimate deformation','Distinguishing an induced event from background microseismicity']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microseismic event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dd6f23b-43eb-5016-8409-833994fef3b0','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dd6f23b-43eb-5016-8409-833994fef3b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dd6f23b-43eb-5016-8409-833994fef3b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13339c9c-f92e-5bcd-bc29-52d38604cc86','Induced seismicity','Earthquakes caused or triggered by human activities that change subsurface stress or pore-fluid pressure, such as fluid injection and extraction, wastewater disposal, hydraulic fracturing, reservoir impoundment, geothermal operations, and mining. Ranging from microseismic events to felt and occasionally damaging earthquakes, induced seismicity is studied by locating events and correlating their timing and position with operations, and is managed by adjusting those operations.','Induced seismicity means earthquakes caused by human activity. Injecting or removing underground fluid can trigger them. So can filling large reservoirs, mining, or geothermal work. Most are tiny, but some can be felt or cause damage. Operators watch and adjust their work to limit them.','It names and frames the class of human-triggered earthquakes so their causes can be identified, their hazard assessed, and operations changed to reduce the risk.','Regulators and operators monitor seismicity near injection wells, dams, and geothermal sites, linking events to operations and using traffic-light protocols to curtail activity when needed.','Geologic & Seismoacoustics',ARRAY['Microseismic monitoring','Microseismic event','Passive seismic monitoring','Pore pressure','Hydraulic fracturing']::text[],ARRAY['Assuming induced events are always tiny, when some have been felt and damaging','Linking every nearby earthquake to operations without checking timing and location','UNSAFE: continuing high-rate fluid injection despite rising felt seismicity instead of curtailing under a response protocol']::text[],ARRAY['Correlating an earthquake swarm with nearby wastewater injection','Applying a traffic-light protocol during geothermal stimulation','Assessing seismic hazard near a newly filled reservoir']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Induced seismicity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13339c9c-f92e-5bcd-bc29-52d38604cc86','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13339c9c-f92e-5bcd-bc29-52d38604cc86') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13339c9c-f92e-5bcd-bc29-52d38604cc86');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1da7935-28e6-5741-a7d5-596ac50f61f7','Passive seismic monitoring','The recording and analysis of naturally occurring or activity-induced ground vibrations without deploying a controlled source, in contrast to active surveys that use explosions or vibrators. It relies on ambient noise, earthquakes, and small induced events to detect subsurface changes, image structure, and locate sources. Continuous arrays of seismometers or geophones capture the wavefield, which is then processed to monitor reservoirs, faults, volcanoes, and induced seismicity.','Passive seismic monitoring listens without making its own signal. It uses natural shaking and small human-caused events. There is no need for a blast or a vibrator source. Sensors record the ground all the time. The records reveal changes and hidden sources below.','It provides long-term, low-impact observation of the subsurface by using signals that already exist, so change over time can be tracked without repeatedly firing a source.','Operators run permanent seismometer arrays over reservoirs, faults, and volcanoes to detect microseismicity, monitor induced events, and image structure from ambient noise.','Geologic & Seismoacoustics',ARRAY['Microseismic monitoring','Seismic ambient noise','Ambient-noise tomography','Induced seismicity','Seismic interferometry']::text[],ARRAY['Confusing passive monitoring with active surveys that use a controlled source','Assuming no source means no useful signal, when ambient noise itself carries information','Underestimating how long a deployment must run to capture rare events']::text[],ARRAY['Watching a reservoir for induced microseismicity over months','Imaging crustal structure from continuous ambient noise','Monitoring a fault zone for small precursory events']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive seismic monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1da7935-28e6-5741-a7d5-596ac50f61f7','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1da7935-28e6-5741-a7d5-596ac50f61f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1da7935-28e6-5741-a7d5-596ac50f61f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fffc138b-7101-536a-9e81-75a29a542e4d','Acoustic approximation','A simplification in seismic modelling that treats the Earth as a fluid supporting only compressional waves, ignoring shear rigidity and thus S-waves and mode conversions. Governed by the scalar acoustic wave equation rather than the full elastic equations, it greatly reduces computational cost and is widely used in exploration imaging and full-waveform inversion. It is accurate where P-wave energy dominates but breaks down where shear effects, converted waves, or strong anisotropy matter.','The acoustic approximation treats rock like a fluid. In this view only push-pull waves exist. Shear waves are left out to save effort. It makes seismic imaging much faster and simpler. It works well when push-pull waves carry most of the energy.','It trades physical completeness for speed, making large-scale seismic imaging and inversion practical when compressional energy dominates and shear effects can be neglected.','Exploration geophysicists use acoustic-approximation modelling in migration and full-waveform inversion of marine and land data, accepting its limits where converted or shear waves are significant.','Geologic & Seismoacoustics',ARRAY['Elastic wave','P-wave','S-wave','Full-waveform inversion','Seismic acoustic impedance']::text[],ARRAY['Applying it where shear waves and conversions are important, biasing the result','Forgetting that it omits S-waves entirely by construction','Assuming faster always means better, when the approximation can distort amplitudes']::text[],ARRAY['Speeding up full-waveform inversion of marine seismic data','Migrating a P-wave-dominated exploration survey','Deciding whether elastic modelling is needed for a converted-wave study']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fffc138b-7101-536a-9e81-75a29a542e4d','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fffc138b-7101-536a-9e81-75a29a542e4d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fffc138b-7101-536a-9e81-75a29a542e4d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee313d59-d6aa-50ba-9a9b-223073f958d1','P-wave','The primary or compressional seismic body wave, in which particles oscillate back and forth along the direction of propagation, alternately compressing and dilating the medium. It is the fastest seismic wave and the first to arrive at a station, travelling through solids, liquids, and gases. Its speed depends on the bulk modulus, shear modulus, and density of the medium, and it is analogous to sound waves in air and water.','A P-wave is the fastest seismic wave. It pushes and pulls the ground along its path. Because it is fastest, it arrives first at a station. It can travel through solid, liquid, and gas. It works much like ordinary sound.','As the first arrival, it anchors earthquake timing and location, and its speed through different materials probes the composition and state of the Earth.','Seismologists pick the P-wave first arrival to locate earthquakes and, in exploration, use P-wave speeds and reflections to image subsurface layers.','Geologic & Seismoacoustics',ARRAY['S-wave','Surface wave','Elastic wave','Body wave','Formation slowness']::text[],ARRAY['Thinking P stands for pressure alone, when it marks the primary, first-arriving wave','Assuming it cannot pass through liquids, when it travels through fluids unlike the S-wave','Confusing its along-path motion with the side-to-side motion of the S-wave']::text[],ARRAY['Picking the first arrival to locate an earthquake','Measuring P-wave speed to infer rock type','Imaging layer boundaries in a reflection survey']::text[],'beginner','Vp = √((K + 4μ/3)/ρ)','P-wave speed equals the square root of the bulk modulus plus four-thirds the shear modulus, divided by density.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='P-wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee313d59-d6aa-50ba-9a9b-223073f958d1','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee313d59-d6aa-50ba-9a9b-223073f958d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee313d59-d6aa-50ba-9a9b-223073f958d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ab788a5-9562-5f84-af27-b8d3f7d97ada','S-wave','The secondary or shear seismic body wave, in which particles oscillate perpendicular to the direction of propagation. Slower than the P-wave, it is the second body wave to arrive. Because fluids have no shear rigidity, the S-wave cannot travel through liquids, and this property, revealed by its absence across the outer core, is key evidence that the outer core is molten. Its speed depends on the shear modulus and density of the medium.','An S-wave shakes the ground side to side across its path. It moves slower than the P-wave. So it arrives second at a station. It cannot pass through liquids at all. Its absence through the outer core shows that layer is molten.','Its arrival after the P-wave gives the time gap used to estimate distance, and its inability to cross liquids reveals molten regions and the state of Earth''s interior.','Seismologists use the P-to-S time gap to estimate earthquake distance and rely on S-wave shadow zones to map the liquid outer core and locate fluid layers.','Geologic & Seismoacoustics',ARRAY['P-wave','Surface wave','Elastic wave','Body wave','Shear modulus']::text[],ARRAY['Assuming the S-wave travels through liquids, when it cannot because fluids lack shear strength','Confusing its perpendicular motion with the along-path motion of the P-wave','Treating it as the first arrival, when the faster P-wave always arrives first']::text[],ARRAY['Estimating distance from the P-to-S arrival gap','Mapping the molten outer core from S-wave shadow zones','Measuring shear-wave speed to assess site stiffness']::text[],'beginner','Vs = √(μ/ρ)','S-wave speed equals the square root of the shear modulus divided by density.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='S-wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ab788a5-9562-5f84-af27-b8d3f7d97ada','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ab788a5-9562-5f84-af27-b8d3f7d97ada') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ab788a5-9562-5f84-af27-b8d3f7d97ada');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6915a4c-7944-5481-b8b3-6baf9810b284','Surface wave','A seismic wave that travels along the Earth''s surface with amplitude decaying with depth, arising from the interaction of body waves with the free surface. The two main types are Rayleigh waves, with retrograde elliptical particle motion in a vertical plane, and Love waves, with horizontal motion transverse to propagation. Slower than body waves but often the largest in amplitude, surface waves are dispersive, so their speed varies with period, which is exploited to probe crustal structure.','Surface waves travel along the ground''s outer skin. Their motion fades with depth. They arrive after the P and S waves. Yet they are often the largest and most damaging. Because their speed changes with period, they reveal the layers below.','Their large amplitude drives much earthquake shaking damage, and their dispersion, with speed depending on period, makes them a primary tool for imaging crustal and upper-mantle structure.','Seismologists analyse surface-wave dispersion to build crustal velocity models, while engineers use it to assess ground stiffness and estimate shaking hazard at a site.','Geologic & Seismoacoustics',ARRAY['P-wave','S-wave','Rayleigh wave','Love wave','Ambient-noise tomography']::text[],ARRAY['Assuming surface waves penetrate deep, when their energy is concentrated near the surface','Ignoring dispersion, which is the very property that makes them useful for imaging','Confusing Rayleigh and Love waves, which have different particle motions']::text[],ARRAY['Inverting dispersion to image the crust','Assessing earthquake shaking hazard at a soft-soil site','Extracting surface waves from ambient noise between stations']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6915a4c-7944-5481-b8b3-6baf9810b284','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6915a4c-7944-5481-b8b3-6baf9810b284') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6915a4c-7944-5481-b8b3-6baf9810b284');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd97f62b3-25b8-5596-b591-1281a8130429','Raypath tomography','A seismic imaging method that reconstructs the spatial distribution of wave speed by inverting travel times of many waves crossing a region along ray paths. Under the high-frequency ray approximation, each travel time is the integral of slowness along its path, and the collected paths form a linear system solved for the velocity structure. Dense, crossing ray coverage improves resolution. It is used from engineering and reservoir scales up to whole-Earth mantle imaging.','Raypath tomography builds a speed map of the underground. It uses the travel times of many waves crossing the area. Each wave follows a path, like a ray of light. Waves that cross from many angles pin down the speeds. The result is an image, much like a medical scan.','It converts many travel-time measurements into a three-dimensional velocity model, revealing structures such as slabs, magma bodies, and reservoirs that alter wave speed.','Geophysicists invert earthquake and survey travel times for velocity models to image the mantle, map magma storage under volcanoes, and characterise reservoirs.','Geologic & Seismoacoustics',ARRAY['Ambient-noise tomography','Formation slowness','P-wave','Seismic interferometry','Elastic wave']::text[],ARRAY['Trusting an image where ray coverage is sparse or paths do not cross','Ignoring that the ray approximation assumes high frequency and can miss finite-frequency effects','Forgetting that a wrong starting model can bias the inversion']::text[],ARRAY['Imaging a subducting slab from earthquake travel times','Mapping magma storage beneath a volcano','Characterising a reservoir with crosswell travel times']::text[],'advanced','t = ∫ s dl','Travel time equals the integral of slowness along the ray path.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Raypath tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd97f62b3-25b8-5596-b591-1281a8130429','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d97f62b3-25b8-5596-b591-1281a8130429') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d97f62b3-25b8-5596-b591-1281a8130429');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '350fc17f-e168-5a40-8374-3f10ed06d81d','Ambient-noise tomography','A tomographic method that images subsurface velocity structure using surface waves extracted from continuous ambient seismic noise rather than earthquakes or active sources. Cross-correlating long records of ambient noise, mostly microseisms, between station pairs recovers the surface-wave response, or empirical Green''s function, between them. Dispersion measured from many pairs is then inverted for velocity structure. Because it needs no earthquakes, it gives dense, even coverage, including in aseismic regions.','This method images the underground using background seismic noise. Ocean-driven microseisms supply most of that noise. Comparing noise between two stations recovers the wave that would travel between them. Many station pairs give dense coverage. It needs no earthquakes at all.','It removes the reliance on earthquakes or active sources, so velocity structure can be imaged anywhere stations exist, including quiet regions, using the ever-present noise field.','Seismologists cross-correlate ambient noise across arrays to map crustal structure, monitor volcanoes, and image basins, obtaining coverage that earthquake data alone cannot provide.','Geologic & Seismoacoustics',ARRAY['Seismic interferometry','Seismic ambient noise','Surface wave','Microseism','Raypath tomography']::text[],ARRAY['Assuming a single short record suffices, when long stacks are needed to recover the signal','Ignoring uneven noise sources, which can bias the recovered waves','Treating the recovered function as an exact rather than an approximate Green''s function']::text[],ARRAY['Imaging crustal structure across a dense station array','Monitoring velocity changes at a volcano over time','Mapping a sedimentary basin without local earthquakes']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient-noise tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '350fc17f-e168-5a40-8374-3f10ed06d81d','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='350fc17f-e168-5a40-8374-3f10ed06d81d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='350fc17f-e168-5a40-8374-3f10ed06d81d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bdf7af50-100c-557b-a290-e0f828dc9336','Seismic interferometry','A technique that reconstructs the seismic response between two receivers as if one were a source, by cross-correlating the wavefields they record from ambient noise or distributed sources. The result approximates the Green''s function, the signal that would travel directly between the two points. It underlies ambient-noise tomography and passive monitoring, turning receivers into virtual sources and enabling imaging and time-lapse studies without a controlled source.','Seismic interferometry makes one sensor act like a source. It does this by comparing what two sensors record. The comparison recovers the wave that would travel between them. This turns receivers into virtual sources. It allows imaging without firing any real source.','It creates virtual sources from existing recordings, so the response between points can be obtained from noise alone, which is the basis of ambient-noise imaging and monitoring.','Geophysicists apply seismic interferometry to ambient noise to build velocity models, monitor time-lapse changes at volcanoes and reservoirs, and image without active shots.','Geologic & Seismoacoustics',ARRAY['Ambient-noise tomography','Seismic ambient noise','Passive seismic monitoring','Surface wave','Microseism']::text[],ARRAY['Expecting a perfect Green''s function, when the result is an approximation from real noise','Ignoring the need for well-distributed sources or long averaging','Confusing the virtual source with a real physical source at the receiver']::text[],ARRAY['Turning a station into a virtual source for imaging','Detecting time-lapse velocity change from repeated noise correlations','Building a crustal model without active shots']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bdf7af50-100c-557b-a290-e0f828dc9336','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bdf7af50-100c-557b-a290-e0f828dc9336') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bdf7af50-100c-557b-a290-e0f828dc9336');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d61c0d5-ebbc-59ae-a149-1faa4da9a463','Seismic ambient noise','The continuous background ground vibration present everywhere, produced mainly by ocean waves, which generate microseisms, and at higher frequencies by wind, weather, and human activity. Long treated only as noise that limits detection of small earthquakes, it is now recognised as a coherent wavefield that can be processed by interferometry and tomography to image the subsurface and monitor change. Its character varies with location, frequency, and time of day.','Seismic ambient noise is the ground''s constant background hum. Ocean waves make most of it. Wind, weather, and traffic add higher-frequency noise. Once seen only as a nuisance, it is now a useful signal. Special methods turn it into images of the underground.','It is both the noise floor that limits earthquake detection and, when processed coherently, a rich signal source for imaging and monitoring the Earth without active sources.','Analysts characterise ambient noise to set detection thresholds and site quality, and exploit it through interferometry for tomography and time-lapse monitoring.','Geologic & Seismoacoustics',ARRAY['Microseism','Seismic interferometry','Ambient-noise tomography','Secondary microseism','Passive seismic monitoring']::text[],ARRAY['Viewing ambient noise only as a nuisance, when it carries usable structural information','Assuming it is uniform, when it varies with location, frequency, and time','Ignoring cultural noise that can dominate the higher-frequency band']::text[],ARRAY['Assessing a candidate seismic station site for noise level','Using ambient noise for interferometric imaging','Tracking daily cultural noise cycles in a city']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic ambient noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d61c0d5-ebbc-59ae-a149-1faa4da9a463','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d61c0d5-ebbc-59ae-a149-1faa4da9a463') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d61c0d5-ebbc-59ae-a149-1faa4da9a463');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd3a410b6-2f37-5fd7-937d-e0be3649dda4','Volcanic tremor','A sustained seismic signal at volcanoes, lasting minutes to days, unlike the brief pulses of discrete earthquakes. Typically concentrated in a band from about one to a few hertz, it is generated by continuous processes such as fluid and gas movement, magma flow, and pressure fluctuations in the conduit and shallow system. Changes in its amplitude and frequency often accompany changes in eruptive activity, making it a key monitoring signal.','Volcanic tremor is a long, steady shaking at volcanoes. It can last minutes, hours, or even days. Moving magma, gas, and fluids cause it. Its strength often rises before or during an eruption. So observers watch it closely for warnings.','Its sustained character reflects ongoing fluid and magma processes, so tracking its strength and frequency helps observers follow unrest and anticipate eruptions.','Volcano observatories monitor tremor amplitude and frequency in real time, using increases and shifts as indicators of rising activity for alerts and forecasts.','Geologic & Seismoacoustics',ARRAY['Harmonic tremor','Volcano infrasound','Tornillo','Lahar infrasound','Seismic ambient noise']::text[],ARRAY['Confusing sustained tremor with a discrete volcanic earthquake','Assuming tremor always means imminent eruption, when it can also accompany quieter unrest','Ignoring frequency changes, which can be as informative as amplitude changes']::text[],ARRAY['Raising an alert as tremor amplitude climbs before an eruption','Tracking tremor to follow magma movement','Distinguishing tremor from background noise at a restless volcano']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volcanic tremor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd3a410b6-2f37-5fd7-937d-e0be3649dda4','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d3a410b6-2f37-5fd7-937d-e0be3649dda4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d3a410b6-2f37-5fd7-937d-e0be3649dda4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85e8ce5a-036c-5cc2-808e-d5492bfd1a75','Harmonic tremor','A form of volcanic tremor whose spectrum shows a fundamental frequency with overtones at integer multiples, giving a regular, tone-like character. It is commonly attributed to resonance of fluid-filled cracks or conduits, or to repeating pressure pulses whose regular spacing sets the fundamental, and its frequencies can shift, or glide, as conditions in the system change. Such spectral structure and gliding are used to infer conduit and fluid processes during unrest.','Harmonic tremor is volcanic tremor with a clear musical tone. Its spectrum shows one main pitch plus evenly spaced overtones. Resonance in fluid-filled cracks or steady pulses can make it. Its pitch can slide up or down over time. These changes hint at what the conduit is doing.','Its ordered spectrum links the signal to resonance or regular pulsing in the volcanic plumbing, so its frequencies and their gliding constrain conduit and fluid behaviour.','Volcanologists analyse harmonic tremor spectra and frequency gliding to infer conduit geometry, fluid activity, and evolving conditions during eruptive episodes.','Geologic & Seismoacoustics',ARRAY['Volcanic tremor','Tornillo','Volcano infrasound','Spectral decomposition','Resonance']::text[],ARRAY['Assuming the overtones are unrelated tones, when they are integer multiples of a fundamental','Ignoring frequency gliding, which records changing conduit conditions','Treating every tremor as harmonic, when many lack clear spectral peaks']::text[],ARRAY['Identifying evenly spaced spectral peaks in tremor','Tracking frequency gliding during an eruptive episode','Inferring conduit resonance from harmonic structure']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic tremor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85e8ce5a-036c-5cc2-808e-d5492bfd1a75','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85e8ce5a-036c-5cc2-808e-d5492bfd1a75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85e8ce5a-036c-5cc2-808e-d5492bfd1a75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f489d06-c1e1-55a5-a7ba-922a22cb002d','Tornillo','A type of long-period volcanic seismic event, named for the screw-like shape of its waveform, marked by a brief onset followed by a slowly decaying, nearly monochromatic tail lasting many seconds. The long, weakly damped ringing is interpreted as resonance of a fluid- or gas-filled crack or cavity, and swarms of tornillos have preceded eruptions at several volcanoes, making them a signal of interest in eruption forecasting.','A tornillo is a screw-shaped volcanic signal. It starts sharply, then rings on slowly for many seconds. The long ringing points to resonance in a gas-filled crack. Swarms of them have come before some eruptions. So observers treat them as warning signs.','Its slowly decaying tone marks resonance of a fluid-filled cavity, and clusters of such events can signal pressurised fluids and possible approaching eruption.','Volcano observatories flag tornillo events and swarms as potential precursors, examining their frequency and decay to infer fluid conditions during unrest.','Geologic & Seismoacoustics',ARRAY['Harmonic tremor','Volcanic tremor','Long-period event','Volcano infrasound','Resonance']::text[],ARRAY['Confusing a tornillo with a brief high-frequency volcano-tectonic earthquake','Assuming a single tornillo forecasts eruption, when swarms carry more weight','Overlooking its long, slowly decaying tail, which defines the event']::text[],ARRAY['Recognising screw-shaped events during volcanic unrest','Tracking a tornillo swarm as a possible precursor','Estimating cavity resonance from the decaying tail']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tornillo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f489d06-c1e1-55a5-a7ba-922a22cb002d','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f489d06-c1e1-55a5-a7ba-922a22cb002d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f489d06-c1e1-55a5-a7ba-922a22cb002d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e965913-c7c8-58d1-a133-192834c912b3','Lahar infrasound','Low-frequency atmospheric sound radiated by a lahar, a volcanic mudflow or debris flow of water and volcanic material moving down a drainage. The turbulent, boulder-laden flow generates infrasound whose amplitude and duration track the flow as it advances. Detected with microbarometers along the channel, often together with the flow''s seismic signal, lahar infrasound supports remote detection and early warning downstream of an advancing, hazardous flow.','A lahar is a fast volcanic mudflow full of rocks and water. As it roars downslope it makes low sound we cannot hear. Pressure sensors along the valley can detect this sound. The signal grows as the flow passes. This gives warning to people downstream.','It provides a remotely detectable signature of an advancing lahar, enabling automatic detection and downstream warning before the deadly flow arrives.','Volcano-hazard programmes place microbarometers and seismic sensors along lahar-prone drainages to detect flows in real time and trigger downstream alerts.','Geologic & Seismoacoustics',ARRAY['Volcano infrasound','Debris-flow seismic signal','Microbarometer','Volcanic tremor','Landslide acoustic signal']::text[],ARRAY['Assuming lahar sound is audible, when its key energy lies below human hearing','Relying on one sensor, when a channel-spanning network gives earlier, surer warning','UNSAFE: entering a lahar-prone channel to service a sensor during unrest without an evacuation plan and lookout']::text[],ARRAY['Detecting an advancing lahar to warn a downstream town','Timing a flow front from sensors along the channel','Combining infrasound and seismic signals to confirm a lahar']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lahar infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e965913-c7c8-58d1-a133-192834c912b3','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e965913-c7c8-58d1-a133-192834c912b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e965913-c7c8-58d1-a133-192834c912b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5ecfd9a-8323-5e5a-bb08-1bb8cfec7ce9','Debris-flow seismic signal','The ground vibration produced as a debris flow of water, sediment, and boulders moves down a channel, generated by basal friction, particle impacts, and turbulence. It typically appears as an emergent, spindle-shaped signal in a broad frequency band, whose amplitude rises and falls with the passage of the flow front and body. Recorded by seismometers or geophones beside the channel, it enables remote detection, front tracking, and warning.','A debris flow is a slurry of water, mud, and boulders rushing downhill. Its friction and impacts shake the ground. A seismometer by the channel records this shaking. The signal swells as the flow passes and fades after. This lets people detect and track the flow from a distance.','It gives a channel-side, remotely sensed record of a passing debris flow, supporting detection, tracking of the flow front, and warning without contact with the hazardous flow.','Hazard monitors install geophones along debris-flow channels to detect events, estimate flow timing and size from signal amplitude, and trigger downstream alerts.','Geologic & Seismoacoustics',ARRAY['Lahar infrasound','Landslide acoustic signal','Rockfall seismic signature','Microseismic event','Surface wave']::text[],ARRAY['Confusing the emergent debris-flow signal with an impulsive earthquake arrival','Estimating flow size from amplitude without accounting for sensor distance','Assuming a single station can locate the flow, when several improve tracking']::text[],ARRAY['Detecting a debris flow from a channel-side geophone','Tracking a flow front along an instrumented channel','Estimating flow magnitude from seismic amplitude']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Debris-flow seismic signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5ecfd9a-8323-5e5a-bb08-1bb8cfec7ce9','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5ecfd9a-8323-5e5a-bb08-1bb8cfec7ce9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5ecfd9a-8323-5e5a-bb08-1bb8cfec7ce9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d2e7bd7-ec4c-5c10-b56a-610d92156722','Cryoseism','A ground-shaking event, also called a frost quake, produced by the sudden cracking of frozen ground or ice when water-saturated soil or rock freezes rapidly and expands. Occurring during sharp cold snaps, it releases built-up stress in a brittle fracture that can produce audible booms and local shaking, but no tectonic fault slip. Cryoseisms are shallow and highly localised, and are sometimes mistaken for small earthquakes.','A cryoseism is a frost quake. It happens when wet ground freezes fast and cracks. The cracking can make a loud boom and brief shaking. It comes from ice, not from a moving fault. People sometimes mistake it for a small earthquake.','It names a cold-weather cracking process distinct from tectonic earthquakes, so such shallow booms and shaking are correctly attributed to freezing rather than faulting.','Seismic analysts and observatories identify cryoseisms during cold snaps to explain reports of booms and shaking that are not tectonic earthquakes.','Geologic & Seismoacoustics',ARRAY['Icequake','Microseismic event','Rockfall seismic signature','Elastic wave','Glacier infrasound']::text[],ARRAY['Mistaking a cryoseism for a tectonic earthquake, when no fault slip is involved','Assuming it occurs anytime, when it needs rapid freezing of saturated ground','Expecting deep sources, when cryoseisms are shallow and very local']::text[],ARRAY['Explaining booms reported during a sudden hard freeze','Distinguishing a frost quake from a small earthquake on records','Mapping shallow, localised cold-weather cracking']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cryoseism');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d2e7bd7-ec4c-5c10-b56a-610d92156722','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d2e7bd7-ec4c-5c10-b56a-610d92156722') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d2e7bd7-ec4c-5c10-b56a-610d92156722');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'efd2b386-6928-5f72-b41c-9dc619b3a1a1','Icequake','A seismic event generated within a glacier or ice sheet by fracturing, stick-slip sliding at the base, crevasse opening, or calving, rather than by tectonic faulting. Icequakes span a wide range of sizes and frequencies and are recorded on seismometers placed on or near the ice. Their locations, rates, and mechanisms are used to study glacier motion, basal conditions, crevassing, and calving, making them a core tool of glacier seismology.','An icequake is a quake inside a glacier or ice sheet. Cracking, sliding, and calving ice cause it, not moving faults. Seismometers on or near the ice record these events. Their pattern reveals how the ice moves and breaks. Studying them helps track glacier behaviour.','It provides a seismic window into glacier processes, letting basal sliding, crevassing, and calving be detected and monitored remotely and continuously.','Glaciologists deploy seismometers on ice to record icequakes, using their locations and timing to study basal slip, crevasse activity, and calving rates.','Geologic & Seismoacoustics',ARRAY['Glacier infrasound','Cryoseism','Microseismic event','Avalanche infrasound','Elastic wave']::text[],ARRAY['Confusing an icequake with a tectonic earthquake, when its source is within the ice','Assuming all icequakes are tiny, when calving events can be large','Treating one mechanism as universal, when several distinct ice processes produce them']::text[],ARRAY['Detecting basal stick-slip beneath a fast-moving glacier','Monitoring calving activity at an ice front','Mapping crevasse opening from icequake locations']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Icequake');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'efd2b386-6928-5f72-b41c-9dc619b3a1a1','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='efd2b386-6928-5f72-b41c-9dc619b3a1a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='efd2b386-6928-5f72-b41c-9dc619b3a1a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '620397e1-2e60-54b7-8d28-da7a1a569c12','Glacier infrasound','Low-frequency atmospheric sound radiated by glacial processes such as calving, crevasse fracture, ice-quake activity, and meltwater flow. Detected with microbarometers near glaciers and ice sheets, often alongside seismic records, it offers a remote acoustic measure of ice dynamics. Because sound propagates efficiently through the atmosphere, infrasound can monitor calving fronts and other ice activity from a distance and in conditions where direct observation is difficult.','Glaciers make low sound as they crack, calve, and drain meltwater. This sound is too deep for us to hear. Pressure sensors near the ice can record it. It lets scientists watch ice activity from afar. This works even when the ice front is hard to see.','It supplies a remote, continuous acoustic signal of ice processes, complementing seismic data and enabling monitoring of calving and other activity from a safe distance.','Researchers place microbarometers near calving fronts and ice sheets to detect and quantify calving and fracturing, pairing infrasound with seismometers.','Geologic & Seismoacoustics',ARRAY['Icequake','Avalanche infrasound','Microbarometer','Volcano infrasound','Cryoseism']::text[],ARRAY['Assuming glacial sound is audible, when much of its energy is infrasonic','Relying on infrasound alone, when pairing with seismic data is more informative','Ignoring wind noise, which can mask faint glacier infrasound']::text[],ARRAY['Detecting calving events at a remote ice front','Quantifying crevasse fracture activity acoustically','Monitoring an ice sheet where direct observation is limited']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Glacier infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '620397e1-2e60-54b7-8d28-da7a1a569c12','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='620397e1-2e60-54b7-8d28-da7a1a569c12') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='620397e1-2e60-54b7-8d28-da7a1a569c12');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '967302ad-d7e0-50e5-bcce-071cd67a3b94','Avalanche infrasound','Low-frequency atmospheric sound produced by a moving snow avalanche, generated by the turbulent powder cloud and the flowing dense core as they rush downslope. Detected by microbarometers or arrays, often kilometres away, it allows avalanches to be identified and timed in real time and in poor visibility. Signal characteristics relate to avalanche size and type, supporting remote detection, automatic cataloguing, and warning in mountain terrain.','A snow avalanche makes low sound as it rushes downhill. This infrasound travels far through the air. Sensors can detect it even kilometres away. It works at night and in storms. This helps spot and time avalanches when no one can see them.','It enables remote, all-weather detection and timing of avalanches, providing an objective record where visual observation fails, for warning and research.','Avalanche services deploy infrasound arrays to detect and catalogue avalanches automatically, supporting road safety decisions and hazard forecasting in mountains.','Geologic & Seismoacoustics',ARRAY['Glacier infrasound','Rockfall seismic signature','Microbarometer','Infrasonic array','Landslide acoustic signal']::text[],ARRAY['Assuming avalanche sound is audible, when the diagnostic energy is infrasonic','Expecting a single sensor to locate the avalanche, when an array is needed for direction','Ignoring wind noise, which can obscure the signal in exposed terrain']::text[],ARRAY['Detecting avalanches over a road corridor at night','Automatically cataloguing avalanche activity in a range','Timing an avalanche during a storm with no visibility']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Avalanche infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '967302ad-d7e0-50e5-bcce-071cd67a3b94','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='967302ad-d7e0-50e5-bcce-071cd67a3b94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='967302ad-d7e0-50e5-bcce-071cd67a3b94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd37eff2-2c18-58d2-8b98-3409a05b93f2','Rockfall seismic signature','The characteristic ground vibration produced when rock detaches and falls, bounces, and rolls down a slope, each impact radiating seismic energy. It typically appears as an emergent, often spindle-shaped signal, richer in higher frequencies than an equivalent earthquake and lacking clear P- and S-wave arrivals, with amplitude reflecting the sequence of impacts. Recorded on nearby seismometers, it allows rockfalls to be detected, located, and sized remotely.','Falling rock shakes the ground each time it hits the slope. This makes a distinct seismic signal. It builds and fades instead of starting sharply. It lacks the clear P and S arrivals of an earthquake. Sensors use this pattern to detect and size rockfalls.','Its distinctive emergent, high-frequency form lets rockfalls be told apart from earthquakes and detected remotely, supporting slope-hazard monitoring.','Slope and infrastructure monitors use seismometers to detect rockfalls, distinguish them from earthquakes by waveform, and estimate their timing and size.','Geologic & Seismoacoustics',ARRAY['Landslide acoustic signal','Debris-flow seismic signal','Rock acoustic emission','Microseismic event','Surface wave']::text[],ARRAY['Mistaking a rockfall signal for an earthquake despite its lack of clear P and S phases','Estimating size from amplitude without correcting for distance','Assuming a single impact, when the signal records many bounces']::text[],ARRAY['Detecting rockfalls above a monitored road or rail line','Separating rockfalls from earthquakes in a catalogue','Estimating rockfall volume from seismic amplitude']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rockfall seismic signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd37eff2-2c18-58d2-8b98-3409a05b93f2','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd37eff2-2c18-58d2-8b98-3409a05b93f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd37eff2-2c18-58d2-8b98-3409a05b93f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2deb6f81-1d7b-552d-a2b4-b06a309c5ffa','Landslide acoustic signal','The seismic and, in some cases, infrasonic energy radiated by a landslide as the failing mass detaches, accelerates, and flows across the ground. Large landslides produce long-period seismic signals from the bulk force of the sliding mass, alongside higher-frequency energy from internal fragmentation and impacts, and can generate infrasound. Analysis of these signals allows remote detection, location, timing, and estimation of landslide volume and dynamics, even in remote terrain.','A landslide sends waves into the ground and sometimes the air as it moves. The sliding mass makes slow, long waves. Breaking and impacts add faster shaking. Sensors far away can record all of this. From it, scientists find the slide''s time, place, and size.','It makes landslides remotely observable, so their occurrence, location, and dynamics can be determined from distant sensors, even where no one witnesses the failure.','Geoscientists analyse long-period seismic signals and infrasound to detect and locate large landslides worldwide, and to reconstruct their volume and motion.','Geologic & Seismoacoustics',ARRAY['Rockfall seismic signature','Debris-flow seismic signal','Acoustic fluidization','Surface wave','Lahar infrasound']::text[],ARRAY['Ignoring the long-period signal that reveals the bulk sliding force','Assuming only local sensors help, when large slides are seen globally','Estimating volume from amplitude without proper modelling']::text[],ARRAY['Detecting a large remote landslide from distant seismometers','Reconstructing slide dynamics from long-period signals','Combining seismic and infrasound records to confirm a failure']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Landslide acoustic signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2deb6f81-1d7b-552d-a2b4-b06a309c5ffa','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2deb6f81-1d7b-552d-a2b4-b06a309c5ffa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2deb6f81-1d7b-552d-a2b4-b06a309c5ffa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd507e576-2304-5ff7-9a64-5172f14f875b','Acoustic fluidization','A proposed mechanism in which strong acoustic pressure fluctuations within a granular or fractured mass momentarily relieve overburden stress at grain contacts, temporarily reducing internal friction and allowing the mass to flow more easily. Invoked to explain the long runout of large landslides and rock avalanches and the behaviour of fault gouge and impact-crater collapse, it remains a debated hypothesis rather than a settled, directly measured process.','Acoustic fluidization is a proposed way granular material flows more easily. Strong vibrations inside the mass briefly ease the pressure between grains. This lowers friction for a moment. The loosened mass can then slide farther. It is a debated idea used to explain very long landslide runouts.','It offers a physical explanation for why some large landslides travel much farther than simple friction predicts, by proposing that internal vibration transiently weakens the mass.','Researchers invoke acoustic fluidization in models of long-runout landslides, rock avalanches, and fault behaviour, testing it against observed mobility and signals.','Geologic & Seismoacoustics',ARRAY['Landslide acoustic signal','Debris-flow seismic signal','Rock acoustic emission','Elastic wave','Fault gouge']::text[],ARRAY['Presenting acoustic fluidization as established fact, when it remains a debated hypothesis','Confusing it with pore-fluid pressure, which is a distinct weakening mechanism','Assuming it applies to every long-runout landslide without evidence']::text[],ARRAY['Explaining the unusually long runout of a rock avalanche','Testing landslide-mobility models against the mechanism','Discussing candidate weakening processes in fault zones']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic fluidization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd507e576-2304-5ff7-9a64-5172f14f875b','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d507e576-2304-5ff7-9a64-5172f14f875b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d507e576-2304-5ff7-9a64-5172f14f875b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bb8d5f2-3c09-584c-8c8c-c38566737c13','Elastic wave','A disturbance that propagates through a solid or fluid by the elastic deformation of the medium, in which particles oscillate about equilibrium and restoring forces transmit energy without net transport of material. In the Earth, elastic waves include compressional and shear body waves and surface waves, all governed by the elastodynamic equations relating stress, strain, and density. Seismic waves are elastic waves, and their speeds depend on the elastic moduli and density of the rock.','An elastic wave travels through matter by tiny stretches and squeezes. Each particle wobbles in place and passes energy on. The material itself does not move along with the wave. Seismic waves are elastic waves in rock. Their speed depends on how stiff and dense the rock is.','It is the general physical basis for all seismic waves, so understanding elastic waves underpins how energy from earthquakes and sources travels through the Earth.','Seismologists model elastic-wave propagation to interpret earthquake records, image the subsurface, and predict how energy from a source will reach a site.','Geologic & Seismoacoustics',ARRAY['P-wave','S-wave','Surface wave','Guided wave','Seismic acoustic impedance']::text[],ARRAY['Thinking the medium travels with the wave, when only the disturbance moves','Assuming fluids carry shear elastic waves, when they support only compressional ones','Treating wave speed as fixed, when it depends on the medium''s stiffness and density']::text[],ARRAY['Modelling how earthquake energy travels to a station','Explaining why P and S waves differ in speed and motion','Predicting site response from elastic properties']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elastic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bb8d5f2-3c09-584c-8c8c-c38566737c13','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bb8d5f2-3c09-584c-8c8c-c38566737c13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bb8d5f2-3c09-584c-8c8c-c38566737c13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '578eb5a0-89d5-5fb8-b3d2-8194fd8b35eb','Guided wave','An elastic or acoustic wave confined to and channelled along a layer, interface, or waveguide by reflections at boundaries, so that energy travels efficiently along the structure with limited spreading. Guided waves are dispersive, with speed depending on frequency, and include surface waves, channel waves in coal seams, tube waves in boreholes, and waves trapped in low-velocity or high-velocity zones. Their confinement and dispersion carry information about the guiding structure.','A guided wave is trapped inside a layer or channel. Boundaries reflect its energy and keep it confined. So it travels far along the structure with little spreading. Its speed changes with frequency. That behaviour reveals the shape and properties of the guide.','By confining energy to a structure, guided waves probe that structure efficiently and reveal its properties through their dispersion and confinement.','Geophysicists use guided waves such as coal-seam channel waves and borehole tube waves to detect layer continuity, fractures, and structural changes.','Geologic & Seismoacoustics',ARRAY['Surface wave','Tube wave','Elastic wave','Dispersion','Borehole acoustic logging']::text[],ARRAY['Assuming guided waves spread like body waves, when confinement limits their spreading','Ignoring dispersion, which is central to how guided waves behave','Treating all trapped waves as identical, when different guides give different modes']::text[],ARRAY['Using coal-seam channel waves to check seam continuity','Analysing borehole tube waves for fractures','Detecting a low-velocity waveguide from trapped energy']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Guided wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '578eb5a0-89d5-5fb8-b3d2-8194fd8b35eb','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='578eb5a0-89d5-5fb8-b3d2-8194fd8b35eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='578eb5a0-89d5-5fb8-b3d2-8194fd8b35eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5eac36e-48dd-5a75-a068-feddb1a11974','Tube wave','A low-frequency guided wave that travels along a fluid-filled borehole as a coupled motion of the fluid column and the borehole wall, the lowest-order Stoneley mode. Slower than the formation body waves and only weakly dispersive, it is a strong, slow arrival in acoustic logging. Because its behaviour is sensitive to open fractures and to formation permeability, tube waves are used to detect fractures and estimate permeability, though they can also mask other arrivals.','A tube wave runs along a fluid-filled borehole. It couples the fluid and the borehole wall together. It moves slower than waves in the surrounding rock. It reacts strongly to open fractures. So loggers use it to find fractures and gauge how fluids flow.','Its sensitivity to fractures and permeability makes the tube wave a diagnostic borehole arrival, while its strength and slowness must also be recognised to avoid confusing other phases.','Borehole geophysicists analyse tube waves in acoustic logs to detect open fractures and estimate permeability, and account for them when interpreting other arrivals.','Geologic & Seismoacoustics',ARRAY['Guided wave','Borehole acoustic logging','Stoneley wave','Full-waveform sonic logging','Formation slowness']::text[],ARRAY['Confusing the slow tube wave with a formation body-wave arrival','Ignoring its sensitivity to fractures, a key diagnostic use','Overlooking how strongly it can mask weaker arrivals in a log']::text[],ARRAY['Detecting open fractures from tube-wave behaviour in a log','Estimating permeability from tube-wave attenuation','Separating tube waves from formation arrivals in processing']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tube wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5eac36e-48dd-5a75-a068-feddb1a11974','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5eac36e-48dd-5a75-a068-feddb1a11974') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5eac36e-48dd-5a75-a068-feddb1a11974');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2b85668-10b0-5020-9893-1937430760d0','Borehole acoustic logging','A well-logging method in which a tool lowered into a borehole emits acoustic pulses and records the waves that travel through the surrounding formation and along the borehole. From the arrival times and waveforms of compressional, shear, and guided modes, it yields formation slowness, elastic properties, porosity indicators, and fracture information versus depth. It is a standard technique in petroleum, mining, geotechnical, and groundwater investigations.','Borehole acoustic logging sends sound pulses into rock from inside a well. A tool records the waves that come back. The travel times reveal how fast waves move in the rock. From that, engineers learn stiffness, porosity, and fractures. It is measured all the way down the hole.','It measures the acoustic and elastic properties of rock around a borehole with depth, supplying data for porosity, rock strength, fracture detection, and tying wells to surface seismic surveys.','Logging engineers run acoustic tools in wells to obtain slowness and elastic logs used for porosity, geomechanics, fracture detection, and seismic-to-well ties.','Geologic & Seismoacoustics',ARRAY['Sonic log','Full-waveform sonic logging','Formation slowness','Tube wave','Dipole sonic logging']::text[],ARRAY['Assuming the log measures the borehole fluid, when it targets the surrounding formation','Ignoring borehole conditions, which can distort the measured arrivals','Treating a single mode as sufficient, when compressional, shear, and guided waves each add information']::text[],ARRAY['Logging a well to obtain porosity and rock strength','Detecting fractures from acoustic waveforms with depth','Tying well logs to a surface seismic survey']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Borehole acoustic logging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2b85668-10b0-5020-9893-1937430760d0','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2b85668-10b0-5020-9893-1937430760d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2b85668-10b0-5020-9893-1937430760d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5062f79e-e97e-5f8e-840b-5d2d77e2131f','Sonic log','A borehole log that records the time for an acoustic pulse to travel a fixed distance through the formation beside the well, reported as interval transit time, or slowness, versus depth. Measured by a tool with transmitters and spaced receivers, it yields compressional and often shear slowness, from which porosity, elastic properties, and integrated travel time for seismic ties are derived. It is one of the most widely run logs in petroleum and geotechnical work.','A sonic log times how fast sound crosses the rock beside a well. It records this travel time all the way down. Slow travel usually means more pore space. Fast travel means dense, hard rock. Engineers use it to estimate porosity and rock strength.','It provides a continuous depth profile of formation slowness, the basic input for estimating porosity, computing elastic properties, and tying well data to surface seismic.','Petrophysicists read sonic logs to estimate porosity and rock strength and to build the velocity profile used to tie well depths to seismic travel times.','Geologic & Seismoacoustics',ARRAY['Borehole acoustic logging','Formation slowness','Full-waveform sonic logging','Dipole sonic logging','Seismic acoustic impedance']::text[],ARRAY['Reading the log as velocity, when it records transit time, the reciprocal of velocity','Ignoring borehole washouts, which bias the measured slowness','Assuming compressional slowness alone gives shear properties without a shear measurement']::text[],ARRAY['Estimating porosity from interval transit time','Building a velocity profile for a seismic-to-well tie','Flagging washout zones that distort the log']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic log');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5062f79e-e97e-5f8e-840b-5d2d77e2131f','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5062f79e-e97e-5f8e-840b-5d2d77e2131f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5062f79e-e97e-5f8e-840b-5d2d77e2131f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7eeb49e-c909-5b3b-9aca-1f41ff6cb7f1','Acoustic televiewer','A borehole imaging tool that rotates a focused ultrasonic beam to scan the borehole wall, recording the amplitude and travel time of the reflected pulse at each angle and depth. The result is an oriented, unwrapped image of the wall in which fractures, bedding, and breakouts appear, along with a caliper of borehole shape. Working in any fluid-filled hole, it maps the orientation and character of fractures and stress-induced features.','An acoustic televiewer scans the wall of a borehole with a spinning sound beam. It measures the echo strength and timing all around. From this it builds a full picture of the wall. Fractures and cracks show up clearly. It also shows the direction those features point.','It produces an oriented acoustic image of the borehole wall, so fractures, bedding, and stress-related breakouts can be mapped in direction and depth.','Geologists and geotechnical engineers run acoustic televiewers to log fracture orientation, bedding, and borehole breakouts for structural and stress analysis.','Geologic & Seismoacoustics',ARRAY['Borehole acoustic logging','Sonic log','Full-waveform sonic logging','Borehole breakout','Fracture mapping']::text[],ARRAY['Confusing the wall image with a formation velocity measurement','Assuming it needs an empty hole, when it requires a fluid-filled borehole','Ignoring tool orientation, which is essential for reading feature direction']::text[],ARRAY['Mapping fracture orientation in a water-well or geotechnical hole','Identifying borehole breakouts to infer stress direction','Imaging bedding to determine dip in a borehole']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic televiewer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7eeb49e-c909-5b3b-9aca-1f41ff6cb7f1','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7eeb49e-c909-5b3b-9aca-1f41ff6cb7f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7eeb49e-c909-5b3b-9aca-1f41ff6cb7f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f3bf9ca-f303-58a0-87fe-8ac0098179b2','Full-waveform sonic logging','An acoustic logging method that records the complete received waveform at an array of receivers rather than only a first-arrival transit time, capturing compressional, shear, and guided modes such as the Stoneley wave. Array processing of these waveforms yields compressional and shear slowness, attenuation, and anisotropy, and supports fracture and permeability analysis. It extends the basic sonic log by using the full signal to characterise rock and fluid properties.','This method records the whole sound waveform in a borehole, not just its first arrival. That captures push-pull, shear, and tube waves together. Processing the full signal gives more rock properties. It reveals stiffness, cracks, and how fluids move. It is a richer version of a basic sonic log.','By keeping the entire waveform, it extracts far more than transit time, including shear slowness, attenuation, and anisotropy, for detailed rock and fluid characterisation.','Logging analysts process full-waveform sonic data to obtain shear and compressional slowness, detect fractures, and estimate permeability and anisotropy in wells.','Geologic & Seismoacoustics',ARRAY['Sonic log','Borehole acoustic logging','Dipole sonic logging','Tube wave','Formation slowness']::text[],ARRAY['Treating it as just a first-arrival log, when it uses the whole waveform','Ignoring guided modes like the Stoneley wave that carry permeability information','Assuming a single receiver suffices, when array processing is central to the method']::text[],ARRAY['Extracting shear slowness from array waveforms','Analysing Stoneley waves for permeability','Assessing anisotropy from full-waveform records']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Full-waveform sonic logging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f3bf9ca-f303-58a0-87fe-8ac0098179b2','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f3bf9ca-f303-58a0-87fe-8ac0098179b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f3bf9ca-f303-58a0-87fe-8ac0098179b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '643d162e-1d0c-57c2-a44e-b3cf642c13b5','Formation slowness','The reciprocal of acoustic wave velocity in a formation, expressed as travel time per unit distance, typically microseconds per foot or per metre, and the quantity a sonic log directly measures. High slowness corresponds to low velocity, as in porous or poorly consolidated rock, while low slowness marks fast, dense rock. Compressional and shear slowness together constrain porosity, elastic moduli, and lithology, and are basic inputs to petrophysics and geomechanics.','Slowness is how long sound takes to cross a set distance in rock. It is the inverse of speed. High slowness means the sound is slow, often in soft or porous rock. Low slowness means fast, dense rock. A sonic log measures this value directly.','It expresses formation velocity in the form a sonic tool measures, giving a direct, depth-continuous parameter for porosity, elastic properties, and rock typing.','Petrophysicists use compressional and shear slowness from sonic logs to compute porosity, elastic moduli, and impedance for reservoir and geomechanical analysis.','Geologic & Seismoacoustics',ARRAY['Sonic log','Borehole acoustic logging','Full-waveform sonic logging','Seismic acoustic impedance','P-wave']::text[],ARRAY['Confusing slowness with velocity, when it is the reciprocal of velocity','Assuming high slowness is an error, when it correctly marks slow, porous rock','Using compressional slowness where shear slowness is required']::text[],ARRAY['Converting sonic slowness to velocity for a seismic tie','Estimating porosity from measured slowness','Computing elastic moduli from compressional and shear slowness']::text[],'intermediate','s = 1/V','Formation slowness equals one divided by the acoustic wave velocity, giving travel time per unit distance.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formation slowness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '643d162e-1d0c-57c2-a44e-b3cf642c13b5','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='643d162e-1d0c-57c2-a44e-b3cf642c13b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='643d162e-1d0c-57c2-a44e-b3cf642c13b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1dc37409-18e8-5f4b-86f1-78c093367add','Dipole sonic logging','An acoustic logging technique that uses directional dipole transmitters to excite flexural waves along the borehole, enabling measurement of shear slowness even in slow formations where a monopole tool cannot directly obtain a shear arrival. With dipoles oriented in two directions, it measures shear-wave anisotropy and its orientation, revealing stress and fracture-induced directionality. It is central to modern geomechanics and fracture characterisation from wells.','Dipole sonic logging pushes the borehole sideways to send a flexing wave along it. This lets it measure shear speed even in soft, slow rock. A plain sonic tool cannot always do that. Using two directions, it detects if shear speed changes with direction. That directionality reveals stress and fractures.','It extends shear measurement to slow formations and reveals directional differences in shear speed, giving key inputs for stress and fracture analysis.','Geomechanics specialists run dipole sonic logs to obtain shear slowness in slow rock and to measure shear anisotropy for stress and fracture characterisation.','Geologic & Seismoacoustics',ARRAY['Sonic log','Full-waveform sonic logging','Formation slowness','Shear-wave anisotropy','Borehole acoustic logging']::text[],ARRAY['Assuming a monopole tool always yields shear slowness, when slow formations need a dipole source','Ignoring the two-direction measurement that reveals anisotropy','Treating measured anisotropy as noise rather than a stress and fracture indicator']::text[],ARRAY['Measuring shear slowness in a slow, unconsolidated formation','Detecting shear anisotropy to infer stress direction','Characterising fracture-induced directionality from a well']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole sonic logging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1dc37409-18e8-5f4b-86f1-78c093367add','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1dc37409-18e8-5f4b-86f1-78c093367add') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1dc37409-18e8-5f4b-86f1-78c093367add');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1d6359e-cee5-5422-97cf-f417889c3870','Acoustic impedance inversion','A seismic processing method that transforms reflection data, which respond to boundaries between layers, into a continuous profile of acoustic impedance, a layer property equal to density times velocity. By removing the wavelet and integrating reflectivity, usually constrained by well logs, inversion yields impedance volumes that relate more directly to rock and fluid properties such as porosity and lithology. It is widely used in reservoir characterisation to map properties between wells.','Seismic data mainly show the boundaries between rock layers. Impedance inversion turns those boundaries into a layer property instead. That property is impedance, the density times the wave speed. It relates closely to porosity and rock type. This helps map rock properties between wells.','It converts boundary-sensitive reflection data into a layer property that ties more directly to rock and fluid characteristics, improving reservoir interpretation between wells.','Reservoir geophysicists invert seismic reflections, constrained by well logs, to produce impedance volumes used to map porosity, lithology, and fluid distribution.','Geologic & Seismoacoustics',ARRAY['Seismic acoustic impedance','Seismic attribute','AVO','Sonic log','Spectral decomposition']::text[],ARRAY['Treating an inversion result as unique, when it depends on the wavelet and constraints','Ignoring well-log control, which stabilises the low-frequency trend','Confusing impedance, a layer property, with reflectivity, a boundary property']::text[],ARRAY['Mapping reservoir porosity from an impedance volume','Constraining an inversion with nearby well logs','Distinguishing lithology using inverted impedance']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance inversion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1d6359e-cee5-5422-97cf-f417889c3870','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1d6359e-cee5-5422-97cf-f417889c3870') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1d6359e-cee5-5422-97cf-f417889c3870');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b438c75b-f458-5e2d-9423-028b533fce58','Seismic acoustic impedance','The product of a rock''s bulk density and its seismic wave velocity, a fundamental property that governs how much acoustic energy reflects at an interface. The contrast in acoustic impedance between adjacent layers sets the reflection coefficient, so impedance controls the strength and polarity of seismic reflections. Derived from density and velocity logs or from seismic inversion, it links seismic amplitudes to rock and fluid properties such as porosity and lithology.','Acoustic impedance is a rock''s density times its wave speed. Where two layers differ in impedance, sound reflects at the boundary. A bigger contrast makes a stronger reflection. So impedance controls what a seismic survey sees. It ties seismic signals to rock properties.','It is the property whose contrast produces seismic reflections, so it links measured amplitudes to the physical rock and fluid properties that geophysicists want to map.','Geophysicists compute impedance from density and velocity logs, model reflections, and invert seismic data for impedance to characterise reservoirs and lithology.','Geologic & Seismoacoustics',ARRAY['Acoustic impedance inversion','Reflection coefficient','Seismic attribute','AVO','Formation slowness']::text[],ARRAY['Forgetting that reflections come from impedance contrast, not impedance alone','Using velocity without density, when impedance needs both','Assuming a strong reflection always means a large impedance increase, ignoring polarity']::text[],ARRAY['Predicting reflection strength from an impedance contrast','Computing impedance from density and sonic logs','Linking a bright seismic reflection to a rock-property change']::text[],'intermediate','Z = ρ·V','Acoustic impedance equals rock bulk density multiplied by seismic wave velocity.','03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic acoustic impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b438c75b-f458-5e2d-9423-028b533fce58','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b438c75b-f458-5e2d-9423-028b533fce58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b438c75b-f458-5e2d-9423-028b533fce58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db13406c-fe27-5f63-9f67-c6a659615869','AVO','Amplitude versus offset, the study of how the amplitude of a seismic reflection changes with source-to-receiver offset, and equivalently with the angle of incidence at the reflector. Governed by the Zoeppritz equations and their approximations, this variation depends on contrasts in compressional velocity, shear velocity, and density across the interface. Because gas and fluid changes affect these contrasts distinctively, AVO analysis is a primary tool for detecting hydrocarbons and characterising reservoir fluids and lithology.','AVO looks at how a reflection''s strength changes with distance between source and receiver. That distance sets the angle the wave hits the layer. The change depends on speed and density contrasts. Gas and fluids shift these contrasts in telltale ways. So AVO helps find gas and study reservoir fluids.','It uses the offset dependence of reflection amplitude to separate the velocity, shear, and density contributions, making it sensitive to fluid and lithology changes a single amplitude cannot reveal.','Exploration geophysicists analyse AVO on prestack seismic gathers to detect gas, distinguish fluids, and characterise reservoir lithology before drilling.','Geologic & Seismoacoustics',ARRAY['Seismic acoustic impedance','Reflection coefficient','Seismic attribute','Acoustic impedance inversion','S-wave']::text[],ARRAY['Analysing AVO on stacked data, when it requires prestack, offset-sorted gathers','Ignoring processing effects that distort true amplitudes','Treating an AVO anomaly as certain proof of gas without corroboration']::text[],ARRAY['Screening a prospect for a gas-related AVO anomaly','Distinguishing fluid types from offset amplitude trends','Calibrating AVO response against well control']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AVO');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db13406c-fe27-5f63-9f67-c6a659615869','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db13406c-fe27-5f63-9f67-c6a659615869') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db13406c-fe27-5f63-9f67-c6a659615869');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4797a04f-9f61-54ab-8553-ce2807595e1a','Seismic attribute','A quantity derived from seismic data to highlight features not obvious in the raw amplitudes, computed from the trace or a group of traces. Attributes include instantaneous measures such as amplitude, phase, and frequency, and multi-trace measures such as coherence, curvature, and dip. Used to reveal stratigraphy, faults, fractures, and fluid or lithology changes, they are central to seismic interpretation and reservoir characterisation, though they must be tied to geology to avoid over-interpretation.','A seismic attribute is a number pulled from seismic data to reveal hidden features. It can measure amplitude, phase, frequency, or how well nearby traces match. These help show faults, channels, and fluid changes. Interpreters use them to map the subsurface. They must be checked against real geology.','It transforms raw seismic data into measures that emphasise specific geological features, aiding interpretation of structure, stratigraphy, and reservoir properties.','Interpreters compute attributes such as coherence and instantaneous frequency to map faults, channels, and reservoir zones on seismic volumes.','Geologic & Seismoacoustics',ARRAY['Spectral decomposition','Acoustic impedance inversion','Seismic acoustic impedance','AVO','Coherence']::text[],ARRAY['Over-interpreting attributes without tying them to geology or well control','Assuming a striking attribute anomaly always reflects a real feature','Stacking many attributes without understanding what each measures']::text[],ARRAY['Mapping faults with a coherence attribute','Highlighting channels using instantaneous frequency','Screening a reservoir zone with multiple attributes']::text[],'intermediate',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic attribute');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4797a04f-9f61-54ab-8553-ce2807595e1a','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4797a04f-9f61-54ab-8553-ce2807595e1a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4797a04f-9f61-54ab-8553-ce2807595e1a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcb7799e-d9dc-59a2-91a1-a65f14adfa51','Spectral decomposition','A seismic analysis technique that resolves the data into its component frequencies as a function of time or depth, producing frequency-dependent amplitude volumes. Because thin layers and geological features respond differently at different frequencies, viewing the data frequency by frequency highlights thickness variations, channels, and stratigraphic detail below normal resolution. It uses time-frequency transforms such as the short-time Fourier, continuous wavelet, or matching-pursuit methods.','Spectral decomposition breaks seismic data into separate frequencies over time. Thin layers stand out more at some frequencies than others. Viewing the data one frequency at a time reveals hidden detail. This sharpens images of channels and thin beds. It uses time-frequency transforms to do so.','It exposes frequency-dependent responses of thin beds and features, revealing stratigraphic detail and thickness changes that broadband amplitude images blur together.','Interpreters apply spectral decomposition to image channels, map bed thickness, and detect subtle stratigraphic features and potential fluid effects in reservoirs.','Geologic & Seismoacoustics',ARRAY['Seismic attribute','Short-time Fourier transform','Acoustic impedance inversion','AVO','Harmonic tremor']::text[],ARRAY['Assuming one frequency shows everything, when different features favour different frequencies','Ignoring the time-frequency trade-off inherent in the transforms','Reading tuning effects as real geology without careful analysis']::text[],ARRAY['Imaging a buried channel at its optimal frequency','Mapping bed thickness from tuning behaviour','Detecting subtle stratigraphic features below normal resolution']::text[],'advanced',NULL,NULL,'03c488e9-47e6-4ec7-9aca-9d8aa42032a4' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcb7799e-d9dc-59a2-91a1-a65f14adfa51','03c488e9-47e6-4ec7-9aca-9d8aa42032a4',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcb7799e-d9dc-59a2-91a1-a65f14adfa51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcb7799e-d9dc-59a2-91a1-a65f14adfa51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4fb3acd-86f1-5c00-a5fb-52380b9aa684','Baryon acoustic oscillations','Baryon acoustic oscillations are the frozen imprint of sound waves that propagated in the hot photon-baryon plasma of the early universe before recombination. Radiation pressure from photons drove spherical density waves outward through the coupled fluid at the plasma sound speed; when recombination released the photons, the waves stalled and left a characteristic overdensity shell at the radius the sound had travelled, the sound horizon. This produces a preferred separation, near 150 megaparsecs comoving, that survives as a small excess in the galaxy two-point correlation function and as oscillatory features in the matter power spectrum.','Sound waves once moved through the hot early universe. They ran through a mix of light and matter. When space cooled, the waves froze in place. This left galaxies more likely to sit a set distance apart. Scientists use that fixed distance as a cosmic ruler.','It provides a standard ruler of known physical length set by early-universe physics, letting cosmologists measure cosmic distances and the expansion history from galaxy clustering.','Galaxy redshift surveys such as SDSS/BOSS and DESI detect the BAO feature in clustering statistics to measure the distance-redshift relation and constrain dark energy.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Acoustic scale','Photon-baryon fluid','Acoustic ruler','Drag epoch','CMB acoustic peak']::text[],ARRAY['Thinking the waves are ongoing sound today, when they froze at recombination','Confusing the comoving BAO scale with a fixed physical scale that ignores expansion','Assuming BAO appears in individual galaxies rather than in their statistical clustering']::text[],ARRAY['Measuring the cosmic distance scale from a galaxy redshift survey','Constraining dark energy with the standard ruler','Cross-checking distances inferred from the CMB']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baryon acoustic oscillations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4fb3acd-86f1-5c00-a5fb-52380b9aa684','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4fb3acd-86f1-5c00-a5fb-52380b9aa684') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4fb3acd-86f1-5c00-a5fb-52380b9aa684');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df4e996a-2caf-56c7-b0ee-0a9bf7f88576','Baryonic acoustic oscillations','A commonly used alternative name for baryon acoustic oscillations, the fossil sound waves of the pre-recombination photon-baryon plasma. Radiation pressure launched acoustic density waves that travelled outward until photons and baryons decoupled, freezing a preferred comoving scale equal to the sound horizon. That scale, near 150 megaparsecs, appears as a bump in the galaxy correlation function and as damped oscillations in the matter power spectrum, and serves as a standard ruler for cosmic distances.','This is another name for baryon acoustic oscillations. Sound waves moved through the hot young universe. They stopped when light and matter split apart. That left a set spacing printed into how galaxies cluster. Astronomers use this spacing to measure distances in space.','Like baryon acoustic oscillations, it names the frozen sound-horizon scale used as a cosmological standard ruler for distance and expansion measurements.','It appears in the same clustering analyses of galaxy surveys that fit the acoustic feature to extract distances and the Hubble parameter.','Astronomical & Cosmological Acoustics',ARRAY['Baryon acoustic oscillations','Sound horizon','Acoustic ruler','Acoustic scale','Photon-baryon fluid']::text[],ARRAY['Treating it as a different phenomenon from baryon acoustic oscillations, when the two names denote the same effect','Assuming it refers to present-day acoustic waves','Confusing the comoving scale with a fixed physical length']::text[],ARRAY['Reading survey papers that use the baryonic spelling','Identifying the clustering feature as a standard ruler','Comparing the scale with the CMB acoustic scale']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baryonic acoustic oscillations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df4e996a-2caf-56c7-b0ee-0a9bf7f88576','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df4e996a-2caf-56c7-b0ee-0a9bf7f88576') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df4e996a-2caf-56c7-b0ee-0a9bf7f88576');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85aee766-ebe6-5949-a55e-c01168cfc665','Acoustic peak','In cosmology, an acoustic peak is a maximum in a power spectrum produced by acoustic oscillations of the primordial photon-baryon fluid. In the cosmic microwave background temperature angular power spectrum, a harmonic series of peaks appears at multipoles set by modes caught at extrema of their oscillation at last scattering, the first near multipole 220. In galaxy clustering the analogous single BAO peak appears in the correlation function at the sound-horizon separation. Peak positions and heights encode the sound horizon, the baryon density, and the geometry of the universe.','An acoustic peak is a bump in a cosmic power chart. It comes from sound waves in the early universe. In the microwave background these bumps form a regular series. The first big peak sits near multipole 220. Their spots and sizes tell us how the universe is built.','The peaks turn early-universe sound into precise measurements of cosmic parameters and act as calibrated scales for geometry and expansion.','Analysts fit peak positions and amplitudes in CMB spectra from experiments like WMAP and Planck to determine the baryon density, matter density, and spatial curvature.','Astronomical & Cosmological Acoustics',ARRAY['CMB acoustic peak','BAO peak','Sound horizon','Acoustic scale','Baryon acoustic oscillations','Silk damping']::text[],ARRAY['Reading peaks as literal sound heard today rather than statistical features','Confusing the CMB harmonic peak series with the single BAO peak in galaxy clustering','Assuming only the first peak carries useful information']::text[],ARRAY['Fitting CMB power spectra to estimate cosmic parameters','Identifying the first peak to test spatial flatness','Comparing peak spacing with the sound horizon']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85aee766-ebe6-5949-a55e-c01168cfc665','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85aee766-ebe6-5949-a55e-c01168cfc665') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85aee766-ebe6-5949-a55e-c01168cfc665');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa8ff403-946b-59da-870c-084984273e06','BAO peak','The BAO peak is the localized excess in the galaxy two-point correlation function at a comoving separation equal to the sound horizon at the baryon drag epoch, near 150 megaparsecs (about 100 h^-1 Mpc). It is the configuration-space manifestation of baryon acoustic oscillations: the frozen acoustic shell of enhanced density surrounding primordial overdensities. Its measured angular and radial extent at a given redshift yields the angular-diameter distance and the Hubble parameter, making it a standard ruler.','The BAO peak is a small bump in a galaxy spacing chart. It sits near a fixed distance of about 150 megaparsecs. This bump is the frozen edge of an early sound wave. Its size on the sky helps measure how far away galaxies are. It also tracks how fast space expands.','It marks the standard-ruler scale in galaxy clustering used to map distances and the expansion rate across cosmic time.','Survey teams locate the peak in correlation-function measurements to extract distance and Hubble-rate constraints at each survey redshift.','Astronomical & Cosmological Acoustics',ARRAY['Baryon acoustic oscillations','Sound horizon','Acoustic ruler','Drag epoch','Acoustic scale']::text[],ARRAY['Confusing the single clustering peak with the CMB peak series','Treating the peak location as a fixed physical length rather than comoving','Expecting a sharp spike instead of a broad, low-amplitude feature']::text[],ARRAY['Measuring the peak position in a survey correlation function','Deriving the Hubble parameter from the radial peak','Testing dark-energy models against the ruler']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BAO peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa8ff403-946b-59da-870c-084984273e06','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa8ff403-946b-59da-870c-084984273e06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa8ff403-946b-59da-870c-084984273e06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '643f3aa8-69cb-599c-b5b6-53613c0d1b0b','Baryon acoustic scale','The baryon acoustic scale is the characteristic length imprinted by baryon acoustic oscillations, equal to the comoving sound horizon evaluated at the baryon drag epoch, near 150 megaparsecs. It sets the separation of the BAO feature in galaxy clustering and, projected onto the last-scattering surface, underlies the angular acoustic scale of the CMB peaks. Because early-universe physics fixes its length, it functions as a cosmological standard ruler for distance and expansion measurements.','The baryon acoustic scale is a fixed cosmic length. It equals how far sound travelled before matter and light split. That distance is about 150 megaparsecs. It shows up as a set spacing between galaxies. Because its length is known, it works as a ruler.','It defines the physical length of the standard ruler used to convert observed clustering separations into cosmic distances.','Cosmologists compute this scale from the baryon and matter densities and compare it with the measured BAO feature to infer distances.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Baryon acoustic oscillations','Drag epoch','Acoustic ruler','Acoustic scale']::text[],ARRAY['Confusing the scale at the drag epoch with the sound horizon at CMB last scattering','Treating the comoving scale as a fixed physical length','Assuming it is directly visible rather than statistical']::text[],ARRAY['Calibrating survey distances against a computed acoustic scale','Comparing the galaxy and CMB acoustic scales','Constraining the baryon density from the scale']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baryon acoustic scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '643f3aa8-69cb-599c-b5b6-53613c0d1b0b','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='643f3aa8-69cb-599c-b5b6-53613c0d1b0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='643f3aa8-69cb-599c-b5b6-53613c0d1b0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce8df0c8-aa34-5953-9fcd-50d389e09dcb','Sound horizon','The sound horizon is the comoving distance an acoustic wave could travel in the photon-baryon fluid from the Big Bang until a specified epoch, obtained by integrating the plasma sound speed over conformal time. Evaluated at photon-baryon decoupling it sets the CMB acoustic scale; evaluated at the slightly later baryon drag epoch it sets the BAO scale in galaxy clustering. Its value, near 150 megaparsecs comoving, depends on the pre-recombination expansion history and the baryon and radiation densities.','The sound horizon is how far a sound wave got in the early universe. It is measured up to the moment light and matter split. You find it by adding up the wave speed over time. It comes out near 150 megaparsecs. This distance sets the size of the cosmic ruler.','It defines the physical length of the standard ruler used by both CMB and galaxy-survey distance measurements.','Cosmologists compute the sound horizon from the baryon and radiation densities and calibrate BAO and CMB distances against it.','Astronomical & Cosmological Acoustics',ARRAY['Comoving sound horizon','Acoustic scale','Drag epoch','Photon-baryon fluid','Acoustic ruler']::text[],ARRAY['Confusing the sound horizon at last scattering with the one at the drag epoch','Ignoring the drop in sound speed as baryon loading grows','Treating it as a distance sound travels today']::text[],ARRAY['Computing the ruler length from cosmic densities','Calibrating CMB acoustic peaks','Setting the BAO clustering scale']::text[],'advanced','r_s = ∫₀^η* c_s dη,  c_s = c/√[3(1+R)]','The sound horizon is the plasma sound speed integrated over conformal time up to the chosen epoch, where the sound speed falls as the baryon-to-photon ratio R rises.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound horizon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce8df0c8-aa34-5953-9fcd-50d389e09dcb','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce8df0c8-aa34-5953-9fcd-50d389e09dcb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce8df0c8-aa34-5953-9fcd-50d389e09dcb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5be239b8-3fe6-5e5c-bf68-b08b38a479ea','Comoving sound horizon','The comoving sound horizon is the sound horizon expressed in comoving coordinates, which factor out cosmic expansion so the scale stays constant on a fixed grid. It equals the photon-baryon sound speed divided by the Hubble rate, integrated over redshift from the given epoch to very early times, equivalently the sound speed integrated over conformal time. At the drag epoch it is close to 150 megaparsecs and provides the fixed length underlying the BAO standard ruler.','Comoving distance ignores the stretching of space. The comoving sound horizon is the sound horizon in that fixed frame. You get it by adding the wave speed divided by the expansion rate. Its value stays constant as space grows. It is about 150 megaparsecs.','It supplies the expansion-independent length used to compare the acoustic scale across different epochs and datasets.','It is the quantity computed by cosmology codes and compared with survey BAO measurements to derive distances.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Drag epoch','Acoustic ruler','Baryon acoustic oscillations','Acoustic scale']::text[],ARRAY['Mixing up comoving and physical (proper) lengths','Assuming the comoving scale changes with time','Forgetting the epoch at which it is evaluated']::text[],ARRAY['Comparing the acoustic scale between CMB and galaxy surveys','Feeding the ruler length into distance fits','Testing expansion history with a fixed comoving scale']::text[],'advanced','r_s(z) = ∫_z^∞ c_s(z'') / H(z'') dz''','The comoving sound horizon is the plasma sound speed divided by the Hubble rate, integrated over redshift from the epoch of interest back to very early times.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comoving sound horizon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5be239b8-3fe6-5e5c-bf68-b08b38a479ea','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5be239b8-3fe6-5e5c-bf68-b08b38a479ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5be239b8-3fe6-5e5c-bf68-b08b38a479ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5360c7c7-d955-5af6-9c1c-8c3a7e3aa310','Drag epoch','The drag epoch, or baryon drag epoch, is the time shortly after photon-baryon decoupling when the residual photon drag on baryons became negligible, at redshift z_drag near 1060. Before it, radiation pressure and photon drag still guided baryon motion; after it, baryons were released and their acoustic pattern froze. Because the BAO pattern in the baryon distribution is set at this moment, the comoving sound horizon at the drag epoch is the scale imprinted in galaxy clustering, slightly larger than the sound horizon at CMB last scattering.','The drag epoch is when light stopped pushing on matter. It came just after light and matter split. At this time the matter''s sound pattern froze. This sets the galaxy ruler distance. It happens at a redshift near 1060.','It fixes the epoch at which the baryon acoustic scale is set, distinguishing the galaxy-clustering ruler from the CMB acoustic scale.','BAO analyses use the sound horizon at the drag epoch, computed from the baryon and matter densities, to calibrate distances.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Baryon acoustic oscillations','Recombination','Baryon acoustic scale','Photon-baryon fluid']::text[],ARRAY['Equating the drag epoch with the last-scattering surface, which differs slightly in redshift','Assuming baryons and photons decouple at exactly the same instant','Using the CMB sound horizon for the galaxy ruler']::text[],ARRAY['Choosing the correct epoch for the BAO ruler','Comparing z_drag with the last-scattering redshift','Computing the drag-epoch sound horizon from densities']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Drag epoch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5360c7c7-d955-5af6-9c1c-8c3a7e3aa310','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5360c7c7-d955-5af6-9c1c-8c3a7e3aa310') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5360c7c7-d955-5af6-9c1c-8c3a7e3aa310');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6113831c-d714-5275-a207-86206f930158','Photon-baryon fluid','The photon-baryon fluid is the tightly coupled plasma of the pre-recombination universe in which photons and baryons behaved as a single fluid because Thomson scattering bound them together. Photon radiation pressure supplied the restoring force and baryons supplied inertia, so the medium supported acoustic oscillations at a sound speed near c/√3, reduced as baryon loading increased. These oscillations are the source of the CMB acoustic peaks and of baryon acoustic oscillations.','Before atoms formed, light and matter were locked together. They acted as one fluid. Light pressure pushed and matter added weight. This let sound waves move through it. The waves ran near the speed of light divided by root three.','It is the medium whose oscillations set the acoustic scale, so its sound speed and inertia govern the CMB peak and BAO physics.','Cosmology codes model this fluid''s sound speed and coupling to predict CMB and matter power spectra fitted to data.','Astronomical & Cosmological Acoustics',ARRAY['Photon-baryon acoustic oscillation','Sound horizon','Primordial acoustic wave','Silk damping','CMB acoustic peak']::text[],ARRAY['Thinking photons and baryons moved independently before recombination','Ignoring how baryon loading lowers the sound speed','Treating the plasma as a vacuum-like medium']::text[],ARRAY['Modelling the sound speed for CMB predictions','Explaining the origin of the acoustic peaks','Tracking baryon loading through recombination']::text[],'advanced','c_s = c / √[3(1+R)],  R = 3ρ_b / (4ρ_γ)','The fluid''s sound speed equals the speed of light divided by the square root of three times one plus R, where R is three-quarters the baryon-to-photon energy-density ratio.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photon-baryon fluid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6113831c-d714-5275-a207-86206f930158','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6113831c-d714-5275-a207-86206f930158') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6113831c-d714-5275-a207-86206f930158');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6082dec-8b77-5b56-a082-fdc65fae21cf','Photon-baryon acoustic oscillation','A photon-baryon acoustic oscillation is an oscillation of the tightly coupled photon-baryon plasma in which photon pressure and gravity drive the fluid to compress and rarefy within dark-matter potential wells. Each Fourier mode oscillates as a driven harmonic system until decoupling, and modes at compression or rarefaction extrema at last scattering produce the CMB temperature peaks while the frozen density pattern produces BAO. It is the microphysical process underlying both the acoustic peaks and the acoustic scale.','This is the back-and-forth motion of the early plasma. Light pressure pushed out and gravity pulled in. So the fluid squeezed and stretched over and over. This motion made the sound waves of the young universe. It left the patterns we see today.','It links the driving physics of pressure and gravity to the observable peaks and BAO scale, explaining why both exist.','Its harmonic solution is used to model peak positions and heights when fitting CMB and clustering data.','Astronomical & Cosmological Acoustics',ARRAY['Photon-baryon fluid','Primordial acoustic wave','CMB acoustic peak','Baryon acoustic oscillations','Acoustic scale']::text[],ARRAY['Picturing a single wave rather than many independent Fourier modes','Forgetting gravity''s role alongside photon pressure','Assuming the oscillation continues after decoupling']::text[],ARRAY['Deriving the harmonic peak series','Explaining odd-even peak height differences','Connecting plasma physics to the BAO scale']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photon-baryon acoustic oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6082dec-8b77-5b56-a082-fdc65fae21cf','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6082dec-8b77-5b56-a082-fdc65fae21cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6082dec-8b77-5b56-a082-fdc65fae21cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8846b27e-4884-5f89-943d-c8888d7abc24','Primordial acoustic wave','A primordial acoustic wave is a pressure wave that propagated in the photon-baryon plasma of the early universe, seeded by inflationary density perturbations and driven by photon pressure against gravitational infall. These waves travelled at the plasma sound speed through the radiation-dominated era and froze at recombination, leaving the acoustic signatures recorded in the cosmic microwave background and in the large-scale distribution of matter.','A primordial acoustic wave is an early cosmic sound wave. It formed from tiny ripples left by inflation. Light pressure and gravity kept it moving. It travelled until atoms formed, then stopped. Its mark still shows in the sky today.','It is the physical wave whose frozen crests define the acoustic scale seen in the CMB and galaxy clustering.','Its behaviour is modelled when interpreting CMB anisotropies and the BAO feature in surveys.','Astronomical & Cosmological Acoustics',ARRAY['Photon-baryon acoustic oscillation','Sound horizon','Photon-baryon fluid','CMB acoustic peak','Baryon acoustic oscillations']::text[],ARRAY['Imagining audible sound rather than a plasma pressure wave','Assuming the waves persist today','Ignoring the inflationary origin of the seeds']::text[],ARRAY['Explaining the origin of the acoustic scale','Tracing perturbations from inflation to recombination','Teaching the physical basis of BAO']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primordial acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8846b27e-4884-5f89-943d-c8888d7abc24','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8846b27e-4884-5f89-943d-c8888d7abc24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8846b27e-4884-5f89-943d-c8888d7abc24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a268ea4e-d228-5484-8a45-7ee0c8b46e88','Acoustic scale','The acoustic scale is the characteristic angular or spatial scale set by the sound horizon at recombination. In the CMB it is the angular acoustic scale, the ratio of the sound horizon at last scattering to the angular-diameter distance to it, which fixes the spacing of the acoustic peaks (acoustic multipole near 300, first peak near multipole 220). In galaxy surveys the comoving acoustic scale is the BAO separation. It is one of the most precisely measured quantities in cosmology.','The acoustic scale is the size of the cosmic sound ruler on the sky. It compares the sound horizon to our distance from it. This angle sets where the CMB peaks fall. The first peak sits near multipole 220. It is measured very precisely.','It converts the fixed sound-horizon length into an observable angle or separation that constrains geometry and expansion.','It is measured from CMB peak spacing and from the BAO feature to test spatial flatness and pin down distances.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','CMB acoustic peak','Acoustic ruler','Baryon acoustic oscillations','Acoustic peak']::text[],ARRAY['Confusing the angular acoustic scale with the comoving BAO scale','Assuming the first peak sits exactly at the acoustic multipole','Ignoring the distance dependence of the angle']::text[],ARRAY['Testing spatial flatness from CMB peak spacing','Comparing the CMB and galaxy acoustic scales','Constraining the Hubble constant']::text[],'advanced','θ_A = r_s(z_*) / D_A(z_*),  ℓ_A = π / θ_A','The angular acoustic scale is the sound horizon at last scattering divided by the angular-diameter distance to last scattering, and the acoustic multipole is pi divided by that angle.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a268ea4e-d228-5484-8a45-7ee0c8b46e88','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a268ea4e-d228-5484-8a45-7ee0c8b46e88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a268ea4e-d228-5484-8a45-7ee0c8b46e88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '347ebf7c-2ce7-5a30-80a2-ec916812d4b9','Silk damping','Silk damping, or diffusion damping, is the suppression of small-scale acoustic oscillations in the photon-baryon fluid caused by photon diffusion near recombination. As the photon mean free path grew, photons random-walked out of overdense regions, smearing temperature and density fluctuations on scales below the diffusion length. This exponentially damps the higher-order CMB acoustic peaks and sets a small-scale cutoff on the acoustic power.','Silk damping smooths out the smallest early sound waves. Near the time atoms formed, light began to leak. Light drifted out of dense spots and blurred them. This wiped out the tiniest ripples. It makes the far CMB peaks fade.','It shapes the falling envelope of the high-multipole CMB peaks and encodes the photon diffusion length at recombination.','Its damping tail is fitted in CMB spectra to constrain the recombination physics and the number of relativistic species.','Astronomical & Cosmological Acoustics',ARRAY['CMB acoustic peak','Photon-baryon fluid','Recombination','Acoustic peak','Photon-baryon acoustic oscillation']::text[],ARRAY['Confusing Silk (diffusion) damping with neutrino free-streaming effects','Assuming it affects large scales equally','Treating the damping as a sharp cutoff rather than exponential']::text[],ARRAY['Fitting the CMB damping tail','Constraining extra relativistic species','Explaining why high peaks shrink']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Silk damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '347ebf7c-2ce7-5a30-80a2-ec916812d4b9','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='347ebf7c-2ce7-5a30-80a2-ec916812d4b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='347ebf7c-2ce7-5a30-80a2-ec916812d4b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad92b591-0412-51c6-ac6c-32d14469e14e','CMB acoustic peak','A CMB acoustic peak is one of the maxima in the angular power spectrum of cosmic microwave background temperature anisotropies produced by acoustic oscillations of the photon-baryon fluid at last scattering. Modes caught at maximum compression or rarefaction imprint a harmonic series of peaks; the first compression peak near multipole 220 fixes spatial geometry, the ratio of odd to even peak heights measures the baryon density, and the peak envelope is shaped by Silk damping.','A CMB acoustic peak is a bump in the microwave sky chart. It comes from squeezing and stretching of the early plasma. The peaks form a regular series. The first peak near multipole 220 shows space is nearly flat. Peak heights reveal how much normal matter exists.','The peak series encodes geometry, baryon and matter densities, and recombination physics in a single, precisely measurable spectrum.','Cosmologists fit peak positions and heights in Planck and WMAP data to determine the core parameters of the standard model.','Astronomical & Cosmological Acoustics',ARRAY['Acoustic peak','Acoustic scale','Silk damping','Photon-baryon acoustic oscillation','Baryon acoustic oscillations']::text[],ARRAY['Confusing the CMB peak series with the single BAO peak','Reading peaks as sound audible today','Assuming even and odd peaks have equal height']::text[],ARRAY['Measuring the baryon density from odd-even peak ratios','Locating the first peak to test flatness','Using peak spacing as an acoustic ruler']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CMB acoustic peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad92b591-0412-51c6-ac6c-32d14469e14e','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad92b591-0412-51c6-ac6c-32d14469e14e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad92b591-0412-51c6-ac6c-32d14469e14e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a34efb5b-95ed-5a94-b4ea-a313b8f59f33','Acoustic ruler','The acoustic ruler, or standard ruler, is the use of the sound-horizon scale imprinted by baryon acoustic oscillations as a length of known physical size for measuring cosmic distances. Because early-universe physics fixes the sound horizon, comparing its apparent angular and redshift extent in galaxy clustering or the CMB with its known comoving length yields the angular-diameter distance and the Hubble parameter as functions of redshift.','The acoustic ruler is a cosmic measuring stick. Its length is the early-universe sound horizon. We know this length from physics. By seeing how big it looks at different times, we find distances. This also tells us the expansion rate.','It anchors the cosmic distance scale to a physically calibrated length, enabling precise tests of dark energy and expansion.','DESI, BOSS, and CMB experiments use the acoustic ruler to map distance versus redshift and constrain cosmological models.','Astronomical & Cosmological Acoustics',ARRAY['Sound horizon','Baryon acoustic oscillations','Acoustic scale','BAO peak','Drag epoch']::text[],ARRAY['Assuming the ruler length is measured rather than computed from early-universe physics','Confusing angular and radial ruler measurements','Ignoring the epoch at which the sound horizon is set']::text[],ARRAY['Mapping the expansion history with survey BAO','Calibrating distances from the CMB acoustic scale','Testing dark-energy models against the ruler']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ruler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a34efb5b-95ed-5a94-b4ea-a313b8f59f33','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a34efb5b-95ed-5a94-b4ea-a313b8f59f33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a34efb5b-95ed-5a94-b4ea-a313b8f59f33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc556177-16f7-5746-8d82-18be81f2e9f8','Helioseismology','Helioseismology is the study of the Sun''s interior through its global and local acoustic and gravity oscillations. Millions of resonant modes, chiefly acoustic p-modes trapped in the solar interior, produce line-of-sight velocity and intensity oscillations observed at the surface with periods near five minutes. By measuring mode frequencies, splittings, and travel times and inverting them, helioseismology reconstructs the Sun''s internal sound speed, density, rotation, and the depth of the convection zone.','Helioseismology studies the inside of the Sun using its natural waves. The Sun rings with sound waves trapped below its surface. These make the surface move up and down every five minutes. Scientists measure these motions in detail. From them they map the Sun''s hidden interior.','It probes solar structure and dynamics that cannot be seen directly, testing models of stellar interiors and the solar dynamo.','Instruments such as SOHO/MDI, GONG, and SDO/HMI record surface Doppler velocities that are analysed to infer internal rotation and sound speed.','Astronomical & Cosmological Acoustics',ARRAY['Asteroseismology','p-mode','g-mode','Solar acoustic mode','Solar Dopplergram']::text[],ARRAY['Assuming the sound escapes into space, when it is trapped inside the Sun','Confusing surface granulation with the resonant modes','Treating the Sun as a single-frequency oscillator']::text[],ARRAY['Inverting mode frequencies for internal sound speed','Measuring the depth of the convection zone','Mapping internal solar rotation']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helioseismology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc556177-16f7-5746-8d82-18be81f2e9f8','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc556177-16f7-5746-8d82-18be81f2e9f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc556177-16f7-5746-8d82-18be81f2e9f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75cd09cb-38d7-547f-a1c8-cb84e1f1b87f','Asteroseismology','Asteroseismology is the study of stellar interiors through the observation and interpretation of stellar oscillation modes. Stars pulsate in standing-wave modes, pressure (p) modes restored by pressure and gravity (g) modes restored by buoyancy, that appear as periodic brightness or radial-velocity variations. Measuring their frequencies, spacings, and splittings and comparing them with stellar models constrains mass, radius, age, internal rotation, and chemical structure, extending helioseismic techniques to stars across the Hertzsprung-Russell diagram.','Asteroseismology reads the vibrations of stars. Stars pulse in steady patterns of sound and buoyancy waves. These make the star''s light rise and fall. By timing these pulses, scientists learn a star''s size and age. It applies Sun-studying methods to distant stars.','It measures fundamental stellar properties and internal structure that are otherwise inaccessible, underpinning stellar and exoplanet studies.','Space photometers like CoRoT, Kepler, and TESS measure oscillation frequencies to derive stellar masses, radii, and ages.','Astronomical & Cosmological Acoustics',ARRAY['Helioseismology','p-mode','g-mode','Mixed mode','Solar-like oscillation']::text[],ARRAY['Assuming all pulsators oscillate coherently like classical variables','Ignoring mode identification before interpreting frequencies','Treating the frequency spectrum as noise']::text[],ARRAY['Deriving red-giant masses and radii for galactic studies','Measuring ages of exoplanet host stars','Probing internal rotation of main-sequence stars']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Asteroseismology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75cd09cb-38d7-547f-a1c8-cb84e1f1b87f','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75cd09cb-38d7-547f-a1c8-cb84e1f1b87f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75cd09cb-38d7-547f-a1c8-cb84e1f1b87f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '970231db-dcb7-57d6-8951-3c569fe9d959','Solar acoustic mode','A solar acoustic mode is a resonant pressure (p) mode oscillation of the Sun in which pressure provides the restoring force. These modes are standing sound waves trapped between a lower turning point set by the rising interior sound speed and an upper reflection near the surface, forming a spectrum of discrete frequencies around 3 mHz (roughly five-minute periods). Their frequencies depend on the sound-speed profile along the wave path, making them the primary diagnostic of solar interior structure.','A solar acoustic mode is a trapped sound wave in the Sun. Pressure is the force that drives it back and forth. The wave bounces between deep layers and the surface. Together these modes ring near a five-minute period. Their pitch reveals the Sun''s inner structure.','It carries information about the sound speed along its path, so its frequency is a direct probe of solar interior conditions.','Its measured frequencies are inverted in helioseismology to reconstruct the Sun''s internal sound speed and density.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','Helioseismology','Acoustic cavity','Mode frequency','Solar-like oscillation']::text[],ARRAY['Confusing acoustic p-modes with buoyancy g-modes','Assuming a single frequency rather than a rich spectrum','Thinking the modes are driven by an external source']::text[],ARRAY['Inverting p-mode frequencies for solar structure','Identifying five-minute oscillations in Doppler data','Comparing observed and modelled mode frequencies']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar acoustic mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '970231db-dcb7-57d6-8951-3c569fe9d959','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='970231db-dcb7-57d6-8951-3c569fe9d959') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='970231db-dcb7-57d6-8951-3c569fe9d959');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c83e7360-20fe-5130-98e3-add715acad6c','p-mode','A p-mode is a pressure mode, an acoustic standing-wave oscillation of a star in which the pressure gradient is the restoring force. In the Sun and solar-like stars, p-modes are trapped in an acoustic cavity between an inner turning point, where the wave refracts as sound speed rises with depth, and the surface, where it reflects. They dominate the observed oscillation spectrum around the frequency of maximum power (about 3 mHz in the Sun) and follow an approximately uniform frequency spacing described by asymptotic theory.','A p-mode is a sound wave trapped inside a star. Pressure is the force that pushes it back. It bounces between a deep layer and the surface. Many p-modes together form an even pattern of pitches. In the Sun they peak near a five-minute period.','P-modes sample the sound-speed structure of the outer and intermediate interior, making them the main tool of helio- and asteroseismology.','Their frequencies and spacings are measured to estimate stellar radius, mass, and internal sound speed.','Astronomical & Cosmological Acoustics',ARRAY['g-mode','f-mode','Large frequency separation','Solar acoustic mode','Acoustic cavity']::text[],ARRAY['Confusing p-modes with g-modes, which are restored by buoyancy not pressure','Assuming their spacing is exactly uniform rather than asymptotic','Ignoring the near-surface effects on their frequencies']::text[],ARRAY['Measuring the large frequency separation of a star','Identifying p-mode ridges in a power spectrum','Inverting p-mode frequencies for interior sound speed']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='p-mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c83e7360-20fe-5130-98e3-add715acad6c','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c83e7360-20fe-5130-98e3-add715acad6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c83e7360-20fe-5130-98e3-add715acad6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '467f210d-19e6-561b-a17e-65dcd6f320d6','g-mode','A g-mode is a gravity mode, an oscillation in which buoyancy, the restoring force from stable stratification quantified by the Brunt-Vaisala frequency, drives the motion. G-modes are trapped in convectively stable radiative regions, largely the deep interior in solar-like stars, where they have low frequencies and near-uniform spacing in period rather than frequency. Because they are evanescent through the convection zone, solar g-modes are extremely difficult to detect, yet they carry unique information about the deep core.','A g-mode is a slow wave inside a star. Buoyancy, not pressure, drives it. It lives in calm, stable inner layers. These modes are spaced evenly in period. In the Sun they are very hard to see.','G-modes probe the deep radiative interior and core, regions that p-modes barely sample.','In evolved stars their signatures within mixed modes reveal core rotation and evolutionary state.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','Mixed mode','Period spacing','g-mode cavity','Asteroseismology']::text[],ARRAY['Confusing g-modes with p-modes','Expecting them to be easily observed at the solar surface','Assuming uniform spacing in frequency rather than in period']::text[],ARRAY['Searching for solar g-mode signatures','Measuring period spacings in red giants','Probing core rotation via mixed modes']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='g-mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '467f210d-19e6-561b-a17e-65dcd6f320d6','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='467f210d-19e6-561b-a17e-65dcd6f320d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='467f210d-19e6-561b-a17e-65dcd6f320d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32159c25-d32a-5936-b438-a2771b1004f2','f-mode','An f-mode is the fundamental mode, a surface-gravity oscillation intermediate between p- and g-modes that has no radial node in its displacement eigenfunction and is restored chiefly by gravity acting at the surface. Its frequency follows an approximate deep-water surface-wave dispersion relation depending mainly on the horizontal wavenumber and surface gravity, largely independent of interior stratification. In helioseismology f-modes are used to probe the near-surface layers and to calibrate the solar radius.','An f-mode is a surface wave on a star. It acts like a wave on deep water. Gravity at the surface pulls it back. Its pitch depends on surface gravity and wavelength. It probes the star''s outer skin.','Because it is nearly independent of the deep interior, the f-mode provides a clean probe of surface gravity and radius.','Solar f-mode frequencies are tracked to monitor changes in the near-surface radius and structure.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','g-mode','Acoustic cavity','Mode frequency','Helioseismology']::text[],ARRAY['Treating the f-mode as an ordinary acoustic p-mode','Assuming it depends strongly on the deep interior','Ignoring its surface-gravity-wave nature']::text[],ARRAY['Calibrating the seismic solar radius','Probing near-surface layers','Separating the f-mode ridge from p-mode ridges']::text[],'advanced','ω² ≈ g k_h','The fundamental mode frequency squared is approximately surface gravity times the horizontal wavenumber, like a deep-water surface wave.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='f-mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32159c25-d32a-5936-b438-a2771b1004f2','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32159c25-d32a-5936-b438-a2771b1004f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32159c25-d32a-5936-b438-a2771b1004f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ddff0cf7-9cc9-556d-8409-839911ec47f1','Mixed mode','A mixed mode is a stellar oscillation that behaves as a pressure mode in the outer acoustic cavity and as a gravity mode in the inner buoyancy cavity, the two cavities being coupled through the evanescent region between them. Such modes arise in evolved stars, notably subgiants and red giants, where the g-mode cavity moves into the observable frequency range. Because mixed modes sample both the deep core and the envelope, they are powerful probes of core structure, evolutionary state, and internal rotation.','A mixed mode acts two ways at once. Near the surface it is a sound wave. Deep inside it is a buoyancy wave. The two link through a thin barrier. These modes let us read a star''s core and outer layers together.','Mixed modes carry core information to the surface, enabling direct measurement of red-giant core properties and rotation.','Kepler mixed-mode period spacings distinguish hydrogen-shell-burning from helium-core-burning red giants.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','g-mode','Period spacing','g-mode cavity','Asteroseismology']::text[],ARRAY['Treating mixed modes as pure p-modes','Ignoring the coupling between the two cavities','Assuming they occur in unevolved main-sequence stars']::text[],ARRAY['Classifying red-giant burning stages','Measuring core rotation in evolved stars','Fitting mixed-mode patterns to models']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mixed mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ddff0cf7-9cc9-556d-8409-839911ec47f1','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ddff0cf7-9cc9-556d-8409-839911ec47f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ddff0cf7-9cc9-556d-8409-839911ec47f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05e90dd9-d70f-5154-88ea-1e3bd2cc57c7','Solar-like oscillation','Solar-like oscillations are stochastically excited and intrinsically damped acoustic p-mode pulsations driven by near-surface turbulent convection, of the kind seen in the Sun. They appear in cool stars with convective envelopes across the main sequence, subgiant, and red-giant phases, producing a bell-shaped power excess centred on the frequency of maximum power with a regular large frequency spacing. Their amplitudes are small, and their statistical, damped nature distinguishes them from coherent classical pulsators.','Solar-like oscillations are gentle star vibrations like the Sun''s. Boiling gas near the surface stirs them up. They are small and they fade and restart at random. Their power forms a broad hump in the spectrum. Cool stars with churning outer layers show them.','They give a rich spectrum of measurable p-modes in many stars, making broad asteroseismic surveys possible.','Kepler and TESS detect solar-like oscillations to measure masses, radii, and ages of thousands of stars.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','Frequency of maximum oscillation power','Large frequency separation','Asteroseismology','Mode frequency']::text[],ARRAY['Assuming they are steady coherent pulsations rather than stochastically driven and damped','Expecting large amplitudes','Confusing them with classical variable-star pulsations']::text[],ARRAY['Measuring the power excess in a Kepler light curve','Deriving stellar mass and radius from scaling relations','Identifying the large separation in the spectrum']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar-like oscillation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05e90dd9-d70f-5154-88ea-1e3bd2cc57c7','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05e90dd9-d70f-5154-88ea-1e3bd2cc57c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05e90dd9-d70f-5154-88ea-1e3bd2cc57c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e078f60a-2eea-5a28-9cd5-7e970a0ca13c','Mode frequency','A mode frequency is the resonant frequency of a specific stellar oscillation eigenmode, identified by its radial order n, spherical-harmonic degree l, and azimuthal order m. For solar-like p-modes the frequencies follow an asymptotic relation organized by the large frequency separation and a small degree-dependent term, so modes fall in a near-regular pattern. Precise mode frequencies are the fundamental observables that are inverted to infer stellar interior structure and rotation.','A mode frequency is the pitch of one stellar vibration. Each mode has labels for its shape and depth. For sound modes these pitches fall in an even ladder. The spacing of the ladder holds physical clues. Scientists measure these pitches with great care.','Mode frequencies are the raw data of seismology, encoding the internal sound speed and structure of a star.','Fitting a star''s mode frequencies against models yields its mass, radius, age, and internal profile.','Astronomical & Cosmological Acoustics',ARRAY['Large frequency separation','Small frequency separation','p-mode','Mode splitting','Asteroseismology']::text[],ARRAY['Reporting a frequency without identifying its n, l, and m','Assuming exact rather than asymptotic regularity','Neglecting near-surface corrections']::text[],ARRAY['Extracting individual frequencies from a power spectrum','Matching a frequency list to a stellar model','Building an echelle diagram']::text[],'advanced','ν_{n,l} ≈ Δν (n + l/2 + ε) − l(l+1) D₀','A p-mode frequency is approximately the large separation times radial order plus half the degree plus a constant, minus a small term that grows with degree.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e078f60a-2eea-5a28-9cd5-7e970a0ca13c','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e078f60a-2eea-5a28-9cd5-7e970a0ca13c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e078f60a-2eea-5a28-9cd5-7e970a0ca13c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e96ec226-2b0e-5c36-a741-14bebedd3699','Large frequency separation','The large frequency separation is the average spacing in frequency between consecutive acoustic overtones of the same spherical-harmonic degree in a star''s oscillation spectrum. In asymptotic theory it equals the inverse of twice the acoustic radius, the sound travel time from centre to surface, and therefore scales with the square root of the star''s mean density. It is a primary asteroseismic observable, used with the frequency of maximum power to estimate stellar mass and radius.','The large frequency separation is the gap between evenly spaced pitches. It equals one over the round-trip sound time in the star. So it tracks the star''s average density. A denser star shows a wider gap. It helps set the star''s size and mass.','It ties the oscillation spectrum to the star''s mean density, anchoring the scaling relations for mass and radius.','Pipelines measure it from the regular spacing of p-mode peaks or from an echelle diagram to derive stellar properties.','Astronomical & Cosmological Acoustics',ARRAY['Small frequency separation','Frequency of maximum oscillation power','Mode frequency','p-mode','Solar-like oscillation']::text[],ARRAY['Confusing the large separation with the small separation','Assuming it is exactly constant across all frequencies','Ignoring the surface term when comparing with models']::text[],ARRAY['Deriving mean density from the spacing','Building an echelle diagram','Applying scaling relations for mass and radius']::text[],'advanced','Δν = (2∫₀^R dr/c)⁻¹ ∝ √(M/R³)','The large frequency separation is the reciprocal of twice the sound-crossing time from centre to surface, and it scales as the square root of the star''s mean density.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Large frequency separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e96ec226-2b0e-5c36-a741-14bebedd3699','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e96ec226-2b0e-5c36-a741-14bebedd3699') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e96ec226-2b0e-5c36-a741-14bebedd3699');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '279d78cd-e091-5218-88e6-32e8d1e627c6','Small frequency separation','The small frequency separation is the frequency difference between acoustic modes of degree l and l+2 with consecutive radial orders, for example the spacing between a radial mode and the degree-two mode one order lower. It is much smaller than the large separation and is sensitive to the sound-speed gradient in the stellar core, which changes as hydrogen is depleted. Because it responds to core conditions, the small separation is a sensitive diagnostic of stellar age for main-sequence solar-like stars.','The small frequency separation is a tiny pitch gap. It compares modes of different shapes. This gap probes the deep core of a star. The core changes as the star ages. So this gap helps measure stellar age.','It provides a nearly independent constraint on core structure and age that complements the large separation.','It is measured from closely spaced peaks and read on an echelle diagram to estimate main-sequence stellar age.','Astronomical & Cosmological Acoustics',ARRAY['Large frequency separation','Mode frequency','p-mode','Asteroseismology','Solar-like oscillation']::text[],ARRAY['Confusing the small separation with the large separation','Measuring it without correct mode identification','Ignoring how it shrinks as a star evolves']::text[],ARRAY['Estimating the age of a solar-like star','Reading closely spaced ridges on an echelle diagram','Constraining core hydrogen content']::text[],'advanced','δν_{02}(n) = ν_{n,0} − ν_{n−1,2}','The small separation of degrees zero and two is the frequency of a radial mode minus that of the degree-two mode one radial order lower.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Small frequency separation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '279d78cd-e091-5218-88e6-32e8d1e627c6','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='279d78cd-e091-5218-88e6-32e8d1e627c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='279d78cd-e091-5218-88e6-32e8d1e627c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd7a6c01-e815-5b57-8193-676cfa8ba05c','Mode splitting','Mode splitting is the lifting of the frequency degeneracy among the 2l+1 azimuthal orders (m) of an oscillation multiplet by symmetry-breaking agents such as rotation or magnetic fields. In a non-rotating, spherical star, modes of the same n and l but different m share a single frequency; rotation or magnetism separates them into a symmetric or distorted pattern whose spacing encodes the internal angular velocity or field. Measuring splittings enables inversions for internal rotation profiles.','Mode splitting breaks one pitch into several. In a still, round star, some modes share a pitch. Spin or magnetism pulls them apart. The spacing shows how fast the inside turns. This reveals a star''s hidden rotation.','It converts a broken symmetry into a measurable frequency pattern, giving access to internal rotation and magnetism.','Split multiplets in solar and stellar spectra are inverted to map how rotation varies with depth and latitude.','Astronomical & Cosmological Acoustics',ARRAY['Rotational splitting','Mode frequency','p-mode','Asteroseismology','Helioseismology']::text[],ARRAY['Assuming all splitting comes from rotation, ignoring magnetic contributions','Confusing splitting with the large or small separation','Neglecting projection effects on the visible m components']::text[],ARRAY['Inverting split multiplets for internal rotation','Detecting magnetic signatures in frequencies','Interpreting rotationally split ridges']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode splitting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd7a6c01-e815-5b57-8193-676cfa8ba05c','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd7a6c01-e815-5b57-8193-676cfa8ba05c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd7a6c01-e815-5b57-8193-676cfa8ba05c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06a7084a-89bb-53a6-99cc-d26bd5736529','Rotational splitting','Rotational splitting is the component of mode splitting caused by stellar rotation, which shifts the frequencies of the azimuthal orders m of a multiplet roughly in proportion to m times a rotation-rate average weighted by the mode''s sensitivity kernel. For high-order p-modes the splitting approaches m times the rotation frequency; the general expression includes the Ledoux constant, which accounts for the Coriolis effect. It is the primary asteroseismic route to internal rotation.','Rotational splitting is pitch spread caused by spin. A turning star shifts each mode by a set amount. The shift grows with the mode''s m label. The size of the shift gives the spin rate. It maps how a star rotates inside.','It links the observed frequency shifts directly to the internal angular velocity along the mode''s sampling region.','Measured splittings are inverted to recover solar and stellar internal rotation as a function of radius and latitude.','Astronomical & Cosmological Acoustics',ARRAY['Mode splitting','Mode frequency','Helioseismology','Asteroseismology','p-mode']::text[],ARRAY['Ignoring the Ledoux constant for low-order modes','Assuming uniform rotation when kernels sample different depths','Confusing rotational splitting with magnetic splitting']::text[],ARRAY['Inverting splittings for the solar rotation profile','Measuring core-to-envelope rotation in red giants','Detecting differential rotation']::text[],'advanced','δν_{n,l,m} = m (1 − C_{n,l}) ⟨Ω⟩ / 2π','The rotational splitting equals the azimuthal order times one minus the Ledoux constant times the kernel-weighted mean angular velocity, divided by two pi.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rotational splitting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06a7084a-89bb-53a6-99cc-d26bd5736529','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06a7084a-89bb-53a6-99cc-d26bd5736529') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06a7084a-89bb-53a6-99cc-d26bd5736529');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34d4fe03-ce63-58e8-841f-696a99a3529f','Acoustic cutoff frequency','The acoustic cutoff frequency is the upper frequency limit above which acoustic waves are no longer trapped and reflected by a stellar atmosphere but propagate outward as running waves. Set by the atmospheric pressure scale height and sound speed, in an isothermal approximation it is roughly the sound speed divided by four pi times the scale height. In the Sun it is near 5.3 mHz; it also sets the approximate scaling of the frequency of maximum oscillation power and thus limits the observable p-mode spectrum.','The acoustic cutoff frequency is a top pitch limit. Below it, sound waves stay trapped in the star. Above it, the waves leak out into space. It depends on the surface layers'' thickness. In the Sun it sits near 5.3 millihertz.','It defines the upper edge of the trapped oscillation spectrum and links to the frequency of maximum power.','It marks where p-mode power fades in the spectrum and helps set the expected oscillation frequency range of a star.','Astronomical & Cosmological Acoustics',ARRAY['Frequency of maximum oscillation power','p-mode','Acoustic cavity','Solar acoustic mode','Solar-like oscillation']::text[],ARRAY['Assuming waves above the cutoff are still trapped','Ignoring the dependence on atmospheric scale height','Confusing it with the frequency of maximum power exactly']::text[],ARRAY['Estimating the upper limit of a star''s p-mode spectrum','Interpreting waves that leak into the atmosphere','Relating the cutoff to the power envelope']::text[],'advanced','ν_ac ≈ c / (4π H_p)','The acoustic cutoff frequency is roughly the sound speed divided by four pi times the atmospheric pressure scale height.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cutoff frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34d4fe03-ce63-58e8-841f-696a99a3529f','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34d4fe03-ce63-58e8-841f-696a99a3529f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34d4fe03-ce63-58e8-841f-696a99a3529f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2a80533-e976-5188-9b24-253e021f045e','Acoustic cavity','An acoustic cavity is the resonant region within a star in which p-mode sound waves are trapped between two turning points: an inner turning point where the rising sound speed refracts the downward-travelling wave back toward the surface, and an outer turning point near the surface where the sharp density drop reflects it. The size and sound-speed structure of this cavity determine the p-mode frequencies and their spacings.','An acoustic cavity is a sound trap inside a star. Waves bounce between two turning points. The deep one bends the wave back up. The shallow one near the surface reflects it down. The cavity''s shape sets the star''s pitches.','It defines where p-modes resonate, so its extent and sound speed fix the observable oscillation frequencies.','Its depth, inferred from mode frequencies, reveals the sound-speed profile and the base of the convection zone.','Astronomical & Cosmological Acoustics',ARRAY['p-mode','Acoustic cutoff frequency','g-mode cavity','Solar acoustic mode','Large frequency separation']::text[],ARRAY['Confusing the acoustic cavity with the g-mode buoyancy cavity','Assuming fixed turning points for all modes','Ignoring how the inner turning point depends on degree']::text[],ARRAY['Locating turning points for a given mode','Relating cavity size to the large separation','Probing the convection-zone base']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cavity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2a80533-e976-5188-9b24-253e021f045e','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2a80533-e976-5188-9b24-253e021f045e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2a80533-e976-5188-9b24-253e021f045e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f759056-eaef-53a2-a0b1-c179c11fe30a','g-mode cavity','The g-mode cavity is the region of a star, a convectively stable radiative zone, where gravity modes are trapped and oscillate. Its boundaries are set by where the mode frequency falls below both the Brunt-Vaisala and Lamb frequencies, so buoyancy can act as the restoring force. In solar-like stars this cavity lies in the deep interior beneath the convective envelope, making pure g-modes hard to observe but rich in core information.','The g-mode cavity is where buoyancy waves live. It sits in calm, stable inner layers. There, gas can bob up and down slowly. In the Sun it lies deep below the churning outer zone. That depth makes these waves hard to detect.','It confines gravity modes to the deep interior, so its structure controls the g-mode period spacing and core diagnostics.','Its properties, sensed through mixed modes, reveal core structure and rotation in evolved stars.','Astronomical & Cosmological Acoustics',ARRAY['g-mode','Mixed mode','Period spacing','Acoustic cavity','Asteroseismology']::text[],ARRAY['Confusing it with the acoustic p-mode cavity','Assuming g-modes reach the surface undamped','Ignoring the buoyancy-frequency boundaries']::text[],ARRAY['Explaining why solar g-modes are faint','Relating the cavity to period spacing','Interpreting mixed-mode behaviour']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='g-mode cavity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f759056-eaef-53a2-a0b1-c179c11fe30a','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f759056-eaef-53a2-a0b1-c179c11fe30a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f759056-eaef-53a2-a0b1-c179c11fe30a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c9eb32d-debc-5bfb-a313-528746b062f0','Asteroseismic surface term','The asteroseismic surface term, or surface effect, is the systematic offset between observed and model-computed oscillation frequencies arising from inadequate modelling of the near-surface layers, where convection, non-adiabatic effects, and turbulent pressure are poorly represented. It grows with frequency and is largely independent of mode degree. Empirical or physically motivated corrections, such as power-law or cubic-inverse formulations, are applied before frequencies are used to infer stellar properties.','The surface term is a known error in mode pitches. Models get the star''s outer layers wrong. This shifts the predicted pitches, more so at high pitch. Scientists correct for it before fitting. Otherwise the star''s size and age come out wrong.','It captures the mismatch at the surface so that interior inferences from mode frequencies remain reliable.','Modellers apply a surface-term correction when fitting Kepler or TESS frequencies to stellar models.','Astronomical & Cosmological Acoustics',ARRAY['Mode frequency','Large frequency separation','p-mode','Asteroseismology','Solar-like oscillation']::text[],ARRAY['Ignoring the surface term when comparing frequencies with models','Assuming it depends strongly on mode degree','Applying a correction calibrated for the wrong type of star']::text[],ARRAY['Correcting model frequencies before a fit','Comparing surface-term formulations','Reducing bias in stellar age estimates']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Asteroseismic surface term');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c9eb32d-debc-5bfb-a313-528746b062f0','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c9eb32d-debc-5bfb-a313-528746b062f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c9eb32d-debc-5bfb-a313-528746b062f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8629421-b061-596d-b564-f9a80c0be7c9','Period spacing','Period spacing is the near-uniform spacing in oscillation period between consecutive gravity modes of the same spherical-harmonic degree, the g-mode analogue of the large frequency separation. Asymptotic theory expresses it as an integral of the Brunt-Vaisala frequency over the g-mode cavity, weighted by the mode degree. In red giants the observed period spacing distinguishes hydrogen-shell-burning stars from helium-core-burning stars.','Period spacing is the even gap between buoyancy-wave periods. It plays the role that pitch spacing does for sound waves. It depends on the star''s stable inner layers. In red giants it reveals the core''s fuel. That shows what stage the star is in.','It encodes the buoyancy structure of the deep interior, giving a direct probe of core conditions and evolutionary state.','Measured from mixed-mode patterns in Kepler data, it separates red-giant burning stages and constrains core structure.','Astronomical & Cosmological Acoustics',ARRAY['g-mode','Mixed mode','g-mode cavity','Large frequency separation','Asteroseismology']::text[],ARRAY['Confusing period spacing with the large frequency separation','Assuming exact uniformity despite mode coupling','Neglecting the degree dependence']::text[],ARRAY['Classifying red-giant evolutionary stages','Measuring core structure from mixed modes','Comparing observed and asymptotic period spacings']::text[],'advanced','ΔΠ_l = 2π² [√(l(l+1)) ∫ N dr/r]⁻¹','The period spacing equals two pi squared divided by the square root of l times l plus one, times the reciprocal of the integral of the buoyancy frequency over radius across the gravity-mode cavity.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Period spacing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8629421-b061-596d-b564-f9a80c0be7c9','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8629421-b061-596d-b564-f9a80c0be7c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8629421-b061-596d-b564-f9a80c0be7c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b07db555-4f9b-5fa7-b00b-a1043be52431','Frequency of maximum oscillation power','The frequency of maximum oscillation power is the frequency at which the bell-shaped envelope of solar-like p-mode power peaks. It is empirically and theoretically linked to the acoustic cutoff frequency, scaling as surface gravity divided by the square root of effective temperature. With the large frequency separation it forms the basis of asteroseismic scaling relations for stellar mass and radius; in the Sun it is near 3050 microhertz.','This is the pitch where a star vibrates most strongly. Its power forms a hump, and this marks the top. It depends on surface gravity and temperature. It helps set a star''s mass and size. In the Sun it is near 3050 microhertz.','It provides a direct handle on surface gravity, anchoring the scaling relations that yield stellar mass and radius.','Pipelines measure it from the smoothed power spectrum of a star to derive mass and radius via scaling relations.','Astronomical & Cosmological Acoustics',ARRAY['Large frequency separation','Acoustic cutoff frequency','Solar-like oscillation','p-mode','Asteroseismology']::text[],ARRAY['Confusing it with the large frequency separation','Assuming it equals the acoustic cutoff exactly','Estimating it without smoothing the noisy spectrum']::text[],ARRAY['Deriving surface gravity from the power envelope','Applying scaling relations for mass and radius','Comparing stars on an oscillation diagram']::text[],'advanced','ν_max ≈ (g/g_☉)(T_eff/T_eff,☉)^{−1/2} ν_max,☉','The frequency of maximum power scales with surface gravity divided by the square root of effective temperature, calibrated to the solar value near 3050 microhertz.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency of maximum oscillation power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b07db555-4f9b-5fa7-b00b-a1043be52431','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b07db555-4f9b-5fa7-b00b-a1043be52431') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b07db555-4f9b-5fa7-b00b-a1043be52431');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17c8d3a6-3a1c-534b-9125-679584cef907','Acoustic glitch','An acoustic glitch is a localized, sharp feature in a star''s internal structure, such as the base of the convection zone or the helium second-ionization zone, that departs from a smooth sound-speed profile and imprints a small oscillatory signature on the oscillation frequencies as a function of radial order. The amplitude and period of this signature encode the location and sharpness of the glitch, enabling measurement of convection-zone depth and envelope helium abundance.','An acoustic glitch is a sharp change deep in a star. It breaks the smooth run of sound speed. This adds a small wobble to the mode pitches. The wobble''s pattern reveals where the change sits. It can even measure the star''s helium.','It turns a sharp structural feature into a measurable frequency signal, giving direct depth and abundance diagnostics.','Its oscillatory signal in frequencies is fitted to locate the convection-zone base and estimate surface helium.','Astronomical & Cosmological Acoustics',ARRAY['Mode frequency','Acoustic cavity','Large frequency separation','Asteroseismology','Helioseismology']::text[],ARRAY['Mistaking the glitch signal for random noise in frequencies','Assuming a smooth interior when a glitch is present','Confusing the helium and convection-zone glitches']::text[],ARRAY['Measuring convection-zone depth from frequencies','Estimating envelope helium abundance','Detecting ionization-zone signatures']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic glitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17c8d3a6-3a1c-534b-9125-679584cef907','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17c8d3a6-3a1c-534b-9125-679584cef907') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17c8d3a6-3a1c-534b-9125-679584cef907');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6274c583-643f-5719-874e-947798ce94f9','Solar Dopplergram','A solar Dopplergram is a two-dimensional map of the line-of-sight velocity across the solar disk, produced by measuring the Doppler shift of a photospheric spectral line at each spatial position. After subtracting rotation and other steady flows, it reveals the small oscillatory velocities of solar acoustic modes, so time series of Dopplergrams are the primary data for global and local helioseismology. Instruments such as SOHO/MDI and SDO/HMI generate them at a regular cadence.','A solar Dopplergram is a map of the Sun''s surface motion. It shows where the surface moves toward or away from us. It uses the Doppler shift of light. Steady spin is removed to reveal tiny wave motions. These maps feed studies of the Sun''s interior.','It captures the surface velocity field so that the Sun''s oscillation modes can be measured and analysed.','Long time series of Dopplergrams from SDO/HMI are Fourier-analysed to extract p-mode frequencies and subsurface flows.','Astronomical & Cosmological Acoustics',ARRAY['Helioseismology','Solar acoustic mode','Ring-diagram analysis','Time-distance helioseismology','p-mode']::text[],ARRAY['Forgetting to remove rotation before reading oscillation signals','Confusing a Dopplergram with a magnetogram or intensity image','Treating a single frame as a mode measurement']::text[],ARRAY['Building oscillation power spectra from velocity maps','Measuring subsurface flows locally','Monitoring the Sun''s five-minute oscillations']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Solar Dopplergram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6274c583-643f-5719-874e-947798ce94f9','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6274c583-643f-5719-874e-947798ce94f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6274c583-643f-5719-874e-947798ce94f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bca0d571-2d1c-53af-b163-407507ba866d','Ring-diagram analysis','Ring-diagram analysis is a local helioseismology technique that measures subsurface flows and structure beneath small patches of the solar surface. Three-dimensional power spectra of the oscillation field over a region show ring-shaped features from p-modes; horizontal flows Doppler-shift these rings, and fitting their distortion yields the flow velocity and sound-speed perturbations as a function of depth. It is widely used to map near-surface flows and their evolution over the solar cycle.','Ring-diagram analysis studies small patches of the Sun. It builds a 3D power chart of the surface waves. The waves form rings in this chart. Flows below the surface shift the rings. Measuring the shift reveals hidden flows and their depth.','It provides depth-resolved maps of horizontal flows and structure under localized regions of the surface.','It is applied to SDO/HMI and GONG data to map near-surface zonal and meridional flows across the disk.','Astronomical & Cosmological Acoustics',ARRAY['Helioseismology','Time-distance helioseismology','Solar Dopplergram','Solar acoustic mode','p-mode']::text[],ARRAY['Assuming it probes the deep interior rather than near-surface layers','Ignoring foreshortening toward the limb','Confusing ring diagrams with global mode analysis']::text[],ARRAY['Mapping subsurface flows under active regions','Tracking meridional circulation','Studying flows over the solar cycle']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ring-diagram analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bca0d571-2d1c-53af-b163-407507ba866d','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bca0d571-2d1c-53af-b163-407507ba866d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bca0d571-2d1c-53af-b163-407507ba866d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1dfd3029-8f28-51f8-b7a7-49d29bd35f1e','Time-distance helioseismology','Time-distance helioseismology is a local technique that measures the travel time of acoustic wave packets between pairs of points on the solar surface, obtained from the cross-correlation of oscillation signals. Differences in travel time along and against a flow, or through regions of differing sound speed, are inverted to map subsurface flows, thermal and magnetic structure, and features such as sunspot interiors and meridional circulation. It is closely analogous to seismic tomography of the Earth.','This method times sound waves crossing the Sun. It picks two surface points and links their signals. The delay between them shows what lies below. Faster or slower waves reveal flows and structure. It works like scanning the Sun with sound.','It converts measured acoustic travel times into three-dimensional maps of subsurface flows and structure.','It is used on SDO/HMI data to image sunspot subsurface structure and measure meridional flow.','Astronomical & Cosmological Acoustics',ARRAY['Helioseismology','Acoustic travel time','Ring-diagram analysis','Solar Dopplergram','Solar acoustic mode']::text[],ARRAY['Confusing travel-time shifts from flows with those from sound-speed changes','Ignoring noise in cross-correlations','Assuming straight ray paths without proper kernels']::text[],ARRAY['Imaging sunspot subsurface structure','Measuring meridional circulation','Detecting emerging active regions']::text[],'advanced',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-distance helioseismology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1dfd3029-8f28-51f8-b7a7-49d29bd35f1e','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1dfd3029-8f28-51f8-b7a7-49d29bd35f1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1dfd3029-8f28-51f8-b7a7-49d29bd35f1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '126cac29-b0c7-5515-a8cd-a0cc5060198d','Acoustic travel time','Acoustic travel time is the time for a sound wave or wave packet to propagate between two locations through a medium, equal to the path integral of the reciprocal local sound speed. In time-distance helioseismology it is the basic observable, measured from cross-correlations of surface oscillations and inverted for subsurface flows and structure; the same quantity underlies acoustic ranging in planetary atmospheres and oceans.','Acoustic travel time is how long sound takes between two points. It adds up one over the sound speed along the path. Slower regions add more time. Faster regions add less. This timing reveals what the sound passed through.','It encodes the sound speed and flows along the wave path, making it the key measurable in travel-time seismology.','Measured travel-time differences on the Sun are inverted to recover subsurface flow and sound-speed maps.','Astronomical & Cosmological Acoustics',ARRAY['Time-distance helioseismology','Helioseismology','Solar acoustic mode','Acoustic cavity','Ring-diagram analysis']::text[],ARRAY['Assuming a single ray path when waves sample a broad region','Confusing travel-time shifts from flow with those from structure','Ignoring the reference travel time']::text[],ARRAY['Inverting travel times for subsurface flows','Comparing outward and inward wave timing','Building a reference travel-time model']::text[],'intermediate','τ = ∫ ds / c_s','The acoustic travel time is the integral along the ray path of one divided by the local sound speed.','2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic travel time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '126cac29-b0c7-5515-a8cd-a0cc5060198d','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='126cac29-b0c7-5515-a8cd-a0cc5060198d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='126cac29-b0c7-5515-a8cd-a0cc5060198d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be9fc01f-8d8c-5c09-b3c7-0fbfbeba0657','Atmospheric infrasound on planets','Atmospheric infrasound on planets refers to low-frequency acoustic waves below the human hearing threshold, under about 20 Hz, that propagate through a planetary atmosphere, generated by sources such as impacts, volcanism, atmospheric turbulence, convective activity, and surface winds. Because true sound requires a gaseous medium, these waves exist only where an atmosphere is present; their propagation depends on atmospheric temperature and wind structure, and their detection probes both the source and the atmosphere itself.','Atmospheric infrasound is very low sound in a planet''s air. It sits below what people can hear. Impacts, winds, and volcanoes can make it. It needs an atmosphere to travel. Studying it reveals both the source and the air.','It provides a remote probe of both energetic events and atmospheric structure on planets with an atmosphere.','Landers, balloons, and orbiters carry pressure sensors to record infrasound on Earth, Venus, Mars, and Titan.','Astronomical & Cosmological Acoustics',ARRAY['Mars infrasound','Bolide infrasound','Meteor acoustic wave','Sonic boom from bolide','Acoustic travel time']::text[],ARRAY['Assuming such sound can cross the vacuum of space between planets','Ignoring how wind and temperature bend the waves','Confusing infrasound with audible sound']::text[],ARRAY['Detecting impacts from atmospheric pressure waves','Studying planetary winds with infrasound','Monitoring volcanic or convective activity']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Atmospheric infrasound on planets');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be9fc01f-8d8c-5c09-b3c7-0fbfbeba0657','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be9fc01f-8d8c-5c09-b3c7-0fbfbeba0657') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be9fc01f-8d8c-5c09-b3c7-0fbfbeba0657');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ac31d61-5ca1-5c92-9497-bcbf3c080e36','Mars infrasound','Mars infrasound is low-frequency acoustic and pressure-wave activity in the thin carbon-dioxide atmosphere of Mars, at and below infrasonic frequencies. It includes pressure fluctuations from convective vortices (dust devils), wind turbulence, and impacts, as well as audible-range sound recorded directly at the surface. The low density and low sound speed of the Martian atmosphere strongly shape wave amplitudes and propagation, and measurements constrain near-surface atmospheric dynamics.','Mars infrasound is very low sound in the Martian air. That air is thin and mostly carbon dioxide. Dust devils, wind, and impacts stir it up. The thin air makes sounds weak and travel oddly. Landers measure it to study the weather.','It gives a direct acoustic window on Martian near-surface turbulence, vortices, and impact events.','InSight pressure sensors and the Perseverance microphone recorded Martian pressure waves and sound near the surface.','Astronomical & Cosmological Acoustics',ARRAY['Atmospheric infrasound on planets','Bolide infrasound','Meteor acoustic wave','Sonic boom from bolide','Acoustic travel time']::text[],ARRAY['Assuming Mars is silent because its atmosphere is thin','Expecting Earth-like sound levels in low-density air','Confusing wind noise with a true acoustic signal']::text[],ARRAY['Detecting dust-devil pressure drops','Recording wind and turbulence at a lander','Searching for impact-generated infrasound']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mars infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ac31d61-5ca1-5c92-9497-bcbf3c080e36','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ac31d61-5ca1-5c92-9497-bcbf3c080e36') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ac31d61-5ca1-5c92-9497-bcbf3c080e36');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8957f088-32d5-56b5-a5f8-9661389d165c','Bolide infrasound','Bolide infrasound is the low-frequency acoustic energy radiated into the atmosphere by a bolide, a bright fireball meteor, from its hypersonic passage and any fragmentation or airburst. The cylindrical shock along the trail and quasi-point explosions from breakup relax into infrasonic waves that can travel thousands of kilometres and be recorded by ground-based arrays. Analysis of the signals yields the source energy, altitude, and trajectory of the object.','Bolide infrasound is deep sound from a big fireball. A fast meteor pushes a shock through the air. As the shock spreads it becomes very low sound. This sound can travel thousands of kilometres. Ground sensors use it to size the meteor.','It lets researchers estimate the energy and path of incoming objects from their long-range acoustic signature.','International infrasound arrays detected and sized major airbursts such as the 2013 Chelyabinsk event.','Astronomical & Cosmological Acoustics',ARRAY['Meteor acoustic wave','Sonic boom from bolide','Atmospheric infrasound on planets','Mars infrasound','Acoustic travel time']::text[],ARRAY['Confusing long-range infrasound with the locally heard boom','Assuming arrival at the same time as the light flash','Ignoring wind effects on propagation']::text[],ARRAY['Estimating fireball energy from array records','Reconstructing a bolide trajectory','Monitoring airbursts with infrasound networks']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bolide infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8957f088-32d5-56b5-a5f8-9661389d165c','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8957f088-32d5-56b5-a5f8-9661389d165c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8957f088-32d5-56b5-a5f8-9661389d165c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '907c3727-8a38-5f6b-8ba9-acf6fff2f1a3','Meteor acoustic wave','A meteor acoustic wave is an acoustic or infrasonic pressure wave generated by a meteor as it traverses a planetary atmosphere, arising from the cylindrical shock along its ionized trail and from fragmentation events. Depending on entry speed, size, and altitude, these waves range from audible sonic booms near large fireballs to long-range infrasound; they are recorded to determine meteor energies, trajectories, and atmospheric properties along the path.','A meteor acoustic wave is sound made by a meteor. The fast meteor shoves the air aside. This makes a shock that turns into sound. Big meteors can be heard as a boom. Sensors use these waves to study the meteor.','It carries the meteor''s energy and geometry into a measurable acoustic signal for atmospheric and meteor science.','Ground microphones and infrasound arrays record meteor waves to estimate mass, speed, and fragmentation altitude.','Astronomical & Cosmological Acoustics',ARRAY['Bolide infrasound','Sonic boom from bolide','Atmospheric infrasound on planets','Meteor','Acoustic travel time']::text[],ARRAY['Assuming every meteor produces audible sound','Confusing electrophonic sounds with the delayed acoustic arrival','Ignoring altitude effects on the shock']::text[],ARRAY['Timing a meteor''s acoustic arrival','Estimating fragmentation altitude','Linking optical and acoustic meteor records']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Meteor acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '907c3727-8a38-5f6b-8ba9-acf6fff2f1a3','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='907c3727-8a38-5f6b-8ba9-acf6fff2f1a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='907c3727-8a38-5f6b-8ba9-acf6fff2f1a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '673d8ec4-833d-57a1-9838-159ae25c0b42','Sonic boom from bolide','A sonic boom from a bolide is the audible shock wave produced when a large meteoroid travels through the lower atmosphere faster than the local speed of sound, generating a ballistic shock that reaches the ground as a sudden loud report. Unlike long-range infrasound, it is heard directly, often delayed by minutes after the fireball is seen because sound travels far slower than light. Its intensity and delay help locate the trajectory and terminal burst.','A sonic boom from a bolide is a loud bang from a fireball. The meteor moves faster than sound. This makes a shock wave that hits the ground. You hear it after you see the flash. That delay is because sound is much slower than light.','It is the near-field, audible expression of a bolide''s shock, useful for locating the object and its burst point.','Witness reports of a delayed boom, combined with fireball timing, help reconstruct meteor trajectories.','Astronomical & Cosmological Acoustics',ARRAY['Bolide infrasound','Meteor acoustic wave','Atmospheric infrasound on planets','Shock wave','Acoustic travel time']::text[],ARRAY['Expecting the boom at the same instant as the flash, when sound arrives much later','Confusing the audible boom with distant infrasound','Assuming all fireballs produce a ground-level boom']::text[],ARRAY['Timing a boom against a fireball sighting','Locating a meteorite fall from boom direction','Distinguishing the boom from an aircraft']::text[],'intermediate',NULL,NULL,'2ffa9e64-cdfc-46eb-886e-2158536093d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic boom from bolide');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '673d8ec4-833d-57a1-9838-159ae25c0b42','2ffa9e64-cdfc-46eb-886e-2158536093d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='673d8ec4-833d-57a1-9838-159ae25c0b42') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='673d8ec4-833d-57a1-9838-159ae25c0b42');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe52abac-aaa2-5569-a59a-2bc163c72f9d','Archaeoacoustics','The interdisciplinary study of sound and acoustics in archaeological and past cultural contexts. It combines acoustic measurement, archaeology, and anthropology to investigate the sonic properties of ancient sites, the sounds people made and heard, and the role of sound in past behaviour. In its strict, measurement-based sense it applies quantitative room-acoustic methods, capturing impulse responses and deriving parameters such as reverberation time and clarity for caves, monuments, and buildings, while a broader usage extends to reconstructing past soundscapes and studying sound-producing artefacts.','Archaeoacoustics studies sound at ancient sites. It asks how old places like caves and temples sounded. Researchers measure echoes and reverberation in these spaces. They also study old instruments and past sounds. The goal is to learn how people used sound long ago.','It exists to add the missing dimension of sound to a past that usually survives only visually. By measuring and modelling how ancient spaces behaved acoustically, it lets researchers ask how sound shaped ritual, communication, and daily life.','A researcher records an impulse response inside a chambered tomb, derives reverberation time and clarity, and compares the result with other sites to judge how speech, chant, or drumming would have carried.','Archaeological & Heritage Acoustics',ARRAY['Sound archaeology','Cave acoustics','Auralization of ancient spaces','Room-acoustic parameters','Music archaeology']::text[],ARRAY['Treating archaeoacoustics as proof that ancient builders deliberately tuned spaces, when acoustic effects can be incidental','Confusing it with fringe claims about mystical sound energy rather than measurable acoustics','Assuming a single measurement captures a site whose shape, surfaces, and openings have changed over millennia']::text[],ARRAY['Measuring the reverberation of a Neolithic stone chamber','Comparing the acoustics of decorated and undecorated cave areas','Assessing whether an amphitheatre supported clear speech']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeoacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe52abac-aaa2-5569-a59a-2bc163c72f9d','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe52abac-aaa2-5569-a59a-2bc163c72f9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe52abac-aaa2-5569-a59a-2bc163c72f9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c47984e9-0d88-5189-ab1e-0dbf0a22a813','Acoustical archaeology','A near-synonym for archaeoacoustics that emphasises the application of acoustic science and measurement to archaeological questions. The label foregrounds the acoustics side, capturing and analysing the sonic behaviour of ancient spaces and artefacts, rather than broader interpretive or soundscape framings. Usage varies between authors, and some treat it as fully interchangeable with archaeoacoustics.','Acoustical archaeology means using sound science to study the past. It is another name for archaeoacoustics. The focus is on measuring how old spaces behave. Researchers record echoes and analyse the numbers. Writers do not all use the term the same way.','It signals a measurement-led approach, bringing the tools of acoustics to bear on sites and objects so that claims about past sound rest on data rather than impression.','An acoustician joining an excavation team to survey a temple''s reverberation and modal behaviour would describe the work as acoustical archaeology.','Archaeological & Heritage Acoustics',ARRAY['Archaeoacoustics','Sound archaeology','Heritage acoustics','Impulse response','Reverberation time']::text[],ARRAY['Assuming it is a distinct discipline from archaeoacoustics rather than an overlapping label','Using it for speculative claims that skip actual acoustic measurement','Expecting a single agreed definition across the literature']::text[],ARRAY['Running an acoustic survey as part of a site investigation','Documenting a monument''s sonic properties before restoration','Reporting measured parameters alongside excavation findings']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustical archaeology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c47984e9-0d88-5189-ab1e-0dbf0a22a813','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c47984e9-0d88-5189-ab1e-0dbf0a22a813') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c47984e9-0d88-5189-ab1e-0dbf0a22a813');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '868fa290-51a5-5225-8ed7-5e4356932cd3','Sound archaeology','An umbrella approach, associated especially with Rupert Till, that studies all sound within an archaeological context rather than only music or only measured acoustics. It treats sound as part of the past environment and human experience, integrating acoustic measurement, music archaeology, soundscape reconstruction, and the study of sound-producing objects. It is deliberately broad, aiming to include research that narrower terms such as music archaeology or archaeoacoustics might exclude.','Sound archaeology studies every kind of sound in the past. It is broader than just old music or echoes. It looks at how whole places once sounded. It joins measurement, instruments, and daily noise together. The aim is a full picture of past hearing.','It exists to keep the study of past sound from splitting into narrow silos, providing a wide frame that treats sound as a normal, meaningful part of any archaeological context.','A project reconstructing a prehistoric site''s soundscape, its instruments, voices, natural sounds, and space acoustics, works under the banner of sound archaeology.','Archaeological & Heritage Acoustics',ARRAY['Archaeoacoustics','Music archaeology','Archaeological soundscape','Acoustic ecology of a site','Auralization of ancient spaces']::text[],ARRAY['Equating it only with ancient music and ignoring ambient and environmental sound','Assuming past sound can be recovered directly rather than inferred and modelled','Treating measured acoustics as the whole field rather than one strand']::text[],ARRAY['Framing a broad study of a site''s total sonic environment','Combining instrument finds with space acoustics in one analysis','Reconstructing the range of sounds heard at a settlement']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound archaeology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '868fa290-51a5-5225-8ed7-5e4356932cd3','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='868fa290-51a5-5225-8ed7-5e4356932cd3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='868fa290-51a5-5225-8ed7-5e4356932cd3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f035d1f7-7ab0-5631-a4fd-f158f62b5b3a','Music archaeology','The study of music and musical behaviour in the human past, drawing on archaeological finds, iconography, written sources, and the analysis and reconstruction of ancient instruments. It investigates how instruments were made and played, the sounds and scales they could produce, and the social and ritual roles of music. It overlaps with organology and ethnomusicology and increasingly uses acoustic analysis of surviving artefacts.','Music archaeology studies music in the distant past. It uses old instruments, pictures, and texts. Researchers examine how instruments were built and played. They test what notes and sounds they could make. This shows the role music had in old societies.','It exists to recover a largely lost human activity, music, by combining physical remains with images and texts, so past musical practice can be studied as evidence rather than guessed at.','A specialist measures the finger holes of an excavated flute, models its possible pitches, and builds a playable replica to test its sound.','Archaeological & Heritage Acoustics',ARRAY['Organology','Bone flute','Archaeological instrument reconstruction','Sound-producing artifact','Ethnomusicology']::text[],ARRAY['Assuming a reconstructed instrument''s tuning matches exactly what ancient players used','Reading modern musical scales onto prehistoric instruments','Treating iconography of instruments as literal technical drawings']::text[],ARRAY['Analysing an excavated bone flute''s playable range','Reconstructing a bronze horn to study its sound','Interpreting instrument depictions on ancient pottery']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Music archaeology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f035d1f7-7ab0-5631-a4fd-f158f62b5b3a','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f035d1f7-7ab0-5631-a4fd-f158f62b5b3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f035d1f7-7ab0-5631-a4fd-f158f62b5b3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88f7e117-0a00-5f29-b018-867deeb7c76c','Palaeolithic soundscape','A reconstruction or conceptualisation of the total sonic environment of the Palaeolithic: the natural sounds, human vocal and instrumental sounds, and the acoustic behaviour of the caves and landscapes in which they occurred. As a research construct it combines evidence from sound-producing artefacts, cave acoustics, and environmental reconstruction. Because direct sonic evidence does not survive, any Palaeolithic soundscape is an informed model rather than a recording of the past.','A Palaeolithic soundscape is the imagined sound world of the Stone Age. It includes nature, voices, and early instruments. It also includes how caves echoed. Researchers build it from clues, not recordings. So it is a careful model of the past.','It gives researchers a way to think about early human life through hearing, not just objects, framing how sound may have structured experience in deep prehistory.','A study pairs finds of bone pipes with cave acoustic measurements to sketch how a decorated chamber might have sounded during a gathering.','Archaeological & Heritage Acoustics',ARRAY['Soundscape','Archaeological soundscape','Cave acoustics','Bone flute','Sound archaeology']::text[],ARRAY['Presenting a modelled soundscape as if it were a recovered recording','Ignoring how much cave shape and climate have changed since the Palaeolithic','Assuming all sounds carried ritual meaning']::text[],ARRAY['Modelling the sound world around a painted cave','Combining instrument finds with environmental reconstruction','Designing a museum audio experience of the Stone Age']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Palaeolithic soundscape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88f7e117-0a00-5f29-b018-867deeb7c76c','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88f7e117-0a00-5f29-b018-867deeb7c76c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88f7e117-0a00-5f29-b018-867deeb7c76c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d61d474-5271-572d-aa99-753f6830656e','Cave acoustics','The acoustic behaviour of natural cave spaces and its measurement and analysis. Caves have irregular geometry and hard, sound-reflecting rock surfaces that produce strong reflections, echoes, long reverberation in large chambers, and pronounced low-frequency resonances in narrow passages. In archaeoacoustics, cave acoustics are quantified through impulse-response measurement and standard room-acoustic parameters, often to compare the sonic character of different areas within a cave.','Cave acoustics is how sound behaves inside caves. Hard rock walls reflect sound strongly. Big chambers ring with long echoes. Narrow tunnels can boom at low pitches. Researchers measure these effects to compare parts of a cave.','It characterises how voices, music, or noise would have carried and been coloured inside a cave, giving a physical basis for questions about how prehistoric people used these spaces.','A team plays a test signal from a loudspeaker and records it at many points to map where a cave is most resonant or echoic.','Archaeological & Heritage Acoustics',ARRAY['Reverberation time','Resonant cave chamber','Rock-art acoustics','Impulse response','Standing wave']::text[],ARRAY['Assuming a cave''s present shape and acoustics match its prehistoric state','Confusing a strong echo with a room resonance, which are different effects','Generalising one chamber''s acoustics to an entire cave system']::text[],ARRAY['Mapping resonant spots through a cave passage','Comparing acoustics near and away from painted panels','Assessing low-frequency booming in a narrow gallery']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cave acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d61d474-5271-572d-aa99-753f6830656e','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d61d474-5271-572d-aa99-753f6830656e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d61d474-5271-572d-aa99-753f6830656e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f549d5e-dd6d-5efc-b533-84123075a906','Rock-art acoustics','The study of the acoustic properties of locations bearing rock art, and of the hypothesis that sound influenced where art was placed. Researchers measure reverberation, echo, and resonance at painted or engraved panels and test whether decorated locations are acoustically distinctive. Some studies report a statistical association between motifs and stronger acoustic response, but the correlation is partial, contested, and does not by itself prove that art was positioned for sonic reasons.','Rock-art acoustics studies how art sites sound. Researchers measure echoes and resonance at painted rocks. Some findings link art spots to strong sound effects. But the link is weak and argued over. It does not prove art was placed for sound.','It tests whether sound was a factor in prehistoric image-making, moving a long-standing idea from anecdote toward measurable, checkable evidence.','Investigators measure impulse responses at decorated and blank panels in the same cave, then compare the acoustic parameters statistically.','Archaeological & Heritage Acoustics',ARRAY['Cave acoustics','Archaeoacoustics','Resonant cave chamber','Reverberation time','Palaeolithic soundscape']::text[],ARRAY['Stating as fact that art was placed for acoustic reasons when the evidence is only a partial correlation','Ignoring that nearness to entrances and other factors also predict art location','Treating a resonant spot measured today as identical to prehistoric conditions']::text[],ARRAY['Comparing acoustics of painted versus unpainted cave walls','Testing whether engraved panels sit at echoing points','Debating acoustic influence on motif placement']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rock-art acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f549d5e-dd6d-5efc-b533-84123075a906','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f549d5e-dd6d-5efc-b533-84123075a906') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f549d5e-dd6d-5efc-b533-84123075a906');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12b02e0e-4767-5e5f-afda-63d99a2b6d8f','Acoustic ecology of a site','The application of acoustic ecology, the study of relationships between living beings and their sonic environment, to a specific archaeological or heritage location. It considers the full set of sounds associated with a site (natural, human, and structural) and how the space''s acoustics shaped the experience of those who used it. For past sites it is necessarily reconstructive, inferring sonic relationships from surviving physical and environmental evidence.','This looks at how a place and its sounds fit together. It covers nature, people, and how the space echoes. It asks how living there felt through hearing. For old sites, it is rebuilt from clues. It joins sound and setting into one picture.','It frames a site not as a silent ruin but as a former living sound environment, helping researchers ask how sound tied people to place.','A study of a hillfort combines wind and animal sounds, human activity, and the acoustics of its ramparts to describe its former sonic setting.','Archaeological & Heritage Acoustics',ARRAY['Acoustic ecology','Soundscape','Archaeological soundscape','Hi-fi soundscape','Sound archaeology']::text[],ARRAY['Treating a reconstructed sound environment as directly recorded fact','Focusing only on human-made sound and ignoring natural and structural sound','Assuming modern background noise reflects the ancient setting']::text[],ARRAY['Describing the total sonic setting of a ceremonial site','Linking a monument''s acoustics to its surroundings','Planning a soundscape reconstruction for interpretation']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic ecology of a site');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12b02e0e-4767-5e5f-afda-63d99a2b6d8f','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12b02e0e-4767-5e5f-afda-63d99a2b6d8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12b02e0e-4767-5e5f-afda-63d99a2b6d8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3dfa6b84-47ce-599d-ba04-9ebee8cfcdaa','Heritage acoustics','The measurement, documentation, conservation, and presentation of the acoustic properties of culturally significant places and objects. It applies standard room-acoustic methods, capturing impulse responses and deriving parameters such as reverberation time, clarity, and definition, to monuments, worship spaces, theatres, and other heritage sites, treating their sonic behaviour as part of the heritage to be recorded and safeguarded. It supports conservation decisions, virtual reconstruction, and public engagement.','Heritage acoustics records how important old places sound. It measures echoes and reverberation in temples and theatres. The sound itself is treated as heritage worth saving. The data guides repairs and virtual models. It also helps share these places with the public.','It preserves an easily overlooked part of cultural heritage, how a place sounds, so acoustic character can be documented before it is altered and recreated for study or visitors.','Conservators measure a cathedral''s reverberation before restoration so the work does not unintentionally change its renowned sound.','Archaeological & Heritage Acoustics',ARRAY['Acoustic heritage','Room-acoustic parameters','Reverberation time','Auralization of ancient spaces','Impulse response']::text[],ARRAY['Assuming a restoration cannot change a space''s acoustics','Recording only reverberation time and ignoring clarity and other parameters','Treating sound as unimportant compared with visible fabric']::text[],ARRAY['Documenting a historic theatre''s acoustics before renovation','Archiving the sound of a worship space for the record','Creating a virtual acoustic model of a monument']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Heritage acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3dfa6b84-47ce-599d-ba04-9ebee8cfcdaa','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3dfa6b84-47ce-599d-ba04-9ebee8cfcdaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3dfa6b84-47ce-599d-ba04-9ebee8cfcdaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c18aece3-9794-50a5-9b57-9b70b5fe44f8','Archaeological soundscape','A reconstruction or study of the soundscape, the total acoustic environment, associated with an archaeological site or period. It integrates evidence of sound sources such as instruments, voices, activities, animals, and weather with the acoustic behaviour of the relevant spaces to model how the past sounded and was heard. Because sound does not survive, an archaeological soundscape is an evidence-based reconstruction rather than a preserved record.','An archaeological soundscape is the rebuilt sound world of a site. It joins likely sources like voices and tools with how the place echoed. Researchers build it from finds and the setting. Sound itself does not survive. So it is a model based on evidence.','It lets archaeologists study experience and atmosphere, asking how a place sounded to the people who lived, worked, or worshipped there.','A study of a Roman street models cart noise, crowds, and building reflections to suggest how loud and lively it would have been.','Archaeological & Heritage Acoustics',ARRAY['Soundscape','Palaeolithic soundscape','Acoustic ecology of a site','Sound archaeology','Auralization of ancient spaces']::text[],ARRAY['Presenting a modelled soundscape as a literal recording of the past','Ignoring how vegetation, buildings, and climate shaped sound','Assuming today''s quiet ruin reflects a once-busy place']::text[],ARRAY['Modelling the sounds of an ancient marketplace','Reconstructing a temple''s ritual sound environment','Building an audio guide from soundscape research']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Archaeological soundscape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c18aece3-9794-50a5-9b57-9b70b5fe44f8','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c18aece3-9794-50a5-9b57-9b70b5fe44f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c18aece3-9794-50a5-9b57-9b70b5fe44f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd991d6b5-1568-5dac-86ba-16c03843281c','Aural architecture','The properties of a space that a listener perceives through sound, including how walls, materials, and geometry shape reflections, reverberation, and the sense of a room, considered as a designed or experienced feature of architecture. Developed by Blesser and Salter, the concept treats the acoustic character of a space as aural architecture analogous to visual architecture, encompassing how spaces are heard and how that hearing carries social and emotional meaning.','Aural architecture is how a space sounds to a listener. Walls and shapes bend and reflect sound. This gives each room its own sonic feel. The idea treats that feel like design you can hear. Spaces speak through sound, not just looks.','It gives a vocabulary for the heard qualities of spaces, so acoustic character can be discussed as a deliberate or meaningful part of architecture and heritage.','An acoustician describes how a cathedral''s long reverberation creates a sense of awe as an example of its aural architecture.','Archaeological & Heritage Acoustics',ARRAY['Room acoustics','Reverberation','Heritage acoustics','Soundscape','Auralization of ancient spaces']::text[],ARRAY['Thinking aural architecture only matters in concert halls, not everyday spaces','Reducing it to reverberation time alone','Assuming the heard qualities of a space are unimportant to its meaning']::text[],ARRAY['Explaining why a stone church feels vast by ear','Analysing how a space''s sound shapes ritual experience','Designing a heritage exhibit around how a space sounds']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural architecture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd991d6b5-1568-5dac-86ba-16c03843281c','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d991d6b5-1568-5dac-86ba-16c03843281c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d991d6b5-1568-5dac-86ba-16c03843281c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80f1d15d-7873-5c9f-90f7-34343d8b3c11','Ancient acoustic space','A general term for a space surviving from antiquity or prehistory that is studied for its acoustic behaviour, such as a cave, tomb, temple, theatre, or amphitheatre. It denotes the physical enclosure and its sonic properties as an object of investigation, rather than a specific theory. Analysis uses standard acoustic measurement to characterise how the space would have handled speech, music, and other sound.','An ancient acoustic space is an old place studied for its sound. It could be a cave, tomb, temple, or theatre. Researchers look at how it handles voices and music. They measure its echoes and reverberation. The focus is the space and how it sounds.','It provides a neutral label for the physical settings archaeoacoustics examines, focusing attention on the enclosure whose sonic behaviour is being measured.','A survey team refers to a rock-cut tomb as an ancient acoustic space when documenting its reverberation and resonances.','Archaeological & Heritage Acoustics',ARRAY['Heritage acoustics','Cave acoustics','Room-acoustic parameters','Reverberation time','Aural architecture']::text[],ARRAY['Assuming every ancient space was built with acoustics in mind','Ignoring that ruins may have lost roofs, surfaces, or fittings that shaped their sound','Comparing spaces without accounting for their different sizes and shapes']::text[],ARRAY['Documenting a theatre''s acoustics for a heritage record','Comparing reverberation across several monuments','Selecting sites for an acoustic survey']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ancient acoustic space');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80f1d15d-7873-5c9f-90f7-34343d8b3c11','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80f1d15d-7873-5c9f-90f7-34343d8b3c11') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80f1d15d-7873-5c9f-90f7-34343d8b3c11');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e87fe9d-831e-5c7d-9e9b-0ceed9c512a3','Ritual acoustics','The study of how sound and the acoustic properties of spaces functioned in ritual and ceremonial contexts, and the hypothesis that some spaces were used or shaped for their sonic effects during ritual. Researchers measure the acoustics of ceremonial sites and consider how features such as strong reverberation, echoes, or low-frequency resonance might have supported chant, drumming, or altered states. The claim that acoustics were deliberately exploited in ritual is plausible but debated and hard to prove.','Ritual acoustics looks at sound in ceremonies. It studies how sacred spaces echo and resonate. Strong echoes might have aided chant or drumming. Some think spaces were chosen for these effects. This idea is reasonable but hard to prove.','It connects the physics of a space to human ceremony, offering a way to ask whether sound was part of how rituals worked and felt.','A researcher measures a temple''s low-frequency resonances and considers whether they align with the pitch range of chanting or drums.','Archaeological & Heritage Acoustics',ARRAY['Archaeoacoustics','Heritage acoustics','Resonant cave chamber','Reverberation time','Archaeological soundscape']::text[],ARRAY['Stating that a space was built for ritual sound when only its acoustics, not intent, can be measured','Assuming any resonance had ritual meaning','Reading modern spiritual ideas about sound onto ancient people']::text[],ARRAY['Measuring resonance in a temple linked to ceremony','Considering how chant would carry in a stone chamber','Debating whether acoustics shaped ritual use of a site']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ritual acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e87fe9d-831e-5c7d-9e9b-0ceed9c512a3','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e87fe9d-831e-5c7d-9e9b-0ceed9c512a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e87fe9d-831e-5c7d-9e9b-0ceed9c512a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85abca7e-7404-596b-9cf5-723e19748437','Resonant cave chamber','A cave chamber whose geometry and hard surfaces produce marked acoustic resonance, reinforcing particular frequencies through standing waves or a strong reverberant field, so that sounds within it are notably amplified, sustained, or coloured. In archaeoacoustics such chambers are identified by impulse-response and frequency-response measurement, and are of interest because their striking sonic behaviour may have drawn human use, though intentional selection is inferred, not proven.','A resonant cave chamber is a cave room that rings. Its shape and hard walls boost certain pitches. Sounds inside grow louder or last longer. Researchers find these rooms by measuring their sound. Such rooms may have drawn people, but that is not certain.','It names the kind of space whose vivid acoustics make it a focus in archaeoacoustics, linking measurable resonance to questions about past human use.','A survey flags a chamber where a sung note is strongly reinforced, then measures its resonant frequencies for the record.','Archaeological & Heritage Acoustics',ARRAY['Cave acoustics','Standing wave','Resonance','Rock-art acoustics','Reverberation time']::text[],ARRAY['Assuming a resonant chamber was necessarily chosen or used for its sound','Confusing a room resonance with a simple echo','Treating today''s resonance as unchanged from prehistoric times']::text[],ARRAY['Identifying a strongly resonant room in a cave survey','Measuring which pitches a chamber reinforces','Discussing possible human use of a resonant space']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant cave chamber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85abca7e-7404-596b-9cf5-723e19748437','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85abca7e-7404-596b-9cf5-723e19748437') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85abca7e-7404-596b-9cf5-723e19748437');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a60e18ba-be87-5072-b6ef-ce0c7015fccf','Lithophone','A percussion instrument or sound-producing object consisting of resonant stone that produces musical or ringing tones when struck. Lithophones range from arrangements of tuned stone bars or slabs to natural rock formations that ring when hit. In music archaeology the term covers both purpose-made stone instruments and natural stones used to produce sound, identified by resonant lithology and, sometimes, wear marks from striking.','A lithophone is a stone that makes musical sounds when struck. Some are sets of tuned stone bars. Others are natural rocks that ring when hit. The stone must resonate to sound clear. People have used them as instruments for a very long time.','It shows that stone, not just wood or metal, can serve as a tuned musical material, extending the record of human music-making to durable mineral instruments.','An archaeologist identifies struck stone bars with ringing tones and wear marks and classifies them as a lithophone.','Archaeological & Heritage Acoustics',ARRAY['Rock gong','Ringstone','Phonolite','Idiophone','Sounding stone']::text[],ARRAY['Assuming any stone rings, when only certain dense, crack-free rock resonates well','Assuming lithophones are always deliberately made, when many are natural rocks used for sound','Treating all cup-marked or worn stones as musical without acoustic evidence']::text[],ARRAY['Testing whether stone bars ring at musical pitches','Identifying wear from repeated striking','Reconstructing a stone instrument for demonstration']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lithophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a60e18ba-be87-5072-b6ef-ce0c7015fccf','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a60e18ba-be87-5072-b6ef-ce0c7015fccf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a60e18ba-be87-5072-b6ef-ce0c7015fccf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c46cd43e-0705-50f4-9e19-7b3a0e308b69','Ringstone','A stone that produces a clear ringing or resonant tone when struck, owing to a dense, elastic, crack-free lithology (such as certain phonolites or fine-grained igneous rocks) that vibrates with low damping. Ringing stones, also called ringing rocks, may occur naturally as boulders or outcrops and have in places been used as sound-producing objects or informal lithophones. The ringing arises from the stone''s material properties and mounting rather than from any hollow interior.','A ringstone is a rock that rings when struck. Dense, crack-free stone vibrates cleanly. This gives a clear, bell-like tone. Some boulders and outcrops ring this way. People have used them to make sound.','It identifies naturally resonant rock, explaining why some stones sound like bells and can serve as found instruments or signalling objects.','A fieldworker taps boulders in an outcrop, notes which ring clearly, and records their lithology and any wear from striking.','Archaeological & Heritage Acoustics',ARRAY['Phonolite','Lithophone','Rock gong','Sounding stone','Resonance']::text[],ARRAY['Assuming a stone rings because it is hollow, when clear tone comes from dense, crack-free rock','Expecting every boulder of the right rock type to ring, when cracks and bedding kill the tone','Reading intentional musical use into any ringing stone without further evidence']::text[],ARRAY['Testing outcrop boulders for a clear ringing tone','Linking ringing rocks to nearby archaeological activity','Selecting stone for a replica lithophone']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ringstone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c46cd43e-0705-50f4-9e19-7b3a0e308b69','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c46cd43e-0705-50f4-9e19-7b3a0e308b69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c46cd43e-0705-50f4-9e19-7b3a0e308b69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7bd969f-e7a3-577c-99bd-54875be971aa','Phonolite','A fine-grained, silica-undersaturated volcanic rock, typically rich in alkali feldspar and feldspathoids, whose name (from the Greek for sounding stone) reflects that thin, dense slabs of it ring with a clear metallic tone when struck. Its dense, fine texture and elasticity give low internal damping, so it vibrates audibly. Some phonolite outcrops and slabs have been used as natural lithophones or ringing stones.','Phonolite is a fine volcanic rock that rings when struck. Its name means sounding stone. Thin, dense slabs give a clear metallic tone. The tight texture lets it vibrate well. People have used it to make musical sounds.','It is the classic example of a naturally resonant rock, showing how a rock''s mineral makeup and texture can make it suitable as a sound-producing material.','A geologist identifies a fine-grained slab that rings when tapped and classifies it as phonolite based on its texture and mineralogy.','Archaeological & Heritage Acoustics',ARRAY['Ringstone','Lithophone','Sounding stone','Igneous rock','Resonance']::text[],ARRAY['Assuming all phonolite rings equally, regardless of thickness and cracks','Thinking the ringing means the rock is metallic rather than a specific volcanic rock','Using the sound alone to identify the rock without checking mineralogy']::text[],ARRAY['Identifying phonolite by its ring and texture','Explaining why certain slabs work as lithophones','Sourcing resonant stone for instrument reconstruction']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonolite');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7bd969f-e7a3-577c-99bd-54875be971aa','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7bd969f-e7a3-577c-99bd-54875be971aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7bd969f-e7a3-577c-99bd-54875be971aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78bb1d19-15b6-5c19-b46a-9c7d1708eeb1','Sounding stone','A general term for a stone that is deliberately struck to produce sound, whether a shaped musical instrument or a natural resonant rock used for signalling, ritual, or music. It spans purpose-made instruments, such as the tuned stone chimes of some historical traditions, and natural ringing rocks or rock gongs. Identification rests on the stone''s resonant behaviour and, where present, wear or manufacture marks indicating repeated striking.','A sounding stone is a rock struck to make sound. Some are shaped, tuned instruments. Others are natural rocks that ring. People used them for music or signals. Marks from striking can show their use.','It provides a broad label linking many kinds of sound-making stone, from crafted chimes to natural ringing rocks, under one functional idea.','A researcher documents a rock bearing repeated strike marks and a clear tone as a sounding stone used for signalling or ritual.','Archaeological & Heritage Acoustics',ARRAY['Lithophone','Rock gong','Ringstone','Phonolite','Sound-producing artifact']::text[],ARRAY['Assuming any marked stone was struck for sound rather than for tool-making or grinding','Treating a poorly resonant stone as a sounding stone without acoustic testing','Overlooking that shaped chimes and natural ringing rocks differ in origin']::text[],ARRAY['Recording strike wear on a resonant boulder','Comparing crafted stone chimes with natural ringing rock','Interpreting a stone''s role in signalling or ritual']::text[],'intermediate',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sounding stone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78bb1d19-15b6-5c19-b46a-9c7d1708eeb1','601f6272-8859-47f6-a873-447c45f286ef',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78bb1d19-15b6-5c19-b46a-9c7d1708eeb1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78bb1d19-15b6-5c19-b46a-9c7d1708eeb1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48862aa5-1837-5f86-b6b0-a6895272fe05','Rock gong','A natural rock, boulder, or slab that produces resonant, often bell- or gong-like tones when struck, and that bears evidence, such as cup-shaped percussion marks or polished, worn spots, of repeated striking to make sound. Documented on several continents, rock gongs are a form of natural lithophone. The characteristic worn playing spots distinguish deliberately used rock gongs from stones that merely happen to ring.','A rock gong is a large rock struck to make ringing sounds. Hitting it can give bell-like tones. Worn or cup-shaped marks show repeated striking. These marks reveal that people used it for sound. Rock gongs are found across many regions.','It provides physical evidence that people used natural rock to make sound, with the wear marks offering rare direct proof of past sound-making activity.','A survey records a boulder with clustered percussion marks that ring when struck and identifies it as a rock gong.','Archaeological & Heritage Acoustics',ARRAY['Lithophone','Ringstone','Cupule acoustics','Sounding stone','Sound-producing artifact']::text[],ARRAY['Assuming any ringing boulder is a rock gong without wear or percussion marks','Confusing cup marks from striking with cupules made as art','Playing or sampling a fragile rock gong in ways that damage it']::text[],ARRAY['Identifying percussion wear on a resonant boulder','Recording a rock gong''s tones and marks','Linking a rock gong to a nearby rock-art site']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rock gong');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48862aa5-1837-5f86-b6b0-a6895272fe05','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48862aa5-1837-5f86-b6b0-a6895272fe05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48862aa5-1837-5f86-b6b0-a6895272fe05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7f775a1-952d-552e-bf5e-7132e9982c58','Cupule acoustics','The study of the acoustic dimension of cupules, small cup-shaped depressions pounded into rock and among the most widespread and ancient forms of rock markings, and of the hypothesis that some were produced for, or associated with, sound. Because cupules are made by repeated percussion, some researchers propose that the sound of their making, or the ringing of the host rock, was significant. The idea is plausible for some resonant rocks but debated and not generally established.','Cupule acoustics studies the sound side of cupules. Cupules are small cup-shaped dents pounded into rock. Making them by striking produces sound. Some think that sound, or the rock''s ring, mattered. This idea fits some rocks but is debated.','It asks whether the act of making cupules, or the resonance of the struck rock, had a sonic purpose, linking a common rock marking to questions of sound.','A researcher tests whether a cupule-covered boulder rings when struck and considers whether sound accompanied the marking.','Archaeological & Heritage Acoustics',ARRAY['Rock gong','Rock-art acoustics','Lithophone','Sounding stone','Sound-producing artifact']::text[],ARRAY['Assuming all cupules were made for sound when many likely had other meanings','Confusing cupules (deliberate markings) with natural weathering pits','Treating a single resonant example as proof for cupules everywhere']::text[],ARRAY['Testing a cupule-marked rock for resonance','Debating whether cupule-making was partly sonic','Recording cupules alongside a rock gong''s playing spots']::text[],'advanced',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cupule acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7f775a1-952d-552e-bf5e-7132e9982c58','601f6272-8859-47f6-a873-447c45f286ef',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7f775a1-952d-552e-bf5e-7132e9982c58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7f775a1-952d-552e-bf5e-7132e9982c58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '678b16f7-c614-537d-9a26-b1615c985ca4','Bullroarer','An ancient sound-producing device consisting of a flat, elongated slat of wood, bone, or stone attached to a cord, which is whirled through the air to produce a pulsating, low-pitched roaring or whirring sound. The blade''s rotation about the cord and its aerodynamic flutter generate the sound, whose pitch depends on the blade''s size and the speed of whirling. Bullroarers are among the oldest and most widespread sound instruments, documented archaeologically and ethnographically, often in ritual contexts.','A bullroarer is a flat slat swung on a cord. Whirling it through the air makes a deep roaring sound. Its spin and flutter create the noise. Bigger slats and faster swings change the pitch. It is one of the oldest known sound tools.','It produces a powerful, carrying sound from simple materials, and in many cultures its distinctive roar has marked ritual or signalling contexts.','An archaeologist identifies a pierced, elongated bone or wood slat with aerodynamic shaping as a probable bullroarer and tests a replica.','Archaeological & Heritage Acoustics',ARRAY['Sound-producing artifact','Music archaeology','Aerophone','Ritual acoustics','Archaeological instrument reconstruction']::text[],ARRAY['Mistaking a pierced pendant or ornament for a bullroarer without aerodynamic shaping','Assuming every bullroarer had the same ritual meaning across cultures','UNSAFE: whirling a bullroarer near people without clear space, as the swinging blade and cord can strike bystanders']::text[],ARRAY['Identifying a slat artefact as a bullroarer','Testing a replica''s sound and pitch range','Interpreting a bullroarer''s ritual or signalling role']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bullroarer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '678b16f7-c614-537d-9a26-b1615c985ca4','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='678b16f7-c614-537d-9a26-b1615c985ca4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='678b16f7-c614-537d-9a26-b1615c985ca4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ed21226-ba83-5fc5-b786-491504e61a8a','Bone flute','A wind instrument made from a hollow animal bone, often a bird''s wing bone or other long bone, into which finger holes are bored, producing pitched sound when blown. Bone flutes are among the oldest surviving musical instruments, with Upper Palaeolithic examples documented in Europe. Their finger-hole spacing and bore allow reconstruction of playable pitch ranges, though the exact playing technique and tuning intent are inferred.','A bone flute is a flute made from a hollow bone. Holes are bored along it to change pitch. Blowing it makes musical notes. Some bone flutes are very old, from the Stone Age. Their holes let us guess what notes they played.','It provides direct evidence of early music-making, letting researchers study the pitches and sounds available to people tens of thousands of years ago.','A specialist measures a Palaeolithic bird-bone flute''s holes and bore, models its pitches, and plays a replica to hear its range.','Archaeological & Heritage Acoustics',ARRAY['Paleolithic flute','Music archaeology','Sound-producing artifact','Archaeological instrument reconstruction','Organology']::text[],ARRAY['Assuming a holed bone is a flute when holes can result from carnivore gnawing','Reading a modern scale onto a prehistoric flute''s tuning','Treating a reconstruction''s sound as the exact original']::text[],ARRAY['Analysing a bird-bone flute''s playable pitches','Distinguishing bored holes from animal tooth marks','Reconstructing a bone flute to study its sound']::text[],'beginner',NULL,NULL,'601f6272-8859-47f6-a873-447c45f286ef' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bone flute');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ed21226-ba83-5fc5-b786-491504e61a8a','601f6272-8859-47f6-a873-447c45f286ef',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ed21226-ba83-5fc5-b786-491504e61a8a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ed21226-ba83-5fc5-b786-491504e61a8a');
